
/* 入口保护：无有效本机会话时不能直接进入工作台；会话不再按使用时长自动过期。 */
(function(){
  try{
    var session=JSON.parse(localStorage.getItem("nnuzc_session")||"null");
    if(!session || !session.uid || !["sa","admin","editor","viewer"].includes(session.role)){
      localStorage.removeItem("nnuzc_session");
      location.replace("./login.html");
      /* 旧版错误抛出语句存在编码残留，重定向后无需继续执行。 */
      return;
      /*
      throw new Error("未登录");
      */
    }
    window.__NNUZC_SESSION__=session;
  }catch(e){
    if(location.pathname.indexOf("login.html")===-1) location.replace("./login.html");
    throw e;
  }
})();
/* 数据持久化保障：localStorage 写入失败时（隐私模式 / 配额已满 / 被禁用）给出明确提示，
   并引导到【数据备份】模块导出或恢复，避免静默丢数据（需求②）。 */
(function(){
  try{
    if(!window.Storage || !Storage.prototype.setItem) return;
    var _origSet = Storage.prototype.setItem;
    var _lastWarn = 0;
    Storage.prototype.setItem = function(k, v){
      try{ _origSet.call(this, k, v); }
      catch(err){
        var now = Date.now();
        if(now - _lastWarn > 4000){
          _lastWarn = now;
          /* legacy corrupted message:
          var msg = "⚠ 保存失败：本地存储不可用或已满。请尽快到【数据备份】导出数据，或清理浏览器存储后重试。";
          */
          var msg = "Local storage is unavailable or full. Export a backup and free browser storage before trying again.";
          if(typeof showToast === "function") showToast(msg, "error");
           else alert(msg);
         }
        throw err;
      }
    };
  }catch(e){}
})();
/* ============ 工具函数 ============ */
// HTML 转义与空值占位工具
function esc(v){ return v==null ? "" : String(v).replace(/&/g,"&amp;").replace(/</g,"&lt;").replace(/>/g,"&gt;").replace(/\"/g,"&quot;").replace(/'/g,"&#39;"); }
function escAttr(v){ return v==null?"":String(v).replace(/&/g,'&amp;').replace(/"/g,'&quot;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/'/g,'&#39;'); }
function attachmentRefIds(value,out){
  out=out||new Set();
  if(!value||typeof value!=="object") return out;
  if(typeof value.id==="string"&&/^[a-f0-9-]{36}$/i.test(value.id)&&(value.url||value.name||value.fileName||value.mime||value.size)) out.add(value.id);
  Object.keys(value).forEach(function(key){const child=value[key];if(child&&typeof child==="object")attachmentRefIds(child,out);});
  return out;
}
async function deleteAttachmentRefs(values){
  const ids=new Set();(Array.isArray(values)?values:[values]).forEach(function(value){attachmentRefIds(value,ids);});
  await Promise.all([...ids].map(function(id){return window.workbench.legacy.attachmentDelete(id).catch(function(){return null;});}));
  return ids.size;
}
/* 将不可信 ID 安全地放入内联事件参数；不可用 HTML 转义替代 JavaScript 字符串转义。 */
function jsArg(v){ return escAttr(JSON.stringify(String(v==null?"":v))); }
function accountInputLen(input,max){ if(input && typeof max==="number" && input.value.length>max) input.value=input.value.slice(0,max); }
window.__workbenchStartupErrors=[];
function reportDataError(context,error){
  const message=context+"："+(error&&error.message?error.message:String(error||"未知错误"));
  console.error("[数智学工] "+message,error);
  window.__workbenchStartupErrors.push(message);
  if(typeof showToast==="function") showToast(context+"失败，请检查数据备份或浏览器控制台。","error");
}
async function reloadAfterPendingSaves(){
  try{ if(window.workbench&&window.workbench.legacy&&typeof window.workbench.legacy.flushStore==="function") await window.workbench.legacy.flushStore(); }
  catch(_error){ return; }
  location.reload();
}

const DEFAULT_TERM = "";
const DEFAULT_TERM_LIST = []; /* v1.33：不再内置学期，全部由用户新增/导入真实学期 */
/* ==== 2026-08-03 废弃学期黑名单（v1.27 删除）：这些学期不再出现在选择器中，若仍在 localStorage 则启动时自动清理相关数据 ==== */
const DEPRECATED_TERMS = ["2002-2003-1学期"];
function getTermList(){
  try{
    const v = localStorage.getItem("nnuzc_term_list");
    if(v){
      const a = JSON.parse(v);
      if(Array.isArray(a) && a.length){
        const seen = new Set();
        const filtered = [];
        for(const t of a){
          if(/^\d{4}-\d{4}-[1-9]学期$/.test(t) && !seen.has(t) && DEPRECATED_TERMS.indexOf(t) === -1){ seen.add(t); filtered.push(t); }
        }
        if(filtered.length) return sortTermsDesc(filtered);
      }
    }
  }catch(e){}
  return sortTermsDesc(DEFAULT_TERM_LIST);
}
function saveTermList(list){ localStorage.setItem("nnuzc_term_list", JSON.stringify(sortTermsDesc(list))); }
const TERM_VALUE_PATTERN=/^\d{4}-\d{4}-[1-9]学期$/;
const TERM_INDEX_STORAGE_KEYS=["nnuzc_academic_terms","nnuzc_academic_warnings","nnuzc_grade_terms","nnuzc_fund_terms","nnuzc_class_officer_assessment_terms"];
const TERM_BUSINESS_STORAGE_KEYS=["nnuzc_student_leaves",
  "nnuzc_students","nnuzc_dorm_dist","nnuzc_dorm_spatial_v1","nnuzc_fund_records","nnuzc_fund_terms",
  "nnuzc_academic_terms","nnuzc_academic_warnings","nnuzc_grade_terms","nnuzc_talks","nnuzc_home","nnuzc_events",
  "nnuzc_checkclass","nnuzc_chaoxing_imports","nnuzc_checkdorm","nnuzc_help","nnuzc_course_schedules","nnuzc_tasks","nnuzc_keycare",
  "nnuzc_workfolder","nnuzc_class_officer_records","nnuzc_class_officer_assessment_terms","nnuzc_meetings","nnuzc_punishments"
];
function collectTermValuesDeep(value,out){
  if(typeof value==="string"){const text=value.trim();if(TERM_VALUE_PATTERN.test(text)&&DEPRECATED_TERMS.indexOf(text)===-1)out.add(text);return;}
  if(Array.isArray(value)){value.forEach(function(item){collectTermValuesDeep(item,out);});return;}
  if(value&&typeof value==="object")Object.keys(value).forEach(function(key){collectTermValuesDeep(value[key],out);});
}
/* 历史兼容：任何业务模块里已经存在、但尚未登记到“学期设置”的有效学期，启动时自动补回全局学期表。
   回收站、备份、缓存和系统设置不参与扫描，避免已删除或归档数据把旧学期重新带回。 */
function reconcileGlobalTermsFromBusinessData(){
  const discovered=new Set(getTermList());
  TERM_BUSINESS_STORAGE_KEYS.forEach(function(key){
    try{const raw=localStorage.getItem(key);if(raw)collectTermValuesDeep(JSON.parse(raw),discovered);}catch(_error){}
  });
  const next=sortTermsDesc(Array.from(discovered));
  if(JSON.stringify(next)!==JSON.stringify(getTermList()))saveTermList(next);
  const settings=getTermSettings();let changed=false;
  next.forEach(function(term){if(!settings[term]){settings[term]={startDate:"",totalWeeks:""};changed=true;}});
  if(changed)saveTermSettings(settings);
  return next;
}
function termObjectHasBusinessData(value,term){
  if(Array.isArray(value))return value.some(function(item){return termObjectHasBusinessData(item,term);});
  if(!value||typeof value!=="object")return false;
  if(String(value.term||"").trim()===term){
    if(Array.isArray(value.rows))return value.rows.length>0;
    return true;
  }
  return Object.keys(value).some(function(key){return termObjectHasBusinessData(value[key],term);});
}
function termHasBusinessData(term){
  return TERM_BUSINESS_STORAGE_KEYS.filter(function(key){return key!=="nnuzc_fund_terms";}).some(function(key){
    try{const raw=localStorage.getItem(key);return !!raw&&termObjectHasBusinessData(JSON.parse(raw),term);}catch(_error){return false;}
  });
}
function removeEmptyTermIndexes(term){
  TERM_INDEX_STORAGE_KEYS.forEach(function(key){
    try{
      const raw=localStorage.getItem(key);if(!raw)return;const list=JSON.parse(raw);if(!Array.isArray(list))return;
      const next=list.filter(function(item){if(!item||String(item.term||"").trim()!==term)return true;return Array.isArray(item.rows)&&item.rows.length>0;});
      if(next.length!==list.length)localStorage.setItem(key,JSON.stringify(next));
    }catch(_error){}
  });
}
function lockedImportTerm(targetTerm){
  const term=String(targetTerm||"").trim();
  if(!TERM_VALUE_PATTERN.test(term)||getTermList().indexOf(term)===-1)throw new Error("导入目标学期无效，请先在“学期设置”中维护该学期。");
  return term;
}
function selectedImportTerm(key){
  const values=selectedViewTerms(key);
  if(values.length!==1)throw new Error("导入前请只选择一个目标学期，不能在“全部学期”或多学期状态下导入。");
  return lockedImportTerm(values[0]);
}
/* 新增全局学期后，自动同步到各模块独立维护的学期列表。 */
function syncTermToModules(t){
  t = (t||"").trim();
  if(!t) return;
  try{
    if(!Array.isArray(window.academicTerms)) window.academicTerms = loadAcademicTerms();
    if(!window.academicTerms.some(function(x){ return x.term === t; })){
      window.academicTerms.push({ id: window.academicTermSeq++, term: t, status: "待录入", rows: [] });
      window.academicTerms = sortTermsDesc(window.academicTerms);
      saveAcademicTerms();
    }
  }catch(e){}
  try{
    if(!Array.isArray(window.academicWarningTerms)) window.academicWarningTerms = loadAcademicWarningTerms();
    if(!window.academicWarningTerms.some(function(x){ return x.term === t; })){
      window.academicWarningTerms.push({ id: window.academicWarningTermSeq++, term: t, status: "待录入", rows: [] });
      window.academicWarningTerms = sortTermsDesc(window.academicWarningTerms);
      saveAcademicWarningTerms();
    }
  }catch(e){}
  try{
    if(!Array.isArray(window.gradeTerms)) window.gradeTerms = loadGradeTerms();
    if(!window.gradeTerms.some(function(x){ return x.term === t; })){
      window.gradeTerms.push({ id: window.gradeTermSeq++, term: t, status: "待录入", rows: [] });
      window.gradeTerms = sortTermsDesc(window.gradeTerms);
      saveGradeTerms();
    }
  }catch(e){}
  try{ ensureFundTerm(t); }catch(e){ reportDataError("资助学期同步",e); }
  try{ classOfficerAssessmentEnsureTerm(t); classOfficerAssessmentSyncTerm(t); }catch(e){}
}
/* 启动时把「当前学期列表」中已有的全部学期，一次性同步到综测数据、学业预警、成绩与排名、资助情况、班委考核模块（仅补建缺失项，不覆盖已有数据）。
   用于：此前在全局新增过学期、但模块里还没对应学期的历史数据，打开系统即自动补齐。 */
function syncAllTermsToModules(){
  const list = getTermList();
  if(!list || !list.length) return;
  list.forEach(function(t){ try{ syncTermToModules(t); }catch(e){} });
}
function getCurrentTerm(){ const list=getTermList(); const v=localStorage.getItem("nnuzc_current_term"); return v && list.indexOf(v)!==-1 ? v : (list[0]||DEFAULT_TERM); }
const TERM_SETTINGS_KEY="nnuzc_term_settings";
function validTermDate(value){ return /^\d{4}-\d{2}-\d{2}$/.test(String(value||"")); }
function getTermSettings(){
  try{
    const raw=localStorage.getItem(TERM_SETTINGS_KEY), data=raw?JSON.parse(raw):{};
    if(!data||Array.isArray(data)||typeof data!=="object") return {};
    const out={};
    Object.keys(data).forEach(function(term){
      const row=data[term]||{}, startDate=String(row.startDate||""), totalWeeks=Math.floor(Number(row.totalWeeks));
      const periods=Array.isArray(row.periods)?row.periods.map(function(item,index){return {no:index+1,start:String(item&&item.start||""),end:String(item&&item.end||"")};}):[];
      if(/^\d{4}-\d{4}-[1-9]学期$/.test(term)){const normalized={startDate:validTermDate(startDate)?startDate:"",totalWeeks:totalWeeks>=1&&totalWeeks<=52?totalWeeks:""};if(periods.length)normalized.periods=periods;out[term]=normalized;}
    });
    return out;
  }catch(_error){ return {}; }
}
function saveTermSettings(settings){ localStorage.setItem(TERM_SETTINGS_KEY,JSON.stringify(settings||{})); }
function termDateText(value){ return validTermDate(value)?value:"未设置"; }
function termWeeksText(value){ const weeks=Math.floor(Number(value)); return weeks>=1&&weeks<=52?weeks+" 周":"未设置"; }
function termEndDate(startDate,totalWeeks){
  const weeks=Math.floor(Number(totalWeeks));
  if(!validTermDate(startDate)||!(weeks>=1&&weeks<=52)) return "";
  const end=new Date(String(startDate)+"T00:00:00"); end.setDate(end.getDate()+weeks*7-1);
  return end.getFullYear()+"-"+String(end.getMonth()+1).padStart(2,"0")+"-"+String(end.getDate()).padStart(2,"0");
}
function currentSemesterWeek(term){
  const item=getTermSettings()[String(term||"")]||{}, startDate=String(item.startDate||""), totalWeeks=Math.floor(Number(item.totalWeeks));
  if(!validTermDate(startDate)||!(totalWeeks>=1&&totalWeeks<=52)) return {text:"请设置开学日期和总教学周数",state:"unset"};
  const today=new Date(); today.setHours(0,0,0,0);
  const start=new Date(startDate+"T00:00:00"), end=new Date(termEndDate(startDate,totalWeeks)+"T00:00:00");
  if(today<start){ const days=Math.ceil((start-today)/86400000); return {text:"尚未开学（还有 "+days+" 天）",state:"before"}; }
  if(today>end) return {text:"本学期已结束",state:"after"};
  const week=Math.floor((today-start)/604800000)+1;
  if(week>totalWeeks) return {text:"教学周已结束（共 "+totalWeeks+" 周）",state:"after"};
  return {text:"第 "+week+" / "+totalWeeks+" 教学周",state:"active",week:week,totalWeeks:totalWeeks};
}
function validateSemesterStart(startDate){
  if(startDate&&!validTermDate(startDate)){ alert("开始时间格式无效，请选择有效日期或留空。"); return false; }
  return true;
}
function saveSemesterSetting(term,startDate,totalWeeks){
  term=String(term||"").trim(); startDate=String(startDate||"").trim();
  const totalWeeksText=String(totalWeeks==null?"":totalWeeks).trim();
  if(!/^\d{4}-\d{4}-[1-9]学期$/.test(term)){ alert("请完整填写学期名称：年份各为 4 位数字，学期序号为 1—9，如 2026-2027-1学期。"); return false; }
  if(!validateSemesterStart(startDate)) return false;
  if(totalWeeksText&&!/^\d+$/.test(totalWeeksText)){ alert("总教学周数应为 1 至 52 周之间的整数，或留空。"); return false; }
  const normalizedWeeks=totalWeeksText?Number(totalWeeksText):"";
  if(totalWeeksText&&!(normalizedWeeks>=1&&normalizedWeeks<=52)){ alert("总教学周数应为 1 至 52 周之间的整数，或留空。"); return false; }
  const list=getTermList(), isNew=!list.includes(term);
  if(isNew){ list.push(term); saveTermList(list); syncTermToModules(term); }
  const settings=getTermSettings(),previous=settings[term]||{}; settings[term]=Object.assign({},previous,{startDate:startDate,totalWeeks:normalizedWeeks}); saveTermSettings(settings);
  if(!getCurrentTerm()) localStorage.setItem("nnuzc_current_term",term);
  reloadAfterPendingSaves();
  return true;
}
function removeSemesterSetting(term){
  term=String(term||"").trim(); const list=getTermList(), idx=list.indexOf(term);
  if(idx===-1){ alert("该学期不存在。"); return; }
  if(termHasBusinessData(term)){ alert("学期“"+term+"”仍被业务数据使用，不能从学期设置删除。请先删除或迁移该学期的业务记录；系统不会让历史数据失去所属学期。"); return; }
  if(!confirm("删除学期“"+term+"”后，它将不再出现在各业务模块的学期选择中；已录入的历史业务数据不会被删除。确定继续？")) return;
  removeEmptyTermIndexes(term);
  list.splice(idx,1); saveTermList(list);
  const settings=getTermSettings(); delete settings[term]; saveTermSettings(settings);
  if(getCurrentTerm()===term) localStorage.setItem("nnuzc_current_term",list.length?sortTermsDesc(list)[0]:"");
  reloadAfterPendingSaves();
}

/* ==== 启动时清理：移除各业务 storage 中引用了废弃学期的数据 ==== */
const PURGE_TERM_DATA_KEYS = ["nnuzc_dorm_dist","nnuzc_dorm_spatial_v1","nnuzc_fund_records","nnuzc_fund_terms","nnuzc_academic_warnings","nnuzc_grade_terms","nnuzc_talks","nnuzc_home","nnuzc_events","nnuzc_checkclass","nnuzc_checkdorm","nnuzc_help","nnuzc_course_schedules","nnuzc_tasks","nnuzc_keycare","nnuzc_workfolder","nnuzc_class_officer_records","nnuzc_students"];
function purgeTermDeep(obj){
  if(Array.isArray(obj)){
    // 数组：剔除元素 term 字段命中废弃学期的项，再递归处理保留下来的项
    const filtered = obj.filter(function(item){ return !(item && typeof item === "object" && DEPRECATED_TERMS.indexOf(item.term) !== -1); });
    if(filtered.length !== obj.length){ __purgeStats.removed += (obj.length - filtered.length); }
    return filtered.map(function(item){ return purgeTermDeep(item); });
  }
  if(obj && typeof obj === "object"){
    const out = {};
    for(const k of Object.keys(obj)){
      // 对象自身 key 为 "term" 且值命中废弃学期 → 删除该字段（避免后续渲染引用到死值）
      if(k === "term" && DEPRECATED_TERMS.indexOf(obj[k]) !== -1){ __purgeStats.removed++; continue; }
      out[k] = purgeTermDeep(obj[k]);
    }
    return out;
  }
  return obj;
}
let __purgeStats = { removed: 0, keys: [], currentFallback: null };
function purgeDeprecatedTermData(){
  if(typeof localStorage === "undefined") return;
  // 1) 白名单
  try{
    const raw = localStorage.getItem("nnuzc_term_list");
    if(raw){
      const a = JSON.parse(raw);
      if(Array.isArray(a)){
        const before = a.length;
        const after = a.filter(function(t){ return DEPRECATED_TERMS.indexOf(t) === -1; });
        if(after.length !== before){
          localStorage.setItem("nnuzc_term_list", JSON.stringify(after));
          __purgeStats.removed += (before - after);
          __purgeStats.keys.push("nnuzc_term_list");
        }
      }
    }
  }catch(e){}
  // 2) 当前学期回退
  try{
    const cur = localStorage.getItem("nnuzc_current_term");
    if(cur && DEPRECATED_TERMS.indexOf(cur) !== -1){
      const list = getTermList();
      const fallback = (list && list.length) ? list[0] : DEFAULT_TERM;
      localStorage.setItem("nnuzc_current_term", fallback);
      __purgeStats.currentFallback = cur + " → " + fallback;
      __purgeStats.keys.push("nnuzc_current_term");
    }
  }catch(e){}
  // 3) 业务数据：递归清理引用废弃学期的项
  for(const key of PURGE_TERM_DATA_KEYS){
    try{
      const raw = localStorage.getItem(key);
      if(!raw) continue;
      const data = JSON.parse(raw);
      const beforeStr = JSON.stringify(data);
      const cleaned = purgeTermDeep(data);
      const afterStr = JSON.stringify(cleaned);
      if(beforeStr !== afterStr){
        localStorage.setItem(key, JSON.stringify(cleaned));
        __purgeStats.keys.push(key);
      }
    }catch(e){}
  }
}
purgeDeprecatedTermData(); /* 启动时立即清理一次 */
reconcileGlobalTermsFromBusinessData(); /* 历史模块学期反向补录到“学期设置”，再初始化当前学期。 */
function setCurrentTerm(t){ localStorage.setItem("nnuzc_current_term", t); reloadAfterPendingSaves(); }
/* 【全局约定】所有学期、学年一律倒序（新学期/学年在前）。
   排序同时支持字符串和业务对象；统一使用数值比较，避免浏览器语言环境、导入顺序或编辑保存改变结果。 */
function academicPeriodText(value){
  if(value===null||value===undefined) return "";
  if(typeof value!=="object") return String(value).trim();
  const keys=["term","year","academicYear","schoolYear","label","name"];
  for(let i=0;i<keys.length;i++){
    if(value[keys[i]]!==null&&value[keys[i]]!==undefined&&String(value[keys[i]]).trim()) return String(value[keys[i]]).trim();
  }
  return "";
}
function academicPeriodParts(value){
  const text=academicPeriodText(value), matched=text.match(/(\d{4})\D+(\d{4})(?:\D*([1-9]\d*))?/);
  if(matched) return [Number(matched[1]),Number(matched[2]),Number(matched[3]||0),text];
  const numbers=(text.match(/\d+/g)||[]).map(Number);
  return [numbers[0]||0,numbers[1]||0,numbers[2]||0,text];
}
function compareAcademicPeriodsDesc(a,b){
  const left=academicPeriodParts(a),right=academicPeriodParts(b);
  for(let i=0;i<3;i++){if(left[i]!==right[i]) return right[i]-left[i];}
  return right[3].localeCompare(left[3],"zh-CN",{numeric:true,sensitivity:"base"});
}
function termSortKey(t){ return academicPeriodText(t); }
function sortTermsDesc(list){ return (list || []).slice().sort(compareAcademicPeriodsDesc); }
function sortAcademicYearsDesc(list){ return (list || []).slice().sort(compareAcademicPeriodsDesc); }
function renderTermSelector(){
  const box = $("#termSelBox");
  if(!box) return;
  const week=CURRENT_TERM?currentSemesterWeek(CURRENT_TERM):null;
  box.innerHTML = CURRENT_TERM ? '<strong style="font-size:14px;color:var(--text)">'+esc(CURRENT_TERM)+'</strong><span style="font-size:13.5px;color:'+(week&&week.state==='active'?'var(--primary)':'var(--muted)')+'"> · '+esc(week?week.text:'')+'</span>' : '<span style="color:var(--muted);font-size:14px">未设置（请到学期设置维护）</span>';
  box.title = "请在“系统管理 > 学期设置”中新增、编辑或切换当前学期。";
}
/* ============ 各模块学期查看/选择（统一下拉，仅可选管理员已增加的学期） ============ */
const viewTerm = {};
const viewTermMulti = {};
function termOptionsHTML(sel){
  const list = sortTermsDesc(getTermList());
  return list.length ? list.map(t=>'<option'+(t===sel?' selected':'')+'>'+t+'</option>').join('') : '<option value="">请先增加学期</option>';
}
function termPicker(key){
  const list=sortTermsDesc(getTermList()),selected=Object.prototype.hasOwnProperty.call(viewTermMulti,key)?viewTermMulti[key]:[viewTerm[key]||CURRENT_TERM].filter(Boolean);
  return qfMulti('viewTerms_'+key,[{v:"",l:"全部学期"}].concat(list.map(function(term){return {v:term,l:term};})),selected);
}
function captureViewTerms(key){
  const values=readMulti('viewTerms_'+key);viewTermMulti[key]=values;if(values.length)viewTerm[key]=values[0];return values;
}
function selectedViewTerms(key){
  if(Object.prototype.hasOwnProperty.call(viewTermMulti,key)){const values=qfArr(viewTermMulti[key]);return values.length?values:sortTermsDesc(getTermList());}
  return [viewTerm[key]||CURRENT_TERM].filter(Boolean);
}
function primaryViewTerm(key){return selectedViewTerms(key)[0]||CURRENT_TERM;}
function selectedViewTermsText(key){const values=selectedViewTerms(key);return values.length===1?values[0]:(values.length+" 个学期");}
function selectedViewTermsFileToken(key){const values=selectedViewTerms(key);return values.length===1?values[0].replace(/学期$/,""):"多学期";}
function resetViewTerms(key){viewTermMulti[key]=[CURRENT_TERM].filter(Boolean);viewTerm[key]=CURRENT_TERM;}
function viewTermKeyForPage(page){return page==="dorm_violate"?"dormviolate":page;}

/* ---- 通用筛选：查询/重置按钮驱动（避免一边改一边闪屏） ---- */
const viewFilter = {};
/* 查询状态与筛选条件分离：未点击「查询」时，不展示业务数据。 */
const queryState = {};
const QUERY_REQUIRED_PAGES = ["student","classroom","dorm","meeting","fund","party","punishment","talks","home","events","psych"];
function queryReady(page){ return queryState[page] === true; }
function setQueryReady(page, value){ queryState[page] = value === true; }

/* ---- qfMulti: multi-select dropdown (badge trigger + checkbox panel) ----
   opts: [{v:"", l:"all X"}, {v:"Y", l:"Y"}]
   cur : array of selected values; undefined/null = no selected condition;
         [] = none checked (reset semantics) */
/* 所有筛选项在组件入口按值去重：基础数据、学生台账或外接模块即使重复传值，
   下拉框也只展示第一条，避免多选角标和筛选列表出现重复学院/年级/班级。 */
function qfUniqueOptions(opts){
  const seen = new Set();
  return (opts || []).filter(function(option){
    const value = String(option && option.v != null ? option.v : "").trim();
    if(seen.has(value)) return false;
    seen.add(value);
    return true;
  });
}
function qfMulti(name, opts, cur){
  const options = qfUniqueOptions(opts);
  const items = options.filter(function(o){ return String(o && o.v != null ? o.v : "") !== ""; });
  let sel;
  if(cur === undefined || cur === null){
    /* 未选条件必须始终保持空选；空数组在 qfMatch 中代表「不过滤」。 */
    sel = [];
  } else if(Array.isArray(cur)){
    sel = cur.slice();
  } else if(cur === ""){
    sel = [];
  } else {
    sel = [String(cur)];
  }
  // 空选仍表示不过滤，但触发器必须保留字段名称（如“全部学院”），避免复选改造后只显示“请选择”而丢失查询字段语义。
  const lbl = (options[0] && String(options[0].v) === "") ? options[0].l : ("all " + name);
  const triggerText = lbl;
  const panelId = 'qfmp_' + Math.random().toString(36).slice(2,9);
  const optsHtml = items.length ? items.map(function(o){
    const value=String(o&&o.v!=null?o.v:""),label=String(o&&o.l!=null?o.l:value);
    return '<label class="qf-multi-opt"><input type="checkbox" value="' + escAttr(value) + '"' +
      (sel.indexOf(value) !== -1 ? ' checked' : '') + '> ' + esc(label) + '</label>';
  }).join("") : '<div class="qf-multi-empty">no options</div>';
  return '<div class="qf-multi" data-qf="' + escAttr(name) + '" data-label="' + escAttr(lbl) + '">'
    + '<button type="button" class="qf-multi-trigger" aria-haspopup="true" aria-expanded="false" aria-controls="' + panelId + '">'
      + '<span class="qf-multi-text">' + triggerText + '</span>'
      + '<span class="qf-multi-count" hidden>0</span>'
      + '<span class="qf-multi-caret">&#9662;</span>'
    + '</button>'
    + '<div class="qf-multi-panel" id="' + panelId + '">'
      + optsHtml
    + '</div>'
  + '</div>';
}
function qfMultiRefresh(multi){
  if(!multi) return;
  const checks = multi.querySelectorAll('.qf-multi-opt input[type=checkbox]');
  const total = checks.length;
  let n = 0;
  for(let i = 0; i < checks.length; i++){ if(checks[i].checked) n++; }
  const lbl = multi.dataset.label || (multi.querySelector('.qf-multi-text')||{}).textContent || "";
  const text = multi.querySelector('.qf-multi-text');
  const cnt = multi.querySelector('.qf-multi-count');
  if(!text) return;
  if(["ccDept","ccGrade","ccCls"].indexOf(multi.dataset.qf)>=0){
    text.textContent=n?Array.from(checks).filter(function(c){return c.checked;}).map(function(c){return c.value;}).join("、"):lbl;cnt.hidden=!n;cnt.textContent=n;return;
  }
  if(n === 0 || n === total){
    /* 空选和全选都不参与筛选；两种状态都保留字段名称。 */
    text.textContent = lbl;
    cnt.hidden = true;
  } else {
    text.textContent = lbl + ' · ' + n;
    cnt.hidden = false;
    cnt.textContent = n;
  }
}
// === 顶层 readMulti：所有 qf-multi 工具栏（学生信息、处分子模块、评奖评优编辑弹窗）共用 ===
function readMulti(name){
  const el = document.querySelector(".qf-multi[data-qf='"+name+"']");
  if(!el) return [];
  const vals = [];
  el.querySelectorAll(".qf-multi-opt input[type=checkbox]:checked").forEach(function(c){
    if(c.value !== "") vals.push(c.value);
  });
  return vals;
}
/* qfArr / qfMatch: filter semantics — empty/null = pass all;
   non-empty array = must include(val); also accepts legacy single string */
function qfArr(v){
  if(v === undefined || v === null || v === "") return [];
  if(Array.isArray(v)) return v.slice();
  return [String(v)];
}
function qfMatch(arr, val){
  const a = qfArr(arr);
  return a.length === 0 || a.indexOf(val) !== -1;
}
function qfInput(name,ph,cur,width,ac){
  return '<input class="in" data-qf="'+escAttr(name)+'" placeholder="'+escAttr(ph)+'" aria-label="'+escAttr(ph||name)+'" autocomplete="'+escAttr(ac||"off")+'" value="'+escAttr(cur||"")+'" style="width:'+(Number(width)||170)+'px">';
}

/* ---- qfSingle: single-select dropdown (与 qf-multi 视觉一致，点选项即关) ----
   opts: [{v:"x", l:"全部 x"}]，cur: 默认值
   panel 强制带 max-height + overflow-x/y + 8px 可见滚动条（2026-07-28 铁律）。 */
function qfSingle(name, opts, cur){
  const options = qfUniqueOptions(opts);
  const items = options.filter(function(o){ return String(o && o.v != null ? o.v : "") !== ""; });
  const hasAll = (options[0] && String(options[0].v) === "");
  const allOpt = hasAll ? options[0] : {v:"", l:"全部 " + name};
  const sel = (cur === undefined || cur === null) ? "" : String(cur);
  const panelId = 'qfsp_' + Math.random().toString(36).slice(2,9);
  function optRow(o, idx){
    const isSel = String(o.v) === sel;
    return '<div class="qf-single-opt' + (isSel?' sel':'') + '" role="option" tabindex="-1" id="' + panelId + '_' + idx + '" data-val="' + esc(o.v) + '">' + esc(o.l) + '</div>';
  }
  const optsHtml = (hasAll ? [optRow(allOpt, 0)] : [])
    .concat(items.map(function(o, i){ return optRow(o, (hasAll?1:0) + i); }))
    .join("");
  // trigger 当前显示：选 "" → 显示 allOpt.l；否则显示 items 中匹配项 label
  let dispLbl = allOpt.l;
  if(sel !== ""){
    const m = items.find(function(o){ return String(o.v) === sel; });
    if(m) dispLbl = m.l;
  }
  return '<div class="qf-single" data-qf="' + escAttr(name) + '" data-cur="' + escAttr(sel) + '">'
    + '<button type="button" class="qf-single-trigger" aria-haspopup="listbox" aria-expanded="false" aria-controls="' + panelId + '">'
      + '<span class="qf-single-text">' + esc(dispLbl) + '</span>'
      + '<span class="qf-single-caret">&#9662;</span>'
    + '</button>'
    + '<div class="qf-single-panel" id="' + panelId + '" role="listbox" aria-label="' + esc(name) + '">' + optsHtml + '</div>'
  + '</div>';
}
function qfSingleValue(name){
  const el = document.querySelector(".qf-single[data-qf='"+name+"']");
  if(!el) return "";
  return el.dataset.cur || "";
}
function qfSingleSet(name, val){
  const el = document.querySelector(".qf-single[data-qf='"+name+"']");
  if(!el) return;
  el.dataset.cur = String(val || "");
  // trigger 文字同步
  const opts = el.querySelectorAll('.qf-single-opt');
  const text = el.querySelector('.qf-single-text');
  el.querySelectorAll('.qf-single-opt').forEach(function(o){ o.classList.remove('sel'); });
  let disp = "";
  opts.forEach(function(o){
    if(o.dataset.val === el.dataset.cur){ o.classList.add('sel'); disp = o.textContent; }
  });
  if(!disp) disp = (el.querySelector('.qf-single-opt[data-val=""]')||{}).textContent || "";
  if(text) text.textContent = disp;
}
function qfGet(page){
  const bar = document.querySelector('.qf-bar[data-page="'+page+'"]');
  if(!bar) return {};
  const s = {};
  bar.querySelectorAll('[data-qf]').forEach(function(el){
    if(el.classList && el.classList.contains('qf-multi')){
      const vals = [];
      el.querySelectorAll('.qf-multi-opt input[type=checkbox]:checked').forEach(function(c){
        if(c.value !== "") vals.push(c.value);
      });
      s[el.dataset.qf] = vals;
    } else if(el.classList && el.classList.contains('qf-single')){
      s[el.dataset.qf] = el.dataset.cur || "";
    } else {
      s[el.dataset.qf] = (el.value || "").trim();
    }
  });
  return s;
}
// delegated click: open/close panel, all/clear, click-outside-close
document.addEventListener('click', function(e){
  const multi = (e.target.closest && e.target.closest('.qf-multi'));
  const sg    = (e.target.closest && e.target.closest('.qf-single'));
  // outside click → close all
  if(!multi && !sg){
    document.querySelectorAll('.qf-multi.open, .qf-single.open').forEach(function(m){
      m.classList.remove('open');
      const tr = m.querySelector('.qf-single-trigger, .qf-multi-trigger');
      if(tr) tr.setAttribute('aria-expanded','false');
    });
    return;
  }
  // 单选点 trigger
  if(sg && e.target.closest('.qf-single-trigger')){
    document.querySelectorAll('.qf-single.open').forEach(function(m){ if(m !== sg) m.classList.remove('open'); });
    document.querySelectorAll('.qf-multi.open').forEach(function(m){ m.classList.remove('open'); });
    sg.classList.toggle('open');
    const tr = sg.querySelector('.qf-single-trigger');
    if(tr) tr.setAttribute('aria-expanded', sg.classList.contains('open') ? 'true' : 'false');
    return;
  }
  // 单选点 option
  if(sg && e.target.closest('.qf-single-opt')){
    const opt = e.target.closest('.qf-single-opt');
    sg.dataset.cur = opt.dataset.val || "";
    sg.querySelectorAll('.qf-single-opt').forEach(function(o){ o.classList.remove('sel'); });
    opt.classList.add('sel');
    const text = sg.querySelector('.qf-single-text');
    if(text) text.textContent = opt.textContent;
    sg.classList.remove('open');
    const tr = sg.querySelector('.qf-single-trigger');
    if(tr) tr.setAttribute('aria-expanded','false');
    // 单选改变即时刷新页面（如 term 下拉）或 fire 自定义事件，便于外部监听
    sg.dispatchEvent(new CustomEvent('qfSingle:change', { bubbles: true, detail: { name: sg.dataset.qf, value: sg.dataset.cur } }));
    return;
  }
  // 关闭其它 qf-multi（单选打开时关闭多选）
  if(multi && e.target.closest('.qf-multi-trigger')){
    document.querySelectorAll('.qf-multi.open').forEach(function(m){ if(m !== multi) m.classList.remove('open'); });
    document.querySelectorAll('.qf-single.open').forEach(function(m){ m.classList.remove('open'); });
    multi.classList.toggle('open');
    if(multi.classList.contains('open')) qfMultiRefresh(multi);
    const tr = multi.querySelector('.qf-multi-trigger');
    if(tr) tr.setAttribute('aria-expanded', multi.classList.contains('open') ? 'true' : 'false');
    return;
  }
  if(multi && e.target.matches && e.target.matches('.qf-multi-opt input[type=checkbox]')){
    qfMultiRefresh(multi);
    return;
  }
});
/* 键盘可达：qf-single / qf-multi 下拉（方向键导航 + Enter 选中 + Esc 关闭，WCAG 2.1.1） */
document.addEventListener('keydown', function(e){
  const k = e.key;
  // qf-single（listbox 单选）
  const sg = e.target.closest && e.target.closest('.qf-single');
  if(sg){
    const trigger = sg.querySelector('.qf-single-trigger');
    const panel = sg.querySelector('.qf-single-panel');
    const opts = Array.prototype.slice.call(sg.querySelectorAll('.qf-single-opt'));
    if(e.target === trigger){
      if(k==='ArrowDown' || k==='Enter' || k===' '){
        e.preventDefault();
        if(!sg.classList.contains('open')){ sg.classList.add('open'); trigger.setAttribute('aria-expanded','true'); }
        const cur = opts.filter(function(o){ return o.classList.contains('sel'); })[0] || opts[0];
        if(cur) cur.focus();
      }
      return;
    }
    if(panel && panel.contains(e.target) && opts.indexOf(e.target) >= 0){
      if(k==='ArrowDown'){ e.preventDefault(); const i=opts.indexOf(e.target); (opts[i+1]||opts[0]).focus(); }
      else if(k==='ArrowUp'){ e.preventDefault(); const i=opts.indexOf(e.target); (opts[i-1]||opts[opts.length-1]).focus(); }
      else if(k==='Home'){ e.preventDefault(); if(opts[0]) opts[0].focus(); }
      else if(k==='End'){ e.preventDefault(); if(opts[opts.length-1]) opts[opts.length-1].focus(); }
      else if(k==='Enter' || k===' '){ e.preventDefault(); e.target.click(); }
      else if(k==='Escape'){ e.preventDefault(); sg.classList.remove('open'); trigger.setAttribute('aria-expanded','false'); trigger.focus(); }
      return;
    }
  }
  // qf-multi（checkbox 多选）
  const multi = e.target.closest && e.target.closest('.qf-multi');
  if(multi){
    const trigger = multi.querySelector('.qf-multi-trigger');
    const panel = multi.querySelector('.qf-multi-panel');
    const boxes = Array.prototype.slice.call(multi.querySelectorAll('.qf-multi-opt input[type=checkbox]'));
    if(e.target === trigger){
      if(k==='ArrowDown' || k==='Enter' || k===' '){
        e.preventDefault();
        if(!multi.classList.contains('open')){ multi.classList.add('open'); trigger.setAttribute('aria-expanded','true'); qfMultiRefresh(multi); }
        if(boxes[0]) boxes[0].focus();
      }
      return;
    }
    if(panel && panel.contains(e.target) && boxes.indexOf(e.target) >= 0){
      if(k==='ArrowDown'){ e.preventDefault(); const i=boxes.indexOf(e.target); (boxes[i+1]||boxes[0]).focus(); }
      else if(k==='ArrowUp'){ e.preventDefault(); const i=boxes.indexOf(e.target); (boxes[i-1]||boxes[boxes.length-1]).focus(); }
      else if(k==='Escape'){ e.preventDefault(); multi.classList.remove('open'); trigger.setAttribute('aria-expanded','false'); trigger.focus(); }
      return;
    }
  }
});
/* 学期筛选/查看下拉统一路由（qfSingle 替代原生 select，带浮层 + 横竖滚动条） */
document.addEventListener('qfSingle:change', function(e){
  const name = e.detail.name, val = e.detail.value;
  if(name === 'academicViewTerm') academicSwitchViewTerm(val);
  else if(name === 'academicWarningViewTerm') academicWarningSwitchViewTerm(val);
  else if(name === 'gradeViewTerm') gradeSwitchViewTerm(val);
  else if(name === 'fundViewTerm'){ const ft = fundTermById(parseInt(val, 10)); if(ft) openEditFundTerm(ft.id); }
  else if(name === 'topTerm'){
    const cfm = $("#confirmTermBtn");
    if(cfm) cfm.style.display = val !== CURRENT_TERM ? '' : 'none';
  }
});
function renderPage(page){
  const p = PAGES[page] ? page : currentView;
  const c=$("#content");
  if(c && PAGES[p]) c.innerHTML = PAGES[p]();
  if(PAGES[p+"_init"]) PAGES[p+"_init"]();
  /* v1.42：页面渲染完成后立即执行一次级联收敛，确保 dept/major/grade/cls 严格按包含关系呈现 */
  if(c && typeof cascadeApplyAll === 'function') cascadeApplyAll(c);
  if(typeof taskUpdateBadge === 'function')taskUpdateBadge();
}
function queryFilter(page){
  viewFilter[page] = qfGet(page);
  // 手动查询发展阶段时，以新选择的阶段替代卡片分类，避免冲突条件使名单为空。
  if(page==="party" && viewFilter[page].category && Array.isArray(viewFilter[page].stage) && viewFilter[page].stage.length) viewFilter[page].category="";
  const termKey=viewTermKeyForPage(page);
  if(document.querySelector('.qf-multi[data-qf="viewTerms_'+termKey+'"]'))captureViewTerms(termKey);
  setQueryReady(page,true);
  if(page.indexOf("dorm_")===0) setQueryReady("dorm",true);
  renderPage(page);
}
function resetFilter(page){
  // v1.67：学生画像默认只查「在校生」，重置后也回到该默认值；党团员发展同理默认在校生。
  if(page==="portrait" || page==="party"){
    viewFilter[page]={status:["在校"]};
  } else {
    viewFilter[page]={};
  }
  setQueryReady(page,false);
  if(page.indexOf("dorm_")===0) setQueryReady("dorm",false);
  const termKey=viewTermKeyForPage(page);
  if(document.querySelector('.qf-multi[data-qf="viewTerms_'+termKey+'"]')||Object.prototype.hasOwnProperty.call(viewTermMulti,termKey))resetViewTerms(termKey);
  renderPage(page);
  // 重置后清空多选框的勾选（与学生模块 stuReset 行为一致）：
  // viewFilter 已清空 → qfGet 读到的即空数组（=不过滤=恢复全部），
  // 但 qfMulti 在 cur=undefined 时默认全选，故需手动把 DOM 复选框取消勾选。
  // 学生画像的 status 默认值已在 renderPage 中重新渲染，此处不再清空。
  if(page!=="portrait" && page!=="party"){
    document.querySelectorAll('.qf-bar[data-page="'+page+'"] .qf-multi').forEach(function(m){
      m.querySelectorAll('.qf-multi-opt input[type=checkbox]').forEach(function(c){ c.checked = false; });
      if(typeof qfMultiRefresh === "function") qfMultiRefresh(m);
    });
  }
  /* v1.42：重置后再次执行级联，确保面板恢复到全可见状态 */
  if(typeof cascadeApplyAll === 'function'){
    document.querySelectorAll('.qf-bar[data-page="'+page+'"]').forEach(function(bar){ cascadeApply(bar); });
  }
}
/* ====== v1.53：单选(qf-single)筛选读取/重置 + 级联（供 谈心谈话/家校联系/心理预警 复用） ======
   读取/重置与系统标准 qfGet 对齐，但正确兼容 qf-single（div + data-cur）；
   级联沿用 v1.42 的 cascadeRowData / cascadeRowPasses / cascadeVisibleSet，
   将「包含/被包含」关系应用到单选下拉：选学院→专业/年级/班级收敛，失效项自动隐藏并清空已选 */
function barFilterGet(bar){
  if(!bar) return {};
  const s = {};
  bar.querySelectorAll('[data-qf]').forEach(function(el){
    const key = el.dataset.qf; if(!key) return;
    if(el.classList && el.classList.contains('qf-multi')){
      const vals=[]; el.querySelectorAll('.qf-multi-opt input[type=checkbox]:checked').forEach(function(c){ if(c.value!=='') vals.push(c.value); }); s[key]=vals;
    } else if(el.classList && el.classList.contains('qf-single')){
      s[key] = el.dataset.cur || "";
    } else {
      s[key] = (el.value || "").trim();
    }
  });
  return s;
}
function barFilterReset(bar){
  if(!bar) return;
  bar.querySelectorAll('[data-qf]').forEach(function(el){
    if(el.classList && el.classList.contains('qf-multi')){
      el.querySelectorAll('.qf-multi-opt input[type=checkbox]').forEach(function(c){ c.checked=false; });
      if(typeof qfMultiRefresh==='function') qfMultiRefresh(el);
    } else if(el.classList && el.classList.contains('qf-single')){
      qfSingleSet(el.dataset.qf, "");
    } else {
      el.value = "";
    }
  });
  if(typeof cascadeApplyAll==='function') cascadeApplyAll(bar);
  if(typeof cascadeSingle==='function') cascadeSingle(bar);
}
function cascadeSingle(bar){
  if(!bar) return;
  const getv=function(n){ const el=bar.querySelector(".qf-single[data-qf='"+n+"']"); return el?(el.dataset.cur||""):""; };
  ['major','grade','cls'].forEach(function(f){
    const el=bar.querySelector(".qf-single[data-qf='"+f+"']"); if(!el) return;
    const ctx={ dept:getv('dept')?[getv('dept')]:[], major:getv('major')?[getv('major')]:[], grade:getv('grade')?[getv('grade')]:[] };
    const visible=cascadeVisibleSet(f,ctx);
    const cur=el.dataset.cur||"";
    el.querySelectorAll('.qf-single-opt').forEach(function(opt){
      const v=(opt.dataset&&opt.dataset.val)||"";
      opt.style.display = (visible && !visible.has(v)) ? 'none' : '';
    });
    if(cur && visible && !visible.has(cur)) qfSingleSet(f,"");
  });
}
document.addEventListener('qfSingle:change', function(e){
  const sg = e.target.closest && e.target.closest('.qf-single'); if(!sg) return;
  if(CASCADE_FIELDS.indexOf(sg.dataset.qf)===-1) return;
  const bar = sg.closest('.qf-bar, .ae-bar, .filter-bar, .zf-query, .academic-edit');
  if(bar) cascadeSingle(bar);
});

function qfBtns(page){
  return '<button class="btn btn-primary btn-sm" onclick="queryFilter(\''+page+'\')">查询</button><button class="btn btn-ghost btn-sm" onclick="resetFilter(\''+page+'\')">重置</button>';
}
/* ====== v1.42 学院/专业/班级/年级筛选级联（包含与被包含） ======
   数据源优先级：ORG_DEPTS / ORG_MAJORS / ORG_CLASSES（v1.38 基础数据维护）→ 回退 students 派生
   级联规则：
   - 学院：顶级，不受其他字段限制
   - 专业：受「学院」限制（受控于学院的多选集合）
   - 年级：受「学院 + 专业」限制
   - 班级：受「学院 + 专业 + 年级」三层限制
   联动方向（自上而下收敛）：
   - 改变学院 → 专业 / 年级 / 班级 面板收缩到该学院下；失效选项自动清勾
   - 改变专业 → 年级 / 班级 面板收缩到该专业下；失效选项自动清勾
   - 改变年级 → 班级 面板收缩到该年级下；失效选项自动清勾
   - 改变班级 → 不触发上级收敛
   触发时机：① 任意 cascade 字段的 qf-multi 勾选变化；② 页面渲染完成后；③ 重置筛选后 */
const CASCADE_FIELDS = ['dept','major','grade','cls'];
function cascadeRowData(field){
  // 返回 [{name, dept, major, grade}] 列表供级联过滤
  if(field === 'dept') return [];
  if(field === 'major'){
    if(ORG_MAJORS.length){
      return ORG_MAJORS.map(function(m){ return {dept:m.dept||'', major:'', grade:'', name:m.name}; });
    }
    return (students||[]).map(function(s){ return {dept:s.dept||'', major:'', grade:'', name:s.major}; });
  }
  if(field === 'grade'){
    if(ORG_CLASSES.length){
      return ORG_CLASSES.map(function(c){ return {dept:c.dept||'', major:c.major||'', grade:c.grade||'', name:c.grade}; });
    }
    return (students||[]).map(function(s){ return {dept:s.dept||'', major:s.major||'', grade:(typeof classGrade==='function'?classGrade(s.cls):''), name:(typeof classGrade==='function'?classGrade(s.cls):'')}; });
  }
  if(field === 'cls'){
    if(ORG_CLASSES.length){
      return ORG_CLASSES.map(function(c){ return {dept:c.dept||'', major:c.major||'', grade:c.grade||'', name:c.name}; });
  }
    return (students||[]).map(function(s){ return {dept:s.dept||'', major:s.major||'', grade:(typeof classGrade==='function'?classGrade(s.cls):''), name:s.cls}; });
  }
  return [];
}
function cascadeRowPasses(field, row, ctx){
  /* row: {dept,major,grade,name}；ctx: {dept:[...],major:[...],grade:[...]}；cls 不参与过滤自身 */
  if(field === 'dept') return true;
  if(field === 'major'){
    if(!ctx.dept.length) return true;
    return ctx.dept.indexOf(row.dept) !== -1;
  }
  if(field === 'grade'){
    if(ctx.dept.length && row.dept && ctx.dept.indexOf(row.dept) === -1) return false;
    if(ctx.major.length && row.major && ctx.major.indexOf(row.major) === -1) return false;
    return true;
  }
  if(field === 'cls'){
    if(ctx.dept.length && row.dept && ctx.dept.indexOf(row.dept) === -1) return false;
    if(ctx.major.length && row.major && ctx.major.indexOf(row.major) === -1) return false;
    if(ctx.grade.length && row.grade && ctx.grade.indexOf(row.grade) === -1) return false;
    return true;
  }
  return true;
}
function cascadeVisibleSet(field, ctx){
  var rows = cascadeRowData(field);
  if(!rows.length) return null;
  var set = new Set();
  rows.forEach(function(r){
    if(r.name && cascadeRowPasses(field, r, ctx)) set.add(r.name);
  });
  return set;
}
function cascadePickEls(scope){
  /* 在 scope 内挑出 4 个 qf-multi 元素；不存在的字段直接返回 null */
  var root = scope || document;
  var pick = function(name){ return root.querySelector ? root.querySelector(".qf-multi[data-qf='"+name+"']") : null; };
  return { dept: pick('dept'), major: pick('major'), grade: pick('grade'), cls: pick('cls'), scopeRoot: root };
}
function cascadeApply(scopeOrEls){
  /* scopeOrEls: HTMLElement(含 .qf-bar/.ae-bar/.qitem) 或 上一步 cascadePickEls 的结果 */
  var els = (scopeOrEls && scopeOrEls.scopeRoot) ? scopeOrEls : cascadePickEls(scopeOrEls);
  if(!els || (!els.dept && !els.major && !els.grade && !els.cls)) return;
  /* 防止递归：cascade 内部取消勾选会派发 change 事件，再次进入 cascadeApply */
  var root = (els.scopeRoot && els.scopeRoot.nodeType===1) ? els.scopeRoot : (els.dept ? els.dept.closest('.qf-bar,.ae-bar,.zf-query,.academic-edit,.filter-bar') : null);
  if(root && root.dataset && root.dataset.cascading === '1') return;
  if(root && root.dataset) root.dataset.cascading = '1';
  try{
    var getVals = function(m){
      if(!m) return [];
      return Array.prototype.slice.call(m.querySelectorAll('.qf-multi-opt input[type=checkbox]:checked')).map(function(c){return c.value;}).filter(Boolean);
    };
    CASCADE_FIELDS.forEach(function(f){
      var m = els[f]; if(!m) return;
      /* 每一层都读取当前勾选状态：上层变更清除失效项后，下层立即按新状态收敛。 */
      var ctx = { dept:getVals(els.dept), major:getVals(els.major), grade:getVals(els.grade) };
      var visible = cascadeVisibleSet(f, ctx);
      m.querySelectorAll('.qf-multi-opt').forEach(function(optEl){
        var cb = optEl.querySelector('input[type=checkbox]');
        if(!cb) return;
        var v = cb.value;
        var hide = (visible && !visible.has(v));
        optEl.style.display = hide ? 'none' : '';
        if(hide && cb.checked) cb.checked = false;
      });
      if(typeof qfMultiRefresh === 'function') qfMultiRefresh(m);
    });
  }finally{
    if(root && root.dataset) root.dataset.cascading = '';
  }
}
function cascadeApplyAll(root){
  /* 对 root 下所有级联筛选组执行一次 cascadeApply；学生管理的 .zf-query 是一整组。 */
  if(!root) root = document.body;
  /* 1) 处理显式工具栏容器 */
  var seen = new Set();
  root.querySelectorAll && root.querySelectorAll('.qf-bar, .ae-bar, .filter-bar, .zf-query, .academic-edit').forEach(function(scope){
    if(seen.has(scope)) return;
    cascadeApply(scope);
    seen.add(scope);
  });
  /* 2) 处理未包含在以上容器中的悬浮 qf-multi（如 stuAdd dormAdd 等弹窗）；
        把所有未归属的 dept+cls 找最近的公共祖先处理 */
  var loose = [];
  root.querySelectorAll && root.querySelectorAll('.qf-multi[data-qf="dept"], .qf-multi[data-qf="cls"], .qf-multi[data-qf="major"], .qf-multi[data-qf="grade"]').forEach(function(m){
    var owner = m.closest('.qf-bar, .ae-bar, .filter-bar, .zf-query, .academic-edit');
    if(owner){ if(!seen.has(owner)){ seen.add(owner); cascadeApply(owner); } }
    else { loose.push(m); }
  });
  if(loose.length){
    /* 把同 modal 内的 loose 元素归为一组 */
    var groups = new Map();
    loose.forEach(function(m){
      var modal = m.closest('.modal, #modal, .drawer, #drawer, .stu-modal, .zf-form, body');
      var key = modal || document.body;
      if(!groups.has(key)) groups.set(key, []);
      groups.get(key).push(m);
    });
    groups.forEach(function(arr, owner){
      var fake = { dept:null, major:null, grade:null, cls:null, scopeRoot: owner };
      arr.forEach(function(m){
        if(m.dataset && m.dataset.qf && CASCADE_FIELDS.indexOf(m.dataset.qf)!==-1) fake[m.dataset.qf]=m;
      });
      cascadeApply(fake);
    });
  }
}
/* 触发：qf-multi 勾选变化 → 向上找最近的级联容器（document.body 兜底）→ cascadeApply */
document.addEventListener('change', function(e){
  var t = e.target; if(!t || t.type !== 'checkbox') return;
  var opt = t.closest && t.closest('.qf-multi-opt'); if(!opt) return;
  var multi = opt.closest && opt.closest('.qf-multi'); if(!multi) return;
  var name = multi.dataset && multi.dataset.qf;
  if(!name || CASCADE_FIELDS.indexOf(name) === -1) return;
  var owner = multi.closest('.qf-bar, .ae-bar, .filter-bar, .zf-query, .academic-edit, #modal, .modal, #drawer, .drawer, .zf-form, body') || document.body;
  cascadeApply(owner);
});
function stuFilterByState(list,state){
  if(!state) return list;
  return list.filter(function(s){
    if(state.kw && !(s.id.includes(state.kw) || s.name.includes(state.kw))) return false;
    if(!qfMatch(state.dept, s.dept)) return false;
    if(!qfMatch(state.major, s.major)) return false;
    if(!qfMatch(state.grade, s.grade)) return false;
    if(!qfMatch(state.cls, s.cls)) return false;
    if(!qfMatch(state.status, s.status)) return false;
    return true;
  });
}
