/* v1.38：基础数据维护（学院/专业/班级）权威来源 + 关联筛选数组 */
const ORG_KEY="nnuzc_orgs";
const ORG_DEPTS=[];
const ORG_MAJORS=[];
const ORG_CLASSES=[];
const ORG_GRADES=[]; /* v1.50：年级独立维护 */
const ORG_ENROLL_TYPES=[]; /* 招生类别独立维护（参照年级；用于班级/学生招生类别下拉） */
const ORG_DORMS=[]; /* 兼容影子：新版以公寓资源为唯一权威来源；此数组仅保留给旧版本回滚和旧备份迁移。 */
const depts=[];

/* 全局排序规则：学院按学院代码；专业按专业代码；年级按所属班级前 6 位；学生按所属组织层级后按学号。 */
const WORKBENCH_COLLATOR=new Intl.Collator("zh-CN",{numeric:true,sensitivity:"base"});
function compareWorkbenchText(a,b){ return WORKBENCH_COLLATOR.compare(String(a||""),String(b||"")); }
function compareWorkbenchCode(a,b){
  const left=String(a||""), right=String(b||"");
  const ln=/^\d+$/.test(left), rn=/^\d+$/.test(right);
  if(ln&&rn){ const d=Number(left)-Number(right); if(d) return d; }
  return compareWorkbenchText(left,right);
}
function deptCodeOf(name){ const item=ORG_DEPTS.find(function(x){return x.name===name;}); return item?item.code:""; }
function majorCodeOf(name){ const item=ORG_MAJORS.find(function(x){return x.name===name;}); return item?item.code:""; }
function classPrefixOf(value){ return String(value&&value.name!==undefined?value.name:value||"").slice(0,6); }
function gradeOrderKey(grade){
  const found=ORG_CLASSES.filter(function(c){return c.grade===grade;}).map(classPrefixOf).sort(compareWorkbenchCode)[0];
  return found||String(grade||"").slice(0,6);
}
function compareStudentsByOrg(a,b){
  return compareWorkbenchCode(deptCodeOf(a.dept),deptCodeOf(b.dept))
    || compareWorkbenchText(a.dept,b.dept)
    || compareWorkbenchCode(majorCodeOf(a.major),majorCodeOf(b.major))
    || compareWorkbenchText(a.major,b.major)
    || compareWorkbenchCode(classPrefixOf(a.cls),classPrefixOf(b.cls))
    || compareWorkbenchText(a.cls,b.cls)
    || compareWorkbenchCode(a.id,b.id);
}
function sortWorkbenchCollections(){
  ORG_DEPTS.sort(function(a,b){return compareWorkbenchCode(a.code,b.code)||compareWorkbenchText(a.name,b.name);});
  ORG_MAJORS.sort(function(a,b){return compareWorkbenchCode(deptCodeOf(a.dept),deptCodeOf(b.dept))||compareWorkbenchCode(a.code,b.code)||compareWorkbenchText(a.name,b.name);});
  ORG_CLASSES.sort(function(a,b){return compareWorkbenchCode(deptCodeOf(a.dept),deptCodeOf(b.dept))||compareWorkbenchCode(majorCodeOf(a.major),majorCodeOf(b.major))||compareWorkbenchCode(classPrefixOf(a),classPrefixOf(b))||compareWorkbenchText(a.name,b.name);});
  ORG_GRADES.sort(function(a,b){return compareWorkbenchCode(a.name,b.name);});
  ORG_DORMS.sort(function(a,b){return compareWorkbenchText(a.zone||"",b.zone||"")||compareWorkbenchText(a.building||"",b.building||"");});
  ORG_ENROLL_TYPES.sort(function(a,b){return compareWorkbenchText(a.name||"",b.name||"");});
  if(Array.isArray(students)) students.sort(compareStudentsByOrg);
}

