    const nodes=Array.from(layer.querySelectorAll('button:not([disabled]),input:not([disabled])')),first=nodes[0],last=nodes[nodes.length-1];
    if(event.shiftKey&&document.activeElement===first){event.preventDefault();last.focus();}
