// 业务日期和界面时间统一按北京时间（UTC+08:00）计算；数据库仍以 ISO/UTC 保存绝对时间。
const SYSTEM_TIME_ZONE="Asia/Shanghai";
function beijingTimeParts(value){
  const parts=new Intl.DateTimeFormat("en-CA",{timeZone:SYSTEM_TIME_ZONE,year:"numeric",month:"2-digit",day:"2-digit",hour:"2-digit",minute:"2-digit",second:"2-digit",hourCycle:"h23"}).formatToParts(new Date(value));
  return parts.reduce(function(result,part){if(part.type!=="literal")result[part.type]=part.value;return result;},{});
}
function beijingIsoDate(value){const p=beijingTimeParts(value==null?Date.now():value);return p.year+"-"+p.month+"-"+p.day;}
function beijingDateTime(value,withSeconds){const p=beijingTimeParts(value==null?Date.now():value);return p.year+"-"+p.month+"-"+p.day+" "+p.hour+":"+p.minute+(withSeconds?":"+p.second:"");}
function beijingLocaleDate(value){return new Intl.DateTimeFormat("zh-CN",{timeZone:SYSTEM_TIME_ZONE,year:"numeric",month:"2-digit",day:"2-digit"}).format(new Date(value==null?Date.now():value));}
function beijingLocaleDateTime(value){return new Intl.DateTimeFormat("zh-CN",{timeZone:SYSTEM_TIME_ZONE,year:"numeric",month:"2-digit",day:"2-digit",hour:"2-digit",minute:"2-digit",second:"2-digit",hourCycle:"h23"}).format(new Date(value==null?Date.now():value));}
window.beijingIsoDate=beijingIsoDate;
window.beijingLocaleDate=beijingLocaleDate;
window.beijingLocaleDateTime=beijingLocaleDateTime;
function fmtNow(){return beijingDateTime(Date.now());}
