const NAV_VISIBILITY_KEY="nnuzc_nav_visibility_v1";
const NAV_VISIBILITY_REQUIRED=new Set(["navCustomize"]);
let navHiddenViews=new Set();
function loadNavVisibility(){
  try{
    const saved=JSON.parse(localStorage.getItem(NAV_VISIBILITY_KEY)||"{}");
    const hidden=Array.isArray(saved)?saved:(Array.isArray(saved.hiddenViews)?saved.hiddenViews:[]);
    navHiddenViews=new Set(hidden.map(function(view){return String(view||"").trim();}).filter(function(view){return view&&VIEWS[view]&&!NAV_VISIBILITY_REQUIRED.has(view);}));
  }catch(_error){navHiddenViews=new Set();}
}
function navMenuIsVisible(view){return !view||NAV_VISIBILITY_REQUIRED.has(view)||!navHiddenViews.has(view);}
async function saveNavVisibility(){
  localStorage.setItem(NAV_VISIBILITY_KEY,JSON.stringify({version:1,hiddenViews:Array.from(navHiddenViews)}));
  try{
    const legacy=window.workbench&&window.workbench.legacy;
    if(legacy&&typeof legacy.flushStore==="function")await legacy.flushStore();
    return true;
  }catch(_error){return false;}
}
function navCustomizationCatalog(){
  const groups=[];
  $$("#nav .nav-group").forEach(function(group){
    const items=[];
    navGroupMembers(group).forEach(function(node){
      const candidates=[];
      if(node.matches&&node.matches(".nav-item[data-view],.nav-sub-item[data-view]"))candidates.push(node);
      if(node.querySelectorAll)candidates.push.apply(candidates,node.querySelectorAll(".nav-item[data-view],.nav-sub-item[data-view]"));
      candidates.forEach(function(item){
        const view=String(item.dataset.view||"").trim();
        if(!view||items.some(function(row){return row.view===view;}))return;
        const icon=(item.querySelector(".ic")||{}).textContent||"•";
        const label=Array.from(item.children||[]).filter(function(child){return child.tagName==="SPAN"&&!child.classList.contains("ic");}).map(function(child){return child.textContent.trim();}).join(" ")||VIEWS[view]||view;
        items.push({view:view,label:label,icon:String(icon).trim()||"•",required:NAV_VISIBILITY_REQUIRED.has(view)});
      });
    });
    if(items.length)groups.push({name:navGroupName(group),items:items});
  });
  return groups;
}
function navVisibilitySummary(){
  const items=navCustomizationCatalog().reduce(function(all,group){return all.concat(group.items);},[]);
  const visible=items.filter(function(item){return navMenuIsVisible(item.view);}).length;
  return {total:items.length,visible:visible,hidden:items.length-visible};
}
function updateNavVisibilitySummary(){
  const el=document.getElementById("navCustomizeSummary");if(!el)return;
  const summary=navVisibilitySummary();
  el.textContent="当前显示 "+summary.visible+" 项，隐藏 "+summary.hidden+" 项，共 "+summary.total+" 项二级菜单。";
}
