/* ============ 渲染 ============ */
function renderNav(){
  filterNav(document.getElementById("navSearch")?document.getElementById("navSearch").value:"");
  const version=document.getElementById("sideVersion");if(version)version.textContent=workbenchBrandName()+"工作台 "+SYS_VER;
}
function filterNav(value){
  const query=String(value||"").trim().toLowerCase();
  $$(".nav-item, .nav-sub-item").forEach(function(item){
    const match=navMenuIsVisible(item.dataset.view)&&(!query||item.textContent.toLowerCase().includes(query));
    item.classList.toggle("hidden",!match);
  });
  $$("#nav .nav-group").forEach(function(group){
    let node=group.nextElementSibling,visible=false;
    while(node&&!node.classList.contains("nav-group")){if((node.classList.contains("nav-item")||node.classList.contains("nav-sub-item"))&&!node.classList.contains("hidden")){visible=true;break;}node=node.nextElementSibling;}
    group.style.display=visible?"":"none";
  });
}
const RETIRED_NAV_GROUP_STATE_KEY="xc_nav_groups_collapsed_v2";
function navGroupName(group){return String(group&&group.textContent||"").trim();}
function navGroupMembers(group){
  const members=[];let node=group&&group.nextElementSibling;
  while(node&&!node.classList.contains("nav-group")){members.push(node);node=node.nextElementSibling;}
  return members;
}
function setNavGroupCollapsed(group,collapsed){
  if(!group)return;
  const isCollapsed=!!collapsed;
  group.classList.toggle("collapsed",isCollapsed);
  group.setAttribute("aria-expanded",isCollapsed?"false":"true");
  navGroupMembers(group).forEach(function(node){node.classList.toggle("nav-group-fold-hidden",isCollapsed);});
}
function navGroupForItem(item){
  if(!item)return null;
  let node=item.closest&&item.closest(".nav-sub");
  if(!node)node=item;
  node=node.previousElementSibling;
  while(node&&!node.classList.contains("nav-group"))node=node.previousElementSibling;
  return node;
}
function expandNavGroupForItem(item){
  const group=navGroupForItem(item);
  if(group&&group.classList.contains("collapsed"))setNavGroupCollapsed(group,false);
}
function initNavGroups(){
  /* 功能分组每次进入或刷新都默认收起；清理旧版本保存的展开/收起状态。 */
  try{localStorage.removeItem(RETIRED_NAV_GROUP_STATE_KEY);}catch(e){}
  $$("#nav .nav-group").forEach(function(group){
    group.setAttribute("role","button");
    group.tabIndex=0;
    group.title="点击展开/收起";
    setNavGroupCollapsed(group,true);
    group.addEventListener("click",function(){setNavGroupCollapsed(group,!group.classList.contains("collapsed"));});
    group.addEventListener("keydown",function(event){if(event.key==="Enter"||event.key===" "){event.preventDefault();group.click();}});
  });
}
const NAV_DRAWER_STATE_KEY="xc_nav_drawer_closed";
const navDrawerMedia=window.matchMedia("(max-width: 900px)");
function isNavDrawerOpen(){
  return navDrawerMedia.matches
    ? document.body.classList.contains("nav-drawer-mobile-open")
    : !document.body.classList.contains("nav-drawer-closed");
}
function syncNavDrawerA11y(){
  const open=isNavDrawerOpen();
  const drawer=document.getElementById("navDrawer");
  const toggle=document.getElementById("navToggle");
  const close=document.getElementById("navClose");
  if(toggle){
    toggle.setAttribute("aria-expanded",open?"true":"false");
    toggle.setAttribute("aria-label",open?"收起导航栏":"展开导航栏");
  }
  if(close) close.setAttribute("aria-label","收起导航栏");
  if(drawer){
    drawer.setAttribute("aria-hidden",open?"false":"true");
    if(open) drawer.removeAttribute("inert");
    else drawer.setAttribute("inert","");
  }
}
function setNavDrawerOpen(open,options){
  const opts=options||{};
  if(navDrawerMedia.matches){
    document.body.classList.toggle("nav-drawer-mobile-open",!!open);
  }else{
    document.body.classList.remove("nav-drawer-mobile-open");
    document.body.classList.toggle("nav-drawer-closed",!open);
    if(opts.persist!==false){
      try{localStorage.setItem(NAV_DRAWER_STATE_KEY,open?"0":"1");}catch(e){}
    }
  }
  syncNavDrawerA11y();
  if(open&&opts.focusSearch){
    setTimeout(function(){const search=document.getElementById("navSearch");if(search){search.focus();search.select();}},260);
  }else if(!open&&opts.restoreFocus){
    const toggle=document.getElementById("navToggle");if(toggle)toggle.focus();
  }
  setTimeout(function(){window.dispatchEvent(new Event("resize"));},260);
}
function initNavDrawer(){
  let desktopClosed=false;
  try{desktopClosed=localStorage.getItem(NAV_DRAWER_STATE_KEY)==="1";}catch(e){}
  document.body.classList.toggle("nav-drawer-closed",desktopClosed);
  const toggle=document.getElementById("navToggle");
  const close=document.getElementById("navClose");
  const backdrop=document.getElementById("navBackdrop");
  if(toggle)toggle.addEventListener("click",function(){setNavDrawerOpen(!isNavDrawerOpen(),{focusSearch:navDrawerMedia.matches});});
  if(close)close.addEventListener("click",function(){setNavDrawerOpen(false,{restoreFocus:true});});
  if(backdrop)backdrop.addEventListener("click",function(){setNavDrawerOpen(false,{restoreFocus:true});});
  const onBreakpointChange=function(){document.body.classList.remove("nav-drawer-mobile-open");syncNavDrawerA11y();};
  if(navDrawerMedia.addEventListener)navDrawerMedia.addEventListener("change",onBreakpointChange);
  else navDrawerMedia.addListener(onBreakpointChange);
  syncNavDrawerA11y();
}
document.getElementById("navSearch")?.addEventListener("input",function(){filterNav(this.value);});
$$(".nav-item, .nav-sub-item").forEach(function(item){item.setAttribute("role","button");item.tabIndex=0;item.addEventListener("keydown",function(event){if(event.key==="Enter"||event.key===" "){event.preventDefault();item.click();}});});
document.addEventListener("keydown",function(event){
  const search=document.getElementById("navSearch");if(!search)return;
  if((event.ctrlKey||event.metaKey)&&event.key.toLowerCase()==="k"){
    event.preventDefault();
    if(!isNavDrawerOpen())setNavDrawerOpen(true,{focusSearch:true});
    else{search.focus();search.select();}
  }else if(event.key==="Escape"){
    if(document.activeElement===search&&search.value){search.value="";filterNav("");}
    else if(isNavDrawerOpen()){event.preventDefault();setNavDrawerOpen(false,{restoreFocus:true});}
  }
});
function renderTop(){
  renderTermSelector();
}
let currentView='dashboard';
/* 浏览器式模块标签：仅保存当前会话的界面状态，不读写业务数据。 */
let openModuleTabs=['dashboard'];
function renderModuleTabs(){
  const host=document.getElementById('moduleTabs');
  if(!host) return;
  host.innerHTML='';
  openModuleTabs.forEach(function(view){
    const tab=document.createElement('div');
    tab.className='module-tab'+(view===currentView?' active':'')+(view==='dashboard'?' fixed':'');
    tab.dataset.tabView=view;
    tab.title=VIEWS[view]||'工作台';
    tab.setAttribute('role','tab');
    tab.setAttribute('tabindex','0');
    tab.setAttribute('aria-selected', view===currentView?'true':'false');
    const label=document.createElement('span');
    label.className='module-tab-label';
    label.textContent=VIEWS[view]||'工作台';
    tab.appendChild(label);
    if(view!=='dashboard'){
      const refresh=document.createElement('button');
      refresh.type='button';
      refresh.className='module-tab-refresh';
      refresh.dataset.refreshTab=view;
      refresh.setAttribute('aria-label','刷新 '+(VIEWS[view]||'模块'));
      refresh.title='刷新';
      refresh.textContent='↻';
      tab.appendChild(refresh);
      const close=document.createElement('button');
      close.type='button';
      close.className='module-tab-close';
      close.dataset.closeTab=view;
      close.setAttribute('aria-label','关闭 '+(VIEWS[view]||'模块'));
      close.textContent='×';
      tab.appendChild(close);
    }
    host.appendChild(tab);
  });
  const active=host.querySelector('.module-tab.active');
  if(active) active.scrollIntoView({block:'nearest',inline:'nearest'});
}
function closeModuleTab(view){
  if(view==='dashboard') return;
  const index=openModuleTabs.indexOf(view);
  if(index<0) return;
  openModuleTabs.splice(index,1);
  if(currentView===view){
    const next=openModuleTabs[Math.max(0,index-1)]||'dashboard';
    goto(next);
  }else renderModuleTabs();
}
function refreshModuleTab(view){
  if(!view) return;
  const target=$('.nav-item[data-view="'+view+'"], .nav-sub-item[data-view="'+view+'"], [data-top-view="'+view+'"]');
  if(!target || target.classList.contains('hidden')) return;
  if(!openModuleTabs.includes(view)) return;
  if(currentView===view){
    const c=$('#content');
    c.innerHTML=PAGES[view]?PAGES[view]():PAGES.dashboard();
    if(PAGES[view+'_init']) PAGES[view+'_init']();
    setTimeout(function(){ if(typeof installDirectModuleImport==='function') installDirectModuleImport(view); },0);
    if(typeof showToast==='function') showToast('已刷新：'+(VIEWS[view]||'工作台'),'ok');
  }else{
    goto(view);
  }
}
const MODULE_TABS_STATE_KEY='nnuzc_module_tabs_state';
/* 模块标签仅属于当前浏览器会话，不能写入业务同步存储；否则每次刷新都会产生一次无意义的数据库写入。 */
const MODULE_TABS_SESSION=window.sessionStorage;
function restoreModuleTabs(){
  /* 2026-08-20：刷新后仅保留工作台标签，其它已打开模块标签自动关闭。 */
  try{ MODULE_TABS_SESSION.removeItem(MODULE_TABS_STATE_KEY); }catch(e){}
  openModuleTabs=['dashboard'];
  currentView='dashboard';
}
document.getElementById('moduleTabs').addEventListener('click',function(e){
  const close=e.target.closest('[data-close-tab]');
  if(close){ closeModuleTab(close.dataset.closeTab); return; }
  const refresh=e.target.closest('[data-refresh-tab]');
  if(refresh){ e.stopPropagation(); refreshModuleTab(refresh.dataset.refreshTab); return; }
  const tab=e.target.closest('[data-tab-view]');
  if(tab) goto(tab.dataset.tabView);
});
document.getElementById('moduleTabs').addEventListener('keydown',function(e){
  if(e.target.tagName==='BUTTON') return; // 刷新/关闭按钮自行处理按键
  const tab=e.target.closest('[data-tab-view]');
  if(tab && (e.key==='Enter'||e.key===' '||e.key==='Spacebar')){ e.preventDefault(); goto(tab.dataset.tabView); }
});
function goto(view,options){
  const gotoOptions=options||{};
  const target=$('.nav-item[data-view="'+view+'"], .nav-sub-item[data-view="'+view+'"], [data-top-view="'+view+'"]');
  if(!target || target.classList.contains("hidden")){
    view=navMenuIsVisible("dashboard")?"dashboard":"navCustomize";
  }
  else if(gotoOptions.expandNavGroup!==false)expandNavGroupForItem(target);
  if(view!=="cockpit"){
    clearInterval(window.__cockpitClockTimer);
    document.body.classList.remove("cockpit-immersive");
    if(document.fullscreenElement&&document.exitFullscreen) document.exitFullscreen().catch(function(){});
  }
  // reset active/expanded states
  $$('.nav-item, .nav-sub-item').forEach(n=>n.classList.remove('active'));
  $$('.nav-item.has-sub').forEach(n=>n.classList.remove('open'));
  $$('.nav-sub').forEach(s=>s.classList.remove('open'));
  // set active and expand parent if sub-item
  const sub=$('.nav-sub-item[data-view="'+view+'"]');
  if(sub){
    sub.classList.add('active');
    const parent=sub.closest('.nav-sub');
    if(parent){ parent.classList.add('open'); parent.previousElementSibling.classList.add('open','active'); }
  } else {
    const top=$('.nav-item[data-view="'+view+'"]');
    if(top) top.classList.add('active');
  }
  if(view==="employment") employmentDefaultGraduateYear();
  currentView=view;
  const cockpitEntry=$("#cockpitEntryBtn");if(cockpitEntry)cockpitEntry.classList.toggle("active",view==="cockpit");
  if(!openModuleTabs.includes(view)) openModuleTabs.push(view);
  renderModuleTabs();
  $("#crumb").textContent=VIEWS[view]||"工作台";
  const c=$("#content");
  c.innerHTML=PAGES[view]?PAGES[view]():PAGES.dashboard();
  if(PAGES[view+"_init"]) PAGES[view+"_init"]();
  /* 页面生成后补上该业务模块的独立导入入口（不会影响原有按钮或数据逻辑）。 */
  setTimeout(function(){ if(typeof installDirectModuleImport==="function") installDirectModuleImport(view); },0);
  if(navDrawerMedia.matches)setNavDrawerOpen(false);
}
$$('.nav-item, .nav-sub-item').forEach(n=>{
  n.addEventListener("click",()=>{
    if(n.dataset.href){ window.location.assign(n.dataset.href); return; }
    if(n.classList.contains('has-sub') && n.dataset.view){
      // v1.45：基础数据维护等父项同时具备导航目标：点击进入对应页面（goto 会自动展开子菜单）
      goto(n.dataset.view);
    } else if(n.classList.contains('has-sub')){
      n.classList.toggle('open');
      const sub=n.nextElementSibling;
      if(sub && sub.classList.contains('nav-sub')) sub.classList.toggle('open');
    } else {
      goto(n.dataset.view);
    }
  });
});

/* ---- 通用组件 ---- */
function barChart(data){
  const max=Math.max(...data.map(d=>d.v),1);
  return '<div class="bar">'+data.map(d=>'<div class="col"><div class="v">'+d.v+'</div><div class="fill" style="height:'+(d.v/max*150)+'px"></div><div class="l">'+d.l+'</div></div>').join('')+'</div>';
}
function donut(percent,color,label){
  return '<div class="donut" style="background:conic-gradient('+color+' '+percent+'%, #eef1f3 0)"><div class="c">'+label+'</div></div>';
}
function table(head,rows){
  if(typeof currentView!=="undefined" && typeof QUERY_REQUIRED_PAGES!=="undefined" && QUERY_REQUIRED_PAGES.indexOf(currentView)!==-1 && !queryReady(currentView)){
    rows='<tr><td colspan="'+Math.max(1,head.length)+'" class="empty">请设置条件后点击「查询」；不设置条件直接查询将显示全部数据。</td></tr>';
  }
  return '<div class="table-scroll"><table><thead><tr>'+head.map(h=>'<th>'+h+'</th>').join('')+'</tr></thead><tbody>'+rows+'</tbody></table></div>';
}
function badge(txt,cls){return '<span class="badge '+cls+'">'+txt+'</span>';}
function curTermFilter(rows){return rows;}

