let academicAnalysisLatestSummary=null;
window.addEventListener("message",function(event){
  const frame=document.getElementById("academicAnalysisFrame");
  if(event.origin!==location.origin||!frame||event.source!==frame.contentWindow||!event.data)return;
  if(event.data.type==="academic-analysis-ready"){academicAnalysisLatestSummary=event.data.summary||null;showToast("学业分析文件已生成，可使用 AI 匿名辅助","ok");}
});
function academicAnalysisRequestSummary(){
  const frame=document.getElementById("academicAnalysisFrame");
  if(academicAnalysisLatestSummary)return Promise.resolve(academicAnalysisLatestSummary);
  if(!frame||!frame.contentWindow)return Promise.reject(new Error("学业分析工具尚未加载。"));
  return new Promise(function(resolve,reject){
    const requestId="aa-"+Date.now()+"-"+Math.random().toString(16).slice(2),timer=setTimeout(function(){cleanup();reject(new Error("请先在下方上传成绩表并生成统计结果。"));},3000);
    const onMessage=function(event){if(event.origin!==location.origin||event.source!==frame.contentWindow||!event.data||event.data.type!=="academic-analysis-summary-response"||event.data.requestId!==requestId)return;cleanup();if(event.data.summary){academicAnalysisLatestSummary=event.data.summary;resolve(event.data.summary);}else reject(new Error("请先生成统计结果后再使用 AI 辅助。"));};
    const cleanup=function(){clearTimeout(timer);window.removeEventListener("message",onMessage);};
    window.addEventListener("message",onMessage);frame.contentWindow.postMessage({type:"academic-analysis-summary-request",requestId:requestId},location.origin);
  });
}
function academicAnalysisAiPrompt(mode,question){
  const boundary="每个班级必须独立分析，只能引用该班自身数据；不得写全院、同年级、其他班级情况，不得进行班级排名或横向比较。";
  if(mode==="plan")return boundary+"请识别各班自身需要优先关注的统计现象，并给出可执行的班级学业帮扶建议。按“依据—建议—复核点”组织，不得推断具体学生身份、家庭情况或个人原因。";
  if(mode==="draft")return boundary+"如摘要包含多个班级序号，请分别生成相互独立、可继续人工编辑的学业分析报告草稿。每份仅包含：本班基本情况、成绩与不及格情况、主要问题、帮扶措施、后续复核清单。不得虚构课程、学生、班级名称或原因。";
  if(mode==="custom")return boundary+"请在该班统计数据能够支持的范围内完成以下要求；超出数据边界时明确说明，不得猜测或补造事实："+question;
  return boundary+"请逐个班级序号独立解读自身统计数据，说明本班成绩、不及格情况、异常或需复核点，并列出结论所依据的数字。不要对具体学生作判断。";
}
async function academicAnalysisAi(mode){
  const result=document.getElementById("academicAnalysisAiResult"),draft=document.getElementById("academicAnalysisAiDraft"),button=document.getElementById("academicAnalysisInterpretBtn"),question=String((document.getElementById("academicAnalysisAiQuestion")||{}).value||"").trim();
  if(mode==="custom"&&!question){showToast("请先填写补充分析要求","warn");return;}
  if(button){button.disabled=true;button.textContent="AI 分析中…";}if(result)result.style.display="block";if(draft)draft.value="正在读取本机匿名汇总……";
  try{
    const summary=await academicAnalysisRequestSummary();
    const system="你是高校辅导员的学业统计辅助助手。输入数据已经在本机完成统计且只包含匿名聚合数字。你不能修改、重算或替代固定统计规则，不能推断学生身份、班级名称、课程名称、家庭背景或心理状态，不能虚构原因。每个班级只能依据自身数据独立分析，禁止引用全院、同年级或其他班级数据，禁止排名和横向比较。所有输出都必须标注为待人工审核草稿，并区分数据事实、合理建议和需人工补充的内容。";
    const content=await aiChat(system,academicAnalysisAiPrompt(mode,question)+"\n\n【本机匿名统计摘要】\n"+JSON.stringify(summary,null,2),"academicAnalysis");
    if(draft)draft.value=String(content||"").trim()||"AI 未返回可用内容。";showToast("AI 学业分析草稿已生成，请人工审核","ok");
  }catch(error){if(draft)draft.value="AI 辅助未完成："+(error&&error.message?error.message:"未知错误");showToast("AI 学业分析未完成","warn");}
  finally{if(button){button.disabled=false;button.textContent="AI 数据解读";}}
}
async function academicAnalysisCopyDraft(){const draft=document.getElementById("academicAnalysisAiDraft"),text=String(draft&&draft.value||"").trim();if(!text){showToast("暂无可复制草稿","warn");return;}try{await navigator.clipboard.writeText(text);showToast("AI 草稿已复制","ok");}catch(_error){draft.focus();draft.select();document.execCommand("copy");showToast("AI 草稿已复制","ok");}}
function academicAnalysisDownloadDraft(){const draft=document.getElementById("academicAnalysisAiDraft"),text=String(draft&&draft.value||"").trim();if(!text){showToast("暂无可下载草稿","warn");return;}const blob=new Blob(["\ufeff"+text],{type:"text/plain;charset=utf-8"}),url=URL.createObjectURL(blob),a=document.createElement("a");a.href=url;a.download="学业分析_AI辅助草稿_"+beijingIsoDate()+".txt";document.body.appendChild(a);a.click();a.remove();setTimeout(function(){URL.revokeObjectURL(url);},200);showToast("AI 草稿已下载","ok");}
