  const smartRules=importFixedOptions("资助情况"),smartLabels=["是否贫困生","困难评定等级","国家助学金","学院助学金","国家励志助学金","学院励志助学金","临时补助"],smartFields=smartLabels.filter(function(label){return Array.isArray(smartRules[label])&&smartRules[label].length&&s.map[label];}).map(function(label){return {key:label,label:label,options:smartRules[label]};});
  const identityFields=["学号","姓名","学院","专业","年级","班级"].filter(function(label){return !!s.map[label];}).map(function(label){return {key:label,label:label};}),allFields=identityFields.concat(smartFields);
