function aiChatBox(id, placeholder){
  return '<div class="ai-chatbox" id="'+id+'_box">'
    +'<div class="ai-chat-out" id="'+id+'_out"><div class="ai-chat-ph">'+esc(placeholder||'输入指令，或点击下方快捷按钮…')+'</div></div>'
    +'<div class="ai-chat-in"><textarea id="'+id+'_in" rows="3" placeholder="输入内容，Ctrl/⌘+Enter 发送…"></textarea>'
    +'<button class="btn btn-primary" id="'+id+'_send">发送</button></div></div>';
}
function bindAiChatBox(id, onSend){
  const box=document.getElementById(id+'_box'); if(!box) return;
  const send=document.getElementById(id+'_send'); const inp=document.getElementById(id+'_in'); const out=document.getElementById(id+'_out');
  if(!send||!inp||!out) return;
  function run(){ const v=(inp.value||'').trim(); if(!v) return; appendAiMsg(out,'user',v); inp.value=''; out.scrollTop=out.scrollHeight; onSend(v, function(txt){ appendAiMsg(out,'ai',txt); out.scrollTop=out.scrollHeight; }); }
  send.onclick=run;
  inp.onkeydown=function(e){ if(e&&e.key==='Enter'&&(e.ctrlKey||e.metaKey)){ e.preventDefault(); run(); } };
}
function appendAiMsg(out, role, text){
  if(!out) return; const ph=out.querySelector('.ai-chat-ph'); if(ph) ph.remove();
  const d=document.createElement('div'); d.className='ai-msg ai-msg-'+(role==='user'?'user':'ai');
  d.innerHTML='<span class="ai-role">'+(role==='user'?'你':'AI')+'</span><div class="ai-bubble">'+esc(text).replace(/\n/g,'<br>')+'</div>';
  out.appendChild(d);
}
