/* ===================== 合规层·敏感词过滤（第三阶段 III-1） ===================== */
var NN_SENS_KEY="nnuzc_sensitive_words";
function aiSensitiveWords(){
  try{ var a=JSON.parse(localStorage.getItem(NN_SENS_KEY)||"null"); if(Array.isArray(a)&&a.length) return a; }catch(e){}
  return ["自杀","自残","自伤","轻生","想死","抑郁症","精神分裂","割腕","安眠药","跳楼","性侵","猥亵"];
}
function aiSensitiveScan(text){
  var t=String(text||""); var hits=[]; var i=0;
  while(i<t.length){
    var c=t.charCodeAt(i);
    if(c>=48&&c<=57){
      var j=i;
      while(j<t.length){ var cj=t.charCodeAt(j); var ch=t[j]; if((cj>=48&&cj<=57)||ch==="x"||ch==="X") j++; else break; }
      var num=t.slice(i,j);
      if(num.length===11&&num[0]==="1") hits.push({type:"phone",match:num,start:i});
      else if(num.length===18) hits.push({type:"idcard",match:num,start:i});
      else if(num.length>=16&&num.length<=19) hits.push({type:"bankcard",match:num,start:i});
      i=j; continue;
    }
    i++;
  }
  var words=aiSensitiveWords();
  for(var w=0;w<words.length;w++){
    var word=words[w]; var idx=t.indexOf(word);
    while(idx>=0){ hits.push({type:"sensitive",match:word,start:idx}); idx=t.indexOf(word,idx+word.length); }
  }
  var hasPII=hits.some(function(h){return h.type==="phone"||h.type==="idcard"||h.type==="bankcard";});
  var hasPsych=hits.some(function(h){return h.type==="sensitive";});
  var level="info"; if(hasPII) level="block"; else if(hasPsych) level="warn";
  return {hits:hits,level:level,hasPII:hasPII,hasPsych:hasPsych};
}
function aiMaskPII(text){
  var t=String(text||""); var sc=aiSensitiveScan(t);
  var pii=sc.hits.filter(function(h){return h.type!=="sensitive";});
  if(!pii.length) return t;
  pii.sort(function(a,b){return b.start-a.start;});
  var arr=t.split("");
  for(var k=0;k<pii.length;k++){
    var h=pii[k]; var m=h.match; var masked;
    if(h.type==="phone") masked=m.slice(0,3)+"****"+m.slice(7);
    else if(h.type==="idcard") masked=m.slice(0,6)+"********"+m.slice(14);
    else masked=m.slice(0,4)+"********"+m.slice(m.length-4);
    arr.splice(h.start,m.length,masked);
  }
  return arr.join("");
}
/* ===================== 合规层·敏感词过滤（III-1）结束 ===================== */

