      +'<div style="margin:8px 0"><b>服务商</b><br><select id="aiProvider" onchange="aiProviderPreset()" style="width:100%;padding:6px 8px;border:1px solid var(--border);border-radius:6px">'
        +'<option value="">自定义（自行填写 Base URL）</option>'
