  kimi:{ baseUrl:"https://api.moonshot.cn/v1", model:"kimi-k2.6", models:["kimi-k2.6"], guide:"在 Kimi 开放平台创建 API Key；推荐使用当前 K2.6 模型。", keyUrl:"https://platform.kimi.com/console/api-keys" },
  siliconflow:{ baseUrl:"https://api.siliconflow.cn/v1", model:"deepseek-ai/DeepSeek-V3", models:["deepseek-ai/DeepSeek-V3"], guide:"在硅基流动控制台创建 API Key，并按账户可用模型填写模型名。", keyUrl:"https://cloud.siliconflow.cn/account/ak" },
  openrouter:{ baseUrl:"https://openrouter.ai/api/v1", model:"openai/gpt-4o-mini" },
