  const gradeRows=(window.gradeTerms||[]).reduce(function(a,t){ return a.concat((t.rows||[]).filter(function(r){ return String(r["学号"])===String(s.id); }).map(function(r){ return {term:t.term, r:r}; })); },[]);
  const L=[];
  L.push("# 重点学生帮扶档案："+(s.name||"")+"（"+(s.id||"")+"）"); L.push("");
