  L.push("## 四、学业预警（个人版）");
  if(warns.length) warns.forEach(function(w){ L.push("- "+(w["预警等级"]||"预警")+"："+(w["原因"]||w["预警原因"]||"—")+"（"+(w["学期"]||"—")+"）"); });
  else L.push("- 暂无学业预警（个人版）记录。");
  L.push("");
  L.push("## 四之一、成绩与排名（个人版）");
