async function aiDocGenerate(){
  const r=document.getElementById("aiDocResult"); if(!r) return;
  if(!aiDocCurType){ r.innerHTML='<span style="color:#c0392b">请先选择一个材料模板。</span>'; return; }
  let md;
  try{ md=aiDocBuild(aiDocCurType, aiDocReadOpts()); }
  catch(e){ r.innerHTML='<span style="color:#c0392b">生成失败：'+esc(e.message||e)+'</span>'; return; }
  r.innerHTML='<div style="margin:8px 0"><b>预览（可编辑）：</b></div>'
    +'<textarea id="aiDocText" style="width:100%;height:340px;padding:8px;border:1px solid var(--border);border-radius:6px;font-family:inherit">'+esc(md)+'</textarea>'
    +'<div style="margin-top:8px">'
    +'<button type="button" onclick="aiDocCopy()" style="padding:6px 12px;border:1px solid var(--border);background:#fff;border-radius:6px;cursor:pointer">复制</button> '
    +'<button type="button" onclick="aiDocDownload(\'txt\')" style="padding:6px 12px;border:1px solid var(--border);background:#fff;border-radius:6px;cursor:pointer">导出 TXT</button> '
    +'<button type="button" onclick="aiDocDownload(\'docx\')" style="padding:6px 12px;border:1px solid var(--border);background:#fff;border-radius:6px;cursor:pointer">导出 Word</button>'
    +' <button type="button" onclick="aiSaveDraft(\'材料：\'+(aiDocCurType||\'草稿\'), document.getElementById(\'aiDocText\').value)" style="padding:6px 12px;border:1px solid var(--border);background:#fff;border-radius:6px;cursor:pointer">保存版本</button>'
    +'</div>';
}
async function aiDocPolish(){
  const t=document.getElementById("aiDocText");
  if(!t){ showToast("请先生成草稿","warn"); return; }
  if(!aiConfigured()){ showToast("请先在设置中配置AI模型","warn"); return; }
  const base=t.value;
  try{
    const sys="你是高校辅导员，擅长把学生工作材料草稿扩写/润色为规范、正式、实事求是的中文公文。基于给定草稿，保留全部事实与数字，提升表达与结构，不编造数据。";
    const user="以下是材料草稿，请润色扩写：\n\n"+base;
    const out=await aiChat(sys,user,"document");
    if(out&&out.trim()){ t.value=out.trim(); showToast("AI 润色完成","ok"); }
  }catch(e){ showToast("AI 润色失败："+(e.message||e),"warn"); }
}
function aiDocCopy(){
  const t=document.getElementById("aiDocText"); if(t){ t.select(); try{ document.execCommand("copy"); }catch(e){} if(navigator.clipboard) navigator.clipboard.writeText(t.value).catch(function(){}); showToast("已复制","ok"); }
}
function aiDocDownload(type){
  const t=document.getElementById("aiDocText"); if(!t) return;
  const name="材料草稿_"+(aiDocCurType||"doc")+(type==="docx"?".docx":".txt");
  if(type==="docx"){ downloadDocxFile(name, t.value); }
  else{ const blob=new Blob([t.value],{type:"text/plain;charset=utf-8"}); const url=URL.createObjectURL(blob); const a=document.createElement("a"); a.href=url; a.download=name; document.body.appendChild(a); a.click(); a.remove(); setTimeout(function(){ URL.revokeObjectURL(url); },200); }
  showToast("已导出","ok");
}
