  const talks=(talkRecords||[]).filter(function(r){ return String(r.sid)===String(s.id); });
  const homes=(homeRecords||[]).filter(function(r){ return String(r.sid)===String(s.id); });
  const events=(eventRecords||[]).filter(function(r){ return String(r.sid)===String(s.id); });
  const pts=aiActPointsList(opts.points);
  const L=[];
  L.push("# 谈心谈话提纲："+(s.name||"")+"（"+(s.id||"")+"）"); L.push("");
  L.push("## 一、学生基本情况");
