/* ============ 评奖评优数据（学业情况 · 评奖评优数据 栏目） ============
 * 字段与 Excel《2024-2025-2学期至2025-2026-1学期成绩信息》保持一致；
 * 学期按 YYYY-YYYY-N学期 校验；每条学期维护一个独立的 18 列成绩列表。
 */
window.academicTerms = window.academicTerms || []; /* 学期容器由“学期设置”统一同步，不在业务模块单独维护。 */
window.academicTermSeq = window.academicTermSeq || 1;

/* 【2026-07-27 任务】评奖评优字段格式元数据
   - 每字段一个 {key,type}，type 决定该列在表格/模板/导出中的显示与校验规则
   - ACADEMIC_FIELDS 顺序与列宽均以此为准（向后兼容旧引用方：ACADEMIC_FIELDS 为 key 数组）
   - 数字字段保留位数：num2 → 2 位小数；int → 整数；percent_int → 百分比整数（显示加 %）；text_rank → x/y 文本；text_multi → 多门文本
   - 下载导入模板统一在第 2 行输出填写示例 */
const ACADEMIC_FIELDS_DEF = [
  {key:"学号", label:"学号", type:"text"},
  {key:"姓名", label:"姓名", type:"text"},
  {key:"学院", label:"学院", type:"text"},
  {key:"年级", label:"年级", type:"text"},
  {key:"班级", label:"班级", type:"text"},
  {key:"综测分数", label:"综合测评总分", type:"num2"},
  {key:"综测班级排名", label:"排名", type:"text_rank"},
  {key:"综测排名百分比", label:"综测排名百分比", type:"percent2"}
];
/* 字段格式说明：第 2 行（格式说明行）单元格内容；同时作为 input title 提示 */
const ACADEMIC_FORMAT_LABEL = {
  text:        "文本",
  text_rank:   "排名，格式 班级排名/班级人数（如 1/50）",
  text_multi:  "文本，多门用「/」分隔",
  num2:        "数值，保留2位小数",
  int:         "整数，保留整数",
  percent_int: "百分比，保留整数",
  percent2:    "百分比，由排名自动计算（排名÷班级人数×100，保留2位小数）"
};
/* ACADEMIC_FIELDS：所有调用方继续使用 key 数组（顺序 = ACADEMIC_FIELDS_DEF 顺序），新字段在末尾 */
const ACADEMIC_FIELDS = ACADEMIC_FIELDS_DEF.map(x => x.key);
const ACADEMIC_FIELD_TYPE_BY_KEY = ACADEMIC_FIELDS_DEF.reduce((m, x) => (m[x.key] = x.type, m), {});
const ACADEMIC_FIELD_LABEL_BY_KEY = ACADEMIC_FIELDS_DEF.reduce((m, x) => (m[x.key] = x.label || x.key, m), {});
/* 导入表头别名：Excel 表头可能使用显示名称（label），导入时映射回内部 key */
const ACADEMIC_HEADER_TO_KEY = ACADEMIC_FIELDS_DEF.reduce((m, x) => { if(x.label && x.label !== x.key) m[x.label] = x.key; return m; }, {});
const ACADEMIC_REQUIRED_KEYS = ["学号","姓名"];
/* 【2026-07-28 任务】按字段格式把原始值规范化为展示值
   - 先走 coerceAcademicValue 归一化（四舍五入），再格式化
   - percent_int 显示时追加「%」后缀（如 52 → "52%"）
   - percent2 显示时追加「%」后缀并保留 2 位小数（如 10 → "10.00%"）
   - num2 用 toFixed(2) 补 0；int 用 parseInt 取整；text_rank 显示「班级排名/班级人数」（如 1/50）；text/text_multi 原样 */
function formatAcademicDisplay(v, type){
  const x = coerceAcademicValue(v, type);
  if(x === "" || x == null) return "";
  if(type === "num2"){ const n = Number(x); return isFinite(n) ? n.toFixed(2) : String(x); }
  if(type === "int"){  const n = parseInt(x, 10); return isFinite(n) ? String(n) : String(x); }
  if(type === "percent_int"){ const n = parseInt(x, 10); return isFinite(n) ? (n + "%") : String(x); }
  if(type === "percent2"){ const n = Number(x); return isFinite(n) ? (n.toFixed(2) + "%") : String(x); }
  if(type === "text_rank"){ return String(x); }
  return String(x);
}
/* 【2026-07-28 任务】导入/保存时按字段类型做四舍五入归一化（自动修正）
   - num2: 保留 2 位小数（Math.round(n*100)/100）
   - percent_int: 整数百分比（允许末尾带 % 字符，自动剥除）
   - percent2: 百分比保留 2 位小数（允许末尾带 % 字符，自动剥除，再四舍五入）
   - int: 整数
   - text_rank: 「班级排名/班级人数」各取整数四舍五入（如 "1.4/50.6" → "1/51"）
   - text/text_rank/text_multi: 原样 trim；解析失败的数值字段保留原样以便上层提示 */
function coerceAcademicValue(v, type){
  if(v == null) return "";
  if(typeof v === "number"){
    if(type === "num2") return Math.round(v * 100) / 100;
    if(type === "int") return Math.round(v);
    if(type === "percent_int") return Math.round(v);
    if(type === "percent2") return Math.round(v * 100) / 100;
    return v;
  }
  const s = String(v).trim();
  if(s === "") return "";
  if(type === "num2"){ const n = Number(s); return isFinite(n) ? Math.round(n * 100) / 100 : s; }
  if(type === "int"){  const n = parseFloat(s); return isFinite(n) ? Math.round(n) : s; }
  if(type === "percent_int"){ const stripped = s.replace(/%/g, ""); const n = parseFloat(stripped); return isFinite(n) ? Math.round(n) : s; }
  if(type === "percent2"){ const stripped = s.replace(/%/g, ""); const n = parseFloat(stripped); return isFinite(n) ? Math.round(n * 100) / 100 : s; }
  if(type === "text_rank"){
    const m = s.split("/");
    if(m.length === 2){
      const a = Number(m[0]), b = Number(m[1]);
      if(isFinite(a) && isFinite(b)) return Math.round(a) + "/" + Math.round(b);
    }
    return s;
  }
  return s;
}

// 列名重命名兼容：旧数据可能以「综测（平均）」为键，读取时回退
function academicCellValue(r, f){
  if(r[f] != null) return r[f];
  if((f === "综测分数" || f === "综测") && r["综测（平均）"] != null) return r["综测（平均）"];
  return undefined;
}

function loadAcademicTerms(){
  try{
    const raw = localStorage.getItem("nnuzc_academic_terms");
    if(raw){
      const a = JSON.parse(raw);
      if(Array.isArray(a)){
        a.forEach(t => { if(!Array.isArray(t.rows)) t.rows=[]; if(!t.status) t.status="待录入"; });
        return a;
      }
    }
  }catch(e){ reportDataError("综测学期加载", e); }
  return []; /* v1.6 起：默认无任何学期 */
}
function saveAcademicTerms(){
  window.academicTerms = sortTermsDesc(window.academicTerms);
  localStorage.setItem("nnuzc_academic_terms", JSON.stringify(window.academicTerms));
}
/* 综测数据自动修复：按字段类型（num2/percent2/int/text_rank）归一化已存在的数据，确保导入前/旧数据格式统一 */
function repairAcademicData(){
  let changed=false;
  const typeMap=ACADEMIC_FIELD_TYPE_BY_KEY||{};
  sortTermsDesc(window.academicTerms||[]).forEach(function(t){
    (t.rows||[]).forEach(function(r){
      ACADEMIC_FIELDS.forEach(function(f){
        const type=typeMap[f]; if(!type) return;
        if(r[f]==null || r[f]==="") return;
        const before=r[f];
        const after=coerceAcademicValue(before, type);
        if(String(after)!==String(before)){ r[f]=after; changed=true; }
      });
      // 同步修复旧键「综测（平均）」
      if(r["综测（平均）"]!=null && r["综测（平均）"]!==""){
        const before=r["综测（平均）"];
        const after=coerceAcademicValue(before, typeMap["综测分数"]||"num2");
        if(String(after)!==String(before)){ r["综测（平均）"]=after; changed=true; }
      }
    });
  });
  if(changed) saveAcademicTerms();
}
window.academicTerms = sortTermsDesc(loadAcademicTerms()); /* 学期一律逆序（新学期在前） */
repairAcademicData();
