function academicWarningDownloadCourseTemplate(){
  const sample={"年级":"2025级","学院":"示例学院","专业":"示例专业","班级":"示例班级","学号":"20250001","姓名":"示例学生","课程代码":"COURSE001","课程名称":"高等数学","开课学院":"公共基础学院","学分":"4","成绩":"52","成绩备注":"","补考成绩":"","重修成绩":"","课程性质":"必修","课程类别":"专业基础课","学期":"2025-2026-1","考核方式":"考试"};
  const rows=[ACADEMIC_WARNING_COURSE_EXPORT_FIELDS.slice(),ACADEMIC_WARNING_COURSE_EXPORT_FIELDS.map(function(f){return sample[f]||'';})];
  downloadXlsxFile('学生不及格课程明细',rows,'学业预警（个人版）课程明细导入模板.xlsx');
  showToast('已下载课程明细导入模板','success');
}



function academicWarningExport(id){
  const t = academicWarningTermById(id); if(!t) return;
  if(!t.rows || !t.rows.length){ alert("当前学期暂无数据可导出。"); return; }
  const headers = ACADEMIC_WARNING_FIELDS.slice();
  const rows = t.rows.map(r => ACADEMIC_WARNING_FIELDS.map(f => { const _v = academicWarningCellValue(r, f); return _v != null ? String(_v) : ""; }));
  rows.unshift(headers);
  downloadXlsxFile("学业预警（个人版）数据_" + t.term, rows, "学业预警（个人版）数据_" + t.term + ".xlsx");
  if(typeof showToast === "function") showToast("已导出 " + t.rows.length + " 条", "ok");
}


/* ============ 成绩与排名（学业情况 · 成绩与排名 栏目，与学业预警平行） ============
   参考学业预警模块：学期维度(gradeTerms) + rows(学生+学期 成绩排名汇总) + courses(课程成绩明细)。
   汇总字段来自「编辑成绩与排名字段模版.xlsx」；课程明细字段来自「编辑课程成绩字段模版.xlsx」。 */
const GRADE_FIELDS = ["学号","姓名","学院","年级","专业","班级","学分加权平均分","学分加权平均分排名","平均学分绩点","平均学分绩点排名","总应获得学分","总分","门数","总学分","获得学分","不及格学分","通过率","算术平均分","算术平均分排名","平均绩点","平均绩点排名","学分绩点和","学分绩点和排名","不及格门次"];
/* 课程成绩明细：每条汇总记录可挂接多门课程；课程自身保留原始学期（同预警课程模式）。
   字段含学生身份信息（学号/姓名等），便于与 Excel 模板直接对齐导入导出。 */
const GRADE_COURSE_FIELDS = ["学号","姓名","性别","课程名称","总评成绩","备注","补考成绩","补考成绩备注","年级","班级","专业","学院","课程代码","开课学院","课程性质","学分","总学时","课程类别","绩点","任课教师","折算成绩","平时成绩","期中成绩","实验成绩","期末成绩"];
const GRADE_COURSE_EXPORT_FIELDS = GRADE_COURSE_FIELDS.slice();
const GRADE_INPUT_ID = {
  "学号":"grNo","姓名":"grName","学院":"grDept","年级":"grGrade","班级":"grCls","专业":"grMajor",
  "学分加权平均分":"grWavg","学分加权平均分排名":"grWavgR","平均学分绩点":"grGpa","平均学分绩点排名":"grGpaR",
  "总应获得学分":"grShould","总分":"grTotal","门数":"grCount","总学分":"grCredit","获得学分":"grGet","不及格学分":"grFailCredit",
  "通过率":"grPass","算术平均分":"grAavg","算术平均分排名":"grAavgR","平均绩点":"grPoint","平均绩点排名":"grPointR",
  "学分绩点和":"grPsum","学分绩点和排名":"grPsumR","不及格门次":"grFailTimes"
};
function gradeCellValue(r, f){ return (r && r[f] != null) ? r[f] : undefined; }
function gradeCourseKey(course){
  const get = function(k){ return String((course && course[k]) || "").trim(); };
  return [get("课程代码"), get("课程名称"), get("学期")].join("|");
}
function gradeNormalizeCourse(course){
  const out={_cid:(course&&course._cid)||genId("gc")};
  GRADE_COURSE_FIELDS.forEach(function(f){ out[f]=String((course&&course[f])||"").trim(); });
  return out;
}
function gradeNormalizeRowCourses(row){
  if(!row || typeof row!=="object") return false;
  if(!Array.isArray(row.courses)){ row.courses=[]; return true; }
  row.courses=row.courses.map(function(course){ return gradeNormalizeCourse(course); });
  return false;
}
function loadGradeTerms(){
  try{
    const raw = localStorage.getItem("nnuzc_grade_terms");
    if(raw){
      const a = JSON.parse(raw);
      if(Array.isArray(a)){
        a.forEach(t => {
          if(!Array.isArray(t.rows)) t.rows=[];
          if(!t.status) t.status="待录入";
          t.rows.forEach(function(row){
            if(!row || typeof row!=="object") return;
            row.courses=(row.courses||[]).map(function(c){ return gradeNormalizeCourse(c); });
          });
        });
        return a;
      }
    }
  }catch(e){ reportDataError("成绩与排名（个人版）学期加载", e); }
  return [];
}
function saveGradeTerms(){ window.gradeTerms=sortTermsDesc(window.gradeTerms); localStorage.setItem("nnuzc_grade_terms", JSON.stringify(window.gradeTerms)); }
window.gradeTerms = sortTermsDesc(loadGradeTerms());
window.gradeTermSeq = Math.max(0, ...(window.gradeTerms||[]).map(function(t){return Number(t.id)||0;})) + 1;
function gradeTermById(id){ return window.gradeTerms.find(t => t.id === id) || null; }
function gradeValidateTerm(raw){
  const t = (raw||"").trim();
  if(!t) return "请输入学期";
  const m = t.match(/^(\d{4})-(\d{4})-[1-9]学期$/);
  if(!m) return "格式错误：请按「YYYY-YYYY-N学期」输入，例如 2026-2027-1学期";
  const y1 = parseInt(m[1], 10), y2 = parseInt(m[2], 10);
  if(y2 !== y1 + 1) return "学年应连续：例如 2026-2027-1学期（第二年=第一年+1）";
  return "";
}
function gradeTermRowsCount(t){ return (t && t.rows && t.rows.length) || 0; }
function renderGradeTermRows(list){
  list = sortTermsDesc(list || window.gradeTerms);
  if(!list.length) return '<tr><td colspan="3" class="empty">暂无学期，请先到“学期设置”新增学期</td></tr>';
  return list.map(t => {
    const cnt = gradeTermRowsCount(t);
    const state = cnt > 0 ? "已录入 " + cnt + " 条" : "待录入";
    return '<tr data-tid="'+ t.id +'">'
      + '<td><b>'+ esc(t.term) +'</b></td>'
      + '<td>'+ (cnt > 0 ? '<span class="badge b-green">'+ state +'</span>' : '<span class="badge b-gray">'+ state +'</span>') +'</td>'
      + '<td>　<a class="lk" onclick="openEditGradeTerm('+ t.id +')">查看</a>　<a class="lk" onclick="openEditGradeTerm('+ t.id +')">编辑</a></td>'
      + '</tr>';
  }).join('');
}
function gradeRefreshList(){
  window.gradeTerms=sortTermsDesc(window.gradeTerms);
  const tb = document.getElementById("gradeTermTbody");
  if(tb) tb.innerHTML = renderGradeTermRows(window.gradeTerms);
  const info = pagerSlice('grade_terms', window.gradeTerms);
  const pg = document.getElementById("gradeTermPager");
  if(pg) pg.innerHTML = renderGenericPager('grade_terms', info, 'gradeTermJump');
  const sgW = document.querySelector('.qf-single[data-qf="gradeViewTerm"]');
  if(sgW){
    sgW.outerHTML = qfSingle('gradeViewTerm', window.gradeTerms.length ? window.gradeTerms.map(function(t){ return {v:String(t.id), l: esc(t.term) + '（' + gradeTermRowsCount(t) + ' 条）'}; }) : [{v:'0', l:'（暂无学期）'}], String(window.gradeViewTermId || '0'));
  }
}
function openAddGradeTerm(){
  showToast("学期只能在“学期设置”中统一新增","warn");goto("semester");
}
async function gradeDeleteTerm(id){
  showToast("学期只能在“学期设置”中统一删除","warn");goto("semester");
}
function gradeSwitchViewTerm(id){
  const i = parseInt(id,10);
  if(!i) return;
  window.gradeViewTermId = i;
  if(typeof renderPage === "function") renderPage("academic");
}
function gradePaneHTML(){
  if(!window.gradeViewTermId || !gradeTermById(window.gradeViewTermId)){
    window.gradeViewTermId = (window.gradeTerms[0] && window.gradeTerms[0].id) || 0;
  }
  const curId = window.gradeViewTermId;
  const curTerm = curId ? gradeTermById(curId) : null;
  const termRows = renderGradeTermRows();
  return `
    <div class="card" style="margin-bottom:14px">
      <div class="tip">成绩与排名（个人版）按学期管理（学生成绩排名汇总 → 每名学生的课程成绩明细）。支持分别导入名单和课程，课程可查看、编辑、删除；维护后会按学号关联到学生全档案。</div>
      <div class="ae-bar" style="padding:0;border:0;background:transparent">
        <div class="row1" style="margin-bottom:10px">
          <div class="filter-item">
            <label>查看学期</label>
            ${qfSingle('gradeViewTerm', window.gradeTerms.length ? window.gradeTerms.map(function(t){ return {v:String(t.id), l: esc(t.term) + '（' + gradeTermRowsCount(t) + ' 条）'}; }) : [{v:'0', l:'（暂无学期）'}], String(curId || '0'))}
          </div>
          <span class="tag">学期由“学期设置”统一同步</span>
          <span style="margin-left:auto;font-size:13px;color:var(--muted)" id="gradeViewSummary"></span>
        </div>
      </div>
      <div class="module-table-wrap table-scroll"><table class="t-table" style="min-width:auto">
        <thead><tr><th style="width:280px">学期</th><th style="width:180px">状态</th><th style="width:200px">操作</th></tr></thead>
        <tbody id="gradeTermTbody">${termRows}</tbody>
      </table></div>
      <div id="gradeTermPager"></div>
    </div>`;
}
function openEditGradeTerm(id){
  const t = gradeTermById(id);
  if(!t) return;
  resetModalLayout();
  const head = '<div style="display:flex;justify-content:space-between;align-items:center;width:100%"><span>📊 编辑成绩与排名（个人版） · '+ t.term +'</span><span style="font-size:13px;color:var(--muted);font-weight:400" id="grRowCount"></span></div>';
  document.getElementById("modalTitle").innerHTML = head;
  const body = `
    <div class="academic-edit">
      <div class="ae-bar">
        <div class="row1">
          <div class="filter-item"><label>关键字</label><input class="field-inline" id="grKw" placeholder="搜索学号 / 姓名" oninput="accountInputLen(this,50)"></div>
          <div class="filter-item"><label>学院</label>${qfMulti("grDept",[{v:"",l:"全部学院"}].concat(depts.map(d=>({v:d,l:d}))), undefined)}</div>
          <div class="filter-item"><label>专业</label>${qfMulti("grMajor",[{v:"",l:"全部专业"}].concat(majors.map(function(m){return {v:m,l:m};})), undefined)}</div>
          <div class="filter-item"><label>年级</label>${qfMulti("grGrade",[{v:"",l:"全部年级"}].concat([...new Set((students||[]).map(s=>classGrade(s.cls)))].filter(Boolean).map(g=>({v:g,l:g}))), undefined)}</div>
          <div class="filter-item"><label>班级</label>${qfMulti("grCls",[{v:"",l:"全部班级"}].concat(classes.map(function(c){return {v:c,l:c};})), undefined)}</div>
          <button class="btn btn-primary btn-sm" onclick="gradeEditQuery(${id})">查询</button>
          <button class="btn btn-ghost btn-sm" onclick="gradeEditReset(${id})">重置</button>
        </div>
        <div class="row2" style="justify-content:flex-end">
          <button class="btn btn-ghost btn-sm" onclick="gradeDownloadTemplate()">下载名单模板</button>
          <button class="btn btn-ghost btn-sm" onclick="gradeDownloadCourseTemplate()">下载课程模板</button>
          <button class="btn btn-ghost btn-sm" onclick="gradeImportPreview(${id})">导入名单/课程</button>
          <button class="btn btn-ghost btn-sm" onclick="gradeExport(${id})">导出名单</button>
          <button class="btn btn-ghost btn-sm" onclick="gradeExportCourses(${id},null)">导出课程</button>
          <button class="btn btn-primary btn-sm" onclick="openGradeRowForm(${id},null)">＋ 新增信息</button>
          <button class="btn btn-danger btn-sm" data-personal-batch="grTableWrap" onclick="gradeBatchDelete(${id})" disabled>批量删除（0）</button>
        </div>
      </div>
      <div class="ae-table-wrap" id="grTableWrap"></div>
    </div>`;
  document.getElementById("modalBody").innerHTML = body;
  document.getElementById("modalFoot").innerHTML = '<button class="btn btn-primary" onclick="closeModal()">关闭</button>';
  document.getElementById("modalFoot").style.display = "flex";
  const m = document.getElementById("modal");
  m.classList.remove("wide"); m.classList.add("xwide");
  var _vw = window.innerWidth || document.documentElement.clientWidth || 1440;
  var _main = document.querySelector('.main');
  var _ml = 204;
  try{ if(_main){ var _mr = _main.getBoundingClientRect(); if(_mr && _mr.width > 0){ _ml = Math.round(_mr.left); } } }catch(e){}
  var _modalLeft = _ml + 12;
  var _modalW = _vw - _modalLeft - 12;
  if(!(_modalW > 200)) _modalW = 1100;
  var _sets = { position:'fixed', left:_modalLeft+'px', right:'12px', top:'72px', bottom:'24px', width:_modalW+'px', 'max-width':'none', height:'auto', 'max-height':'none', transform:'none', margin:'0', 'box-sizing':'border-box', 'flex-direction':'column', display:'flex' };
  for(var _k in _sets){ try{ m.style.setProperty(_k, _sets[_k], 'important'); }catch(e){} }
  var _rule = '#modal.xwide{position:fixed !important;left:'+_modalLeft+'px !important;right:12px !important;top:72px !important;bottom:24px !important;width:'+_modalW+'px !important;max-width:none !important;height:auto !important;max-height:none !important;transform:none !important;margin:0 !important;box-sizing:border-box !important;display:flex !important;flex-direction:column !important;}';
  var _xs = document.getElementById('_xwideFix');
  if(_xs){ _xs.textContent = _rule; } else { _xs = document.createElement('style'); _xs.id = '_xwideFix'; _xs.textContent = _rule; document.head.appendChild(_xs); }
  $("#mask").classList.add("show");
  m.classList.add("show");
  document.getElementById("grRowCount").textContent = gradeTermRowsCount(t) ? "已录入 " + gradeTermRowsCount(t) + " 条" : "暂无数据";
  gradeRebuildTable(id);
}
function renderGradeEditTable(id, rows){
  const t = gradeTermById(id);
  if(!t) return "";
  const list = (rows || t.rows || []);
  if(!list.length){
    return '<tr><td colspan="'+ (GRADE_FIELDS.length + 2) +'" class="empty">该学期暂无成绩与排名（个人版）数据。点击「下载导入模板」取得 Excel 模板，按格式填入后通过「导入」上传，或逐行点击右上「新增信息」录入。</td></tr>';
  }
  return list.map((r) => {
    const cells = GRADE_FIELDS.map(f => { const _v = gradeCellValue(r, f); return '<td><div class="cell" data-tid="'+attr(id)+'" data-rid="'+attr(r._rid)+'" data-k="'+attr(f)+'" title="'+attr(_v != null ? String(_v) : '')+'">'+esc(_v != null ? String(_v) : '')+'</div></td>'; }).join("");
    const courseCount=Array.isArray(r.courses)?r.courses.length:0;
    return '<tr data-rid="'+attr(r._rid)+'">'+ personalAcademicSelectionCell(r) + cells +'<td style="text-align:center;white-space:nowrap"><a class="lk" onclick="openGradeCourses('+Number(id)+','+jsArg(r._rid)+')">课程（'+courseCount+'）</a>　<a class="lk" onclick="openGradeRowForm('+Number(id)+','+jsArg(r._rid)+')">编辑</a>　<a class="lk danger" onclick="gradeRowDelete('+Number(id)+','+jsArg(r._rid)+')">删除</a></td></tr>';
  }).join("");
}
function gradeRebuildTable(id){
  const t = gradeTermById(id);
  const wrap = document.getElementById("grTableWrap");
  if(!wrap || !t) return;
  const visRows = (t.rows||[]).filter(r => r.__hit !== false);
  const fk = (document.getElementById("grKw")?document.getElementById("grKw").value:"") + '|' + JSON.stringify(readMulti("grDept")) + '|' + JSON.stringify(readMulti("grMajor")) + '|' + JSON.stringify(readMulti("grGrade")) + '|' + JSON.stringify(readMulti("grCls"));
  const info = pagerSlice('gr_'+id, visRows, fk);
  wrap.dataset.termId=String(id);
  wrap.innerHTML = '<table><thead><tr>'+ personalAcademicSelectionHeader('grTableWrap') + GRADE_FIELDS.map(f => '<th>'+ f +'</th>').join('') +'<th style="width:230px">操作</th></tr></thead><tbody id="grTbody">'+ renderGradeEditTable(id, info.slice) +'</tbody></table>' + renderGenericPager('gr_'+id, info, 'grJump_'+id);
  personalAcademicSelectionUpdate('grTableWrap');
}
function grfAutoFill(no){
  setStudentFormValues(studentByExactId(no),"",{sid:"grNo",name:"grName",dept:"grDept",major:"grMajor",grade:"grGrade",cls:"grCls"});
}
function grfNameAutoFill(name){resolveStudentNameInput(name,function(student,typed){setStudentFormValues(student,typed,{sid:"grNo",name:"grName",dept:"grDept",major:"grMajor",grade:"grGrade",cls:"grCls"});},"成绩记录");}
function grfEsc(v){ return String(v == null ? "" : v).replace(/&/g,'&amp;').replace(/"/g,'&quot;').replace(/</g,'&lt;').replace(/>/g,'&gt;'); }
function openGradeRowForm(id, editingRid){
  const t = gradeTermById(id); if(!t) return;
  const isEdit = editingRid != null;
  const editingRow = isEdit ? (t.rows||[]).find(x => x._rid === editingRid) : null;
  if(isEdit && !editingRow) return;
  const title = isEdit ? "编辑成绩与排名（个人版）数据" : "新增成绩与排名（个人版）数据";
  const v = (f) => editingRow ? (gradeCellValue(editingRow, f) || "") : "";
  const idOf = f => GRADE_INPUT_ID[f] || ("grf_" + f);
  const f2 = (lab,key,mode) => '<div class="field"><label>'+lab+'</label><input id="'+idOf(key)+'" value="'+grfEsc(v(key))+'" '+(mode?'inputmode="'+mode+'"':'')+'></div>';
  const body = `
    <div class="tip" style="margin-bottom:14px">${isEdit ? '修改该行字段数据，提交后保存。' : '输入学号或姓名自动匹配学籍信息；同名学生请在弹窗中人工选择，其余成绩字段手动填写。'}</div>
    <div class="row1"><div class="field"><label>学号 *</label><input id="${idOf('学号')}" value="${grfEsc(v('学号'))}" placeholder="输入学号自动匹配" oninput="grfAutoFill(this.value)"></div></div>
    <div class="row1"><div class="field"><label>姓名 *</label><input id="${idOf('姓名')}" value="${grfEsc(v('姓名'))}" placeholder="输入姓名自动匹配" onchange="grfNameAutoFill(this.value)"></div></div>
    <div class="row2" style="display:grid;grid-template-columns:1.2fr 0.7fr 1fr;gap:10px">
      <div class="field"><label>学院 *</label><input id="${idOf('学院')}" value="${grfEsc(v('学院'))}" placeholder="自动匹配"></div>
      <div class="field"><label>年级 *</label><input id="${idOf('年级')}" value="${grfEsc(v('年级'))}" placeholder="自动匹配"></div>
      <div class="field"><label>班级 *</label><input id="${idOf('班级')}" value="${grfEsc(v('班级'))}" placeholder="自动匹配"></div>
    </div>
    <div class="row1"><div class="field"><label>专业</label><input id="${idOf('专业')}" value="${grfEsc(v('专业'))}" placeholder="自动匹配"></div></div>
    <div class="row2" style="display:grid;grid-template-columns:1fr 1fr;gap:10px">${f2('学分加权平均分','学分加权平均分','decimal')}${f2('学分加权平均分排名','学分加权平均分排名','numeric')}</div>
    <div class="row2" style="display:grid;grid-template-columns:1fr 1fr;gap:10px">${f2('平均学分绩点','平均学分绩点','decimal')}${f2('平均学分绩点排名','平均学分绩点排名','numeric')}</div>
    <div class="row2" style="display:grid;grid-template-columns:1fr 1fr 1fr;gap:10px">${f2('总应获得学分','总应获得学分','decimal')}${f2('总分','总分','decimal')}${f2('门数','门数','numeric')}</div>
    <div class="row2" style="display:grid;grid-template-columns:1fr 1fr 1fr;gap:10px">${f2('总学分','总学分','decimal')}${f2('获得学分','获得学分','decimal')}${f2('不及格学分','不及格学分','decimal')}</div>
    <div class="row2" style="display:grid;grid-template-columns:1fr 1fr;gap:10px">${f2('通过率','通过率')}${f2('算术平均分','算术平均分','decimal')}</div>
    <div class="row2" style="display:grid;grid-template-columns:1fr 1fr;gap:10px">${f2('算术平均分排名','算术平均分排名','numeric')}${f2('平均绩点','平均绩点','decimal')}</div>
    <div class="row2" style="display:grid;grid-template-columns:1fr 1fr;gap:10px">${f2('平均绩点排名','平均绩点排名','numeric')}${f2('学分绩点和','学分绩点和','decimal')}</div>
    <div class="row2" style="display:grid;grid-template-columns:1fr 1fr;gap:10px">${f2('学分绩点和排名','学分绩点和排名','numeric')}${f2('不及格门次','不及格门次','numeric')}</div>
    <input type="hidden" id="grfEditingRid" value="${editingRid||''}">
  `;
  openModal(title, body, () => {
    const get = k => { const el = document.getElementById(idOf(k)); return el ? (el.value||"").trim() : ""; };
    const noVal = get('学号'), name = get('姓名'), dept = get('学院'), grade = get('年级'), cls = get('班级');
    if(!noVal){ showToast("请填写学号","error"); return false; }
    if(!name){ showToast("请填写姓名","error"); return false; }
    if(!dept){ showToast("请填写学院","error"); return false; }
    if(!grade){ showToast("请填写年级","error"); return false; }
    if(!cls){ showToast("请填写班级","error"); return false; }
    const newRow = {};
    GRADE_FIELDS.forEach(f => { newRow[f] = get(f); });
    if(isEdit){ Object.keys(newRow).forEach(k => editingRow[k] = newRow[k]); showToast("已保存该行","ok"); }
    else { newRow._rid = "r" + Date.now() + Math.floor(Math.random()*1e6); newRow.courses = []; t.rows.push(newRow); showToast("已新增一条数据","ok"); }
    saveGradeTerms();
    gradeRebuildTable(id);
    const rc = document.getElementById("grRowCount"); if(rc) rc.textContent = "已录入 " + t.rows.length + " 条";
    return true;
  });
  setTimeout(()=>{ const noVal = (document.getElementById(idOf('学号'))||{}).value || ""; if(noVal) grfAutoFill(noVal); }, 50);
}
async function gradeRowDelete(id, rid){
  const t = gradeTermById(id); if(!t) return;
  const target=(t.rows||[]).find(function(x){return x._rid===rid;});
  const courseCount=target&&Array.isArray(target.courses)?target.courses.length:0;
  const moved=await recycleMoveRecords("gradeRow","grade_row",[recycleNestedRecordId(id,rid)]);if(!moved)return;
  gradeRebuildTable(id);
  const rc = document.getElementById("grRowCount"); if(rc) rc.textContent = t.rows.length ? "已录入 " + t.rows.length + " 条" : "暂无数据";
}
function gradeEditQuery(id){
  const t = gradeTermById(id); if(!t) return;
  const kw = (document.getElementById("grKw").value || "").trim();
  const dept = readMulti("grDept"), major = readMulti("grMajor"), grade = readMulti("grGrade"), cls = readMulti("grCls");
  t.rows.forEach(r => {
    r.__hit = true;
    if(kw){ r.__hit = r.__hit && ((r["学号"]||"").includes(kw) || (r["姓名"]||"").includes(kw)); }
    if(dept.length){ r.__hit = r.__hit && dept.includes(r["学院"]); }
    if(major.length){ r.__hit = r.__hit && major.includes(r["专业"]); }
    if(grade.length){ r.__hit = r.__hit && grade.includes(r["年级"]); }
    if(cls.length){ r.__hit = r.__hit && cls.includes(r["班级"]); }
  });
  gradeRebuildTable(id);
}
