    +'<button class="btn btn-primary" style="min-height:82px" onclick="gradeOpenMappedImport('+Number(id)+',\'list\')">导入成绩与排名（个人版）名单<br><small>学号、学分加权平均分、平均学分绩点等</small></button>'
    +'<button class="btn btn-primary" style="min-height:82px" onclick="gradeOpenMappedImport('+Number(id)+',\'course\')">导入课程成绩<br><small>学号、课程名称、总评成绩等</small></button>'
    +'</div>';
  openModal('导入成绩与排名（个人版）数据 · '+term.term, body, function(){return false;});
  document.getElementById('modalFoot').innerHTML='<button class="btn btn-ghost" onclick="closeModal()">取消</button>';
