function acExportAcademicDetail(){
  const cbs = document.querySelectorAll("#acExportTermList .ac-term-cb:checked");
  const ids = Array.prototype.slice.call(cbs).map(c => Number(c.value));
  if(!ids.length){ if(typeof showToast==="function") showToast("请至少选择一个学期","err"); return; }
  const terms = ids.map(id => academicTermById(id)).filter(Boolean);
  const headers = ["学院","年级","班级","学号","姓名"];
  const labelScore = ACADEMIC_FIELD_LABEL_BY_KEY["综测分数"];
  const labelRank = ACADEMIC_FIELD_LABEL_BY_KEY["综测班级排名"];
  const labelPct = ACADEMIC_FIELD_LABEL_BY_KEY["综测排名百分比"];
  terms.forEach(t => {
    headers.push(t.term + " " + labelScore);
    headers.push(t.term + " " + labelRank);
    headers.push(t.term + " " + labelPct);
  });
  const map = {};
  terms.forEach(t => {
    (t.rows||[]).forEach(r => {
      const sid = String(r["学号"]||"").trim();
      if(!sid) return;
      if(!map[sid]) map[sid] = { base:{}, per:{} };
      const o = map[sid];
      ["学院","年级","班级","姓名"].forEach(f => {
        if((o.base[f]==null || o.base[f]==="") && r[f]!=null && String(r[f]).trim()!=="") o.base[f] = String(r[f]);
      });
      o.base["学号"] = sid;
      o.per[t.term] = {
        "综测分数": academicCellValue(r,"综测分数"),
        "综测班级排名": r["综测班级排名"],
        "综测排名百分比": r["综测排名百分比"]
      };
    });
  });
  /* 学籍信息兜底：学号匹配到学生主档时补全空白的 学院/年级/班级/姓名 */
  const allStudents = (typeof students !== "undefined") ? students : (window.students || []);
  allStudents.forEach(s => {
    const sid = String(s.id);
    if(map[sid]){
      const o = map[sid];
      if(!o.base["姓名"]) o.base["姓名"] = s.name || "";
      if(!o.base["学院"]) o.base["学院"] = s.dept || "";
      if(!o.base["年级"]) o.base["年级"] = (typeof classGrade === "function") ? classGrade(s.cls) : "";
      if(!o.base["班级"]) o.base["班级"] = s.cls || "";
      if(!o.base["学号"]) o.base["学号"] = sid;
    }
  });
  const sids = Object.keys(map).sort((a,b) => {
    const oa = map[a], ob = map[b];
    const ca = oa.base["班级"]||"", cb = ob.base["班级"]||"";
    if(ca !== cb) return ca < cb ? -1 : 1;
    return a < b ? -1 : 1;
  });
  const rowsOut = sids.map(sid => {
    const o = map[sid];
    const row = [ o.base["学院"]||"", o.base["年级"]||"", o.base["班级"]||"", o.base["学号"]||"", o.base["姓名"]||"" ];
    terms.forEach(t => {
      const c = o.per[t.term] || {};
      row.push((c["综测分数"]!=null && c["综测分数"]!=="") ? formatAcademicDisplay(c["综测分数"],"num2") : "");
      row.push((c["综测班级排名"]!=null && c["综测班级排名"]!=="") ? String(c["综测班级排名"]) : "");
      row.push((c["综测排名百分比"]!=null && c["综测排名百分比"]!=="") ? formatAcademicDisplay(c["综测排名百分比"],"percent2") : "");
    });
    return row;
  });
  const fn = "综测详情_" + terms.map(t => t.term).join("_") + ".xlsx";
  downloadXlsxFile("综测详情", [headers].concat(rowsOut), fn);
  if(typeof showToast === "function") showToast("已导出 "+ rowsOut.length +" 名学生综测详情","ok");
}

function renderAcademicEditTable(id, rows){
  const t = academicTermById(id);
  if(!t) return "";
  const list = (rows || t.rows || []);
  if(!list.length){
    return '<tr><td colspan="'+ (ACADEMIC_FIELDS.length + 2) +'" class="empty">该学期暂无成绩数据。点击「下载导入模板」取得 Excel 模板，按格式填入后通过「导入」上传，或逐行点击右上「新增信息」录入。</td></tr>';
  }
  return list.map((r, idx) => {
    const cells = ACADEMIC_FIELDS.map(f => { const _v = academicCellValue(r, f); const _fmt = ACADEMIC_FORMAT_LABEL[ACADEMIC_FIELD_TYPE_BY_KEY[f]] || ""; const _disp = formatAcademicDisplay(_v, ACADEMIC_FIELD_TYPE_BY_KEY[f] || "text"); const _raw = (_v != null ? String(_v) : ''); return '<td><div class="cell" data-tid="'+attr(id)+'" data-rid="'+attr(r._rid)+'" data-k="'+attr(f)+'" title="'+attr(_fmt ? _fmt + ' | 原始值：' + _raw : _raw)+'">'+esc(_disp != null ? String(_disp) : '')+'</div></td>'; }).join("");
    const cbTd = '<td style="text-align:center"><input type="checkbox" class="ae-row-cb" data-rid="'+attr(r._rid)+'" title="选中以批量删除"></td>';
    return '<tr data-rid="'+attr(r._rid)+'">'+ cbTd + cells +'<td style="text-align:center;white-space:nowrap"><a class="lk" onclick="openAcademicRowForm('+Number(id)+','+jsArg(r._rid)+')">编辑</a>　<a class="lk danger" onclick="academicRowDelete('+Number(id)+','+jsArg(r._rid)+')">删除</a></td></tr>';
  }).join("");
}
/* 【2026-07-27 任务】表格列宽自适应新字段；行内 input 加 title 显示该字段的格式说明 */
function academicRebuildTable(id){
  const t = academicTermById(id);
  const wrap = document.getElementById("aeTableWrap");
  if(!wrap || !t) return;
  const ths = ACADEMIC_FIELDS.map(f => '<th title="'+ (ACADEMIC_FORMAT_LABEL[ACADEMIC_FIELD_TYPE_BY_KEY[f]] || "") +'">'+ ACADEMIC_FIELD_LABEL_BY_KEY[f] +'</th>').join("");
  /* 铁律：分页切片（仅渲染当前页行）+ 分页条 */
  const visRows = (t.rows||[]).filter(r => r.__hit !== false);
  const fk = (document.getElementById("aeKw")?document.getElementById("aeKw").value:"") + '|' + JSON.stringify(readMulti("aeDept")) + '|' + JSON.stringify(readMulti("aeMajor")) + '|' + JSON.stringify(readMulti("aeGrade")) + '|' + JSON.stringify(readMulti("aeCls"));
  const info = pagerSlice('ae_'+id, visRows, fk);
  const selectAllTh = '<th style="width:42px;text-align:center"><input type="checkbox" title="全选当前页" onchange="academicToggleSelectAll('+Number(id)+')"></th>';
  wrap.innerHTML = '<table><thead><tr>'+ selectAllTh + ths +'<th style="width:120px">操作</th></tr></thead><tbody id="aeTbody">'+ renderAcademicEditTable(id, info.slice) +'</tbody></table>' + renderGenericPager('ae_'+id, info, 'aeJump_'+id);
  academicSyncSelection();
}

/* 学期切换：顶部「查看学期」下拉选择当前学期 */
