/* 学生导入统一使用真实上传文件解析，字段键与下载模板的中文表头一致。 */
const STU_IMPORT_MAX_FILE_BYTES=5*1024*1024;
const STU_IMPORT_MAX_ROWS=2000;
function stuImportFileError(fileObj){
  if(!fileObj) return "请先选择文件";
  if(fileObj.size>STU_IMPORT_MAX_FILE_BYTES) return "文件超过 5 MB，请拆分后再导入";
  if(!/\.(xlsx|xls|csv)$/i.test(fileObj.name||"")) return "仅支持 .xlsx、.xls 或 .csv 文件";
  return "";
}
async function stuImportParse(fileObj){
  const hints=[];STU_IMPORT_FIELDS.forEach(function(field){hints.push(field[0],field[1]);(STU_IMPORT_ALIASES[field[0]]||[]).forEach(function(alias){hints.push(alias);});});
  const rows=await parseWorkbookToRows(fileObj,hints);
  // 系统模板会在数据区末尾附带以「※」开头的说明行，不能将其当作学生记录校验。
  return rows.filter(function(row){ return !/^※/.test(String(row["学号"]||"").trim()); });
}
function stuImportEnumIssues(row){return importEnumIssues("学生管理",row);}
function stuImportValidate(rows,mapping,mode){
  mode=mode||"add";
  const errors=[]; const requiredMap=mapping.filter(m=>STU_IMPORT_FIELDS.find(f=>f[0]===m.sysKey && f[2]));
  const ok=[];
  const existIds=new Set(students.map(s=>s.id));
  const idCounts=new Map();
  rows.forEach(function(r){
    const id=String(r["学号"]||"").trim();
    if(id) idCounts.set(id,(idCounts.get(id)||0)+1);
  });
  rows.forEach((r,i)=>{
    r=Object.assign({},r);
    const rowErrs=[];
    /* 第 3 步已将 Excel 原列转换为固定系统字段，校验必须读取系统字段而非原表头。 */
    requiredMap.forEach(m=>{ if(!String(r[m.sysLabel]||"").trim()) rowErrs.push({field:m.sysLabel,msg:"必填字段为空"}); });
    const cls=String(r["班级"]||"").trim();
    if(cls && !studentClassRecord(cls)){
      const missingHierarchy=["学院","专业","年级"].filter(function(field){return !String(r[field]||"").trim();});
      if(missingHierarchy.length) rowErrs.push({field:"班级",msg:"班级未维护；自动添加新班级需同时填写："+missingHierarchy.join("、")});
    }
    stuImportEnumIssues(r).forEach(function(issue){rowErrs.push(issue);});
    const id=String(r["学号"]||"").trim();
    if(id && idCounts.get(id)>1) rowErrs.push({field:"学号",msg:"导入文件内学号重复"});
    const gender=String(r["性别"]||"").trim();
    if(gender && !STU_GENDERS.includes(gender)) rowErrs.push({field:"性别",msg:"取值必须是：男 / 女"});
    const idcard=String(r["身份证号"]||"").trim();
    if(idcard && !studentIdentityInfo(idcard)) rowErrs.push({field:"身份证号",msg:"证件号码格式、出生日期或校验码不正确；支持内地身份证、港澳台居民居住证及港澳台身份证号"});
    studentImportDateFields(r).forEach(function(item){
      if(item.result.error)rowErrs.push({field:item.field,msg:item.result.error});
      else r[item.field]=item.result.value;
    });
    if(mode==="add"){
      if(id && existIds.has(id)) rowErrs.push({field:"学号",msg:"学号已存在（与现有数据冲突）"});
    } else if(mode==="cover"){
      if(id && !existIds.has(id)) rowErrs.push({field:"学号",msg:"学号不存在（无法覆盖）"});
    }
    // both 模式：学号无论是否存在均允许
    if(rowErrs.length===0) ok.push(r);
    else errors.push({row:i+2,field:rowErrs.map(e=>e.field).join("、"),msg:rowErrs.map(e=>e.msg).join("；"),data:r});
  });
  return {ok,errors};
}
function stuImport(){
  const steps=["选择导入文件","确认导入信息","字段映射","校验 & 导入"];
  const S={curStep:0,fileObj:null,rows:[],rawRows:[],headers:[],mapping:[],errors:[],okCount:0,skipCount:0,mode:"add",busy:false,validating:false};
  const owner=document.createElement("span");owner.hidden=true;owner.dataset.studentImportOwner="";
  window.__studentImportState=S;
  function isCurrent(){return window.__studentImportState===S&&owner.parentNode===$("#modalBody")&&$("#mask").classList.contains("show");}
  function busyControls(){
    if(!isCurrent())return;
    document.querySelectorAll('#modalFoot button[onclick="stuImportNext()"],#modalFoot #stuImpGoBtn').forEach(function(button){button.disabled=S.busy||S.validating||(S.curStep===0&&!S.fileObj);});
    document.querySelectorAll('#modalFoot button[onclick="stuImportPrev()"]').forEach(function(button){button.disabled=S.busy;});
  }

  function stepBar(){
    return `<div class="flow" style="margin-bottom:18px">
      ${steps.map((s,i)=>{
        const dotCls=i<S.curStep?'done':(i===S.curStep?'cur':'');
        const capCls=i<S.curStep?'done':(i===S.curStep?'cur':'');
        const lnCls=i<S.curStep?'done':'';
        const ln=i<steps.length-1?`<div class="ln ${lnCls}"></div>`:'';
        return `<div class="step"><div class="dot ${dotCls}">${i<S.curStep?'✓':i+1}</div><div class="cap ${capCls}">${s}</div></div>${ln}`;
      }).join('')}
    </div>`;
  }
  function tplToolbar(){
    return `<div class="import-toolbar">
      <a class="import-link" href="javascript:;" onclick="stuImportTemplate()">点击下载导入模板</a>
      <span class="sep">·</span>
      <a class="import-rule-link" href="javascript:;" onclick="stuImportShowRule()">点击查看导入规则</a>
    </div>`;
  }
  function step1Html(){
    const fileInfo=S.fileObj?`<div class="import-file-info">
      <span style="color:#12805c;font-size:17px">📄</span>
      <span class="fn">${S.fileObj.name}</span>
      <span class="fs">${(S.fileObj.size/1024).toFixed(1)} KB</span>
      <span class="re" onclick="stuImportResetFile()">✕ 重新选择</span>
    </div>`:'';
    return stepBar()
      + tplToolbar()
      + `<div class="import-drop" id="stuImportDrop" onclick="$('#stuImportFile').click()">
          <div class="ico">📁</div>
          <div class="t1">点击或将文件拖拽到这里导入</div>
          <div class="t2">支持扩展名：.xlsx、.xls、.csv</div>
          <input type="file" id="stuImportFile" style="display:none" accept=".xlsx,.xls,.csv">
        </div>`
      + fileInfo
      + `<div class="field" style="margin-top:12px"><label><span style="color:#d6453d">*</span> 导入方式</label>
          <div class="import-mode-row" id="stuImportMode">
            <label class="mode-item checked"><input type="radio" name="stuImportMode" value="add" checked onchange="stuImportModeChange(this)"> <span class="ml">增加记录</span><span class="desc">只增加新的记录，已存在的记录不变</span></label>
            <label class="mode-item"><input type="radio" name="stuImportMode" value="cover" onchange="stuImportModeChange(this)"> <span class="ml">覆盖记录</span><span class="desc">只对存在的记录进行更新</span></label>
            <label class="mode-item"><input type="radio" name="stuImportMode" value="both" onchange="stuImportModeChange(this)"> <span class="ml">增加+覆盖记录</span><span class="desc">不存在的新增，存在的更新</span></label>
          </div>
        </div>`
      + `<div class="import-required"><b>必填字段：</b>学号、姓名、班级、学籍状态。民族、政治面貌只能使用系统现有选项；学籍状态必须使用系统现有选项。发现非标准写法时，系统会给出近似候选，须人工逐项确认后才会修正。已维护班级自动匹配学院、专业、年级等信息；未维护班级需同时提供学院、专业、年级，导入时可确认自动添加到基础数据维护。文件大小不超过 5 MB，单次不超过 2000 条。</div>`;
  }
  function step2Html(){
    return stepBar()
      + tplToolbar()
      + `<div class="tip">已识别 <b>${S.rawRows.length}</b> 行数据、<b>${S.headers.length}</b> 个 Excel 表头。请确认导入方式与数据预览，下一步设置字段映射。</div>`
      + `<div class="import-preview"><div class="ph"><b>数据预览</b><span>前 3 行</span></div><div style="max-height:220px;overflow:auto"><table><thead><tr>${S.headers.map(h=>`<th>${esc(h)}</th>`).join('')}</tr></thead><tbody>${S.rawRows.slice(0,3).map(r=>`<tr>${S.headers.map(h=>`<td>${esc(r[h]||'')}</td>`).join('')}</tr>`).join('')}</tbody></table></div></div>`;
  }
  function step3Html(){
    return stepBar()
      + tplToolbar()
      + `<div style="display:flex;justify-content:space-between;align-items:center;margin-top:4px">
          <div style="font-size:13px;color:var(--text);font-weight:600">📋 已自动识别 <span style="color:var(--primary)">${S.rawRows.length}</span> 行数据，请确认字段映射</div>
          <button type="button" class="btn btn-ghost btn-sm" onclick="$('#stuImportFile').click()">📤 重新上传</button>
          <input type="file" id="stuImportFile" style="display:none" accept=".xlsx,.xls,.csv">
        </div>`
      + `<div class="tip" style="margin-top:12px"><b>字段映射：</b>左侧系统字段固定，右侧选择 Excel 列（表头）。带 * 的字段必须映射。</div><table class="import-field-table">
          <thead><tr><th style="width:42%">系统字段</th><th style="width:46%">Excel 列（表头）</th><th style="width:12%;text-align:center">必填</th></tr></thead>
          <tbody>${S.mapping.map((m,i)=>{
            const opts=`<option value="">不导入</option>`+S.headers.map(h=>`<option value="${attr(h)}" ${h===m.excelCol?'selected':''}>${esc(h)}</option>`).join('');
            return `<tr>
              <td><input class="in" value="${attr(m.sysLabel)}" readonly style="background:#f7fafa"></td>
              <td><select class="in" onchange="stuImportMapChange(${i},this.value)">${opts}</select></td>
              <td style="text-align:center;color:#d6453d;font-weight:700">${m.required?'*':''}</td>
            </tr>`;
          }).join('')}</tbody>
        </table>`
      + `<div class="import-preview">
          <div class="ph"><b>数据预览</b><span>前 3 行（共 ${S.rawRows.length} 行）</span></div>
          <div style="max-height:200px;overflow:auto">
            <table style="width:100%;border-collapse:collapse;font-size:13px">
              <thead><tr>${S.mapping.map(m=>`<th style="background:#f7fafa;padding:7px 10px;text-align:left;font-weight:600;color:var(--muted);border-bottom:1px solid var(--line);position:sticky;top:0">${esc(m.sysLabel)}</th>`).join('')}</tr></thead>
              <tbody>${S.rawRows.slice(0,3).map(r=>`<tr>${S.mapping.map(m=>`<td style="padding:7px 10px;border-bottom:1px solid var(--line);color:var(--text)">${esc(r[m.excelCol]||'')}</td>`).join('')}</tr>`).join('')}</tbody>
            </table>
          </div>
        </div>`;
  }
  function step4Html(){
    return stepBar()
      + tplToolbar()
      + `<div class="import-progress">
          <div class="pg-head"><b>正在校验数据…</b><span id="stuImpPgNum">0 / ${S.rows.length}</span></div>
          <div class="pg-bar"><div class="pg-fill" id="stuImpPgFill"></div></div>
          <div class="pg-status" id="stuImpPgStatus">已读取表头，正在逐行校验必填项与数据格式…</div>
        </div>`
      + `<div class="import-summary" id="stuImpSummary" style="display:none">
          <div class="kpi total"><div class="n" id="kTotal">0</div><div class="l">总行数</div></div>
          <div class="kpi ok"><div class="n" id="kOk">0</div><div class="l">校验通过</div></div>
          <div class="kpi fail"><div class="n" id="kFail">0</div><div class="l">校验失败</div></div>
          <div class="kpi skip"><div class="n" id="kSkip">0</div><div class="l">将跳过</div></div>
        </div>`
      + `<div id="stuImpErrors" style="display:none"></div>`;
  }
  function step5Html(){
    const err=S.errors.length;
    const total=S.rows.length;
    const ok=S.okCount;
    return stepBar()
      + tplToolbar()
      + (err===0
        ? `<div class="import-finish"><div class="ico">✅</div><div class="t1">导入完成</div><div class="t2">已成功导入 ${ok} 条学生数据，可前往学生信息管理查看</div></div>`
        : `<div class="import-finish"><div class="ico">⚠️</div><div class="t1">部分导入完成</div><div class="t2">共 ${total} 条数据，成功 ${ok} 条，失败 ${err} 条（原因详见下方）</div></div>`)
      + `<div class="import-summary" style="margin-top:18px">
          <div class="kpi total"><div class="n">${total}</div><div class="l">总行数</div></div>
          <div class="kpi ok"><div class="n">${ok}</div><div class="l">成功导入</div></div>
          <div class="kpi fail"><div class="n">${err}</div><div class="l">失败行</div></div>
          <div class="kpi skip"><div class="n">${S.skipCount}</div><div class="l">已跳过</div></div>
        </div>`
      + (err>0?`<div class="import-errors" style="margin-top:18px">
          <div class="eh"><span>错误清单（最多展示 ${Math.min(err,50)} 行）</span><span style="color:var(--muted);font-weight:400">失败原因：必填项缺失 / 格式错误 / 与现有数据冲突</span></div>
          <table>
            <thead><tr><th>行号</th><th>错误字段</th><th>错误描述</th><th>学号</th><th>姓名</th></tr></thead>
            <tbody>${S.errors.slice(0,50).map(e=>`<tr><td>第 ${esc(e.row)} 行</td><td>${esc(e.field)}</td><td>${esc(e.msg)}</td><td>${esc((e.data&&e.data["学号"])||'—')}</td><td>${esc((e.data&&e.data["姓名"])||'—')}</td></tr>`).join('')}</tbody>
          </table>
        </div>
        <div style="margin-top:14px;padding:12px 14px;background:#fff8e6;border:1px solid #f5d77f;border-radius:8px;font-size:13px;color:#7a5d12;line-height:1.7">
          💡 <b>建议处理方式：</b>① 点击下方"下载错误数据"按钮，将失败行导出为 CSV；② 在原文件中修正后，再次上传；③ 确认无误后点击"完成"关闭弹窗。
        </div>`:'');
  }

  function render(initial){
    if(!initial&&!isCurrent())return;
    let body='', foot='';
    if(S.curStep===0){
      body=step1Html();
      foot=`<button class="btn btn-ghost" onclick="closeModal()">取消</button>
            <button class="btn btn-primary" onclick="stuImportNext()" ${S.fileObj?'':'disabled style="opacity:.5;cursor:not-allowed"'}>下一步 →</button>`;
    } else if(S.curStep===1){
      body=step2Html();
      foot=`<button class="btn btn-ghost" onclick="stuImportPrev()">← 上一步</button>
            <button class="btn btn-primary" onclick="stuImportNext()">下一步 →</button>`;
    } else if(S.curStep===2){
      body=step3Html();
      foot=`<button class="btn btn-ghost" onclick="stuImportPrev()">← 上一步</button>
            <button class="btn btn-primary" onclick="stuImportNext()">校验数据 →</button>`;
    } else if(S.curStep===3){
      body=S.imported?step5Html():step4Html();
      foot=S.imported
        ? `<button class="btn btn-ghost" onclick="stuImportDownloadErr()" ${S.errors.length?'':'disabled style="display:none"'}>📥 下载错误数据</button><button class="btn btn-primary" onclick="closeModal()">完成</button>`
        : `<button class="btn btn-ghost" onclick="stuImportPrev()">← 上一步</button><button class="btn btn-primary" onclick="stuImportNext()" id="stuImpGoBtn" disabled style="opacity:.5;cursor:not-allowed">确认导入 →</button>`;
    } else {
      body=step5Html();
      foot=`<button class="btn btn-ghost" onclick="stuImportDownloadErr()" ${S.errors.length?'':'disabled style="display:none"'}>📥 下载错误数据</button>
            <button class="btn btn-ghost" onclick="closeModal()">关闭</button>
            <button class="btn btn-primary" onclick="closeModal()">完成</button>`;
    }
    $("#modalTitle").textContent="导入";
    $("#modalBody").innerHTML=body;
    $("#modalBody").appendChild(owner);
    $("#modalFoot").innerHTML=foot;
    $("#mask").classList.add("show"); $("#modal").classList.add("show");
    // 文件变化绑定
    const f=$("#stuImportFile");
    if(f){
      f.onchange=function(){
        if(this.files && this.files[0]){
          selectImportFile(this.files[0]);
        }
      };
    }
    bindDrop();
    if(S.curStep===3&&!S.imported) runValidateAnim();
    busyControls();
  }

  function selectImportFile(file){
    if(S.busy||S.validating)return;
    Object.assign(S,{fileObj:file,curStep:0,rows:[],rawRows:[],headers:[],mapping:[],errors:[],okRows:[],okCount:0,skipCount:0,imported:false});
    render();
  }
  function bindDrop(){
    const d=$("#stuImportDrop"); if(!d) return;
    d.ondragover=e=>{e.preventDefault();d.classList.add("over");};
    d.ondragleave=()=>d.classList.remove("over");
    d.ondrop=e=>{
      e.preventDefault(); d.classList.remove("over");
      const f=e.dataTransfer.files&&e.dataTransfer.files[0];
      if(f)selectImportFile(f);
    };
  }

  function runValidateAnim(){
    const total=S.rows.length;
    const fill=$("#stuImpPgFill"), num=$("#stuImpPgNum"), status=$("#stuImpPgStatus");
    if(!fill) return;
    S.validating=true;
    status.textContent="正在校验学生数据…";
    setTimeout(()=>{
      if(!isCurrent())return;
      // 跑校验
      const {ok,errors}=stuImportValidate(S.rows,S.mapping,S.mode);
      S.validating=false;
      fill.style.width="100%";num.textContent=total+" / "+total;
      S.okCount=ok.length; S.errors=errors; S.okRows=ok;
      // 计算将跳过（学号已存在/重复）的行数
      S.skipCount=S.errors.filter(e=>/已存在/.test(e.msg)).length;
      $("#kTotal").textContent=total;
      $("#kOk").textContent=ok.length;
      $("#kFail").textContent=S.errors.length;
      $("#kSkip").textContent=S.skipCount;
      $("#stuImpSummary").style.display="";
      // 错误清单
      if(S.errors.length){
        const enumErrorCount=S.errors.filter(function(error){return /民族|政治面貌|学籍状态/.test(error.field||"")&&/不是系统现有/.test(error.msg||"");}).length;
        $("#stuImpErrors").innerHTML=(enumErrorCount?`<div class="tip" style="margin:12px 0;border-color:#efb1ac;background:#fff5f4;color:#9f2f28">⚠️ 检测到 <b>${enumErrorCount}</b> 行民族、政治面貌或学籍状态不是系统现有选项。下列失败行不会写入，请根据学号、姓名和非法值修正后重新导入。</div>`:"")+`<div class="import-errors">
          <div class="eh"><span>错误清单（${S.errors.length} 条）</span><span style="color:var(--muted);font-weight:400">可下载后修正再上传</span></div>
          <table>
            <thead><tr><th>行号</th><th>错误字段</th><th>错误描述</th><th>学号</th><th>姓名</th></tr></thead>
            <tbody>${S.errors.slice(0,10).map(e=>`<tr><td>第 ${esc(e.row)} 行</td><td>${esc(e.field)}</td><td>${esc(e.msg)}</td><td>${esc((e.data&&e.data["学号"])||'—')}</td><td>${esc((e.data&&e.data["姓名"])||'—')}</td></tr>`).join('')}</tbody>
          </table>
        </div>`;
        $("#stuImpErrors").style.display="";
      }
      status.textContent="校验完成，请点击下一步查看结果";
      $("#stuImpGoBtn").disabled=false;
      $("#stuImpGoBtn").style.opacity="";
      $("#stuImpGoBtn").style.cursor="";
    },0);
  }

  // 暴露给弹窗内联事件
  window.stuImportTemplate=stuImportTemplate;
  window.stuImportNext=async function(){
    if(!isCurrent()||S.busy||S.validating||S.imported)return;
    S.busy=true;busyControls();
    try{
    if(S.curStep===0){
      if(!S.fileObj){ alert("请先选择文件"); return; }
      const fileError=stuImportFileError(S.fileObj);
      if(fileError){ alert(fileError); return; }
      try{ S.rawRows=await stuImportParse(S.fileObj); }
      catch(e){ if(isCurrent())alert("读取失败："+(e.message||e)); return; }
      if(!isCurrent())return;
      if(!S.rawRows.length){ alert("文件中没有可读取的数据行。"); return; }
      if(S.rawRows.length>STU_IMPORT_MAX_ROWS){ alert("单次导入不能超过 "+STU_IMPORT_MAX_ROWS+" 条，请拆分后再导入。"); return; }
      S.headers=Object.keys(S.rawRows.reduce(function(all,row){Object.keys(row).forEach(function(key){all[key]=1;});return all;},{}));
      S.mapping=STU_IMPORT_FIELDS.map(function(f){
        const candidates=[f[1],f[0]].concat(STU_IMPORT_ALIASES[f[0]]||[]).map(smartHeader);
        const excelCol=S.headers.find(function(header){return candidates.indexOf(smartHeader(header))>=0;})||"";
        return {sysKey:f[0],sysLabel:f[1],excelCol:excelCol,required:f[2]};
      });
      S.curStep=1;
    } else if(S.curStep===1){
      S.curStep=2;
    } else if(S.curStep===2){
      const missing=S.mapping.filter(function(m){return m.required&&!m.excelCol;});
      const duplicate=S.mapping.filter(function(m,index){return m.excelCol&&S.mapping.some(function(other,otherIndex){return otherIndex<index&&other.excelCol===m.excelCol;});});
      if(missing.length||duplicate.length){showToast(missing.length?"请映射必填字段："+missing.map(function(m){return m.sysLabel;}).join("、"):"同一 Excel 表头不能重复映射","error");return;}
      S.rows=importWizardToRows(S.rawRows,S.mapping);
      const smartMatch=await importConfirmApproximateMatches("学生管理",S.rows,S.mapping.map(function(m){return {key:m.sysLabel,label:m.sysLabel};}));
      if(!isCurrent()||!smartMatch.confirmed)return;
      S.curStep=3;
    } else if(S.curStep===3){
      // 已维护班级先按权威关系回填；未维护班级保留导入层级，确认后自动建立基础数据。
      const rows=(S.okRows||[]).map(normalizeStudentImportRowByClass);
      if(!rows.length){ S.imported=true; render(); return; }
      const pendingStudents=rows.map(function(r){return {
        id:r["学号"],dept:r["学院"],major:r["专业"],grade:r["年级"],cls:r["班级"]||"",counsel:r["辅导员"]||"",level:r["学历"]||"",length:r["学制"]||"",enrollType:r["招生类别"]||"",deptCode:"",majorCode:""
      };});
      if(!confirmAndAddMissingStudentBasicData(pendingStudents,"学生导入")) return;
      const progress=window.WorkbenchProgress&&WorkbenchProgress.begin({title:'学生信息导入',message:'正在写入 '+rows.length+' 条学生数据…'});
      try{
        if(progress)progress.update(25,'正在写入 '+rows.length+' 条学生数据…');
        if(writeImportedRows(rows,S.mode)===false){if(progress)progress.cancel();return;}
        if(progress)progress.update(85,'正在确认学生数据已经完整保存…');
        if(window.workbench&&workbench.legacy&&workbench.legacy.flushStore)await workbench.legacy.flushStore();
        S.imported=true;
        if(progress)progress.succeed('学生信息导入完成：成功写入 '+rows.length+' 条');
        render();
      }catch(error){if(progress)progress.fail('学生信息导入失败：'+(error.message||error));showToast('学生信息导入失败：'+(error.message||error),'error');return;}
    }
    render();
    }finally{S.busy=false;busyControls();}
  };
  window.stuImportPrev=function(){ if(!S.busy&&!S.validating&&S.curStep>0){ S.curStep--; render(); } };
  window.stuImportResetFile=function(){ selectImportFile(null); };
  window.stuImportMapChange=function(i,val){
    S.mapping[i].excelCol=val;
  };
  window.stuImportModeChange=function(radio){
    S.mode=radio.value;
    const items=document.querySelectorAll('.import-mode-row .mode-item');
    items.forEach(l=>l.classList.remove('checked'));
    radio.parentElement.classList.add('checked');
  };
  window.stuImportShowRule=function(){
    alert("导入规则：\n1. 必填：学号、姓名、班级、学籍状态。\n2. 民族、政治面貌、学籍状态只能使用系统现有选项；发现非标准或近似写法时会弹出候选修正，必须人工逐项确认，系统不会静默替换；保留非法值的行不会导入。\n3. 学籍状态选项："+STU_STATUS.join(" / ")+"。\n4. 已维护班级的学院、专业、年级等信息按基础数据自动匹配；未维护班级需同时提供学院、专业、年级，校验后可确认自动添加到基础数据维护。\n5. 学号不可与现有数据重复；如需覆盖请选择「覆盖记录」或「增加+覆盖记录」。\n6. 证件号码支持内地身份证、港澳台居民居住证及港澳台身份证号；大陆身份证可补出生日期和性别，港澳台居住证可补出生日期。出生日期、入学日期支持 2026年10月6日、20261006、2026-10-06、2026/10/6、2026.10.6 及 Excel 日期，统一保存为 YYYYMMDD。无效或年月日顺序不明确的日期须修正后导入。\n7. 单次不超过 2000 条，文件大小不超过 5 MB。");
  };
  window.stuImportDownloadErr=function(){
    if(!S.errors.length) return;
    stuImportErrorsCSV(S.errors);
  };
  openModal("导入","",null);
  render(true);
}
const STU_EXPORT_FIELDS=[
  ["id","学号",true],["name","姓名",true],["usedName","曾用名",true],["gender","性别",true],["ethnic","民族",true],
  ["birth","出生日期",true],["idcard","身份证号",true],["examNo","考生号",true],["political","政治面貌",true],
  ["photo","学籍照片",true,function(s){return s.photo&&(s.photo.name||s.photo.id)||"";}],["idPhoto","证件照",true,function(s){return s.idPhoto&&(s.idPhoto.name||s.idPhoto.id)||"";}],
  ["disab","残疾情况",true],["disabCert","残疾人证 PDF",true,function(s){return s.disabCert?"已上传":"";}],["cadre","当前班级干部任职",true],["cadreHistory","历史班级干部任职",true],
  ["dept","学院",true],["major","专业",true],["grade","年级",true],["cls","班级",true],
  ["counsel","辅导员",true],["level","学历",true],["length","学制",true],["enrollType","招生类别",true],
  ["source","生源地",true],["enroll","入学日期",true],["graduateYear","毕业年份",true],["transferNote","转专业备注",true],
  ["status","学籍状态",true,function(s){return stuStatusLabel(s.status||"");}],["statusNote","学籍异动备注",true],
  ["statusAttachment","学籍异动单（图片）",true,function(s){return s.statusAttachment&&(s.statusAttachment.name||s.statusAttachment.id)||"";}],
  ["phone","手机号",true],["qq","QQ号",true],["wechat","微信号",true],
  ["address","家庭住址",true],["fatherName","父亲姓名",true],["fatherPhone","父亲电话",true],
  ["motherName","母亲姓名",true],["motherPhone","母亲电话",true],
  ["emgName","紧急联系人",true],["emgRel","紧急联系人关系",true],["emgPhone","紧急联系人电话",true],
  ["accom","住宿情况",true],["building","楼栋",true],["room","房间号",true],["bed","床位",true],
];
function stuExport(){
  const checkBoxes=STU_EXPORT_FIELDS.map(([k,l,checked])=>`<label style="display:flex;align-items:center;gap:6px;padding:4px 0;cursor:pointer"><input type="checkbox" class="stu-export-field" data-field="${k}" ${checked?'checked':''}> ${l}</label>`).join('');
  openModal("学生信息导出",
    `<div style="display:flex;gap:12px;align-items:center;margin-bottom:12px">
       <label>模板：</label><select class="in"><option>学生花名册</option></select>
       <button class="btn btn-primary btn-sm">＋ 新增</button>
     </div>
     <div style="border:1px solid var(--border);border-radius:8px;padding:12px">
       <div style="font-weight:700;margin-bottom:8px">字段（拖拽可排序）：</div>
       <div style="display:grid;grid-template-columns:repeat(4,1fr);gap:4px 12px">${checkBoxes}</div>
     </div>`,
    null);
  $("#modalFoot").innerHTML='<button class="btn btn-ghost" onclick="closeModal()">取消</button><button class="btn btn-primary" onclick="stuExportDo()">导出</button>';
}
function stuPhotoImportKey(value){return studentIdentityNumber(value).replace(/[()]/g,"");}
function stuPhotoImportFileBase(fileName){return String(fileName||"").replace(/\.[^.]+$/,"").trim();}
function stuPhotoUnmatchedInfo(fileName,mode){
  const base=stuPhotoImportFileBase(fileName),key=stuPhotoImportKey(base);
  const candidates=students.filter(function(student){
    return [student.id,student.idcard,student.examNo,student.name].some(function(value){
      const token=stuPhotoImportKey(value);
      return token && key.indexOf(token)>=0;
    });
  });
  const student=candidates.length===1?candidates[0]:null;
  return {
    fileName:String(fileName||""),
    studentId:student?String(student.id||""):(mode==="id"?base:""),
    name:student?String(student.name||""):"",
    reason:student?"文件名未严格符合所选命名方式":"未在学生管理中找到对应学生"
  };
}
function stuPhotoImportDetailsHtml(items,kind){
  if(!items.length) return "";
  const title=kind==="unmatched"?"未匹配学生信息":"保存失败文件";
  const color=kind==="unmatched"?"#a15c00":"#b42318";
  const rows=items.map(function(item){
    return '<tr><td>'+esc(item.fileName||"—")+'</td><td>'+esc(item.studentId||"未识别")+'</td><td>'+esc(item.name||"未识别")+'</td><td>'+esc(item.reason||"—")+'</td></tr>';
  }).join("");
  return '<div style="margin-top:10px"><b style="color:'+color+'">'+title+'（'+items.length+'）</b><div class="list-scroll" style="max-height:220px;margin-top:6px"><table><thead><tr><th>照片文件</th><th>学号</th><th>姓名</th><th>原因</th></tr></thead><tbody>'+rows+'</tbody></table></div></div>';
}
function stuPhotoImport(kind){
  const meta=kind==="idPhoto"?{key:"idPhoto",label:"证件照",icon:"🪪"}:{key:"photo",label:"学籍照片",icon:"🖼️"};
  openModal("导入"+meta.label,
    `<div class="tip" style="margin:0 0 12px">${meta.icon} 将按文件名匹配学生并保存为<b>${meta.label}</b>；原有学籍照片和证件照互不覆盖。</div>
     <div style="margin-bottom:12px"><b>照片命名方式：</b>
       <label style="margin-left:8px;cursor:pointer"><input type="radio" name="photoName" value="id" checked> 学号</label>
       <label style="margin-left:8px;cursor:pointer"><input type="radio" name="photoName" value="idcard"> 身份证号</label>
       <label style="margin-left:8px;cursor:pointer"><input type="radio" name="photoName" value="examNo"> 考生号</label>
     </div>
     <div style="border:1px dashed var(--border);border-radius:8px;padding:32px;text-align:center;color:var(--muted);cursor:pointer" onclick="$('#stuPhotoFile').click()">
       <div style="font-size:29px">${meta.icon}</div>
       <div style="margin-top:8px">点击选择${meta.label}文件</div>
       <div style="font-size:12.5px;margin-top:4px">支持 JPG / PNG / WEBP，单张不超过 8MB</div>
       <input type="file" id="stuPhotoFile" style="display:none" accept="image/*" multiple>
     </div>
     <div id="stuPhotoResult" class="tip" style="margin-top:12px">请确保照片文件名与所选的学号、身份证号或考生号一致（考生号请保留前导 0；英文字母不区分大小写，港澳号码的括号可省略），系统将自动匹配并同步至学生画像。号码重复时会提示相关学生，需修正后再导入。</div>`,
    null);
  const file=$('#stuPhotoFile');
  if(file) file.onchange=async function(){
    const mode=(document.querySelector('input[name=photoName]:checked')||{}).value||'id';
    const files=Array.from(file.files||[]);if(!files.length)return;
    const progress=window.WorkbenchProgress&&WorkbenchProgress.begin({title:meta.label+'导入',message:'正在匹配并保存 '+files.length+' 张照片…'});
    let ok=0,fail=0;
    const unmatched=[],failed=[];
    const uploadedPhotos=[],replacedPhotos=[];
    try{
    for(let index=0;index<files.length;index++){
      const f=files[index];
      if(progress)progress.update(Math.max(5,Math.round(index/files.length*80)),'正在处理 '+(index+1)+' / '+files.length+'：'+f.name);
      if(!(/^image\//.test(f.type||"")||/\.(jpg|jpeg|png|gif|webp|bmp)$/i.test(f.name||""))){ fail++; failed.push({fileName:f.name,reason:"不是支持的图片格式"}); continue; }
      if(Number(f.size||0)>8*1024*1024){ fail++; failed.push({fileName:f.name,reason:"超过单张 8MB 限制"}); continue; }
      const key=stuPhotoImportKey(stuPhotoImportFileBase(f.name));
      const matchField=["id","idcard","examNo"].includes(mode)?mode:"id";
      const matches=key?students.filter(function(student){return stuPhotoImportKey(student[matchField])===key;}):[];
      if(matches.length>1){unmatched.push({fileName:f.name,studentId:matches.map(function(student){return student.id;}).join("、"),name:matches.map(function(student){return student.name;}).join("、"),reason:({id:"学号",idcard:"身份证号",examNo:"考生号"}[matchField])+"重复，匹配到多名学生，请修正号码后重新导入"});continue;}
      const s=matches[0];
      if(!s){ unmatched.push(stuPhotoUnmatchedInfo(f.name,mode)); continue; } // 未匹配不阻断其余照片导入
      try{
        const att=await window.workbench.legacy.attachmentUploadFile(f.name,f);
        if(s[meta.key] && typeof s[meta.key]==='object' && s[meta.key].id) replacedPhotos.push(s[meta.key]);
        s[meta.key]={id:att.id, name:att.name, url:att.url, mime:f.type||'application/octet-stream', size:att.size};
        uploadedPhotos.push(s[meta.key]);
        ok++;
      }catch(e){ fail++; failed.push({fileName:f.name,studentId:s.id,name:s.name,reason:"附件保存失败："+(e&&e.message||e||"未知错误")}); } // 单张失败不影响其他张
    }
    try{persistStudents();}catch(error){await deleteAttachmentRefs(uploadedPhotos);throw error;}
    await deleteAttachmentRefs(replacedPhotos);
    if(progress)progress.update(90,'正在确认照片和学生档案已经完整保存…');
    if(window.workbench&&workbench.legacy&&workbench.legacy.flushStore)await workbench.legacy.flushStore();
    let msg=meta.label+'匹配成功 '+ok+' 张，未匹配 '+unmatched.length+' 张';
    if(fail) msg+='，保存失败 '+fail+' 张';
    msg+='，已存入学生档案并同步至学生画像。';
    $('#stuPhotoResult').innerHTML='<div>'+esc(msg)+'</div>'+stuPhotoImportDetailsHtml(unmatched,"unmatched")+stuPhotoImportDetailsHtml(failed,"failed");
    $('#modalFoot').innerHTML='<button class="btn btn-ghost" onclick="closeModal()">关闭</button>';
    if(progress)progress.succeed(meta.label+'导入完成：成功 '+ok+' 张');
    }catch(error){if(progress)progress.fail(meta.label+'导入失败：'+(error.message||error));showToast(meta.label+'导入失败：'+(error.message||error),'error');}
  };
  $('#modalFoot').innerHTML='<button class="btn btn-ghost" onclick="closeModal()">取消</button>';
}
function renderStuDeptStat(list){
  const total=list.length;
  const items=depts.map(d=>`<li onclick="stuFilterByDept('${d}')"><span>${d}</span><span class="num">${list.filter(s=>s.dept===d).length}</span></li>`).join('');
  return '<div class="stu-stat-head" onclick="stuFilterByDept(\'\')">合计('+total+')</div><ul class="stu-stat-list">'+items+'</ul>';
}
function stuFilterByDept(dept){
  const multi = document.querySelector(".zf-query .qf-multi[data-qf='dept']");
  if(!multi) return;
  multi.querySelectorAll(".qf-multi-opt input[type=checkbox]").forEach(function(c){
    c.checked = (dept && c.value === dept);
  });
  if(typeof qfMultiRefresh === "function") qfMultiRefresh(multi);
  stuQuery();
}
