PAGES.student_init=()=>{ if(queryReady("student")) stuRefreshTable(); else stuSyncChkAll(); };
PAGES.student_mine=()=>{
  const sess=window.__NNUZC_SESSION__||{};
  const s = students.find(x=> (sess.studentId && String(x.id)===String(sess.studentId)) || (sess.name && x.name===sess.name)) || students[0];
  if(!s) return '<div class="card">未找到本人信息</div>';
  return '<div style="max-width:880px">'+studentForm(s)+'</div>';
};

/* ============ 班级干部管理 ============
   任职台账是班级干部数据的权威来源；在任与历史任职分别同步到学生主档案。 */
function classOfficerAssessmentLevel(value){
  value=String(value||"").trim();
  if(CLASS_OFFICER_ASSESSMENT_LEVELS.includes(value))return value;
  if(value==="称职")return "良好";
  if(value==="不称职")return "不及格";
  return "";
}
function classOfficerAssessmentNormalizeTerm(term){
  if(!term||typeof term!=="object")return null;
  const name=String(term.term||"").trim();if(!name)return null;
  const rows=Array.isArray(term.rows)?term.rows.map(function(row,index){
    if(!row||typeof row!=="object")return null;
    const studentId=String(row.studentId||"").trim(),position=String(row.position||"").trim();if(!studentId||!position)return null;
    return {id:String(row.id||("coa_"+name+"_"+index+"_"+studentId)),appointmentId:String(row.appointmentId||""),studentId:studentId,position:position,level:classOfficerAssessmentLevel(row.level||row.assessmentLevel),updatedAt:String(row.updatedAt||"")};
  }).filter(Boolean):[];
  return {term:name,rows:rows,createdAt:String(term.createdAt||new Date().toISOString()),updatedAt:String(term.updatedAt||"")};
}
let classOfficerFilter={kw:"",dept:[],major:[],grade:[],cls:[],position:[],status:[]};
let classOfficerAssessmentFilter={kw:"",dept:[],major:[],grade:[],cls:[],position:[],status:[],level:[]};
function classOfficerNormalizeRecord(record,index){
  if(!record||typeof record!=="object")return null;
  const sid=String(record.studentId||record.sid||record.idNumber||"").trim();
  const position=String(record.position||record.post||record.role||"").trim();
  if(!sid||!position)return null;
  const status=/离任|卸任|退出|离职/.test(String(record.status||""))?"已离任":"在任";
  return {
    id:String(record.id||("co_legacy_"+(index||0)+"_"+sid)),studentId:sid,
    position:position,
    startDate:String(record.startDate||record.joinDate||"").trim(),endDate:String(record.endDate||"").trim(),status:status,
    duties:String(record.duties||record.responsibility||"").trim(),note:String(record.note||"").trim(),
    customFieldValues:record.customFieldValues&&typeof record.customFieldValues==="object"&&!Array.isArray(record.customFieldValues)?record.customFieldValues:{},
    createdAt:String(record.createdAt||record.updatedAt||fmtNow()),updatedAt:String(record.updatedAt||record.createdAt||fmtNow())
  };
}
function classOfficerStudentIds(){return Array.from(new Set((classOfficerRecords||[]).map(function(record){return String(record.studentId||"");}).filter(Boolean)));}
function classOfficerStudentRecords(studentId){
  studentId=String(studentId||"");
  return (classOfficerRecords||[]).filter(function(record){return String(record.studentId)===studentId;}).sort(function(a,b){
    return (a.status==="在任"?0:1)-(b.status==="在任"?0:1)||String(b.startDate||b.updatedAt||"").localeCompare(String(a.startDate||a.updatedAt||""),"zh-CN",{numeric:true})||String(a.position||"").localeCompare(String(b.position||""),"zh-CN");
  });
}
function classOfficerSummaryForStudent(studentId,status){
  const student=students.find(function(item){return String(item.id)===String(studentId);});
  return classOfficerStudentRecords(studentId).filter(function(record){return !status||record.status===status;}).map(function(record){
    const meta=[student&&student.cls,record.status].filter(Boolean).join("，");
    return record.position+(meta?("（"+meta+"）"):"");
  }).join("；");
}
function syncClassOfficerStudents(studentIds,options){
  const ids=Array.from(new Set((studentIds||[]).map(function(value){return String(value||"");}).filter(Boolean)));
  let changed=0;
  ids.forEach(function(id){
    const student=students.find(function(item){return String(item.id)===id;});
    if(!student)return;
    const currentSummary=classOfficerSummaryForStudent(id,"在任"),historySummary=classOfficerSummaryForStudent(id,"已离任");
    if(String(student.cadre||"")!==currentSummary){student.cadre=currentSummary;changed++;}
    if(String(student.cadreHistory||"")!==historySummary){student.cadreHistory=historySummary;changed++;}
  });
  if(changed&&(!options||options.persist!==false))persistStudents();
  return changed;
}
function classOfficerAutoEndNonCampus(options){
  const nonCampusIds=new Set((students||[]).filter(function(student){return !isOnCampusStudent(student);}).map(function(student){return String(student.id||"");}).filter(Boolean));
  const endedIds=new Set();
  (classOfficerRecords||[]).forEach(function(record){
    if(record.status!=="在任"||!nonCampusIds.has(String(record.studentId||"")))return;
    record.status="已离任";
    record.endDate=record.endDate||beijingIsoDate();
    record.updatedAt=fmtNow();
    endedIds.add(String(record.studentId));
  });
  if(!endedIds.size)return 0;
  persistClassOfficerRecords();
  syncClassOfficerStudents(Array.from(endedIds),{persist:false});
  if(!options||options.syncAssessments!==false)classOfficerAssessmentSyncAllTerms();
  return endedIds.size;
}
function classOfficerStudentIsManaged(studentId){return classOfficerStudentRecords(studentId).length>0;}
function classOfficerValueOptions(values,current,allLabel){
  const unique=Array.from(new Set((values||[]).map(function(v){return String(v||"").trim();}).filter(Boolean))).sort(function(a,b){return b.localeCompare(a,"zh-CN",{numeric:true});});
  return '<option value="">'+esc(allLabel||"全部")+'</option>'+unique.map(function(value){return '<option value="'+attr(value)+'"'+(value===current?' selected':'')+'>'+esc(value)+'</option>';}).join("");
}
function classOfficerFilteredRecords(){
  const state=classOfficerFilter||{},kw=String(state.kw||"").trim().toLowerCase();
  return (classOfficerRecords||[]).filter(function(record){
    const student=students.find(function(item){return String(item.id)===String(record.studentId);})||{};
    if(kw&&[record.studentId,student.name,student.cls,record.position,record.duties,record.note].join(" ").toLowerCase().indexOf(kw)<0)return false;
    if(!qfMatch(state.dept,student.dept||""))return false;
    if(!qfMatch(state.major,student.major||""))return false;
    if(!qfMatch(state.grade,student.grade||classGrade(student.cls||"")))return false;
    if(!qfMatch(state.cls,student.cls||""))return false;
    if(!qfMatch(state.position,record.position||""))return false;
    if(!qfMatch(state.status,record.status||""))return false;
    return true;
  }).sort(function(a,b){
    const sa=students.find(function(item){return String(item.id)===String(a.studentId);})||{},sb=students.find(function(item){return String(item.id)===String(b.studentId);})||{};
    return (a.status==="在任"?0:1)-(b.status==="在任"?0:1)||String(sa.cls||"").localeCompare(String(sb.cls||""),"zh-CN",{numeric:true})||String(a.position||"").localeCompare(String(b.position||""),"zh-CN")||String(a.studentId||"").localeCompare(String(b.studentId||""),"zh-CN",{numeric:true});
  });
}
function classOfficerRows(list){
  if(!list.length)return '<tr><td colspan="10" class="co-empty">暂无匹配的班级干部任职记录</td></tr>';
  return list.map(function(record){
    const student=students.find(function(item){return String(item.id)===String(record.studentId);})||{};
    const initial=String(student.name||"?").slice(0,1);
    const statusClass=record.status==="在任"?"active":"ended";
    const action=record.status==="在任"?'<a class="lk" href="javascript:;" onclick="classOfficerEnd('+jsArg(record.id)+')">离任</a>':'';
    return '<tr>'
      +'<td><div class="co-student"><span class="co-avatar">'+esc(initial)+'</span><span><b>'+esc(student.name||"未匹配学生")+'</b><small>'+esc(record.studentId)+'</small></span></div></td>'
      +'<td>'+esc(student.dept||"")+'</td><td>'+esc(student.grade||classGrade(student.cls||""))+'</td><td>'+esc(student.cls||"")+'</td>'
      +'<td class="co-position">'+esc(record.position)+'</td><td>'+esc(record.startDate||"—")+'</td><td>'+esc(record.endDate||"—")+'</td>'
      +'<td><span class="co-status '+statusClass+'">'+esc(record.status)+'</span></td><td>'+esc(record.duties||"—")+'</td>'
      +'<td class="co-table-actions"><a class="lk" href="javascript:;" onclick="classOfficerView('+jsArg(record.id)+')">查看</a><a class="lk" href="javascript:;" onclick="classOfficerEdit('+jsArg(record.id)+')">编辑</a>'+action+'<a class="lk danger" href="javascript:;" onclick="classOfficerDelete('+jsArg(record.id)+')">删除</a></td></tr>';
  }).join("");
}
function classOfficerAssessmentTermByName(term){
  term=String(term||"").trim();
  return (classOfficerAssessmentTerms||[]).find(function(item){return item.term===term;})||null;
}
function classOfficerAssessmentEnsureTerm(term){
  term=String(term||"").trim();if(!term)return null;
  let item=classOfficerAssessmentTermByName(term);
  if(!item){item={term:term,rows:[],createdAt:fmtNow(),updatedAt:""};classOfficerAssessmentTerms.push(item);persistClassOfficerAssessmentTerms();}
  return item;
}
function classOfficerAssessmentActiveRecord(row){
  return (classOfficerRecords||[]).find(function(record){return record.status==="在任"&&String(record.id)===String(row&&row.appointmentId);})||null;
}
function classOfficerAssessmentSyncTerm(term){
  const item=classOfficerAssessmentEnsureTerm(term);if(!item)return null;
  const before=JSON.stringify(item.rows||[]),active=(classOfficerRecords||[]).filter(function(record){return record.status==="在任";}),rows=Array.isArray(item.rows)?item.rows:[];
  active.forEach(function(record){
    let row=rows.find(function(value){return String(value.appointmentId)===String(record.id);});
    if(!row)row=rows.find(function(value){return !value.appointmentId&&String(value.studentId)===String(record.studentId)&&String(value.position)===String(record.position);});
    if(!row){row={id:"coa_"+Date.now()+"_"+Math.random().toString(16).slice(2),appointmentId:String(record.id),studentId:String(record.studentId),position:String(record.position),level:"",updatedAt:""};rows.push(row);}
    row.appointmentId=String(record.id);row.studentId=String(record.studentId);row.position=String(record.position);
  });
  item.rows=rows.filter(function(row){return !!classOfficerAssessmentActiveRecord(row)||!!classOfficerAssessmentLevel(row.level);});
  if(before!==JSON.stringify(item.rows)){item.updatedAt=fmtNow();persistClassOfficerAssessmentTerms();}
  return item;
}
function classOfficerAssessmentSyncAllTerms(){
  sortTermsDesc(getTermList()).forEach(function(term){classOfficerAssessmentSyncTerm(term);});
}
function classOfficerAssessmentStats(term){
  const item=classOfficerAssessmentTermByName(term),rows=item&&Array.isArray(item.rows)?item.rows:[];
  const active=rows.filter(function(row){return !!classOfficerAssessmentActiveRecord(row);});
  return {active:active.length,completed:active.filter(function(row){return !!classOfficerAssessmentLevel(row.level);}).length,history:rows.filter(function(row){return !classOfficerAssessmentActiveRecord(row)&&!!classOfficerAssessmentLevel(row.level);}).length};
}
function classOfficerAssessmentStatus(stats){
  if(!stats.active)return "暂无在任班委";
  if(stats.completed===0)return "待考核";
  if(stats.completed<stats.active)return "考核中";
  return "已完成";
}
function classOfficerAssessmentTermRows(terms){
  if(!terms.length)return '<tr><td colspan="5" class="co-empty">请先到“系统管理 &gt; 学期设置”新增学期</td></tr>';
  return terms.map(function(term){
    const stats=classOfficerAssessmentStats(term),status=classOfficerAssessmentStatus(stats);
    return '<tr><td><b>'+esc(term)+'</b></td><td>'+stats.active+' 人</td><td>'+stats.completed+' / '+stats.active+(stats.history?'（另有历史 '+stats.history+' 条）':'')+'</td><td><span class="co-status '+(status==="已完成"?'active':'ended')+'">'+esc(status)+'</span></td><td><a class="lk" href="javascript:;" onclick="classOfficerAssessmentOpen('+jsArg(term)+')">进入考核</a></td></tr>';
  }).join("");
}
function classOfficerAppointmentPane(){
  const all=classOfficerRecords||[],current=all.filter(function(record){return record.status==="在任";}),list=classOfficerFilteredRecords(),info=pagerSlice("class_officer",list,JSON.stringify(classOfficerFilter));
  const cadreCount=new Set(current.map(function(record){return record.studentId;})).size;
  const classCount=new Set(current.map(function(record){const student=students.find(function(item){return String(item.id)===String(record.studentId);});return student&&student.cls;}).filter(Boolean)).size;
  const recordClasses=all.map(function(record){const student=students.find(function(item){return String(item.id)===String(record.studentId);});return student&&student.cls;});
  const recordMajors=all.map(function(record){const student=students.find(function(item){return String(item.id)===String(record.studentId);});return student&&student.major;});
  const positions=Array.from(new Set(all.map(function(record){return record.position;}).filter(Boolean))).sort(function(a,b){return a.localeCompare(b,"zh-CN");});
  return '<div class="class-officer-page">'
    +'<div class="class-officer-head"><div></div><button class="btn btn-primary" onclick="classOfficerAdd()">＋ 新增任职</button></div>'
    +'<div class="co-kpi-grid"><div class="co-kpi"><div class="n">'+current.length+'</div><div class="l">当前在任岗位</div></div><div class="co-kpi"><div class="n">'+cadreCount+'</div><div class="l">当前在任学生</div></div><div class="co-kpi"><div class="n">'+classCount+'</div><div class="l">已覆盖班级</div></div><div class="co-kpi"><div class="n">'+all.filter(function(record){return record.status==="已离任";}).length+'</div><div class="l">历史任职记录</div></div></div>'
    +'<div class="card co-card"><div class="co-toolbar qf-bar" data-page="classOfficerAppointment">'
      +'<div class="co-filter co-keyword"><label>关键字</label><input id="coFilterKw" value="'+attr(classOfficerFilter.kw)+'" placeholder="搜索学号、姓名、班级或职务" onkeydown="if(event.key===\'Enter\')classOfficerApplyFilters()"></div>'
      +'<div class="co-filter"><label>学院</label>'+qfMulti("coDept",[{v:"",l:"全部学院"}].concat(depts.map(function(value){return {v:value,l:value};})),classOfficerFilter.dept)+'</div>'
      +'<div class="co-filter"><label>专业</label>'+qfMulti("coMajor",[{v:"",l:"全部专业"}].concat(Array.from(new Set(majors.concat(recordMajors).filter(Boolean))).map(function(value){return {v:value,l:value};})),classOfficerFilter.major)+'</div>'
      +'<div class="co-filter"><label>年级</label>'+qfMulti("coGrade",[{v:"",l:"全部年级"}].concat(grades.map(function(value){return {v:value,l:value};})),classOfficerFilter.grade)+'</div>'
      +'<div class="co-filter"><label>班级</label>'+qfMulti("coCls",[{v:"",l:"全部班级"}].concat(Array.from(new Set(classes.concat(recordClasses).filter(Boolean))).map(function(value){return {v:value,l:value};})),classOfficerFilter.cls)+'</div>'
      +'<div class="co-filter"><label>职务</label>'+qfMulti("coPosition",[{v:"",l:"全部职务"}].concat(positions.map(function(value){return {v:value,l:value};})),classOfficerFilter.position)+'</div>'
      +'<div class="co-filter"><label>任职状态</label>'+qfMulti("coStatus",[{v:"",l:"全部状态"},{v:"在任",l:"在任"},{v:"已离任",l:"已离任"}],classOfficerFilter.status)+'</div>'
      +'<button class="btn btn-primary btn-sm" onclick="classOfficerApplyFilters()">查询</button><button class="btn btn-ghost btn-sm" onclick="classOfficerResetFilters()">重置</button>'
      +'<div class="co-actions"><button class="btn btn-ghost btn-sm" onclick="classOfficerImport()">⬆ 导入</button><button class="btn btn-ghost btn-sm" onclick="classOfficerExport()">⬇ 导出</button><button class="btn btn-ghost btn-sm" onclick="classOfficerImportTemplate()">下载模板</button></div>'
    +'</div><div class="module-table-wrap co-table">'+table(["学生","学院","年级","班级","职务","任职日期","离任日期","状态","职责说明","操作"],classOfficerRows(info.slice))+'</div>'+renderGenericPager("class_officer",info,"classOfficerJump")+'</div></div>';
}
function classOfficerAssessmentPane(){
  classOfficerAssessmentSyncAllTerms();
  const terms=sortTermsDesc(getTermList());
  if(!Array.isArray(window.classOfficerAssessmentViewTerms))window.classOfficerAssessmentViewTerms=[];
  window.classOfficerAssessmentViewTerms=window.classOfficerAssessmentViewTerms.filter(function(term){return terms.indexOf(term)>=0;});
  const selected=window.classOfficerAssessmentViewTerms,visibleTerms=selected.length?terms.filter(function(term){return selected.indexOf(term)>=0;}):terms;
  return '<div class="card" style="margin-bottom:14px">'
    +'<div class="tip">班委考核按系统学期管理。学期来自“系统管理 &gt; 学期设置”，每学期名单自动同步当前在任班委；离任人员不再参与考核，已完成的历史考核只读保留。</div>'
    +'<div class="ae-bar qf-bar" data-page="classOfficerAssessmentTerms" style="padding:0;border:0;background:transparent"><div class="row1" style="margin-bottom:10px"><div class="filter-item"><label>学期</label>'
    +qfMulti('classOfficerAssessmentViewTerms',[{v:'',l:'全部学期'}].concat(terms.map(function(term){const stats=classOfficerAssessmentStats(term);return {v:term,l:term+'（在任 '+stats.active+' 人）'};})),selected)
    +'</div><button class="btn btn-primary btn-sm" onclick="classOfficerAssessmentApplyTermFilter()">查询</button><button class="btn btn-ghost btn-sm" onclick="classOfficerAssessmentResetTermFilter()">重置</button><button class="btn btn-ghost btn-sm"'+(terms.length?' onclick="openExportClassOfficerAssessmentMulti()"':' disabled')+'>⬇ 导出多学期考核</button><span style="margin-left:auto;font-size:13px;color:var(--muted)">考核等级：优秀、良好、中等、及格、不及格</span></div></div>'
    +'<div class="module-table-wrap table-scroll"><table class="t-table" style="min-width:auto"><thead><tr><th style="width:280px">学期</th><th>在任考核人数</th><th>已考核</th><th>状态</th><th>操作</th></tr></thead><tbody>'+classOfficerAssessmentTermRows(visibleTerms)+'</tbody></table></div></div>';
}
PAGES.classOfficer=function(){
  if(!window.classOfficerSubTab)window.classOfficerSubTab="appointments";
  const pane=window.classOfficerSubTab==="assessment"?classOfficerAssessmentPane():classOfficerAppointmentPane();
  return '<h2 class="ptitle">🎖️ 班级干部管理 <span class="tag">任职台账 · 按学期考核</span></h2>'
    +'<div class="sub">班级干部任职与班委考核平行管理；任职变更自动同步学生档案及各学期考核名单。</div>'
    +'<div class="tabs" role="tablist" style="margin:0 0 12px"><div class="tab '+(window.classOfficerSubTab==="appointments"?'active':'')+'" onclick="switchClassOfficerSubTab(\'appointments\')">🎖️ 任职管理</div><div class="tab '+(window.classOfficerSubTab==="assessment"?'active':'')+'" onclick="switchClassOfficerSubTab(\'assessment\')">📊 班委考核</div></div>'+pane;
};
PAGES.classOfficer_init=function(){};
function switchClassOfficerSubTab(tab){window.classOfficerSubTab=tab==="assessment"?"assessment":"appointments";renderPage("classOfficer");}
function classOfficerAssessmentApplyTermFilter(){window.classOfficerAssessmentViewTerms=readMulti("classOfficerAssessmentViewTerms");renderPage("classOfficer");}
function classOfficerAssessmentResetTermFilter(){window.classOfficerAssessmentViewTerms=[];renderPage("classOfficer");}
function classOfficerAssessmentAllRows(term){
  const item=classOfficerAssessmentTermByName(term);
  return item&&Array.isArray(item.rows)?item.rows.slice():[];
}
function classOfficerAssessmentFilteredRows(term){
  const state=classOfficerAssessmentFilter||{},kw=String(state.kw||"").trim().toLowerCase();
  return classOfficerAssessmentAllRows(term).filter(function(row){
    const record=classOfficerAssessmentActiveRecord(row),student=students.find(function(item){return String(item.id)===String(row.studentId);})||{};
    const status=record?"在任":"已离任（历史考核）",level=row.level||"未考核";
    if(kw&&[row.studentId,student.name,student.dept,student.major,student.grade,student.cls,row.position,status,level].join(" ").toLowerCase().indexOf(kw)<0)return false;
    if(!qfMatch(state.dept,student.dept||""))return false;
    if(!qfMatch(state.major,student.major||""))return false;
    if(!qfMatch(state.grade,student.grade||classGrade(student.cls||"")))return false;
    if(!qfMatch(state.cls,student.cls||""))return false;
    if(!qfMatch(state.position,row.position||""))return false;
    if(!qfMatch(state.status,status))return false;
    if(!qfMatch(state.level,level))return false;
    return true;
  });
}
function classOfficerAssessmentOptionValues(term,key){
  const values=classOfficerAssessmentAllRows(term).map(function(row){
    const record=classOfficerAssessmentActiveRecord(row),student=students.find(function(item){return String(item.id)===String(row.studentId);})||{};
    if(key==="dept")return student.dept||"";if(key==="major")return student.major||"";if(key==="grade")return student.grade||classGrade(student.cls||"");if(key==="cls")return student.cls||"";if(key==="position")return row.position||"";if(key==="status")return record?"在任":"已离任（历史考核）";if(key==="level")return row.level||"未考核";return "";
  }).filter(Boolean);
  return Array.from(new Set(values)).sort(function(a,b){return String(a).localeCompare(String(b),"zh-CN",{numeric:true});});
}
function classOfficerAssessmentRows(term){
  const rows=classOfficerAssessmentFilteredRows(term);
  rows.sort(function(a,b){const aa=classOfficerAssessmentActiveRecord(a)?0:1,bb=classOfficerAssessmentActiveRecord(b)?0:1,sa=students.find(function(student){return String(student.id)===String(a.studentId);})||{},sb=students.find(function(student){return String(student.id)===String(b.studentId);})||{};return aa-bb||String(sa.cls||"").localeCompare(String(sb.cls||""),"zh-CN",{numeric:true})||String(a.position||"").localeCompare(String(b.position||""),"zh-CN");});
  if(!rows.length)return '<tr><td colspan="8" class="co-empty">本学期暂无在任班委，请先在“任职管理”新增在任记录</td></tr>';
  return rows.map(function(row){
    const record=classOfficerAssessmentActiveRecord(row),student=students.find(function(item){return String(item.id)===String(row.studentId);})||{},readonly=!record;
    const options='<option value="">请选择</option>'+CLASS_OFFICER_ASSESSMENT_LEVELS.map(function(level){return '<option value="'+attr(level)+'"'+(row.level===level?' selected':'')+'>'+esc(level)+'</option>';}).join("");
    return '<tr><td>'+esc(student.dept||"")+'</td><td>'+esc(student.grade||classGrade(student.cls||""))+'</td><td>'+esc(student.cls||"")+'</td><td>'+esc(row.studentId)+'</td><td>'+esc(student.name||"未匹配学生")+'</td><td>'+esc(row.position)+'</td><td><span class="co-status '+(record?'active':'ended')+'">'+(record?'在任':'已离任（历史考核）')+'</span></td><td><select class="in coa-level-select" data-row-id="'+attr(row.id)+'" aria-label="'+attr((student.name||row.studentId)+'班委考核等级')+'" onchange="classOfficerAssessmentSet('+jsArg(term)+','+jsArg(row.id)+',this.value)"'+(readonly?' disabled title="历史考核只读"':'')+'>'+options+'</select></td></tr>';
  }).join("");
}
function classOfficerAssessmentModalBody(term){
  const stats=classOfficerAssessmentStats(term),state=classOfficerAssessmentFilter||{};
  const multi=function(name,label,key,allLabel){return '<div class="filter-item"><label>'+label+'</label>'+qfMulti(name,[{v:"",l:allLabel}].concat(classOfficerAssessmentOptionValues(term,key).map(function(value){return {v:value,l:value};})),state[key]||[])+'</div>';};
  return '<div class="coa-assessment-layout"><div class="tip coa-assessment-tip">名单与“任职管理”的当前在任记录自动同步。只有在任班委可填写考核等级；离任后的已完成考核作为历史记录只读保留。</div>'
    +'<div class="qf-bar coa-assessment-filters" data-page="classOfficerAssessment"><div class="filter-item"><label>关键字</label>'+qfInput("coaKw","搜索学号、姓名或职务",state.kw,170)+'</div>'
    +multi("coaDept","学院","dept","全部学院")+multi("coaMajor","专业","major","全部专业")+multi("coaGrade","年级","grade","全部年级")+multi("coaCls","班级","cls","全部班级")+multi("coaPosition","职务","position","全部职务")+multi("coaStatus","任职状态","status","全部状态")+multi("coaLevel","考核等级","level","全部等级")
    +'<button class="btn btn-primary btn-sm coa-filter-action" onclick="classOfficerAssessmentQuery('+jsArg(term)+')">查询</button><button class="btn btn-ghost btn-sm coa-filter-action" onclick="classOfficerAssessmentReset('+jsArg(term)+')">重置</button></div>'
    +'<div id="coaTermSummary" class="coa-assessment-summary">在任 '+stats.active+' 人，已考核 '+stats.completed+' 人'+(stats.history?'，历史考核 '+stats.history+' 条':'')+'，当前显示 '+classOfficerAssessmentFilteredRows(term).length+' 条</div><div class="module-table-wrap table-scroll coa-assessment-table"><table class="t-table" style="min-width:980px"><thead><tr><th>学院</th><th>年级</th><th>班级</th><th>学号</th><th>姓名</th><th>职务</th><th>任职状态</th><th>考核等级</th></tr></thead><tbody id="coaTermTbody">'+classOfficerAssessmentRows(term)+'</tbody></table></div></div>';
}
function classOfficerAssessmentOpen(term){
  term=String(term||"").trim();if(getTermList().indexOf(term)<0){alert("该学期已不在系统学期设置中。 ");return;}
  if(window.classOfficerAssessmentFilterTerm!==term){classOfficerAssessmentFilter={kw:"",dept:[],major:[],grade:[],cls:[],position:[],status:[],level:[]};window.classOfficerAssessmentFilterTerm=term;}
  classOfficerAssessmentSyncTerm(term);
  openModal("班委考核 · "+term,classOfficerAssessmentModalBody(term));
  document.getElementById("modal").classList.add("xwide","class-officer-assessment-modal");
  document.getElementById("modalFoot").innerHTML='<button class="btn btn-ghost" onclick="closeModal()">关闭</button><button class="btn btn-primary" onclick="classOfficerAssessmentExport('+jsArg(term)+')">⬇ 导出本学期考核</button>';
}
function classOfficerAssessmentUpdateModalSummary(term){
  const stats=classOfficerAssessmentStats(term),summary=document.getElementById("coaTermSummary");if(summary)summary.textContent="在任 "+stats.active+" 人，已考核 "+stats.completed+" 人"+(stats.history?"，历史考核 "+stats.history+" 条":"")+"，当前显示 "+classOfficerAssessmentFilteredRows(term).length+" 条";
}
function classOfficerAssessmentQuery(term){
  const value=function(id){const element=document.querySelector('[data-qf="'+id+'"]');return element&&element.value!=null?String(element.value||"").trim():"";};
  classOfficerAssessmentFilter={kw:value("coaKw"),dept:readMulti("coaDept"),major:readMulti("coaMajor"),grade:readMulti("coaGrade"),cls:readMulti("coaCls"),position:readMulti("coaPosition"),status:readMulti("coaStatus"),level:readMulti("coaLevel")};
  const tbody=document.getElementById("coaTermTbody");if(tbody)tbody.innerHTML=classOfficerAssessmentRows(term);classOfficerAssessmentUpdateModalSummary(term);
}
function classOfficerAssessmentReset(term){
  classOfficerAssessmentFilter={kw:"",dept:[],major:[],grade:[],cls:[],position:[],status:[],level:[]};classOfficerAssessmentOpen(term);
}
function classOfficerAssessmentSet(term,rowId,level){
  const item=classOfficerAssessmentTermByName(term),row=item&&(item.rows||[]).find(function(value){return String(value.id)===String(rowId);});if(!row)return;
  if(!classOfficerAssessmentActiveRecord(row)){alert("该班委已离任，历史考核不可修改。 ");classOfficerAssessmentOpen(term);return;}
  level=String(level||"").trim();if(level&&CLASS_OFFICER_ASSESSMENT_LEVELS.indexOf(level)<0){alert("考核等级不合法。 ");return;}
  row.level=level;row.updatedAt=fmtNow();item.updatedAt=fmtNow();persistClassOfficerAssessmentTerms();renderPage("classOfficer");classOfficerAssessmentOpen(term);showToast(level?"班委考核等级已保存":"已清空班委考核等级","success");
}
function classOfficerAssessmentExport(term){
  const item=classOfficerAssessmentTermByName(term),rows=item&&Array.isArray(item.rows)?item.rows:[];if(!rows.length){alert("本学期没有可导出的班委考核记录。 ");return;}
  const data=rows.map(function(row){const student=students.find(function(item){return String(item.id)===String(row.studentId);})||{};return [term,row.studentId,student.name||"",student.dept||"",student.major||"",student.grade||classGrade(student.cls||""),student.cls||"",row.position,classOfficerAssessmentActiveRecord(row)?"在任":"已离任（历史考核）",row.level||"未考核",row.updatedAt||""];});
  downloadXlsxFile("班委考核",[["学期","学号","姓名","学院","专业","年级","班级","职务","任职状态","考核等级","更新时间"]].concat(data),"班委考核-"+term+".xlsx");showToast("已导出 "+rows.length+" 条班委考核记录","success");
}
function openExportClassOfficerAssessmentMulti(){
  classOfficerAssessmentSyncAllTerms();
  const terms=sortTermsDesc(getTermList()).map(function(term){return classOfficerAssessmentTermByName(term);}).filter(Boolean);
  if(!terms.length){showToast("暂无班委考核学期可导出","error");return;}
  const items=terms.map(function(item){return '<label style="display:flex;align-items:center;gap:8px;padding:8px 12px;border:1px solid var(--border);border-radius:8px;cursor:pointer"><input type="checkbox" class="coa-export-term-cb" value="'+attr(item.term)+'" checked><span style="font-weight:600">'+esc(item.term)+'</span><span style="color:var(--muted);font-size:12.5px">（'+(item.rows||[]).length+' 条）</span></label>';}).join("");
  const body='<div class="tip" style="margin-bottom:12px">勾选要导出的学期。导出文件按学号合并，基础身份字段只出现一次，每个所选学期分别生成“职务”和“考核等级”列。</div><div id="coaExportTermList" style="display:flex;flex-direction:column;gap:8px;max-height:52vh;overflow:auto">'+items+'</div><div style="margin-top:12px;display:flex;gap:8px"><button class="btn btn-ghost btn-sm" onclick="document.querySelectorAll(\'#coaExportTermList .coa-export-term-cb\').forEach(function(item){item.checked=true;})">全选</button><button class="btn btn-ghost btn-sm" onclick="document.querySelectorAll(\'#coaExportTermList .coa-export-term-cb\').forEach(function(item){item.checked=false;})">全不选</button></div>';
  openModal("导出班委多学期考核",body,function(){
    if(!document.querySelectorAll("#coaExportTermList .coa-export-term-cb:checked").length){showToast("请至少选择一个学期","error");return false;}
    classOfficerAssessmentExportMulti();return true;
  });
  const ok=document.getElementById("modalOk");if(ok)ok.textContent="导出 Excel";
}
function classOfficerAssessmentExportMulti(){
  const selected=Array.prototype.slice.call(document.querySelectorAll("#coaExportTermList .coa-export-term-cb:checked")).map(function(input){return input.value;});
  if(!selected.length){showToast("请至少选择一个学期","error");return;}
  const terms=selected.map(function(term){return classOfficerAssessmentTermByName(term);}).filter(Boolean),map={};
  terms.forEach(function(item){
    (item.rows||[]).forEach(function(row){
      const sid=String(row.studentId||"").trim();if(!sid)return;
      if(!map[sid])map[sid]={student:students.find(function(value){return String(value.id)===sid;})||{},per:{}};
      if(!map[sid].per[item.term])map[sid].per[item.term]=[];
      map[sid].per[item.term].push(row);
    });
  });
  const headers=["学院","专业","年级","班级","学号","姓名"];
  terms.forEach(function(item){headers.push(item.term+" 职务");headers.push(item.term+" 考核等级");});
  const rows=Object.keys(map).sort(function(a,b){const sa=map[a].student||{},sb=map[b].student||{};return String(sa.cls||"").localeCompare(String(sb.cls||""),"zh-CN",{numeric:true})||a.localeCompare(b,"zh-CN",{numeric:true});}).map(function(sid){
    const data=map[sid],student=data.student||{},row=[student.dept||"",student.major||"",student.grade||classGrade(student.cls||""),student.cls||"",sid,student.name||""];
    terms.forEach(function(item){
      const values=(data.per[item.term]||[]).slice().sort(function(a,b){return String(a.position||"").localeCompare(String(b.position||""),"zh-CN");});
      row.push(values.map(function(value){return value.position||"";}).join("；"));row.push(values.map(function(value){return value.level||"未考核";}).join("；"));
    });
    return row;
  });
  const fileName="班委多学期考核_"+terms.map(function(item){return item.term;}).join("_")+".xlsx";
  downloadXlsxFile("班委多学期考核",[headers].concat(rows),fileName);showToast("已导出 "+rows.length+" 名学生的 "+terms.length+" 个学期班委考核","success");
}
function classOfficerApplyFilters(){
  const value=function(id){const element=document.getElementById(id);return element?String(element.value||"").trim():"";};
  classOfficerFilter={kw:value("coFilterKw"),dept:readMulti("coDept"),major:readMulti("coMajor"),grade:readMulti("coGrade"),cls:readMulti("coCls"),position:readMulti("coPosition"),status:readMulti("coStatus")};
  getPager("class_officer").page=1;renderPage("classOfficer");
}
function classOfficerResetFilters(){classOfficerFilter={kw:"",dept:[],major:[],grade:[],cls:[],position:[],status:[]};getPager("class_officer").page=1;renderPage("classOfficer");}
function classOfficerApplyStudent(student){
  if(!student)return null;
  [["coSid",student.id],["coName",student.name],["coDept",student.dept],["coMajor",student.major],["coGrade",student.grade||classGrade(student.cls||"")],["coCls",student.cls]].forEach(function(pair){const element=document.getElementById(pair[0]);if(element)element.value=pair[1]||"";});
  const hint=document.getElementById("coStudentHint");if(hint)hint.textContent="已匹配："+[student.id,student.dept,student.cls].filter(Boolean).join(" · ");
  const results=document.getElementById("coNameResults");if(results){results.innerHTML="";results.classList.remove("show");}
  return student;
}
function classOfficerClearStudentMatch(keepName){
  ["coSid","coDept","coMajor","coGrade","coCls"].forEach(function(id){const element=document.getElementById(id);if(element)element.value="";});
  if(!keepName){const name=document.getElementById("coName");if(name)name.value="";}
}
function classOfficerStudentFill(){
  const sid=String((document.getElementById("coSid")||{}).value||"").trim(),student=students.find(function(item){return String(item.id)===sid;});
  if(student)return classOfficerApplyStudent(student);
  ["coName","coDept","coMajor","coGrade","coCls"].forEach(function(id){const element=document.getElementById(id);if(element)element.value="";});
  const hint=document.getElementById("coStudentHint");if(hint)hint.textContent=sid?"未找到该学号，可改用姓名搜索并选择学生":"可输入学号，或在右侧输入姓名搜索";
  const results=document.getElementById("coNameResults");if(results){results.innerHTML="";results.classList.remove("show");}
  return null;
}
function classOfficerNameSearch(){
  const input=document.getElementById("coName"),results=document.getElementById("coNameResults"),hint=document.getElementById("coStudentHint");if(!input||!results)return;
  const query=String(input.value||"").trim().toLowerCase(),currentSid=String((document.getElementById("coSid")||{}).value||"").trim(),currentStudent=students.find(function(item){return String(item.id)===currentSid;});
  if(currentStudent&&String(currentStudent.name||"").trim().toLowerCase()!==query)classOfficerClearStudentMatch(true);
  if(!query){results.innerHTML="";results.classList.remove("show");if(hint)hint.textContent="可输入学号，或输入姓名关键字搜索";return;}
  const matches=students.filter(function(student){return isOnCampusStudent(student)&&String(student.name||"").toLowerCase().indexOf(query)>=0;}).sort(function(a,b){const ae=String(a.name||"").toLowerCase()===query?0:1,be=String(b.name||"").toLowerCase()===query?0:1;return ae-be||String(a.name||"").localeCompare(String(b.name||""),"zh-CN")||String(a.id||"").localeCompare(String(b.id||""),"zh-CN",{numeric:true});}).slice(0,20);
  const exact=matches.filter(function(student){return String(student.name||"").trim().toLowerCase()===query;});
  if(exact.length===1){classOfficerApplyStudent(exact[0]);return;}
  if(!matches.length){results.innerHTML='<div class="co-name-empty">没有匹配的学生，请先在学生管理中维护</div>';results.classList.add("show");if(hint)hint.textContent="未找到姓名匹配结果";return;}
  results.innerHTML=matches.map(function(student){return '<button type="button" class="co-name-option" onclick="classOfficerPickStudent('+jsArg(student.id)+')"><b>'+esc(student.name)+'</b><span>'+esc([student.id,student.dept,student.cls].filter(Boolean).join(" · "))+'</span></button>';}).join("");
  results.classList.add("show");if(hint)hint.textContent=exact.length>1?"检测到同名学生，请根据学号和班级选择":"找到 "+matches.length+" 名学生，请选择";
}
function classOfficerPickStudent(studentId){const student=students.find(function(item){return String(item.id)===String(studentId);});return classOfficerApplyStudent(student);}
function classOfficerStatusChanged(){
  const status=document.getElementById("coStatus"),end=document.getElementById("coEndDate");if(!status||!end)return;
  if(status.value==="已离任"&&!end.value)end.value=isoToday();
  if(status.value==="在任")end.value="";
}
function classOfficerForm(record){
  record=record||{};const student=students.find(function(item){return String(item.id)===String(record.studentId||"");})||{};
  return '<div class="co-form-note">任职学生必须已存在于“学生管理”。保存后，系统会自动生成任职摘要并同步到该学生的“学生干部任职情况”字段。</div>'
    +'<div class="row2"><div class="field"><label>学号 <span style="color:#d6453d">*</span></label><input id="coSid" value="'+attr(record.studentId||"")+'" autocomplete="off" oninput="classOfficerStudentFill()" placeholder="输入完整学号"></div><div class="field co-name-field"><label>姓名搜索 <span style="color:#d6453d">*</span></label><input id="coName" value="'+attr(student.name||"")+'" autocomplete="off" oninput="classOfficerNameSearch()" onfocus="classOfficerNameSearch()" placeholder="输入姓名或姓名关键字"><div id="coNameResults" class="co-name-results"></div><div id="coStudentHint" class="co-readonly-hint">'+(student?("已匹配："+[student.id,student.dept,student.cls].filter(Boolean).join(" · ")):"可输入学号，或输入姓名关键字搜索")+'</div></div></div>'
    +'<div class="row2"><div class="field"><label>学院</label><input id="coDept" value="'+attr(student.dept||"")+'" readonly></div><div class="field"><label>专业</label><input id="coMajor" value="'+attr(student.major||"")+'" readonly></div></div>'
    +'<div class="row2"><div class="field"><label>年级</label><input id="coGrade" value="'+attr(student.grade||classGrade(student.cls||""))+'" readonly></div><div class="field"><label>班级</label><input id="coCls" value="'+attr(student.cls||"")+'" readonly></div></div>'
    +'<div class="row2"><div class="field"><label>职务 <span style="color:#d6453d">*</span></label><input id="coPosition" value="'+attr(record.position||"")+'" autocomplete="off" placeholder="请手动输入具体职务"></div><div class="field"><label>任职日期</label><input id="coStartDate" type="date" value="'+attr(record.startDate||isoToday())+'"></div></div>'
    +'<div class="row2"><div class="field"><label>任职状态</label><select id="coStatus" onchange="classOfficerStatusChanged()"><option value="在任"'+(record.status!=="已离任"?' selected':'')+'>在任</option><option value="已离任"'+(record.status==="已离任"?' selected':'')+'>已离任</option></select></div><div class="field"><label>离任日期</label><input id="coEndDate" type="date" value="'+attr(record.endDate||"")+'"><div class="co-readonly-hint">状态选择“已离任”时自动填写当天，也可调整为实际日期。</div></div></div>'
    +'<div class="field"><label>职责说明</label><textarea id="coDuties" rows="3" maxlength="500" placeholder="填写分工、负责事项或工作职责">'+esc(record.duties||"")+'</textarea></div>'
    +'<div class="field"><label>备注</label><textarea id="coNote" rows="2" maxlength="500" placeholder="可填写换届、兼任等补充说明">'+esc(record.note||"")+'</textarea></div>';
}
function classOfficerOpen(recordId){
  const record=recordId?classOfficerRecords.find(function(item){return String(item.id)===String(recordId);}):null,oldStudentId=record&&record.studentId;
  openModal(record?"编辑班级干部任职":"新增班级干部任职",classOfficerForm(record),function(){
    const value=function(id){const element=document.getElementById(id);return element?String(element.value||"").trim():"";};
    const studentId=value("coSid"),student=students.find(function(item){return String(item.id)===studentId;}),position=value("coPosition"),startDate=value("coStartDate"),endDate=value("coEndDate"),status=value("coStatus")==="已离任"?"已离任":"在任";
    if(!student){alert("未在学生管理中找到学号“"+studentId+"”，请先维护学生基本信息。 ");return false;}
    if(!student.cls){alert("该学生尚未维护班级，不能录入班级干部任职。 ");return false;}
    if(!position){alert("请手动输入职务。 ");return false;}
    if(status==="在任"&&!isOnCampusStudent(student)){alert("该学生学籍状态不是在校生，不能设置为在任。 ");return false;}
    if(startDate&&endDate&&endDate<startDate){alert("离任日期不能早于任职日期。 ");return false;}
    if(status==="已离任"&&!endDate){alert("已离任记录必须填写离任日期。 ");return false;}
    const duplicate=classOfficerRecords.some(function(item){return (!record||String(item.id)!==String(record.id))&&String(item.studentId)===studentId&&item.position===position&&String(item.startDate||"")===startDate&&item.status===status;});
    if(duplicate){alert("该学生已有相同职务、任职日期和状态的记录，请勿重复添加。 ");return false;}
    const saved=classOfficerNormalizeRecord(Object.assign({},record||{id:"co_"+Date.now()+"_"+Math.random().toString(16).slice(2)}, {studentId:studentId,position:position,startDate:startDate,endDate:status==="已离任"?endDate:"",status:status,duties:value("coDuties"),note:value("coNote"),createdAt:record&&record.createdAt||fmtNow(),updatedAt:fmtNow()}),0);
    if(record)Object.assign(record,saved);else classOfficerRecords.push(saved);
    persistClassOfficerRecords();syncClassOfficerStudents([oldStudentId,studentId]);classOfficerAssessmentSyncAllTerms();renderPage("classOfficer");showToast(record?"任职记录已更新并同步学生档案及考核名单":"任职记录已新增并同步学生档案及各学期考核名单","success");
  });
  classOfficerStudentFill();
}
function classOfficerAdd(){classOfficerOpen("");}
function classOfficerEdit(recordId){classOfficerOpen(recordId);}
function classOfficerView(recordId){
  const record=classOfficerRecords.find(function(item){return String(item.id)===String(recordId);});if(!record)return;
  const student=students.find(function(item){return String(item.id)===String(record.studentId);})||{};
  const item=function(label,value,wide){return '<div class="co-detail-item'+(wide?' co-detail-wide':'')+'"><span>'+esc(label)+'</span><b>'+esc(value||"—")+'</b></div>';};
  openModal("班级干部任职详情",'<div class="co-detail-grid">'+item("姓名",student.name)+item("学号",record.studentId)+item("学院",student.dept)+item("专业",student.major)+item("年级",student.grade||classGrade(student.cls||""))+item("班级",student.cls)+item("职务",record.position)+item("任职日期",record.startDate)+item("离任日期",record.endDate)+item("任职状态",record.status)+item("职责说明",record.duties,true)+item("备注",record.note,true)+'</div>');
  document.getElementById("modalFoot").innerHTML='<button class="btn btn-ghost" onclick="closeModal()">关闭</button><button class="btn btn-primary" onclick="closeModal();classOfficerEdit('+jsArg(record.id)+')">编辑</button>';
}
function classOfficerEnd(recordId){
  const record=classOfficerRecords.find(function(item){return String(item.id)===String(recordId);});if(!record)return;
  if(!confirm("确认将“"+record.position+"”标记为已离任？"))return;
  record.status="已离任";record.endDate=record.endDate||isoToday();record.updatedAt=fmtNow();persistClassOfficerRecords();syncClassOfficerStudents([record.studentId]);classOfficerAssessmentSyncAllTerms();renderPage("classOfficer");showToast("已标记离任并同步学生档案及考核名单","success");
}
async function classOfficerDelete(recordId){
  const index=classOfficerRecords.findIndex(function(item){return String(item.id)===String(recordId);});if(index<0)return;
  const record=classOfficerRecords[index],moved=await recycleMoveRecords("classOfficer","class_officer_record",[record.id]);if(!moved)return;
  syncClassOfficerStudents([record.studentId]);classOfficerAssessmentSyncAllTerms();renderPage("classOfficer");showToast("任职记录已移入回收站，学生档案及考核名单已同步","success");
}
const CLASS_OFFICER_IMPORT_FIELDS=[
  {key:"studentId",label:"学号",required:true,aliases:["学生学号","学生编号"]},{key:"position",label:"职务",required:true,aliases:["岗位","班干部职务","学生干部任职"]},
  {key:"startDate",label:"任职日期",aliases:["开始日期","任职时间"]},{key:"endDate",label:"离任日期",aliases:["结束日期","离任时间"]},{key:"status",label:"任职状态",aliases:["状态"]},{key:"duties",label:"职责说明",aliases:["职责","分工"]},{key:"note",label:"备注"}
];
function classOfficerImportTemplate(){
  downloadXlsxFile("班级干部任职导入模板",[CLASS_OFFICER_IMPORT_FIELDS.map(function(field){return field.label;}),["20250001","班长",isoToday(),"","在任","统筹班级日常事务",""]],"班级干部任职导入模板.xlsx");
}
function classOfficerImport(){
  openMappedImportWizard({name:"班级干部任职",fields:CLASS_OFFICER_IMPORT_FIELDS,requiredFields:["学号","职务"],template:"classOfficerImportTemplate()",
    validate:function(rows){
      const ok=[],errors=[];
      rows.forEach(function(row,index){
        const studentId=String(row.studentId||"").trim(),student=students.find(function(item){return String(item.id)===studentId;}),status=/离任|卸任|退出/.test(String(row.status||""))?"已离任":"在任",startDate=String(row.startDate||"").trim(),endDate=String(row.endDate||"").trim();
        let message="";
        if(!studentId||!student)message="学号未在学生管理中找到";else if(!student.cls)message="该学生尚未维护班级";else if(!String(row.position||"").trim())message="职务不能为空";else if(status==="在任"&&!isOnCampusStudent(student))message="学籍状态不是在校生，不能设置为在任";else if(startDate&&endDate&&endDate<startDate)message="离任日期不能早于任职日期";else if(status==="已离任"&&!endDate)message="已离任记录必须填写离任日期";
        if(message)errors.push({row:index+2,msg:message});else ok.push(Object.assign({},row,{studentId:studentId,status:status,startDate:startDate,endDate:endDate}));
      });
      return {ok:ok,errors:errors};
    },
    apply:function(rows){
      let ok=0,skip=0;const touched=[];
      rows.forEach(function(row,index){
        const duplicate=classOfficerRecords.some(function(item){return String(item.studentId)===row.studentId&&item.position===String(row.position||"").trim()&&String(item.startDate||"")===String(row.startDate||"")&&item.status===row.status;});
        if(duplicate){skip++;return;}
        classOfficerRecords.push(classOfficerNormalizeRecord({id:"co_"+Date.now()+"_"+index+"_"+Math.random().toString(16).slice(2),studentId:row.studentId,position:row.position,startDate:row.startDate,endDate:row.status==="已离任"?row.endDate:"",status:row.status,duties:row.duties,note:row.note,createdAt:fmtNow(),updatedAt:fmtNow()},index));touched.push(row.studentId);ok++;
      });
      persistClassOfficerRecords();syncClassOfficerStudents(touched);classOfficerAssessmentSyncAllTerms();return {ok:ok,skip:skip};
    },after:function(result){renderPage("classOfficer");showToast("班级干部任职导入完成：写入 "+result.ok+" 条，跳过 "+result.skip+" 条","success");}
  });
}
function classOfficerExport(){
  const records=classOfficerFilteredRecords();if(!records.length){alert("当前筛选结果没有可导出的任职记录。 ");return;}
  const rows=records.map(function(record){const student=students.find(function(item){return String(item.id)===String(record.studentId);})||{};return [record.studentId,student.name||"",student.dept||"",student.major||"",student.grade||classGrade(student.cls||""),student.cls||"",record.position,record.startDate,record.endDate,record.status,record.duties,record.note];});
  downloadXlsxFile("班级干部任职",[["学号","姓名","学院","专业","年级","班级","职务","任职日期","离任日期","任职状态","职责说明","备注"]].concat(rows),"班级干部任职台账.xlsx");showToast("已导出 "+records.length+" 条任职记录","success");
}

/* ---------- 通用时间工具 ---------- */
function fmtTimeStr(ts){return beijingDateTime(ts);}
function nowStr(){return fmtTimeStr(Date.now());}
function classroomSelfCriticismKey(r){
  const base=(r.term||"")+"|"+(r.course||"")+"|"+(r.week||"")+"|"+(r.section||"")+"|"+(r.date||"");
  return base+(r.attachmentKeySuffix?("|"+r.attachmentKeySuffix):"");
}
function attachmentDisplayUrl(a){
  if(!a||typeof a!=="object") return "";
  const name=String(a.name||a.fileName||"");
  const extMime=/\.pdf$/i.test(name)?"application/pdf":/\.png$/i.test(name)?"image/png":/\.gif$/i.test(name)?"image/gif":/\.webp$/i.test(name)?"image/webp":/\.bmp$/i.test(name)?"image/bmp":/\.(?:jpg|jpeg)$/i.test(name)?"image/jpeg":"application/octet-stream";
  const mime=/^(?:application\/pdf|image\/(?:png|jpeg|gif|webp|bmp))$/i.test(String(a.mime||""))?String(a.mime):extMime;
  const stored=String(a.url||(a.id?("/attachments/"+a.id):""));
  if(/^\/attachments\/[a-f0-9-]{36}$/i.test(stored)) return stored+"?type="+encodeURIComponent(mime);
  const legacy=String(a.dataUrl||"");
  return /^data:(?:application\/pdf|image\/(?:png|jpeg|gif|webp|bmp));base64,[A-Za-z0-9+/=\s]+$/i.test(legacy)?legacy:"";
}
function classroomAttachmentUrl(a){
  return attachmentDisplayUrl(a);
}
function viewSelfCriticismAdmin(id, key){
  const s=students.find(x=>x.id===id); if(!s||!s.classroomSelfCriticism) return;
  let sc=s.classroomSelfCriticism[key]; if(!sc) return;
  const arr=Array.isArray(sc)?sc.slice():(sc.id||sc.url||sc.fileName||sc.dataUrl?[sc]:[]); /* 兼容旧版单文件结构 */
  if(!arr.length){ alert('该考勤记录尚未上传检讨附件'); return; }
  let body='';
  arr.forEach(function(a,idx){
    const isImg=/^image\//i.test(a.mime||"");
    const title=escAttr(a.fileName||("附件"+(idx+1)));
    const attachmentUrl=classroomAttachmentUrl(a);
    if(!attachmentUrl) return;
    body+='<div style="margin-bottom:14px"><div style="font-size:12.5px;color:var(--muted);margin-bottom:4px">'+title+'</div>';
    if(isImg){
      body+='<div style="text-align:center"><img src="'+attr(attachmentUrl)+'" style="max-width:100%;max-height:420px;border:1px solid #ddd;border-radius:6px"></div>';
    }else{
      body+='<div style="height:420px"><iframe src="'+attr(attachmentUrl)+'" style="width:100%;height:100%;border:1px solid #ddd;border-radius:6px"></iframe></div>';
      body+='<div style="margin-top:6px"><a href="'+attr(attachmentUrl)+'" download="'+attr(a.fileName||("检讨"+(idx+1)))+'">⬇ 下载 / 另存为查看</a></div>';
    }
    body+='</div>';
  });
  openModal('学生检讨 - '+escAttr(s.name)+'（'+arr.length+' 份）', body);
  $("#modalFoot").style.display='none';
}
async function deleteClassroomRec(stuId, scKey){
  const s=students.find(x=>x.id===stuId); if(!s) return;
  const i=s.classroom.findIndex(r=>classroomSelfCriticismKey(r)===scKey);
  if(i>=0){
    const record=s.classroom[i];if(!record.id){record.id=genId("classAttendance");persistStudents();if(window.workbench&&window.workbench.legacy)await window.workbench.legacy.flushStore();}
    const moved=await recycleMoveRecords("classAttendance","class_attendance",[recycleNestedRecordId(stuId,record.id)]);if(!moved)return;
  }
  goto("classroom");
}
/* 检讨附件（PDF + 图片，可多选）：待上传文件 / 已存文件 分别管理 */
let absPendingFiles=[];
let absEditFiles=[];
let absOriginalFiles=[];
function absScFileSelChanged(input){
  for(const f of Array.from(input.files||[])){ absPendingFiles.push(f); }
  absScRenderFileList();
}
function absScRemovePending(i){ if(absPendingFiles[i]) absPendingFiles.splice(i,1); absScRenderFileList(); }
function absScRemoveAtt(i){ if(absEditFiles[i]) absEditFiles.splice(i,1); absScRenderFileList(); }
function absScRenderFileList(){
  const box=document.getElementById("absScFileList"); if(!box) return;
  const items=[];
  (absEditFiles||[]).forEach(function(a,i){ items.push('<div style="display:inline-block;margin:3px 6px 3px 0;padding:4px 8px;background:#eef6f0;border:1px solid #cfe3d4;border-radius:6px;font-size:12.5px">📎 '+escAttr(a.fileName||a.name||"附件")+'（已存）<span style="cursor:pointer;color:#c0392b;margin-left:6px" onclick="absScRemoveAtt('+i+')">✕</span></div>'); });
  absPendingFiles.forEach(function(f,i){ items.push('<div style="display:inline-block;margin:3px 6px 3px 0;padding:4px 8px;background:#fff8e6;border:1px solid #f5d77f;border-radius:6px;font-size:12.5px">📄 '+escAttr(f.name)+'（待上传）<span style="cursor:pointer;color:#c0392b;margin-left:6px" onclick="absScRemovePending('+i+')">✕</span></div>'); });
  box.innerHTML=items.join('');
}
window.absScFileSelChanged=absScFileSelChanged;
window.absScRemovePending=absScRemovePending;
window.absScRemoveAtt=absScRemoveAtt;
/* ---------- 课堂管理 · 旷课记录 分页（铁律：参照 stuPager · ①②③ 滚动条 + 分页条数） ---------- */
const classroomPager = { page: 1, pageSize: 20 };
let classroomLastFilterKey = '';
function classroomFilterKey(){
  return JSON.stringify(viewFilter.classroom || {}) + '|' + JSON.stringify(selectedViewTerms("classroom"));
}
function classroomGetPageSlice(list){
  const total = list.length;
  const size = classroomPager.pageSize || 20;
  const totalPages = Math.max(1, Math.ceil(total / size));
  if(!classroomPager.page || classroomPager.page < 1) classroomPager.page = 1;
  if(classroomPager.page > totalPages) classroomPager.page = totalPages;
  const start = (classroomPager.page - 1) * size;
  return { total: total, totalPages: totalPages, slice: list.slice(start, start + size), start: start, end: Math.min(start + size, total) };
}
function classroomGoPage(p){
  p = parseInt(p, 10);
  if(!p || p < 1) p = 1;
  classroomPager.page = p;
  renderPage("classroom");
}
function classroomSetPageSize(n){
  n = parseInt(n, 10) || 20;
  classroomPager.pageSize = n;
  classroomPager.page = 1;
  renderPage("classroom");
}
function renderClassroomPager(info){
  const tp = info.totalPages, cur = classroomPager.page, size = classroomPager.pageSize;
  const makeBtn = function(p, label, active){
    return '<button class="stu-page-btn'+(active?' active':'')+'" onclick="classroomGoPage('+p+')">'+(label||p)+'</button>';
  };
  const pageBtns = [];
  if(tp <= 7){
    for(let i=1; i<=tp; i++) pageBtns.push(makeBtn(i, i, i===cur));
  } else {
    pageBtns.push(makeBtn(1, 1, cur===1));
    if(cur > 4) pageBtns.push('<span class="stu-page-ellipsis">…</span>');
    const from = Math.max(2, cur-2), to = Math.min(tp-1, cur+2);
    for(let i=from; i<=to; i++) pageBtns.push(makeBtn(i, i, i===cur));
    if(cur < tp-3) pageBtns.push('<span class="stu-page-ellipsis">…</span>');
    pageBtns.push(makeBtn(tp, tp, cur===tp));
  }
  const sizes = [10,20,30,50,100,500,1000,5000];
  const sizeOpts = sizes.map(function(n){ return '<option value="'+n+'"'+(n===size?' selected':'')+'>'+n+'条/页</option>'; }).join("");
  return ''
    + '<div class="stu-pager">'
    + '<span class="stu-pager-info">共 <strong>'+info.total+'</strong> 条数据</span>'
    + '<div class="stu-pager-pages">'+pageBtns.join("")+'</div>'
    + '<select class="stu-pager-size" onchange="classroomSetPageSize(+this.value)">'+sizeOpts+'</select>'
    + '<span class="stu-pager-jump">跳至 <input type="number" id="classroomJumpInput" min="1" max="'+tp+'" value="'+cur+'"> 页 <button class="btn btn-primary btn-sm" onclick="classroomGoPage(+document.getElementById(\'classroomJumpInput\').value)">确定</button></span>'
    + '</div>';
}
/* ---------- 通用分页器（铁律：①②③ 横向/纵向滚动条 + 分页条数；复用于 宿舍/资助/党团/处分/学业情况 等） ---------- */
const PAGERS = {};
function getPager(key){
  if(!PAGERS[key]) PAGERS[key] = { page:1, pageSize:20, _lastKey:null };
  return PAGERS[key];
}
function pagerSlice(key, list, filterKey){
  const p = getPager(key);
  if(filterKey !== undefined && filterKey !== p._lastKey){ p.page = 1; p._lastKey = filterKey; } /* 筛选项变更自动回到第 1 页 */
  const total = (list||[]).length;
  const size = p.pageSize || 20;
  const totalPages = Math.max(1, Math.ceil(total / size));
  if(!p.page || p.page < 1) p.page = 1;
  if(p.page > totalPages) p.page = totalPages;
  const start = (p.page - 1) * size;
  return { total: total, totalPages: totalPages, slice: (list||[]).slice(start, start + size), start: start, end: Math.min(start + size, total) };
}
function pagerRerender(key){
  /* ae_/aw_ 前缀：重渲染学业编辑弹窗表格；其余：整页重渲染 */
  if(key.indexOf('ae_')===0) academicRebuildTable(parseInt(key.slice(3), 10));
  else if(key.indexOf('aw_')===0) academicWarningRebuildTable(parseInt(key.slice(3), 10));
  else if(key.indexOf('fund_')===0) fundRebuildTable(parseInt(key.slice(5), 10));
  else if(key.indexOf('gr_')===0) gradeRebuildTable(parseInt(key.slice(3), 10));
  else if(typeof currentView !== 'undefined') renderPage(currentView);
}
function pagerGoPage(key, p){
  p = parseInt(p, 10); if(!p || p < 1) p = 1;
  getPager(key).page = p;
  pagerRerender(key);
}
function pagerSetPageSize(key, n){
  n = parseInt(n, 10) || 20;
  const p = getPager(key); p.pageSize = n; p.page = 1;
  pagerRerender(key);
}
function renderGenericPager(key, info, jumpId){
  const p = getPager(key);
  const tp = info.totalPages, cur = p.page, size = p.pageSize;
  const makeBtn = function(pp, label, active){
    return '<button class="stu-page-btn'+(active?' active':'')+'" onclick="pagerGoPage(\''+key+'\','+pp+')">'+(label||pp)+'</button>';
  };
  const pageBtns = [];
  if(tp <= 7){
    for(let i=1; i<=tp; i++) pageBtns.push(makeBtn(i, i, i===cur));
  } else {
    pageBtns.push(makeBtn(1, 1, cur===1));
    if(cur > 4) pageBtns.push('<span class="stu-page-ellipsis">…</span>');
    const from = Math.max(2, cur-2), to = Math.min(tp-1, cur+2);
    for(let i=from; i<=to; i++) pageBtns.push(makeBtn(i, i, i===cur));
    if(cur < tp-3) pageBtns.push('<span class="stu-page-ellipsis">…</span>');
    pageBtns.push(makeBtn(tp, tp, cur===tp));
  }
  const sizes = [10,20,30,50,100,500,1000,5000];
  const sizeOpts = sizes.map(function(n){ return '<option value="'+n+'"'+(n===size?' selected':'')+'>'+n+'条/页</option>'; }).join("");
  return ''
    + '<div class="stu-pager">'
    + '<span class="stu-pager-info">共 <strong>'+info.total+'</strong> 条数据</span>'
    + '<div class="stu-pager-pages">'+pageBtns.join("")+'</div>'
    + '<select class="stu-pager-size" onchange="pagerSetPageSize(\''+key+'\',+this.value)">'+sizeOpts+'</select>'
    + '<span class="stu-pager-jump">跳至 <input type="number" id="'+jumpId+'" min="1" max="'+tp+'" value="'+cur+'"> 页 <button class="btn btn-primary btn-sm" onclick="pagerGoPage(\''+key+'\',+document.getElementById(\''+jumpId+'\').value)">确定</button></span>'
    + '</div>';
}
/* ---------- 课堂管理 · 按学期课表 ---------- */
const COURSE_SCHEDULE_FIELDS=["学期","班级","星期","周次","课程","课程类别","节次","任课老师","地点"];
function courseScheduleDay(value){
  const raw=String(value==null?"":value).trim().replace(/\s/g,"");
  const map={"1":1,"一":1,"星期一":1,"周一":1,"周1":1,"Monday":1,"MONDAY":1,"2":2,"二":2,"星期二":2,"周二":2,"周2":2,"Tuesday":2,"TUESDAY":2,"3":3,"三":3,"星期三":3,"周三":3,"周3":3,"Wednesday":3,"WEDNESDAY":3,"4":4,"四":4,"星期四":4,"周四":4,"周4":4,"Thursday":4,"THURSDAY":4,"5":5,"五":5,"星期五":5,"周五":5,"周5":5,"Friday":5,"FRIDAY":5,"6":6,"六":6,"星期六":6,"周六":6,"周6":6,"Saturday":6,"SATURDAY":6,"7":7,"日":7,"天":7,"星期日":7,"星期天":7,"周日":7,"周天":7,"周7":7,"Sunday":7,"SUNDAY":7};
  return map[raw]||0;
}
function courseScheduleDayText(day){ return day?"星期"+["","一","二","三","四","五","六","日"][day]:""; }
function courseScheduleWeekText(value){ return String(value==null?"":value).trim().replace(/[第周\s]/g,""); }
function courseScheduleHasWeek(value,week){
  if(!week) return false;
  const text=courseScheduleWeekText(value);
  if(!text) return true;
  return text.split(/[，,、;；]+/).some(function(part){
    const m=String(part).trim().match(/^(\d+)(?:\s*[-~至]\s*(\d+))?(?:\s*[(（]([单双])[)）])?$/);
    if(!m) return false;
    const start=parseInt(m[1],10), end=m[2]?parseInt(m[2],10):start, tag=m[3];
    if(tag==="单"&&week%2===0) return false;
    if(tag==="双"&&week%2===1) return false;
    return week>=Math.min(start,end)&&week<=Math.max(start,end);
  });
}
function courseScheduleDateMeta(term,date){
  if(!validTermDate(date)) return {week:0,day:0,message:"请选择有效日期"};
  const item=getTermSettings()[String(term||"")]||{}, startDate=String(item.startDate||""), totalWeeks=Math.floor(Number(item.totalWeeks));
  if(!validTermDate(startDate)||!(totalWeeks>=1&&totalWeeks<=52)) return {week:0,day:0,message:"请先在“学期设置”中维护该学期的开始时间和总教学周数"};
  const start=new Date(startDate+"T00:00:00"), target=new Date(String(date)+"T00:00:00"), offset=Math.floor((target-start)/86400000), week=Math.floor(offset/7)+1;
  if(offset<0||week>totalWeeks) return {week:0,day:0,message:"所选日期不在“"+term+"”的教学周范围内"};
  return {week:week,day:target.getDay()||7,message:"第 "+week+" 周 · "+courseScheduleDayText(target.getDay()||7)};
}
function courseScheduleMatches(term,cls,date){
  const meta=courseScheduleDateMeta(term,date);
  if(!cls||!meta.week||!meta.day) return {meta:meta,rows:[]};
  const rows=courseSchedules.filter(function(row){return String(row.term||"")===String(term||"")&&String(row.cls||"")===String(cls||"")&&Number(row.day)===meta.day&&courseScheduleHasWeek(row.weeks,meta.week);}).sort(function(a,b){return String(a.section||"").localeCompare(String(b.section||""));});
  return {meta:meta,rows:rows};
}
function courseScheduleRows(term){ return courseSchedules.filter(function(row){return String(row.term||"")===String(term||"");}).sort(function(a,b){ const last=function(x,y){ return !x&&!y?0:(!x?1:(!y?-1:String(x).localeCompare(String(y)))); }, ma=courseScheduleOrgMeta(a.cls), mb=courseScheduleOrgMeta(b.cls); return last(ma.dept,mb.dept)||last(ma.major,mb.major)||last(ma.grade,mb.grade)||String(a.cls||"").localeCompare(String(b.cls||""))||Number(a.day)-Number(b.day)||String(a.section||"").localeCompare(String(b.section||"")); }); }
function courseScheduleOrgMeta(cls){ const c=ORG_CLASSES.find(function(x){return x.name===cls;})||{}, m=String(cls||"").match(/^((?:19|20|21)\d{2})(?=级|[^\d])/); return {dept:c.dept||"",major:c.major||"",grade:c.grade||(m?m[1]+"级":"")}; }
function courseScheduleImportTemplate(){
  const sample=[CURRENT_TERM,"示例班级","星期一","1-16","高等数学","必修","第1-2节","张老师","教一101"];
  const rows=[COURSE_SCHEDULE_FIELDS,sample];
  downloadXlsxFile("课表导入模板",rows,"课表导入模板.xlsx");
}
function courseScheduleImport(options){
  options=options&&typeof options==="object"?options:{};
  let targetTerm="";try{targetTerm=options.term?lockedImportTerm(options.term):selectedImportTerm("classroom");}catch(error){showToast(error.message,"warn");return;}
  const returnView=options.returnView||"courseTimetable";
  openMappedImportWizard({name:"课表 · "+targetTerm,fields:COURSE_SCHEDULE_FIELDS,requiredFields:["班级","星期","周次","课程","节次","任课老师"],template:"courseScheduleImportTemplate()",
    validate:function(rows){
      const ok=[],errors=[],seen=new Set();
      rows.forEach(function(row,index){
        const term=targetTerm;row["学期"]=targetTerm;const cls=String(row["班级"]||"").trim(), day=courseScheduleDay(row["星期"]), weeks=courseScheduleWeekText(row["周次"]), course=String(row["课程"]||"").trim(), section=String(row["节次"]||"").trim(), teacher=String(row["任课老师"]||"").trim();
        const meta=getTermSettings()[term]||{}, key=[term,cls,day,weeks,course,section,teacher].join("|");
        if(!getTermList().includes(term)) errors.push({row:index+2,msg:"学期不存在："+term});
        else if(!validTermDate(meta.startDate)||!(Number(meta.totalWeeks)>=1)) errors.push({row:index+2,msg:"学期未设置开学日期或总教学周数："+term});
        else if(!ORG_CLASSES.some(function(item){return String(item.name||"")===cls;})) errors.push({row:index+2,msg:"班级不存在："+cls});
        else if(!day) errors.push({row:index+2,msg:"星期格式无效，请填写星期一至星期日"});
        else if(!weeks||!course||!section||!teacher) errors.push({row:index+2,msg:"周次、课程、节次、任课老师均为必填"});
        else if(seen.has(key)) errors.push({row:index+2,msg:"文件内存在重复课表行"});
        else { seen.add(key); row.__courseSchedule={term:term,cls:cls,day:day,weeks:weeks,course:course,category:String(row["课程类别"]||"").trim(),section:section,teacher:teacher,location:String(row["地点"]||"").trim()}; ok.push(row); }
      });
      return {ok:ok,errors:errors};
    },
    apply:function(rows){ let ok=0,skip=0; rows.forEach(function(row){ const item=row.__courseSchedule; if(!item){skip++;return;} if(courseSchedules.some(function(existing){return [existing.term,existing.cls,Number(existing.day),courseScheduleWeekText(existing.weeks),existing.course,existing.section,existing.teacher].join("|")===[item.term,item.cls,item.day,item.weeks,item.course,item.section,item.teacher].join("|");})){skip++;return;} courseSchedules.push(Object.assign({id:genId("schedule")},item)); ok++; }); persistCourseSchedules(); return {ok:ok,skip:skip}; },
    after:function(result){ goto(returnView); showToast("课表导入完成："+result.ok+" 条写入，"+result.skip+" 条跳过","success"); }
  });
}
window.courseScheduleImport=courseScheduleImport;
window.courseScheduleImportTemplate=courseScheduleImportTemplate;
function pdfScheduleDecodeLiteral(raw){
  const bytes=[];
  for(let i=0;i<raw.length;i++){
    const code=raw.charCodeAt(i);
    if(code===92&&i+1<raw.length){ const next=raw.charAt(++i); if(/[0-7]/.test(next)){ let oct=next; while(i+1<raw.length&&oct.length<3&&/[0-7]/.test(raw.charAt(i+1)))oct+=raw.charAt(++i); bytes.push(parseInt(oct,8)); } else { const escapes={n:10,r:13,t:9,b:8,f:12}; bytes.push(escapes[next]===undefined?next.charCodeAt(0):escapes[next]); } }
    else bytes.push(code&255);
  }
  if(bytes.length>=2&&bytes.length%2===0){ let out=""; for(let i=0;i<bytes.length;i+=2)out+=String.fromCharCode((bytes[i]<<8)|bytes[i+1]); return out; }
  return String.fromCharCode.apply(null,bytes);
}
async function pdfScheduleInflate(bytes){
  if(typeof DecompressionStream!=="function") throw new Error("当前浏览器不支持 PDF 文本解压，请使用 Excel 课表导入。");
  const stream=new Blob([bytes]).stream().pipeThrough(new DecompressionStream("deflate"));
  const raw=new Uint8Array(await new Response(stream).arrayBuffer()), chunks=[];
  for(let index=0;index<raw.length;index+=8192) chunks.push(String.fromCharCode.apply(null,raw.subarray(index,index+8192)));
  return chunks.join("");
}
async function pdfScheduleTextEvents(file){
  const data=new Uint8Array(await file.arrayBuffer()), marker=new TextEncoder().encode("stream"), endMarker=new TextEncoder().encode("endstream"), pages=[];
  const find=function(needle,start){ outer:for(let i=start;i<=data.length-needle.length;i++){for(let j=0;j<needle.length;j++)if(data[i+j]!==needle[j])continue outer;return i;}return -1; };
  for(let pos=0;(pos=find(marker,pos))>=0;){
    let start=pos+marker.length; if(data[start]===13)start++; if(data[start]===10)start++;
    const end=find(endMarker,start); if(end<0)break; let raw=data.slice(start,end); while(raw.length&&[10,13].includes(raw[raw.length-1]))raw=raw.slice(0,-1); pos=end+endMarker.length;
    let content=""; try{content=await pdfScheduleInflate(raw);}catch(_error){continue;}
    if(!/\bBT\b/.test(content)||!/(?:Tj|TJ)/.test(content))continue;
    const events=[], pattern=/1\s+0\s+0\s+1\s+(-?[\d.]+)\s+(-?[\d.]+)\s+Tm[\s\S]*?\(((?:\\.|[^\\)])*)\)\s*Tj/g; let match;
    while((match=pattern.exec(content))){ const text=pdfScheduleDecodeLiteral(match[3]).replace(/[\u0000-\u001f]/g,"").trim(); if(text)events.push({x:Number(match[1]),y:Number(match[2]),text:text}); }
    const rects=[], rectPattern=/(-?[\d.]+)\s+(-?[\d.]+)\s+(-?[\d.]+)\s+(-?[\d.]+)\s+re\b/g; let rectMatch;
    while((rectMatch=rectPattern.exec(content))){ const rect={x:Number(rectMatch[1]),y:Number(rectMatch[2]),w:Number(rectMatch[3]),h:Number(rectMatch[4])}; if(rect.h>10&&rect.h<400&&rect.w>5)rects.push(rect); }
    if(events.length) pages.push({events:events,rects:rects});
  }
  return pages;
}
function pdfScheduleClassName(title){
  const raw=String(title||"").replace(/课表.*$/," ").trim(), exact=ORG_CLASSES.find(function(row){return String(row.name||"")===raw;});
  if(exact)return exact.name;
  const digits=(raw.match(/\d{4,}/)||[])[0];
  const guessed=digits&&ORG_CLASSES.find(function(row){return String(row.name||"").indexOf(digits)>=0;});
  return guessed?guessed.name:raw;
}
function pdfScheduleClassify(course,detail){
  const marker=(String(course||"").match(/[◆◇●○★]/)||[])[0]||"", nature=(String(detail||"").match(/课程性质简介[:：]\s*([^/\s]+)/)||[])[1]||"";
  /* 课表标题后的图例符号表示实际授课类别，应优先于课程性质简介。 */
  const category=({"◆":"讨论","◇":"上机","●":"实践","○":"实验","★":"讲课"}[marker]||"")||nature;
  return {course:String(course||"").replace(/[◆◇●○★]/g,"").trim(),category:category};
}
function pdfScheduleRowFromText(term,cls,day,courseText,detail,sectionText,weeksText){
  const classified=pdfScheduleClassify(courseText,detail), section=String(sectionText||"").trim(), weeks=courseScheduleWeekText(weeksText), teacher=(String(detail||"").match(/教师[:：]\s*([^/]+)/)||[])[1]||"", location=(String(detail||"").match(/(?:地点|场地)[:：]\s*([^/]+)/)||[])[1]||"";
  if(!day||!classified.course||!section||!weeks||!teacher)return null;
  return {term:term,cls:cls,day:day,weeks:weeks,course:classified.course,category:classified.category,section:section.indexOf("第")===0?section:"第"+section.replace(/节$/,'')+"节",teacher:teacher.replace(/[（(].*$/,"").trim(),location:location};
}
async function pdfScheduleRecognize(file){
  if(!file||!/\.pdf$/i.test(file.name||""))throw new Error("请选择 PDF 格式的课表文件。");
  const pages=await pdfScheduleTextEvents(file), rows=[];
  let term="", firstCls="";
  pages.forEach(function(page){
    const events=Array.isArray(page)?page:(page.events||[]), rects=page&&page.rects||[];
    /* 每页独立识别学期与班级：学校导出的课表常为多班合订，每页一个班级。 */
    const pageText=events.map(function(item){return item.text;}).join(" ");
    const termMatch=pageText.match(/(\d{4})-(\d{4})学年第?\s*([1-9])\s*学期/);
    if(termMatch)term=termMatch[1]+"-"+termMatch[2]+"-"+termMatch[3]+"学期";
    const pageTitle=(pageText.match(/([^\s]{2,}?)课表/)||[])[1]||"";
    const pageCls=pageTitle?pdfScheduleClassName(pageTitle):"";
    if(!firstCls&&pageCls)firstCls=pageCls;

    /* 汇总页版式：星期/节次/课程按横行成组，详情在右侧相邻文本块。统一处理合并单元格的三种形态：
       ① 星期列纵向合并（多行课程共用一个星期标签）② 节次列纵向合并（相邻两行共用居中的节次文本）
       ③ 星期标签与课程同行成组（节次在相邻行）。星期归属优先按单元格矩形范围，无矩形时退回最近的星期标签。 */
    const bands=[]; events.slice().sort(function(a,b){return b.y-a.y||a.x-b.x;}).forEach(function(item){let band=bands.find(function(group){return Math.abs(group.y-item.y)<3;});if(!band){band={y:item.y,items:[]};bands.push(band);}band.items.push(item);});
    const dayLabels=events.filter(function(item){return /^星期/.test(item.text)&&courseScheduleDay(item.text);});
    const dayCells=dayLabels.map(function(label){
      const rect=rects.find(function(r){return label.x>=r.x-1&&label.x<=r.x+r.w+1&&label.y>=r.y-1&&label.y<=r.y+r.h+1;});
      return {day:courseScheduleDay(label.text),y0:rect?rect.y:label.y-14,y1:rect?rect.y+rect.h:label.y+14};
    });
    const dayOf=function(y){
      const cell=dayCells.filter(function(c){return y>=c.y0-1&&y<=c.y1+1;}).sort(function(a,b){return (b.y1-b.y0)-(a.y1-a.y0);})[0];
      if(cell)return cell.day;
      const label=dayLabels.slice().sort(function(a,b){return Math.abs(a.y-y)-Math.abs(b.y-y);})[0];
      return label?courseScheduleDay(label.text):0;
    };
    const weeksOf=function(detail){ const m=String(detail||"").match(/周数[:：]\s*([^\/]+)/), weeks=m?m[1].replace(/[周\s]/g,"").replace(/（/g,"(").replace(/）/g,")"):""; return /^\d+(-\d+)?(\([单双]\))?([,，、]\d+(-\d+)?(\([单双]\))?)*$/.test(weeks)?weeks:""; };
    bands.forEach(function(band){
      const items=band.items.filter(function(item){return !/[\/:：]/.test(String(item.text||""));}).sort(function(a,b){return a.x-b.x;});
      if(!items.length)return;
      const inlineDay=courseScheduleDay(items[0]&&items[0].text), rest=inlineDay?items.slice(1):items;
      if(!rest.length)return;
      const day=inlineDay||dayOf(band.y);
      if(!day)return;
      let sectionItem=null, courseItem=null;
      if(rest.length>=2&&/^\d+(-\d+)?$/.test(String(rest[0].text||"").trim())){ sectionItem=rest[0]; courseItem=rest[1]; }
      else{
        courseItem=rest[0];
        sectionItem=events.filter(function(item){return item.x<courseItem.x&&/^\d+(-\d+)?$/.test(String(item.text||"").trim());}).sort(function(a,b){return Math.abs(a.y-band.y)-Math.abs(b.y-band.y);})[0]||null;
        if(sectionItem&&Math.abs(sectionItem.y-band.y)>30)sectionItem=null;
      }
      if(!courseItem||!sectionItem)return;
      const detail=events.filter(function(item){return item.x>courseItem.x+50&&Math.abs(item.y-band.y)<=12;}).sort(function(a,b){return b.y-a.y;}).map(function(item){return item.text;}).join(""), row=pdfScheduleRowFromText(term,pageCls,day,courseItem.text,detail,sectionItem.text,weeksOf(detail));
      if(row)rows.push(row);
    });

    /* 网格页版式：星期位于列标题，课程详情按相同 x 坐标纵向排列。 */
    const dayColumns=events.map(function(item){return {item:item,day:courseScheduleDay(item.text)};}).filter(function(entry){return entry.day&&/^星期/.test(entry.item.text);});
    const xGroups=[];
    events.filter(function(item){return item.x>90&&item.y<515;}).forEach(function(item){let group=xGroups.find(function(entry){return Math.abs(entry.x-item.x)<1;});if(!group){group={x:item.x,items:[]};xGroups.push(group);}group.items.push(item);});
    xGroups.forEach(function(group){
      const dayEntry=dayColumns.slice().sort(function(a,b){return Math.abs((a.item.x-29)-group.x)-Math.abs((b.item.x-29)-group.x);})[0];
      if(!dayEntry||Math.abs((dayEntry.item.x-29)-group.x)>45)return;
      const items=group.items.sort(function(a,b){return b.y-a.y;}), starts=[];
      items.forEach(function(item,index){const next=items[index+1];if(next&&/^\s*\(\d+(?:-\d+)?节\)/.test(next.text||"")&&!/^(时间段|节次|星期)/.test(item.text||""))starts.push(index);});
      starts.forEach(function(startIndex,position){
        const endIndex=position+1<starts.length?starts[position+1]:items.length, courseItem=items[startIndex], detail=items.slice(startIndex+1,endIndex).map(function(item){return item.text;}).join(""), timing=detail.match(/^\s*\((\d+(?:-\d+)?节)\)\s*([^/]+?)周(?:\/|$)/);
        if(!timing)return;
        const row=pdfScheduleRowFromText(term,pageCls,dayEntry.day,courseItem.text,detail,timing[1],timing[2]);
        if(row)rows.push(row);
      });
    });
  });
  /* 去重键含班级：不同班级的相同课程行互不覆盖。 */
  const seen=new Set(), unique=rows.filter(function(row){const key=[row.cls,row.day,row.weeks,row.course,row.section,row.teacher].join("|");if(seen.has(key))return false;seen.add(key);return true;}), classes=Array.from(new Set(unique.map(function(row){return row.cls;}).filter(Boolean)));
  return {term:term,cls:firstCls,classes:classes,rows:unique};
}
