/* ---------- 课表智能识别：先提取，再由人工逐行确认，绝不把 AI 结果直接写入课表。 ---------- */
function courseScheduleAiJson(content){
  const text=String(content||"").replace(/^```(?:json)?\s*/i,"").replace(/\s*```$/i,"").trim();
  const start=text.indexOf("{"),end=text.lastIndexOf("}"); if(start<0||end<=start)throw new Error("AI 未返回可读取的课表 JSON");
  const value=JSON.parse(text.slice(start,end+1)); if(!value||typeof value!=="object"||Array.isArray(value)||!Array.isArray(value.rows))throw new Error("AI 返回的课表结构不完整");
  return value;
}
function courseScheduleAiNormalize(result,source){
  const rows=(result&&result.rows||[]).slice(0,300).map(function(raw){
    const item=raw&&typeof raw==="object"?raw:{}, confidence=Math.max(0,Math.min(100,Math.round(Number(item.confidence==null?70:item.confidence)||0)));
    const fields={cls:String(item.cls||result.cls||"").trim(),day:courseScheduleDay(item.day||item.weekday||""),weeks:courseScheduleWeekText(item.weeks||item.week||""),course:String(item.course||item.name||"").trim(),category:String(item.category||"").trim(),section:String(item.section||"").trim(),teacher:String(item.teacher||"").trim(),location:String(item.location||"").trim()};
    const uncertain=Array.isArray(item.uncertainFields)?item.uncertainFields.map(function(x){return String(x||"").trim();}).filter(Boolean):[];
    ["cls","day","weeks","course","section","teacher"].forEach(function(key){if(!fields[key])uncertain.push(key);}); if(confidence<75)uncertain.push("低置信度");
    return Object.assign(fields,{confidence:confidence,uncertain:Array.from(new Set(uncertain))});
  });
  const context=window.__courseScheduleAiContext||{};
  return {term:String(result&&result.term||context.term||primaryViewTerm("classroom")||"").trim(),rows:rows,warnings:Array.isArray(result&&result.warnings)?result.warnings.map(function(x){return String(x||"").trim();}).filter(Boolean).slice(0,8):[],source:source||"AI"};
}
function courseScheduleAiWorkbookFile(file){
  if(/\.(?:et|ett)$/i.test(file.name||"")) return new File([file],String(file.name||"课表").replace(/\.(?:et|ett)$/i,".xls"),{type:"application/vnd.ms-excel"});
  return file;
}
function courseScheduleAiWorkbookText(sheets){
  return (sheets||[]).slice(0,8).map(function(sheet){return "【工作表："+String(sheet.name||"")+"】\n"+(sheet.rows||[]).slice(0,160).map(function(row){return (row||[]).slice(0,20).map(function(cell){return String(cell==null?"":cell).replace(/[\t\r\n]+/g," ").trim();}).join("\t");}).join("\n");}).join("\n\n").slice(0,30000);
}
async function courseScheduleAiVision(file){
  const cfg=getAIConfig()||{};
  if(!aiConfigured())throw new Error("请先在“AI 智能助手 → 设置”配置支持图片输入的模型。");
  if(!aiFeatureEnabled(cfg,"courseSchedule"))throw new Error("“课表智能识别”已在 AI 设置中关闭。");
  if(cfg.courseScheduleOutboundApproved!==true)throw new Error("请先在“AI 智能助手 → 设置”勾选允许发送课表截图。");
  if(file.size>12*1024*1024)throw new Error("图片超过 12MB，请压缩或裁剪后重试。");
  const bytes=new Uint8Array(await file.arrayBuffer()); let binary=""; for(let i=0;i<bytes.length;i+=8192)binary+=String.fromCharCode.apply(null,bytes.subarray(i,i+8192));
  const res=await fetch("/api/ai/course-schedule-recognize",{method:"POST",headers:{"Content-Type":"application/json","X-Workbench-Token":TOKEN},body:JSON.stringify({imageBase64:btoa(binary),highDetail:true})});
  const data=await res.json().catch(function(){return {};}); if(!res.ok)throw new Error(data.error||("AI 接口返回 "+res.status));
  if(data.usage&&AI_CFG_CACHE)AI_CFG_CACHE.usage=data.usage;
  return courseScheduleAiNormalize(courseScheduleAiJson(data.content),"课表截图 AI");
}
async function courseScheduleAiRecognize(file){
  const name=String(file&&file.name||""), ext=(name.match(/\.([^.]+)$/)||[])[1]||"";
  if(/^(?:jpg|jpeg|png|webp)$/i.test(ext))return courseScheduleAiVision(file);
  if(/^(?:xlsx|xls|csv|et|ett)$/i.test(ext)){
    if(!aiConfigured())throw new Error("Excel/WPS 课表需先在“AI 智能助手 → 设置”配置 AI；常规模板仍可用“导入课表”手动映射。");
    const text=courseScheduleAiWorkbookText(await smartReadWorkbook(courseScheduleAiWorkbookFile(file)));
    const content=await aiChat("你是高校课表结构识别助手。仅从用户提供的工作表内容抽取课表，不得猜测。返回严格 JSON：{\"term\":\"\",\"cls\":\"\",\"rows\":[{\"cls\":\"\",\"day\":1,\"weeks\":\"\",\"course\":\"\",\"category\":\"\",\"section\":\"\",\"teacher\":\"\",\"location\":\"\",\"confidence\":0,\"uncertainFields\":[\"\"]}],\"warnings\":[\"\"]}。day 为1至7；看不清或文件没有的字段留空并列入 uncertainFields；不要输出 Markdown。",text,"courseSchedule");
    return courseScheduleAiNormalize(courseScheduleAiJson(content),"Excel/WPS AI");
  }
  if(/^pdf$/i.test(ext)){
    const local=await pdfScheduleRecognize(file); if(!local.rows.length)throw new Error("未能从该 PDF 提取文字课表。扫描件请导出为 PNG/JPG 后用本入口识别。");
    return courseScheduleAiNormalize({term:local.term,cls:local.cls,rows:local.rows.map(function(row){return Object.assign({confidence:82,uncertainFields:[]},row);}),warnings:["PDF 已在本机解析；请逐行确认后再导入。"]},"PDF 本机识别");
  }
  if(/^(?:txt|tsv)$/i.test(ext)){
    if(!aiConfigured())throw new Error("文本课表需先配置 AI。");
    const content=await aiChat("你是高校课表结构识别助手。把用户提供的文本解析为严格 JSON：{\"term\":\"\",\"cls\":\"\",\"rows\":[{\"cls\":\"\",\"day\":1,\"weeks\":\"\",\"course\":\"\",\"category\":\"\",\"section\":\"\",\"teacher\":\"\",\"location\":\"\",\"confidence\":0,\"uncertainFields\":[\"\"]}],\"warnings\":[\"\"]}。不确定字段留空；不要 Markdown。",(await file.text()).slice(0,30000),"courseSchedule");
    return courseScheduleAiNormalize(courseScheduleAiJson(content),"文本 AI");
  }
  throw new Error("暂不支持该文件类型。请上传 Excel/WPS（.xlsx/.xls/.et/.ett）、CSV、文字型 PDF、TXT 或 JPG/PNG/WebP 课表。");
}
