window.accPick=function(kind,val,checked){
  const arr=accSel[kind];
  if(checked){ if(!arr.includes(val))arr.push(val); } else { const i=arr.indexOf(val); if(i>=0)arr.splice(i,1); }
  if(kind==='grade') accRebuildClasses();
  accRefreshBox(kind);
};
function accMsdBox(kind,label,sid,ph,panelInner,panelId){
  return `<div class='field'><label>${esc(label)}</label>`
    +`<div class='msd'>`
    +`<div class='msd-box' onclick="this.parentElement.classList.toggle('open')"><span class='sum' id='${attr(sid)}'>${accSummary(kind,ph)}</span><span class='arw'>▾</span></div>`
    +`<div class='msd-panel'${panelId?` id='${attr(panelId)}'`:''}>${panelInner}</div>`
    +`</div></div>`;
}

let dormTab="dist";
let dormBatchSel=new Set(); /* 宿舍批量修改选中学号集合 */
function dormBatchUpdateMaster(){
  const master=document.getElementById('dormBatchMaster');
  if(!master) return;
  const boxes=document.querySelectorAll('.dorm-batch-cb');
  let checked=0,total=0;
  boxes.forEach(function(cb){ total++; if(cb.checked) checked++; });
  master.checked=total>0 && checked===total;
  master.indeterminate=checked>0 && checked<total;
  if(window.WorkbenchUI)WorkbenchUI.selectionSummary(master.closest('.card')?.querySelector('.toolbar'),'dorm','跨页已选 '+dormBatchSel.size+' 人，本页 '+checked+' 人');
}
function dormToggleOne(id,checked){
  if(checked){ dormBatchSel.add(String(id)); } else { dormBatchSel.delete(String(id)); }
  dormBatchUpdateMaster();
}
function dormToggleAll(checked){
  const boxes=document.querySelectorAll('.dorm-batch-cb');
  boxes.forEach(function(cb){ cb.checked=checked; if(checked){ dormBatchSel.add(String(cb.value)); } else { dormBatchSel.delete(String(cb.value)); } });
  dormBatchUpdateMaster();
}
function dormBatchEdit(){
  const ids=[...dormBatchSel];
  if(ids.length===0){ showToast('请先勾选要批量修改的学生','warn'); return; }
  const zones=[]; dormResourceBuildings().forEach(function(d){ if(d.zone && zones.indexOf(d.zone)<0) zones.push(d.zone); });
  const hasDormMaster = zones.length>0;
  let zoneField, buildingField;
  if(hasDormMaster){
    const zoneOpts='<option value="">— 不修改 —</option>'+zones.map(function(z){ return '<option value="'+escAttr(z)+'">'+esc(z)+'</option>'; }).join('');
    zoneField='<div class="field"><label>区位</label><select id="dbZone" class="role" onchange="dormBatchBuildingOptions()">'+zoneOpts+'</select></div>';
    buildingField='<div class="field"><label>宿舍楼</label><select id="dbBuilding" class="role"><option value="">— 不修改 —</option></select></div>';
  } else {
    zoneField='<div class="field"><label>区位</label><input id="dbZone" placeholder="（公寓资源未配置宿舍楼，可自由填）"></div>';
    buildingField='<div class="field"><label>宿舍楼</label><input id="dbBuilding" placeholder="不填表示不修改"></div>';
  }
  openModal('批量修改住宿信息（'+ids.length+'人）',
    '<div class="tip" style="margin-bottom:12px">仅填写需要修改的字段，留空（或选"不修改"）将保持原值不变。</div>'
    +'<div class="row2"><div class="field"><label>住宿情况</label><select id="dbAccom"><option value="">— 不修改 —</option><option value="校内">校内</option><option value="租房">租房</option><option value="走读">走读</option></select></div>'+zoneField+'</div>'
    +'<div class="row2">'+buildingField+'<div class="field"><label>房间号</label><input id="dbRoom" placeholder="不填表示不修改"></div></div>'
    +'<div class="row2"><div class="field"><label>床位号</label><input id="dbBed" placeholder="不填表示不修改"></div></div>',
    function(){
      const fields={};
      const accom=$('#dbAccom').value; if(accom!=='') fields.accom=accom;
      const room=$('#dbRoom').value.trim(); if(room!=='') fields.room=room;
      const bed=$('#dbBed').value.trim(); if(bed!=='') fields.bed=bed;
      const zone=$('#dbZone').value.trim();
      const building=$('#dbBuilding').value.trim();
      if(building!=='') fields.building=building;
      if(!accom && !room && !bed && !building){ showToast('请至少填写一项要修改的内容','warn'); return false; }
      const result=dormApplyRowsAtomically(ids,function(id){
        const batch=dormApplyRowsAtomically.context,s=batch.students.get(String(id));if(!s)return null;
        const cur=dormDistributionRow(s);
        return {student:s,fields:{accom:fields.accom!==undefined?fields.accom:cur.accom,zone:fields.building!==undefined?zone:cur.zone,building:fields.building!==undefined?fields.building:cur.building,room:fields.room!==undefined?fields.room:cur.room,bed:fields.bed!==undefined?fields.bed:cur.bed}};
      });
      if(result.failed){showToast('批量修改存在缺项或床位冲突，已回滚全部修改','error');return false;}
      const n=result.ok;
      showToast('已批量修改 '+n+' 名学生的住宿信息','ok');
      goto('dorm');
    });
  if(hasDormMaster) dormBatchBuildingOptions();
}
window.dormBatchEdit=dormBatchEdit;
function dormBatchClearCommit(ids){
  const unique=Array.from(new Set((ids||[]).map(function(id){return String(id==null?"":id).trim();}).filter(Boolean))),api=window.__DORM_SPATIAL__;
  if(api&&typeof api.checkoutStudents==="function")return api.checkoutStudents(unique,"批量清除住宿","batch");
  const snapshot=dormMutationSnapshot(),selected=new Set(unique),targets=students.filter(function(student){return selected.has(String(student.id));}),records=Array.isArray(dormDistRecords)?dormDistRecords:[];
  const actionable=targets.filter(function(student){const row=dormDistributionRow(student);return records.some(function(record){return String(record.studentId||record.id||"")===String(student.id);})||["accom","zone","building","room","bed"].some(function(key){return !!String(row[key]||"").trim();});});
  try{
    actionable.forEach(function(student){["accom","zone","building","room","bed"].forEach(function(key){student[key]="";});});
    const cleared=new Set(actionable.map(function(student){return String(student.id);}));dormDistRecords=records.filter(function(record){return !cleared.has(String(record.studentId||record.id||""));});
    if(actionable.length){persistStudents();persistDormDist();if(api&&typeof api.onAccommodationChanged==="function")api.onAccommodationChanged(undefined,{render:false});}
    return {ok:actionable.length,skip:unique.length-actionable.length,failed:false};
  }catch(error){dormMutationRollback(snapshot);reportDataError("批量清除住宿",error);showToast("批量清除住宿失败，全部修改已回滚","error");return {ok:0,skip:unique.length,failed:true,error:error};}
}
function dormBatchClear(){
  const known=new Map(students.filter(isOnCampusStudent).map(function(student){return [String(student.id),student];})),ids=[];
  Array.from(dormBatchSel).forEach(function(id){const sid=String(id);if(known.has(sid))ids.push(sid);else dormBatchSel.delete(sid);});
  if(!ids.length){dormBatchUpdateMaster();showToast("请先勾选要批量清除住宿的学生","warn");return;}
  const records=Array.isArray(dormDistRecords)?dormDistRecords:[],targets=ids.map(function(id){return known.get(id);}),withInfo=targets.filter(function(student){const row=dormDistributionRow(student);return records.some(function(record){return String(record.studentId||record.id||"")===String(student.id);})||["accom","zone","building","room","bed"].some(function(key){return !!String(row[key]||"").trim();});}),withBeds=withInfo.filter(function(student){const row=dormDistributionRow(student);return row.accom==="校内"&&!!String(row.building||"").trim()&&!!String(row.room||"").trim()&&!!String(row.bed||"").trim();});
  if(!withInfo.length){showToast("所选学生暂无可清除的住宿信息","warn");return;}
  const state=window.__DORM_SPATIAL__&&typeof window.__DORM_SPATIAL__.getState==="function"?window.__DORM_SPATIAL__.getState():null,selectedIds=new Set(ids),leaderCount=state?(state.leaders||[]).filter(function(item){return item.status==="current"&&selectedIds.has(String(item.studentId));}).length:0;
  const names=targets.slice(0,8).map(function(student){return '<span class="batch-chip"><span class="bc-name">'+esc(student.name||student.id)+'</span><span class="bc-meta">'+esc(student.id)+'</span></span>';}).join("")+(targets.length>8?'<span class="muted">等 '+targets.length+' 人</span>':"");
  openModal("批量清除住宿（"+ids.length+"人）",'<div class="tip" style="margin-bottom:12px;color:#a33"><b>确认后将清空所选学生的住宿情况、区位、宿舍楼、房间号和床位号。</b></div><div class="row2" style="margin-bottom:12px"><div class="stat"><div class="lab">可清除住宿信息</div><div class="num">'+withInfo.length+'</div></div><div class="stat"><div class="lab">释放当前床位</div><div class="num">'+withBeds.length+'</div></div></div>'+(leaderCount?'<div class="tip" style="margin-bottom:12px">其中 '+leaderCount+' 名宿舍长的当前身份将同步结束。</div>':'')+'<div class="field"><label>清除名单</label><div style="display:flex;flex-wrap:wrap;gap:6px;padding-top:6px">'+names+'</div></div><div class="tip" style="margin-top:14px">操作会释放当前床位、结束宿舍长身份并保留入住历史；不会删除学生和宿舍资源。'+(ids.length>withInfo.length?' 另有 '+(ids.length-withInfo.length)+' 人未录入住宿信息，将自动跳过。':'')+'</div>',function(){
    const result=dormBatchClearCommit(ids);if(!result||result.failed)return false;
    dormBatchSel.clear();showToast(result.ok?'已批量清除 '+result.ok+' 名学生的住宿信息':'所选学生暂无可清除的住宿信息',result.ok?'ok':'warn');goto("dorm");
  });
  const ok=document.getElementById("modalOk");if(ok){ok.textContent="确认清除";ok.className="btn btn-danger";}
}
window.dormBatchClear=dormBatchClear;
window.dormBatchClearCommit=dormBatchClearCommit;
window.dormBatchBuildingOptions=function(){
  const zoneEl=$('#dbZone'); const bEl=$('#dbBuilding'); if(!zoneEl||!bEl) return;
  const zone=zoneEl.value||"";
  const builds=dormResourceBuildings().filter(function(d){return d.zone===zone;}).map(function(d){return d.building;}).filter(Boolean);
  bEl.innerHTML='<option value="">— 不修改 —</option>'+builds.map(function(b){ return '<option value="'+escAttr(b)+'">'+esc(b)+'</option>'; }).join('');
};
function dormDistributionRecord(studentId){
  const sid=String(studentId==null?"":studentId).trim();
  const batch=dormApplyRowsAtomically.context;if(batch)return batch.records.get(sid)||null;
  const records=Array.isArray(dormDistRecords)?dormDistRecords:[],cached=dormDistributionRecord.lookup;
  if(!cached||cached.records!==records||cached.length!==records.length){
    const byStudent=new Map();records.forEach(function(record){const key=String(record.studentId||record.id||"").trim();if(!byStudent.has(key))byStudent.set(key,record);});
    dormDistributionRecord.lookup={records:records,length:records.length,byStudent:byStudent};
  }
  return dormDistributionRecord.lookup.byStudent.get(sid)||null;
}
function dormResourceBuildings(includeInactive){
  if(window.__DORM_SPATIAL__&&typeof window.__DORM_SPATIAL__.buildingRows==="function")return window.__DORM_SPATIAL__.buildingRows(!!includeInactive);
  return (ORG_DORMS||[]).map(function(item){return {zone:String(item.zone||"").trim()||"未分区",building:String(item.building||"").trim(),status:"active"};}).filter(function(item){return item.building;});
}
function dormMasterData(building){
  const value=String(building==null?"":building).trim();
  const batch=dormApplyRowsAtomically.context;if(batch)return batch.buildings.get(value)||null;
  if(value&&window.__DORM_SPATIAL__&&typeof window.__DORM_SPATIAL__.buildingInfo==="function")return window.__DORM_SPATIAL__.buildingInfo(value);
  return value?dormResourceBuildings(true).find(function(item){return String(item.building||"").trim()===value;})||null:null;
}
function ensureDormMasterData(zone,building){
  const cleanBuilding=String(building==null?"":building).trim();
  if(!cleanBuilding)return {zone:String(zone||"").trim(),building:"",added:false,updated:false};
  const cleanZone=String(zone==null?"":zone).trim(),fallbackZone=cleanZone||"未分区";
  let row=dormMasterData(cleanBuilding),added=false,updated=false;
  if(!row&&window.__DORM_SPATIAL__&&typeof window.__DORM_SPATIAL__.ensureBuilding==="function"){row=window.__DORM_SPATIAL__.ensureBuilding(fallbackZone,cleanBuilding);added=!!row;}
  if(!row){row={zone:fallbackZone,building:cleanBuilding};}
  const batch=dormApplyRowsAtomically.context;if(batch)batch.buildings.set(cleanBuilding,row);
  return {zone:String(row.zone||fallbackZone),building:cleanBuilding,added:added,updated:updated};
}
function syncDormBuildingZone(building,zone){
  const cleanBuilding=String(building||"").trim(),cleanZone=String(zone||"").trim();
  let studentChanged=false,recordChanged=false;
  students.forEach(function(student){if(String(student.building||"").trim()===cleanBuilding&&student.zone!==cleanZone){student.zone=cleanZone;studentChanged=true;}});
  (dormDistRecords||[]).forEach(function(record){if(String(record.building||"").trim()===cleanBuilding&&record.zone!==cleanZone){record.zone=cleanZone;recordChanged=true;}});
  if(studentChanged)persistStudents();
  if(recordChanged)persistDormDist();
  return studentChanged||recordChanged;
}
function reconcileDormMasterData(){
  let masterChanged=false,studentChanged=false,recordChanged=false;
  const byStudent={};students.filter(isOnCampusStudent).forEach(function(student){byStudent[String(student.id)]=student;});
  students.filter(isOnCampusStudent).forEach(function(student){const building=String(student.building||"").trim();if(!building)return;let master=dormMasterData(building);if(!master){const result=ensureDormMasterData(student.zone,building);master=dormMasterData(building)||result;masterChanged=true;}if(student.zone!==master.zone){student.zone=master.zone;studentChanged=true;}});
  (dormDistRecords||[]).forEach(function(record){const sid=String(record.studentId||record.id||""),student=byStudent[sid],building=String(record.building||(student&&student.building)||"").trim();if(!student||!building)return;let master=dormMasterData(building);if(!master){const result=ensureDormMasterData(record.zone||student.zone,building);master=dormMasterData(building)||result;masterChanged=true;}if(record.zone!==master.zone){record.zone=master.zone;recordChanged=true;}});
  if(studentChanged)persistStudents();
  if(recordChanged)persistDormDist();
  return {masters:masterChanged,students:studentChanged,records:recordChanged};
}
function dormDistributionRow(student){
  const record=dormDistributionRecord(student.id)||{};
  const building=record.building!==undefined?record.building:(student.building||"");
  const dormInfo=dormMasterData(building)||{};
  return {
    id:student.id,studentId:student.id,
    dept:student.dept||"",major:student.major||"",grade:student.grade||classGrade(student.cls||""),cls:student.cls||"",
    name:student.name||"",gender:student.gender||"",
    accom:record.accom!==undefined?record.accom:(student.accom||""),
    zone:dormInfo.zone||record.zone||student.zone||"",
    building:building,
    room:record.room!==undefined?record.room:(student.room||""),
    bed:record.bed!==undefined?record.bed:(student.bed||"")
  };
}
function dormDistRows(){
  /* 名单以学生管理的在校生为唯一来源；住宿记录只补充住宿字段。 */
  const state=viewFilter.dorm_dist||{};
  let recs=clsStudents().filter(isOnCampusStudent).map(dormDistributionRow);
  recs=recs.filter(function(r){ return qfMatch(state.dept,r.dept)&&qfMatch(state.major,r.major)&&qfMatch(state.grade,r.grade)&&qfMatch(state.cls,r.cls)&&qfMatch(state.accom,r.accom)&&qfMatch(state.zone,r.zone); });
  if(state.kw){ const k=state.kw.trim(); recs=recs.filter(function(r){ return (r.id||"").indexOf(k)>=0||(r.name||"").indexOf(k)>=0; }); }
  return recs;
}
