function dormViolateRows(){
  /* 返回【数据数组】（铁律：分页切片用）；导出与展示共用 */
  const state=viewFilter.dorm_violate||{};
  const ss=stuFilterByState(clsStudents(),state);
  const terms=selectedViewTerms("dormviolate");
  const recs=[];
  ss.forEach(function(s){ (s.dorm||[]).forEach(function(r,idx){ if(terms.indexOf(r.term||"")>=0) recs.push(Object.assign({},r,{name:s.name,cls:s.cls,dept:s.dept,major:s.major,id:s.id,_sid:s.id,_idx:idx})); }); });
  return recs.filter(function(r){ return qfMatch(state.building, (r.dorm||"").slice(0,2)) && qfMatch(state.major, r.major); });
}
