function readImageThumb(f){
  return new Promise((resolve)=>{
    const r=new FileReader();
    r.onload=()=>{ const img=new Image(); img.onload=()=>{ const c=document.createElement('canvas'); const w=120,h=Math.max(1,Math.round(120*img.height/img.width)); c.width=w;c.height=h; c.getContext('2d').drawImage(img,0,0,w,h); try{ resolve(c.toDataURL('image/jpeg',0.7)); }catch(e){ resolve(''); } }; img.onerror=()=>resolve(''); img.src=r.result; };
    r.onerror=()=>resolve(''); r.readAsDataURL(f);
  });
}
/* 学籍照片 / 证件照兼容读取：旧数据为 data:image/...;base64,... 字符串；新数据为后端附件引用对象 {id,name,url}。
   统一返回可直接用于 <img src> 的值；非法/缺失返回空串。 */
function stuImageSrc(photo){
  const p=photo;
  if(!p) return "";
  if(typeof p === "string") return /^data:image\/(?:png|jpeg|gif|webp|bmp);base64,[A-Za-z0-9+/=\s]+$/i.test(p)?p:"";
  if(p && typeof p === "object") return attachmentDisplayUrl(p);
  return "";
}
function stuPhotoSrc(s){return stuImageSrc(s&&s.photo);}
function stuIdPhotoSrc(s){return stuImageSrc(s&&s.idPhoto);}
/* 读取图片原图（不缩放、不压缩，保证原像素与画质），返回 data:image/...;base64,... */
function readImageFull(f){
  return new Promise((resolve)=>{
    const r=new FileReader();
    r.onload=()=>resolve(r.result||'');
    r.onerror=()=>resolve('');
    r.readAsDataURL(f);
  });
}
window.readImageThumb=readImageThumb;

function fundImport(targetTerm){
  try{targetTerm=lockedImportTerm(targetTerm||(viewTerm&&viewTerm.fund)||CURRENT_TERM);}catch(error){showToast(error.message,"warn");return;}
  window.__fundImportTargetTerm=targetTerm;
  const headers=FUND_DATA_HEADERS.slice();
  openMappedImportWizard({name:"资助情况",fields:headers,requiredFields:["学号"],template:"fundImportTemplate()",
    validate:function(rows){
      const seen=new Set(),ok=[],errors=[];
      rows.forEach(function(row,index){const sid=String(row["学号"]||"").trim(),term=targetTerm,key=sid+"|"+term;row["学期"]=targetTerm;if(!sid)errors.push({row:index+2,msg:"学号为空"});else if(seen.has(key))errors.push({row:index+2,msg:"同一学期学号重复："+sid+"（"+term+"）"});else if(!students.some(function(s){return String(s.id)===sid;}))errors.push({row:index+2,msg:"学号不存在："+sid});else{seen.add(key);ok.push(row);}});
      return {ok:ok,errors:errors};
    },
    apply:function(rows){return runFundRecordBatch(function(){let ok=0;rows.forEach(function(r){const sid=String(r["学号"]||"").trim(),s=students.find(function(x){return String(x.id)===sid;});if(!s)return;applyFundRecord(sid,s.name,s.dept,s.grade,s.cls,targetTerm,{isPoor:r["是否贫困生"]==="是",poorLevel:normalizeFundLevel(r["困难评定等级"]),national:r["国家助学金"]==="是",college:r["学院助学金"]==="是",nationalMotivational:r["国家励志助学金"]==="是",collegeMotivational:r["学院励志助学金"]==="是",temporaryAid:r["临时补助"]==="是",other:r["其他资助"]||"—"});ok++;});return {ok:ok,skip:rows.length-ok};});},
    after:function(){renderPage("fund");}
  });
}
