async function fundImportParse(fileObj){ return await parseWorkbookToRows(fileObj,FUND_DATA_HEADERS); }
/* ===== 资助导入：预处理（按学号自动匹配学籍 + 一致性校验） =====
   规则：表格内有学号即可；若同时填写了 姓名/学院/专业/班级 等学籍信息，则与学生管理核对，
   不一致收集到 mismatches（继续导入时以系统学籍为准）；若未填学籍信息则自动匹配系统学籍。 */
function fundImportProcess(rows){
  if(!rows||!rows.length){ $('#fundImportPreview').innerHTML='<div class="import-summary" style="margin-top:12px">文件中没有可导入的数据行。</div>'; return; }
  var mismatches=[]; // {sid,name,field,excel,system}
  var ok=[], errors=[];
  var seen=new Set();
  rows.forEach(function(r,i){
    const sid=smartCell(r,["学号"]);
    if(!sid){ errors.push({row:i+2, msg:"学号为空"}); return; }
    const stu=students.find(function(x){return String(x.id)===String(sid);});
    if(!stu){ errors.push({row:i+2, msg:"学号不存在："+sid}); return; }
    var targetTerm=(typeof window.__fundImportTargetTerm==='string' && window.__fundImportTargetTerm.trim())?window.__fundImportTargetTerm:CURRENT_TERM;
    var term=lockedImportTerm(targetTerm);
    var recordKey=sid+"|"+term;
    if(seen.has(recordKey)){ errors.push({row:i+2, msg:"同一学期学号重复："+sid+"（"+term+"）"}); return; }
    seen.add(recordKey);
    const row={"学号":sid};
    // 学籍字段：自动匹配 + 一致性校验
    var stuInfoMap={"姓名":stu.name||"","民族":stu.ethnic||stu.nation||"","学院":stu.dept||"","专业":stu.major||"","年级":stu.grade||classGrade(stu.cls)||"","班级":stu.cls||""};
    Object.keys(stuInfoMap).forEach(function(f){
      var excelRaw=smartCell(r,[f]);
      var sysVal=String(stuInfoMap[f]||"").trim();
      if(!excelRaw){
        row[f]=sysVal; // Excel 无此字段 → 自动匹配系统学籍
      } else if(String(excelRaw).trim()!==sysVal){
        mismatches.push({sid:sid, name:stu.name||"", field:f, excel:String(excelRaw).trim(), system:sysVal});
        row[f]=sysVal; // 以系统学籍为准暂存
      } else {
        row[f]=sysVal;
      }
    });
    // 学期锁定：无论 Excel 是否包含“学期”列，均写入用户在当前功能中选择的目标学期。
    row["学期"]=term;
    // 资助字段
    row["是否贫困生"]=smartCell(r,["是否贫困生"]);
    row["困难评定等级"]=normalizeFundLevel(smartCell(r,["困难评定等级","贫困等级"]));
    row["国家助学金"]=smartCell(r,["国家助学金"]);
    row["学院助学金"]=smartCell(r,["学院助学金"]);
    row["国家励志助学金"]=smartCell(r,["国家励志助学金"]);
    row["学院励志助学金"]=smartCell(r,["学院励志助学金"]);
    row["临时补助"]=smartCell(r,["临时补助"]);
    row["其他"]=smartCell(r,["其他资助","其他"]);
    ok.push(row);
  });
  // 预览
  const prevCols=["学号","姓名","民族","学院","专业","年级","班级","学期","是否贫困生","困难评定等级","国家助学金","学院助学金","国家励志助学金","学院励志助学金","临时补助","其他"];
  const prev=ok.map(function(r){ return '<tr><td>'+prevCols.map(function(c){ return esc(r[c]); }).join('</td><td>')+'</td></tr>'; }).join('');
  var html='<div class="import-preview"><div class="ph"><b>预览（'+ok.length+' 行可导入 / '+errors.length+' 行错误）</b></div>'
    +'<div style="max-height:240px;overflow:auto"><table class="import-field-table"><thead><tr>'+prevCols.map(function(c){return '<th>'+c+'</th>';}).join('')+'</tr></thead><tbody>'+prev+'</tbody></table></div></div>';
  if(mismatches.length){
    var mRows=mismatches.map(function(m){
      return '<tr><td style="padding:4px 10px;border-bottom:1px solid var(--border)">'+esc(m.sid)+'</td>'
        +'<td style="padding:4px 10px;border-bottom:1px solid var(--border)">'+esc(m.name)+'</td>'
        +'<td style="padding:4px 10px;border-bottom:1px solid var(--border)">'+esc(m.field)+'</td>'
        +'<td style="padding:4px 10px;border-bottom:1px solid var(--border);color:var(--danger)">'+esc(m.excel)+'</td>'
        +'<td style="padding:4px 10px;border-bottom:1px solid var(--border);color:var(--primary)">'+esc(m.system)+'</td></tr>';
    }).join('');
    html+='<div class="import-summary" style="margin-top:10px"><div style="font-size:13px;color:var(--danger);margin-bottom:6px">⚠ 发现 <b>'+mismatches.length+'</b> 处学籍信息与学生管理不一致（将以<b>系统学籍</b>为准）：</div>'
      +'<div style="max-height:200px;overflow-y:auto;border:1px solid var(--border);border-radius:6px"><table style="width:100%;font-size:12.5px;border-collapse:collapse">'
      +'<thead><tr style="background:var(--bg-alt)"><th style="padding:6px 10px;text-align:left">学号</th><th style="padding:6px 10px;text-align:left">姓名</th><th style="padding:6px 10px;text-align:left">字段</th><th style="padding:6px 10px;text-align:left">导入值</th><th style="padding:6px 10px;text-align:left">系统值</th></tr></thead><tbody>'+mRows+'</tbody></table></div></div>';
  }
  if(errors.length){
    var eRows=errors.map(function(e){ return '<li style="font-size:12.5px;color:var(--muted)">第 '+e.row+' 行：'+esc(e.msg)+'</li>'; }).join('');
    html+='<div class="import-summary" style="margin-top:10px"><div style="font-size:13px;color:var(--muted);margin-bottom:4px">以下行将被跳过：</div><ul style="margin:0;padding-left:18px">'+eRows+'</ul></div>';
  }
  html+='<div class="import-summary" style="margin-top:10px"><div class="kpi ok"><div class="n">'+ok.length+'</div><div class="l">可导入</div></div><div class="kpi fail"><div class="n">'+errors.length+'</div><div class="l">错误</div></div></div>';
  $('#fundImportPreview').innerHTML=html;
  const foot=document.getElementById('modalFoot');
  foot.innerHTML='<button class="btn btn-ghost" onclick="closeModal()">取消</button><button class="btn btn-primary" id="fundImportOk">确认导入 '+ok.length+' 条'+(mismatches.length?'（以系统学籍为准）':'')+'</button>';
  const okBtn=document.getElementById('fundImportOk');
  if(okBtn) okBtn.onclick=function(){ fundImportApplyData(ok); };
}
/* ===== 资助情况：显示源（fundRecords）与写入目标联动 =====
   同步写入学生档案与按学期的独立记录表，保证列表与档案一致。 */
function normalizeFundLevel(v){
  v=(v==null?"":String(v)).trim();
  if(!v || v==="—" || v==="未认定" || v==="未评定") return "未评定等级";
  return v==="困难"?"比较困难":v;
}
function fundRecordForStudentTerm(sid,term){
  const key=String(sid==null?"":sid), target=String(term==null?"":term);
  const batch=applyFundRecord.context;if(batch)return batch.records.get(JSON.stringify([key,target]))||null;
  return (fundRecords||[]).find(function(r){return String(r.studentId||r.id||"")===key && String(r.term||"")===target;})||null;
}
function fundLatestRecordForStudent(sid){
  const key=String(sid==null?"":sid);
  const batch=applyFundRecord.context;if(batch)return batch.latest.get(key)||null;
  return sortTermsDesc((fundRecords||[]).filter(function(r){return String(r.studentId||r.id||"")===key;}))[0]||null;
}
function fundProfileSnapshot(record){
  if(!record) return {};
  return {term:record.term||"",isPoor:record.isPoor===true,poorLevel:normalizeFundLevel(record.poorLevel),national:record.national===true,college:record.college===true,nationalMotivational:record.nationalMotivational===true,collegeMotivational:record.collegeMotivational===true,temporaryAid:record.temporaryAid===true,other:record.other||"—"};
}
function syncFundProfileSnapshot(student){
  if(!student) return false;
  const next=fundProfileSnapshot(fundLatestRecordForStudent(student.id));
  if(JSON.stringify(student.fund||{})===JSON.stringify(next)) return false;
  student.fund=next;
  return true;
}
function runFundRecordBatch(work){
  if(applyFundRecord.context)return work();
  const beforeRecords=JSON.parse(JSON.stringify(fundRecords||[])),beforeTerms=JSON.parse(JSON.stringify(window.fundTerms||[])),beforeSeq=window.fundTermSeq;
  const beforeProfiles=students.map(function(student){return {student:student,present:Object.prototype.hasOwnProperty.call(student,"fund"),fund:JSON.parse(JSON.stringify(student.fund||{}))};});
  const batch={students:new Map(students.map(function(student){return [String(student.id),student];})),records:new Map(),latest:new Map(),changedStudents:new Set(),termsDirty:false};
  (fundRecords||[]).forEach(function(record){const sid=String(record.studentId||record.id||""),key=JSON.stringify([sid,String(record.term||"")]);if(!batch.records.has(key))batch.records.set(key,record);});
  sortTermsDesc(fundRecords||[]).forEach(function(record){const sid=String(record.studentId||record.id||"");if(!batch.latest.has(sid))batch.latest.set(sid,record);});
  applyFundRecord.context=batch;
  try{
    const result=work();let profileChanged=false;batch.changedStudents.forEach(function(student){if(syncFundProfileSnapshot(student))profileChanged=true;});
    if(profileChanged)persistStudents();if(batch.recordsChanged)persistFund();if(batch.termsDirty)saveFundTerms();return result;
  }catch(error){
    applyFundRecord.context=null;fundRecords=beforeRecords;window.fundTerms=beforeTerms;window.fundTermSeq=beforeSeq;
    beforeProfiles.forEach(function(item){if(item.present)item.student.fund=item.fund;else delete item.student.fund;});
    try{persistStudents();persistFund();saveFundTerms();}catch(rollbackError){reportDataError("资助批次回滚",rollbackError);}throw error;
  }finally{applyFundRecord.context=null;}
}
function applyFundRecord(sid, name, dept, grade, cls, term, vals){
  term=term||CURRENT_TERM;
  /* 困难评定等级是独立字段；“是否贫困生=否”时也必须保留“未评定等级”等用户选择。 */
  if(vals) vals.poorLevel=normalizeFundLevel(vals.poorLevel);
  const batch=applyFundRecord.context,s=batch?batch.students.get(String(sid)):students.find(x=>x.id===sid);
  if(Array.isArray(fundRecords)){ const recordId="fund_"+encodeURIComponent(sid)+"_"+encodeURIComponent(term); let rec=fundRecordForStudentTerm(sid,term); if(!rec){ rec={id:recordId,studentId:sid,name:name,dept:dept,major:(s&&s.major)||"",grade:grade,cls:cls,term:term}; fundRecords.push(rec); } else { rec.id=rec.id||recordId; rec.studentId=sid; } rec.isPoor=vals.isPoor; rec.poorLevel=vals.poorLevel; rec.national=vals.national; rec.college=vals.college; rec.nationalMotivational=vals.nationalMotivational; rec.collegeMotivational=vals.collegeMotivational; rec.temporaryAid=vals.temporaryAid; rec.other=vals.other; if(batch){batch.records.set(JSON.stringify([String(sid),String(term)]),rec);const latest=batch.latest.get(String(sid));if(!latest||sortTermsDesc([rec,latest])[0]===rec)batch.latest.set(String(sid),rec);batch.recordsChanged=true;} }
  ensureFundTerm(term);
  if(batch){if(s)batch.changedStudents.add(s);return;}
  if(s && syncFundProfileSnapshot(s)) persistStudents();
  persistFund();
}
window.applyFundRecord=applyFundRecord;
function persistDormDist(){ dormDistributionRecord.lookup=null;try{ localStorage.setItem("nnuzc_dorm_dist", JSON.stringify(dormDistRecords||[])); }catch(e){ reportDataError("宿舍分布记录保存",e); throw e; } }
function persistFund(){ try{ localStorage.setItem("nnuzc_fund_records", JSON.stringify(fundRecords||[])); }catch(e){ reportDataError("资助记录保存",e); throw e; } }
/* ===== 资助情况：模块内学期列表（fundTerms）持久化与查询 ===== */
const FUND_TERMS_KEY="nnuzc_fund_terms";
function saveFundTerms(){ try{ window.fundTerms=sortTermsDesc(window.fundTerms); localStorage.setItem(FUND_TERMS_KEY, JSON.stringify(window.fundTerms||[])); }catch(e){ reportDataError("资助学期保存",e); throw e; } }
function loadFundTerms(){
  let raw="", merged=false;
  try{
    raw = localStorage.getItem(FUND_TERMS_KEY)||"";
    const v = JSON.parse(raw||"[]");
    if(Array.isArray(v)) window.fundTerms = v.map(function(t){ return {id:Number(t.id)||0, term:String(t.term||"")}; }).filter(function(t){ return t.term; });
  }catch(e){ reportDataError("资助学期加载",e); }
  const usedIds=new Set(),usedTerms=new Set();
  let nextId=window.fundTerms.reduce(function(max,item){return Math.max(max,Number(item.id)||0);},0);
  window.fundTerms=window.fundTerms.filter(function(item){if(usedTerms.has(item.term)){merged=true;return false;}usedTerms.add(item.term);return true;}).map(function(item){
    if(!Number.isInteger(item.id)||item.id<=0||usedIds.has(item.id)){item.id=++nextId;merged=true;}
    usedIds.add(item.id);
    return item;
  });
  /* 合并 fundRecords 中已存在的学期，保证历史数据在列表可见 */
  (fundRecords||[]).forEach(function(r){
    const term=String(r.term||"");
    if(term && !usedTerms.has(term)){
      window.fundTerms.push({id:++nextId,term:term});
      usedTerms.add(term);
      merged=true;
    }
  });
  window.fundTerms = sortTermsDesc(window.fundTerms);
  window.fundTermSeq = nextId;
  const normalized=JSON.stringify(window.fundTerms);
  /* 刷新仅读取：仅在历史记录确有缺失学期或既有格式需要归一化时才回写一次。 */
  if((raw || merged) && normalized!==raw) saveFundTerms();
}
function fundTermById(id){ return window.fundTerms.find(function(t){ return t.id===id; }) || null; }
function fundTermByTerm(term){ const t=String(term||"").trim(); return window.fundTerms.find(function(x){ return (x.term||"")===t; }) || null; }
function fundValidateTerm(raw){
  const t=(raw||"").trim();
  if(!t) return "请输入学期";
  const m=t.match(/^(\d{4})-(\d{4})-([1-9])学期$/);
  if(!m) return "格式错误：请按「YYYY-YYYY-N学期」输入，例如 2026-2027-1学期";
  const y1=parseInt(m[1],10), y2=parseInt(m[2],10);
  if(y2!==y1+1) return "学年应连续：例如 2026-2027-1学期（第二年=第一年+1）";
  return "";
}
function ensureFundTerm(term){
  term=String(term||"").trim(); if(!term) return;
  if(getTermList().indexOf(term)===-1) throw new Error("学期“"+term+"”未在学期设置中维护，不能写入资助情况。");
  if(!window.fundTerms.some(function(t){ return t.term===term; })){
    window.fundTerms.push({id: (window.fundTermSeq = (window.fundTermSeq||0) + 1), term: term});
    window.fundTerms = sortTermsDesc(window.fundTerms);
    if(applyFundRecord.context)applyFundRecord.context.termsDirty=true;else saveFundTerms();
  }
}
const DORM_DIST_KEY="nnuzc_dorm_dist", FUND_KEY="nnuzc_fund_records";
function loadStandaloneModuleRecords(){
  try{const v=JSON.parse(localStorage.getItem(DORM_DIST_KEY)||"[]");if(Array.isArray(v))dormDistRecords=v;}catch(e){reportDataError("宿舍分布记录加载",e);}
  try{const v=JSON.parse(localStorage.getItem(FUND_KEY)||"[]");if(Array.isArray(v)){fundRecords=v;let changed=false;fundRecords.forEach(function(r){const sid=String(r.studentId||r.id||"");if(!sid)return;r.studentId=sid;const stableId="fund_"+encodeURIComponent(sid)+"_"+encodeURIComponent(r.term||CURRENT_TERM||"");if(r.id!==stableId){r.id=stableId;changed=true;}});if(changed)persistFund();}}catch(e){reportDataError("资助记录加载",e);}
  loadFundTerms();
}
/* 学生档案保留最近一次资助录入，台账才是权威来源。
   启动时仅清除不存在于台账的历史快照，修复旧版删除学期留下的残留数据。 */
function reconcileFundProfileSnapshots(){
  let changed=false;
  students.forEach(function(s){
    if(syncFundProfileSnapshot(s)) changed=true;
  });
  if(changed) persistStudents();
  return changed;
}
