function persistStudentLoans(){
  try{ studentLoanRecords=(studentLoanRecords||[]).slice().sort(function(a,b){return compareAcademicPeriodsDesc(a,b)||String(a.studentId||"").localeCompare(String(b.studentId||""),"zh-CN",{numeric:true});}); localStorage.setItem(STUDENT_LOAN_KEY,JSON.stringify(studentLoanRecords)); }
  catch(e){ reportDataError("助学贷款记录保存",e); throw e; }
}
function studentLoanCurrentYear(){
  const term=String(CURRENT_TERM||"").trim(), matched=term.match(/^(\d{4}-\d{4})-/);
  if(matched) return matched[1]+"学年";
  const now=beijingIsoDate().split("-").map(Number), start=now[1]>=7?now[0]:now[0]-1;
  return start+"-"+(start+1)+"学年";
}
function studentLoanValidYear(value){
  const matched=String(value||"").trim().match(/^(\d{4})-(\d{4})学年$/);
  return !!(matched&&Number(matched[2])===Number(matched[1])+1);
}
function studentLoanYears(){
  const values=[];
  function add(value){ value=String(value||"").trim(); if(studentLoanValidYear(value)&&values.indexOf(value)<0) values.push(value); }
  add(studentLoanCurrentYear());
  (typeof getTermList==="function"?getTermList():[]).forEach(function(term){const matched=String(term||"").match(/^(\d{4}-\d{4})-/);if(matched)add(matched[1]+"学年");});
  studentLoanRecords.forEach(function(record){add(record.year);});
  return sortAcademicYearsDesc(values);
}
function studentLoanUnique(values){
  return Array.from(new Set((values||[]).map(function(value){return String(value||"").trim();}).filter(Boolean))).sort(function(a,b){return a.localeCompare(b,"zh-CN",{numeric:true});});
}
function studentLoanOption(values,current,blank){
  return '<option value="">'+esc(blank)+'</option>'+values.map(function(value){return '<option value="'+escAttr(value)+'"'+(String(value)===String(current)?' selected':'')+'>'+esc(value)+'</option>';}).join("");
}
function studentLoanStudent(record){ return students.find(function(student){return String(student.id)===String(record&&record.studentId);})||{}; }
function studentLoanFilteredRecords(){
  const f=studentLoanFilters;
  return studentLoanRecords.filter(function(record){
    const student=studentLoanStudent(record), text=[record.studentId,record.name,student.name,record.bank,record.dept,record.major,record.grade,record.cls].join(" ").toLowerCase();
    return (!f.year||record.year===f.year)&&(!f.kw||text.indexOf(f.kw.toLowerCase())>=0)&&(!f.dept||(record.dept||student.dept||"")===f.dept)&&(!f.major||(record.major||student.major||"")===f.major)&&(!f.grade||(record.grade||student.grade||"")===f.grade)&&(!f.cls||(record.cls||student.cls||"")===f.cls);
  }).sort(function(a,b){return String(b.year||"").localeCompare(String(a.year||""),"zh-CN",{numeric:true})||String(a.dept||"").localeCompare(String(b.dept||""),"zh-CN")||String(a.cls||"").localeCompare(String(b.cls||""),"zh-CN",{numeric:true})||String(a.studentId||"").localeCompare(String(b.studentId||""),"zh-CN",{numeric:true});});
}
function studentLoanMoney(value){
  if(value===""||value===null||value===undefined) return "—";
  const amount=Number(value); return Number.isFinite(amount)?amount.toLocaleString("zh-CN",{style:"currency",currency:"CNY",minimumFractionDigits:2}):"—";
}
