/* ===== 宿舍分布：显示源（dormDistRecords）与写入目标联动 =====
   同步写入学生档案与宿舍分布记录表，使列表与档案实时联动。 */
function applyDormDistribution(id, fields){
  const batch=dormApplyRowsAtomically.context,s=batch?batch.students.get(String(id)):students.find(function(item){return String(item.id)===String(id);});
  if(!s || !isOnCampusStudent(s)){showToast("仅能为当前在校生维护住宿信息","warn");return false;}
  fields=Object.assign({},fields||{});
  const current=dormDistributionRow(s),next={};
  ["accom","zone","building","room","bed"].forEach(function(key){next[key]=String(fields[key]!==undefined?fields[key]:(current[key]||"")).trim();});
  if(["","校内","租房","走读"].indexOf(next.accom)<0){showToast("住宿情况仅支持：校内、租房、走读或未录入","warn");return false;}
  const knownMaster=next.building?dormMasterData(next.building):null;if(knownMaster)next.zone=String(knownMaster.zone||next.zone||"").trim();
  if(next.accom==="校内"&&!next.zone)next.zone="未分区";
  if(next.accom==="校内"&&(!next.building||!next.room||!next.bed)){showToast("校内住宿必须完整填写宿舍楼、房间号和床位号","warn");return false;}
  if(next.accom!=="校内"){next.zone="";next.building="";next.room="";next.bed="";}
  if(next.accom==="校内"){
    const bedNumber=Number(next.bed),spatialState=batch?batch.spatial:window.__DORM_SPATIAL__&&typeof window.__DORM_SPATIAL__.getState==="function"?window.__DORM_SPATIAL__.getState():null;
    if(!Number.isInteger(bedNumber)||bedNumber<1){showToast("床位号必须为大于 0 的整数","warn");return false;}next.bed=String(bedNumber);
    if(spatialState&&bedNumber>Number((spatialState.settings||{}).maxBedCount||30)){showToast("床位号超过当前单间安全上限","warn");return false;}
    const roomResource=batch?batch.rooms.get(dormBatchRoomKey(next)):spatialState&&(spatialState.rooms||[]).find(function(room){return String(room.zone||"").trim()===next.zone&&String(room.building||"").trim()===next.building&&String(room.room||"").trim()===next.room;});
    if(roomResource&&roomResource.status==="inactive"){showToast("目标宿舍已停用，不能安排入住","warn");return false;}
    if(roomResource&&bedNumber>Number(roomResource.bedCount||0)){showToast("目标宿舍仅配置 "+roomResource.bedCount+" 个床位，不能写入 "+bedNumber+" 号床","warn");return false;}
    const conflict=batch?Array.from(batch.occupied.get(dormBatchBedKey(next))||[]).find(function(other){return String(other.id)!==String(s.id);}):students.filter(isOnCampusStudent).find(function(other){
      if(String(other.id)===String(s.id))return false;
      const row=dormDistributionRow(other);
      return row.accom==="校内"&&String(row.zone||"").trim()===next.zone&&String(row.building||"").trim()===next.building&&String(row.room||"").trim()===next.room&&String(row.bed||"").trim()===next.bed;
    });
    if(conflict){showToast("床位 "+next.zone+" "+next.building+" "+next.room+"室 "+next.bed+"号已分配给 "+conflict.id+" "+conflict.name,"warn");return false;}
  }
  const studentSnapshot=batch?null:JSON.parse(JSON.stringify(s)),recordsSnapshot=batch?null:JSON.parse(JSON.stringify(dormDistRecords||[])),orgSnapshot=batch?null:JSON.parse(JSON.stringify(ORG_DORMS||[])),spatialSnapshot=batch?null:window.__DORM_SPATIAL__&&typeof window.__DORM_SPATIAL__.getState==="function"?window.__DORM_SPATIAL__.getState():null;
  try{
    if(next.accom==="校内"){const master=ensureDormMasterData(next.zone,next.building);next.building=master.building;next.zone=master.zone;}
    ["accom","zone","building","room","bed"].forEach(function(key){s[key]=next[key];});
    if(!Array.isArray(dormDistRecords))dormDistRecords=[];
    let rec=dormDistributionRecord(s.id);if(!rec){rec={id:s.id,studentId:s.id};dormDistRecords.push(rec);}
    rec.id=s.id;rec.studentId=s.id;rec.name=s.name;rec.dept=s.dept;rec.major=s.major;rec.grade=s.grade||classGrade(s.cls||"");rec.cls=s.cls;rec.gender=s.gender;
    ["accom","zone","building","room","bed"].forEach(function(key){rec[key]=next[key];});
    if(batch){
      batch.records.set(String(s.id),rec);
      const oldBed=batch.occupied.get(dormBatchBedKey(current));if(oldBed)oldBed.delete(s);
      if(next.accom==="校内"){const key=dormBatchBedKey(next);if(!batch.occupied.has(key))batch.occupied.set(key,new Set());batch.occupied.get(key).add(s);}
      return true;
    }
    persistStudents();persistDormDist();
    if(window.__DORM_SPATIAL__&&typeof window.__DORM_SPATIAL__.onAccommodationChanged==="function")window.__DORM_SPATIAL__.onAccommodationChanged(s.id);
    return true;
  }catch(error){
    if(batch)throw error;
    Object.keys(s).forEach(function(key){delete s[key];});Object.assign(s,studentSnapshot);dormDistRecords=recordsSnapshot;ORG_DORMS.splice(0,ORG_DORMS.length,...orgSnapshot);if(spatialSnapshot&&window.__DORM_SPATIAL__&&typeof window.__DORM_SPATIAL__.restoreState==="function")window.__DORM_SPATIAL__.restoreState(spatialSnapshot);try{persistStudents();persistDormDist();saveOrgs();}catch(_ignore){}reportDataError("住宿信息保存",error);showToast("住宿信息保存失败，已回滚本次修改","error");return false;
  }
}
window.applyDormDistribution=applyDormDistribution;
window.dormEdit=function(id){
  const student=students.find(function(item){return String(item.id)===String(id);}); if(!student)return;
  const s=dormDistributionRow(student);
  const zones=[]; dormResourceBuildings().forEach(d=>{ if(d.zone && zones.indexOf(d.zone)<0) zones.push(d.zone); });
  const hasDormMaster = zones.length>0;
  const curZoneObj = dormMasterData(s.building);
  const curZone = curZoneObj? curZoneObj.zone : "";
  window.__dormEditCurBuilding = s.building || "";
  let zoneField, buildingField;
  if(hasDormMaster){
    const zoneOpts='<option value="">—</option>'+zones.map(z=>'<option value="'+escAttr(z)+'"'+(z===curZone?' selected':'')+'>'+esc(z)+'</option>').join('');
    zoneField='<div class="field"><label>区位</label><select id="dEditZone" class="role" onchange="dormBuildingOptions()">'+zoneOpts+'</select></div>';
    buildingField='<div class="field"><label>宿舍楼</label><select id="dEditBuilding" class="role"></select></div>';
  } else {
    zoneField='<div class="field"><label>区位</label><input id="dEditZone" value="'+escAttr(curZone)+'" placeholder="（公寓资源未配置宿舍楼，可自由填）"></div>';
    buildingField='<div class="field"><label>宿舍楼</label><input id="dEditBuilding" value="'+escAttr(s.building)+'"></div>';
  }
  openModal('编辑住宿信息',
    "<div class='field'><label>学号</label><input value='"+escAttr(s.id)+"' readonly></div>"
    +"<div class='field'><label>姓名</label><input value='"+escAttr(s.name)+"' readonly></div>"
    +"<div class='row2'><div class='field'><label>住宿情况</label><select id='dEditAccom'><option"+(s.accom==='校内'?' selected':'')+">校内</option><option"+(s.accom==='租房'?' selected':'')+">租房</option><option"+(s.accom==='走读'?' selected':'')+">走读</option></select></div>"+zoneField+"</div>"
    +"<div class='row2'>"+buildingField+"<div class='field'><label>房间号</label><input id='dEditRoom' value='"+escAttr(s.room)+"'></div></div>"
    +"<div class='row2'><div class='field'><label>床位号</label><input id='dEditBed' value='"+escAttr(s.bed)+"'></div></div>"
    + (hasDormMaster?'<div style="font-size:12.5px;color:#888;margin-top:4px">区位与宿舍楼选项来自「宿舍管理 → 公寓资源」；如列表未列出，请先在公寓资源中新增宿舍楼。</div>':''),
    function(){
      const accom=$('#dEditAccom').value;
      const zone=$('#dEditZone')?($('#dEditZone').value||''):'';
      const building=$('#dEditBuilding')?($('#dEditBuilding').value||''):'';
      const room=$('#dEditRoom').value, bed=$('#dEditBed').value;
      if(!applyDormDistribution(id,{accom:accom,zone:zone,building:building,room:room,bed:bed}))return false;
      goto('dorm');
    });
  if(hasDormMaster) window.dormBuildingOptions();
};
window.dormBuildingOptions=function(){
  const zoneEl=$('#dEditZone'); const bEl=$('#dEditBuilding'); if(!zoneEl||!bEl) return;
  const zone=zoneEl.value||"";
  const builds=dormResourceBuildings().filter(d=>d.zone===zone).map(d=>d.building).filter(Boolean);
  const cur=window.__dormEditCurBuilding||"";
  bEl.innerHTML='<option value="">—</option>'+builds.map(b=>'<option value="'+escAttr(b)+'"'+(b===cur?' selected':'')+'>'+esc(b)+'</option>').join('');
};
window.dormAddBuildingOptions=function(){
  const zoneEl=document.getElementById("daZone"); const bEl=document.getElementById("daBuilding"); if(!zoneEl||!bEl) return;
  const zone=zoneEl.value||"";
  const builds=dormResourceBuildings().filter(d=>d.zone===zone).map(d=>d.building).filter(Boolean);
  bEl.innerHTML='<option value="">—</option>'+builds.map(function(b){return '<option value="'+escAttr(b)+'">'+esc(b)+'</option>';}).join('');
};
window.dormDel=function(id){
  if(window.__DORM_SPATIAL__&&typeof window.__DORM_SPATIAL__.checkoutStudent==="function"){if(window.__DORM_SPATIAL__.checkoutStudent(id,"清除住宿","manual"))goto('dorm');return;}
  if(!confirm('确定清除该学生的住宿信息？学生仍会保留在在校生名单中。'))return;
  const sid=String(id);
  const student=students.find(function(item){return String(item.id)===sid;}),studentSnapshot=student?JSON.parse(JSON.stringify(student)):null,recordsSnapshot=JSON.parse(JSON.stringify(dormDistRecords||[]));
  try{if(student){student.accom="";student.zone="";student.building="";student.room="";student.bed="";}dormDistRecords=(Array.isArray(dormDistRecords)?dormDistRecords:[]).filter(function(record){return String(record.studentId||record.id||"")!==sid;});persistStudents();persistDormDist();goto('dorm');}
  catch(error){if(student&&studentSnapshot){Object.keys(student).forEach(function(key){delete student[key];});Object.assign(student,studentSnapshot);}dormDistRecords=recordsSnapshot;try{persistStudents();persistDormDist();}catch(_ignore){}reportDataError("清除住宿",error);showToast("清除住宿失败，已回滚","error");}
};
function ensureStudentNested(s){
  /* 兼容旧版 localStorage 数据：保证嵌套字段存在，避免 PAGES 读取 undefined 崩溃 */
  if(!s || typeof s!=="object") return s;
  /* 统一真实导入数据与旧表单字段，避免详情显示空白或编辑后形成双字段。 */
  const aliases={ethnic:"nation",birth:"birthDate",idcard:"idCard",address:"homeAddr",building:"dormBuild",room:"dormRoom",level:"eduLevel",enroll:"enrollDate",source:"origin",enrollType:"studentCategory"};
  Object.keys(aliases).forEach(function(k){ if((s[k]===undefined||s[k]===null||s[k]==="") && s[aliases[k]]!=null) s[k]=s[aliases[k]]; });
  fillStudentIdentityFields(s);
  /* 历史数据未维护学籍状态时按系统既有默认语义补为“在校”；名单外旧值保留，编辑时必须重新选择。 */
  if(!String(s.status||"").trim()) s.status="在校";
  if(!Array.isArray(s.classroom)) s.classroom=[];
  if(!Array.isArray(s.dorm)) s.dorm=[];
  if(!Array.isArray(s.punishments)) s.punishments=[];
  if(!s.classroomSelfCriticism || typeof s.classroomSelfCriticism!=="object") s.classroomSelfCriticism={};
  if(!s.fund || typeof s.fund!=="object") s.fund={term:"",isPoor:false,poorLevel:"—",national:false,college:false,nationalMotivational:false,collegeMotivational:false,temporaryAid:false,other:"—"};
  if(!s.party || typeof s.party!=="object") s.party={stage:"群众",date:"",branch:"",contact:"",materials:"—"};
  if(!s.psych || typeof s.psych!=="object") s.psych={level:"正常",issues:[],note:"",updated:""};
  return s;
}
function normalizeAllStudents(){
  let changed=false;
  for(const s of students){
    const before=JSON.stringify(s);
    delete s.remark1;
    delete s.remark2;
    delete s.customFields;
    ensureStudentNested(s);
    /* 已删除：2026-08-04 班委管理模块 — 清除其遗留的对象格式 s.cadre({role,joinDate})，
       保留「学生干部任职」字符串字段；对象格式即来自该模块的设置 */
    if(s && typeof s.cadre==="object"){ delete s.cadre; changed=true; }
    if(JSON.stringify(s)!==before) changed=true;
  }
  return changed;
}
function loadStudents(){
  try{
    const raw=localStorage.getItem("nnuzc_students");
    if(raw){
      const arr=JSON.parse(raw);
      if(Array.isArray(arr)){
        students.length=0;
        arr.forEach(s=>students.push(s));
      }
      /* 兼容：宿舍违纪记录权威保存在学生 s.dorm，但历史上曾单独落到 nnuzc_dorm，
         启动时把它合并回 s.dorm，避免早期新增的违纪记录在刷新后丢失。 */
      try{
        const dormRaw=localStorage.getItem("nnuzc_dorm");
        if(dormRaw){
          const dm=JSON.parse(dormRaw);
          if(dm && typeof dm==="object"){
            students.forEach(function(s){
              const ds=dm[s.id];
              if(Array.isArray(ds) && ds.length){
                s.dorm=Array.isArray(s.dorm)?s.dorm:[];
                ds.forEach(function(r){
                  /* 主档 s.dorm 是当前权威数据。历史独立缓存只补缺，不得因为
                     自定义字段或附件发生变化而把同一条违纪记录重复合并回来。 */
                  const sameRecord=function(x){
                    if(r.customFieldRecordId&&x.customFieldRecordId) return String(r.customFieldRecordId)===String(x.customFieldRecordId);
                    return String(r.term||"")===String(x.term||"")
                      && String(r.date||"")===String(x.date||"")
                      && String(r.dorm||"")===String(x.dorm||"")
                      && String(r.reason||"")===String(x.reason||"");
                  };
                  if(!s.dorm.some(sameRecord)) s.dorm.push(r);
                });
              }
            });
          }
        }
      }catch(e){ /* ignore */ }
    }
    /* 嵌套字段仅用于本次运行时兼容。服务端会省略空数组/默认对象，启动时回写会导致每次刷新重复同步全体学生。 */
    normalizeAllStudents();
    recomputeFilterOptions();
  }catch(e){ reportDataError("学生信息加载",e); }
}
/* v1.38：学院/专业/班级/年级 过滤选项从「基础数据维护」派生（关联）；基础数据为空时回退到学生信息，保证筛选可用 */
function distinctDepts(){ return (students||[]).map(function(s){return s.dept;}).filter(Boolean); }
function recomputeFilterOptions(){
  sortWorkbenchCollections();
  classes.length=0; majors.length=0; grades.length=0; depts.length=0;
  var deptsSrc = ORG_DEPTS.length ? ORG_DEPTS.map(function(d){ return d.name; }) : (students||[]).map(function(s){ return s.dept; }).filter(Boolean);
  deptsSrc.forEach(function(d){ if(d && depts.indexOf(d)<0) depts.push(d); });
  var majSrc = ORG_MAJORS.length ? ORG_MAJORS.map(function(m){ return m.name; }) : (students||[]).map(function(s){ return s.major; }).filter(Boolean);
  majSrc.forEach(function(m){ if(m && majors.indexOf(m)<0) majors.push(m); });
  var clsSrc = ORG_CLASSES.length ? ORG_CLASSES.map(function(c){ return c.name; }) : (students||[]).map(function(s){ return s.cls; }).filter(Boolean);
  clsSrc.forEach(function(c){ if(c && classes.indexOf(c)<0) classes.push(c); });
  classes.sort(function(a,b){ return compareWorkbenchCode(classPrefixOf(a),classPrefixOf(b))||compareWorkbenchText(a,b); });
  var gSrc = ORG_GRADES.length ? ORG_GRADES.map(function(g){ return g.name; }) : (ORG_CLASSES.length ? ORG_CLASSES.map(function(c){ return c.grade; }).filter(Boolean) : (students||[]).map(function(s){ return s.grade; }).filter(Boolean));
  gSrc.forEach(function(g){ if(g && grades.indexOf(g)<0) grades.push(g); });
}
/* 所有业务模块的级联选择均从「基础数据维护」派生，避免仅因尚无业务记录而漏项。 */
function orgFilterValues(field){
  if(field==="dept") return ORG_DEPTS.map(function(d){return d.name;}).filter(Boolean);
  if(field==="major") return ORG_MAJORS.map(function(m){return m.name;}).filter(Boolean);
  if(field==="grade") return (ORG_GRADES.length ? ORG_GRADES.map(function(g){return g.name;}) : ORG_CLASSES.map(function(c){return c.grade;}).filter(Boolean).filter(function(v,i,a){return a.indexOf(v)===i;})).sort(function(a,b){return compareWorkbenchCode(gradeOrderKey(a),gradeOrderKey(b))||compareWorkbenchText(a,b);});
  if(field==="cls") return ORG_CLASSES.map(function(c){return c.name;}).filter(Boolean).sort(function(a,b){ return compareWorkbenchCode(classPrefixOf(a),classPrefixOf(b))||compareWorkbenchText(a,b); });
  return [];
}
function persistStudents(){
  try{ classOfficerAutoEndNonCampus(); sortWorkbenchCollections(); localStorage.setItem("nnuzc_students", JSON.stringify(students)); }catch(e){ reportDataError("学生信息保存",e); throw e; }
  if(window.__DORM_SPATIAL__&&typeof window.__DORM_SPATIAL__.onStudentDataChanged==="function")window.__DORM_SPATIAL__.onStudentDataChanged({source:"student-management"});
}
window.persistStudents=persistStudents;
function persistDormViolation(){
  try{
    const map={};
    students.forEach(s=>{ if(s.dorm && s.dorm.length) map[s.id]=s.dorm; });
    localStorage.setItem("nnuzc_dorm", JSON.stringify(map));
  }catch(e){ reportDataError("宿舍违纪记录保存",e); throw e; }
}
window.persistDormViolation=persistDormViolation;
/* 不在启动时同步：学生主档案已是宿舍违纪记录的权威来源；仅在用户实际新增、修改、删除违纪记录时调用。 */
/* 宿舍管理只维护住宿信息；学生身份和在校名单统一来自学生管理。 */
function dormAddBody(){
  const zones=[]; dormResourceBuildings().forEach(d=>{ if(d.zone && zones.indexOf(d.zone)<0) zones.push(d.zone); });
  let zoneField='', buildingField;
  if(zones.length){
    const zoneOpts='<option value="">—</option>'+zones.map(z=>'<option value="'+escAttr(z)+'">'+esc(z)+'</option>').join('');
    zoneField='<div class="field"><label>区位</label><select id="daZone" class="role" onchange="dormAddBuildingOptions()">'+zoneOpts+'</select></div>';
    buildingField='<div class="field"><label>宿舍楼</label><select id="daBuilding" class="role"></select></div>';
  } else {
    zoneField='<div class="field"><label>区位</label><input id="daZone" placeholder="如 东区" maxlength="20"></div>';
    buildingField='<div class="field"><label>楼栋</label><input id="daBuilding" placeholder="如 A栋" maxlength="20"></div>';
  }
  return '<div class="tip" style="margin-bottom:12px">名单与学生管理中的在校生自动同步。这里只能为已有在校生新增住宿信息；姓名、学院、专业、年级、班级等身份信息请在学生管理中维护。</div>'
    +'<div class="row2"><div class="field"><label>学号 <span style="color:#d6453d">*</span></label><input id="daId" placeholder="如 2024010101" maxlength="20"></div>'
    +'<div class="field"><label>姓名</label><input id="daName" maxlength="20" placeholder="可输入姓名匹配在校生"></div></div>'
    +'<div class="row2"><div class="field"><label>性别</label><input id="daGender" readonly></div>'
    +'<div class="field"><label>学院</label><input id="daDept" readonly></div></div>'
    +'<div class="row2"><div class="field"><label>专业</label><input id="daMajor" readonly></div>'
    +'<div class="field"><label>年级</label><input id="daGrade" readonly></div></div>'
    +'<div class="row2"><div class="field"><label>班级</label><input id="daCls" readonly></div>'
    +'<div class="field"><label>住宿情况 <span style="color:#d6453d">*</span></label>'+qfSingle("daAccom",[{v:"",l:"请选择"},{v:"校内",l:"校内"},{v:"租房",l:"租房"},{v:"走读",l:"走读"}],"")+'</div></div>'
    +'<div class="row2">'+zoneField+buildingField+'</div>'
    +'<div class="row2"><div class="field"><label>房间号</label><input id="daRoom" placeholder="如 302" maxlength="10"></div><div class="field"><label>床位号</label><input id="daBed" placeholder="如 3" maxlength="10"></div></div>';
}
function dormAddAutoFill(){
  const idEl=document.getElementById("daId");
  if(!idEl)return;
  const id=idEl.value.trim();
  if(!id)return;
  const s=students.find(function(x){return String(x.id)===id;});
  if(!s){showToast("该学号不在学生管理中，请先新增学生","warn");return;}
  if(!isOnCampusStudent(s)){showToast("该学生当前不是在校生，不能录入住宿信息","warn");return;}
  if(s.name)document.getElementById("daName").value=s.name;
  document.getElementById("daGender").value=s.gender||"";
  document.getElementById("daDept").value=s.dept||"";
  setTimeout(function(){
    const majorEl=document.getElementById("daMajor");
    if(majorEl)majorEl.value=s.major||"";
    document.getElementById("daGrade").value=s.grade||classGrade(s.cls||"");
    document.getElementById("daCls").value=s.cls||"";
    const dist=dormDistributionRow(s);
    if(dist.accom)qfSingleSet("daAccom",dist.accom);
    if(dist.building){
      const zd=dormMasterData(dist.building);
      const ze=document.getElementById("daZone");
      if(ze){ze.value=dist.zone||(zd&&zd.zone)||"";if(zd)window.dormAddBuildingOptions();}
      const be=document.getElementById("daBuilding"); if(be) be.value=dist.building;
    }
    if(dist.room)document.getElementById("daRoom").value=dist.room;
    if(dist.bed)document.getElementById("daBed").value=dist.bed;
  },30);
  showToast && showToast("已匹配在校生 "+s.name+"，可录入住宿信息","info");
}
function dormAddApplyStudent(s){
  if(!s)return;
  if(!isOnCampusStudent(s)){if(typeof showToast==="function")showToast("该学生当前不是在校生，不能录入住宿信息","warn");return;}
  const id=document.getElementById("daId"),name=document.getElementById("daName"),major=document.getElementById("daMajor");
  if(id)id.value=s.id||"";if(name)name.value=s.name||"";if(major)major.value=s.major||"";
  const gender=document.getElementById("daGender"),dept=document.getElementById("daDept"),grade=document.getElementById("daGrade"),cls=document.getElementById("daCls");
  if(gender)gender.value=s.gender||"";if(dept)dept.value=s.dept||"";if(grade)grade.value=s.grade||classGrade(s.cls||"");if(cls)cls.value=s.cls||"";
  const dist=dormDistributionRow(s);if(dist.accom)qfSingleSet("daAccom",dist.accom);
  if(dist.building){const zd=dormMasterData(dist.building),ze=document.getElementById("daZone");if(ze){ze.value=dist.zone||(zd&&zd.zone)||"";if(zd)window.dormAddBuildingOptions();}const be=document.getElementById("daBuilding");if(be)be.value=dist.building;}
  const room=document.getElementById("daRoom"),bed=document.getElementById("daBed");if(room)room.value=dist.room||"";if(bed)bed.value=dist.bed||"";
  if(typeof showToast==="function")showToast("已匹配在校生 "+(s.name||s.id)+"，可录入住宿信息","info");
}
function dormAddNameAutoFill(name){resolveStudentNameInput(name,function(student){if(student)dormAddApplyStudent(student);},"住宿分配");}
window.dormAddCommit=function(o){
  /* 只为学生管理中的在校生新增或更新住宿信息，绝不在此新增/修改学生身份。
     - 床位唯一性：同 区位+楼栋+房间号+床位号 不可被另一学生占用
     - 校内住宿必须填 楼栋/房间号/床位号 */
  o=o||{};
  const id=String(o.id||"").trim(), accom=String(o.accom||"").trim();
  const zone=String(o.zone||"").trim(), building=String(o.building||"").trim(), room=String(o.room||"").trim(), bed=String(o.bed||"").trim();
  if(!id) return {ok:false,error:"请填写学号"};
  const ex=students.find(function(s){return String(s.id)===id;});
  if(!ex) return {ok:false,error:"该学号不在学生管理中，请先在学生管理新增该学生"};
  if(!isOnCampusStudent(ex)) return {ok:false,error:"该学生当前不是在校生，不能录入住宿信息"};
  if(!accom) return {ok:false,error:"请选择住宿情况"};
  if(accom==="校内"){
    if(!building) return {ok:false,error:"校内住宿请填写楼栋"};
    if(!room) return {ok:false,error:"校内住宿请填写房间号"};
    if(!bed) return {ok:false,error:"校内住宿请填写床位号"};
  }
  if(accom==="校内"){
    const master=dormMasterData(building),targetZone=String((master&&master.zone)||zone||"").trim();
    const dup=students.filter(isOnCampusStudent).find(function(s){const dist=dormDistributionRow(s);return String(s.id)!==id && dist.accom==="校内" && String(dist.zone||"").trim()===targetZone && (dist.building||"")===building && (dist.room||"")===room && (dist.bed||"")===bed;});
    if(dup) return {ok:false,error:"该床位已分配给 "+dup.id+" "+dup.name+"，请重新指定"};
  }
  const existed=!!dormDistributionRecord(id)||["accom","building","room","bed"].some(function(key){return !!String(ex[key]||"").trim();});
  if(!applyDormDistribution(ex.id,{accom:accom,zone:zone,building:building,room:room,bed:bed}))return {ok:false,error:"住宿信息未保存，请检查床位号、房间容量或占用冲突"};
  return {ok:true,action:existed?"update":"insert",student:ex};
};
window.dormAdd=function(){
  openModal("新增住宿分配",dormAddBody(),function(){
    const r=window.dormAddCommit({
      id:document.getElementById("daId").value,
      accom:qfSingleValue("daAccom"),
      zone:(document.getElementById("daZone")||{}).value||"",
      building:document.getElementById("daBuilding").value,
      room:document.getElementById("daRoom").value,
      bed:document.getElementById("daBed").value
    });
    if(!r.ok){alert(r.error);return false;}
    showToast(r.action==="update"?"已更新学生 "+r.student.name+" 的住宿信息":"已录入学生 "+r.student.name+" 的住宿信息","success");
    goto("dorm");
  });
  const idEl=document.getElementById("daId");
  if(idEl)idEl.addEventListener("blur",dormAddAutoFill);
  const nameEl=document.getElementById("daName");
  if(nameEl)nameEl.addEventListener("change",function(){dormAddNameAutoFill(this.value);});
};
function dormMutationSnapshot(){return {students:JSON.parse(JSON.stringify(students)),records:JSON.parse(JSON.stringify(dormDistRecords||[])),orgs:JSON.parse(JSON.stringify(ORG_DORMS||[])),spatial:window.__DORM_SPATIAL__&&typeof window.__DORM_SPATIAL__.getState==="function"?window.__DORM_SPATIAL__.getState():null};}
function dormMutationRollback(snapshot){if(!snapshot)return;students.splice(0,students.length,...snapshot.students);dormDistRecords=snapshot.records;ORG_DORMS.splice(0,ORG_DORMS.length,...snapshot.orgs);if(snapshot.spatial&&window.__DORM_SPATIAL__&&typeof window.__DORM_SPATIAL__.restoreState==="function")window.__DORM_SPATIAL__.restoreState(snapshot.spatial);try{persistStudents();persistDormDist();saveOrgs();}catch(_ignore){}}
function dormBatchRoomKey(row){return JSON.stringify([row.zone,row.building,row.room].map(function(value){return String(value||"").trim();}));}
function dormBatchBedKey(row){return dormBatchRoomKey(row)+"|"+String(Number(row.bed)||row.bed||"");}
function dormApplyRowsAtomically(rows,resolve,prepare){
  if(!rows||!rows.length)return {ok:0,skip:0,failed:false};
  const snapshot=dormMutationSnapshot(),api=window.__DORM_SPATIAL__,batch={students:new Map(students.map(function(s){return [String(s.id),s];})),records:new Map(),buildings:new Map(),rooms:new Map(),occupied:new Map(),spatial:snapshot.spatial};
  (dormDistRecords||[]).forEach(function(r){const key=String(r.studentId||r.id||"").trim();if(!batch.records.has(key))batch.records.set(key,r);});
  const refreshResources=function(){
    const masters=api&&typeof api.buildingRows==="function"?api.buildingRows(true):(batch.spatial&&batch.spatial.buildings||ORG_DORMS||[]);
    batch.buildings=new Map(masters.map(function(item){return [String(item.building||"").trim(),item];}));
    batch.rooms=new Map((batch.spatial&&batch.spatial.rooms||[]).map(function(room){return [dormBatchRoomKey(room),room];}));
  };
  refreshResources();dormApplyRowsAtomically.context=batch;let ok=0;
  try{
    const write=function(){
      if(typeof prepare==="function")prepare();
      if(api&&typeof api.getState==="function")batch.spatial=api.getState();refreshResources();
      students.filter(isOnCampusStudent).forEach(function(student){const row=dormDistributionRow(student);if(row.accom!=="校内")return;const key=dormBatchBedKey(row);if(!batch.occupied.has(key))batch.occupied.set(key,new Set());batch.occupied.get(key).add(student);});
      for(let i=0;i<(rows||[]).length;i++){
        const target=resolve(rows[i]);if(!target)continue;
        if(!applyDormDistribution(target.student.id,target.fields))throw new Error("住宿批次存在无效数据或床位冲突");ok++;
      }
      if(ok){persistStudents();persistDormDist();if(api&&typeof api.onAccommodationChanged==="function")api.onAccommodationChanged(undefined,{render:false});}
      return {ok:ok,skip:(rows||[]).length-ok,failed:false};
    };
    return api&&typeof api.runBatch==="function"?api.runBatch(write):write();
  }catch(error){dormApplyRowsAtomically.context=null;dormMutationRollback(snapshot);reportDataError("住宿批量导入",error);return {ok:0,skip:(rows||[]).length,failed:true,error:error};}
  finally{dormApplyRowsAtomically.context=null;}
}
function dormImportResolveRow(r){
  const sid=String(r&&r["学号"]||"").trim(),batch=dormApplyRowsAtomically.context,student=batch?batch.students.get(sid):students.find(function(item){return String(item.id)===sid&&isOnCampusStudent(item);});if(!student||!isOnCampusStudent(student))return null;
  const current=dormDistributionRow(student);
  return {student:student,fields:{accom:String(r["住宿情况"]||"").trim(),zone:String(r["区位"]||current.zone||"").trim(),building:String(r["宿舍楼"]||r["楼栋"]||current.building||"").trim(),room:String(r["房间号"]||current.room||"").trim(),bed:String(r["床位号"]||current.bed||"").trim()}};
}
function dormImportMissingResources(rows){
  const api=window.__DORM_SPATIAL__,state=api&&typeof api.getState==="function"?api.getState():null;if(!state)return [];
  const missing=new Map();
  (rows||[]).forEach(function(row){
    const target=dormImportResolveRow(row);if(!target||target.fields.accom!=="校内")return;
    const fields=target.fields,master=fields.building?dormMasterData(fields.building):null,zone=String(master&&master.zone||fields.zone||"未分区").trim()||"未分区",building=fields.building,room=fields.room;
    if(!building||!room)return;
    const exists=(state.rooms||[]).some(function(item){return String(item.zone||"").trim()===zone&&String(item.building||"").trim()===building&&String(item.room||"").trim()===room;});if(exists)return;
    const key=[zone,building,room].join("\u001f"),bed=Number(fields.bed),current=missing.get(key);if(current){if(Number.isInteger(bed)&&bed>current.bedHint)current.bedHint=bed;}else missing.set(key,{zone:zone,building:building,room:room,bedHint:Number.isInteger(bed)&&bed>0?bed:0});
  });
  return Array.from(missing.values());
}
function dormImportApplyRows(rows){
  // 写入入口再次校验，防止绕过向导或校验后数据变化造成空记录“导入成功”。
  const validation=dormImportValidate(rows||[]);
  if(validation.errors.length)return {ok:0,skip:(rows||[]).length,failed:true,errors:validation.errors,addedRooms:0};
  const missing=dormImportMissingResources(rows);
  if(missing.length){
    const shown=missing.slice(0,12).map(function(item){return "• "+item.zone+" · "+item.building+" · "+item.room+"室"+(item.bedHint?"（至少 "+item.bedHint+" 个床位）":"");}).join("\n"),more=missing.length>12?"\n…另有 "+(missing.length-12)+" 间":"";
    if(!confirm("导入数据中有 "+missing.length+" 间宿舍尚未在“公寓资源”中建立：\n\n"+shown+more+"\n\n继续后，系统将自动新增这些宿舍楼、房间及所需床位，再导入学生住宿信息。是否继续？"))return {ok:0,skip:(rows||[]).length,failed:false,cancelled:true,addedRooms:0};
  }
  const api=window.__DORM_SPATIAL__,result=dormApplyRowsAtomically(rows,dormImportResolveRow,function(){
    if(!missing.length)return;if(!api||typeof api.ensureRoom!=="function")throw new Error("公寓资源接口不可用");
    missing.forEach(function(item){if(!api.ensureRoom(item.zone,item.building,item.room,item.bedHint))throw new Error("无法新增宿舍资源："+item.building+" "+item.room);});
  });
  result.addedRooms=result.failed?0:missing.length;return result;
}
window.dormImportApplyRows=dormImportApplyRows;
function dormImport(){
  const fields=["学号","姓名","住宿情况","区位",{key:"楼栋",label:"宿舍楼",aliases:["楼栋","楼宇"]},"房间号","床位号"];
  openMappedImportWizard({name:"住宿信息",fields:fields,requiredFields:["学号","住宿情况"],template:"dormImportTemplate()",
    infoHtml:'学号、住宿情况为必填；住宿情况只能填写“校内”“租房”“走读”。校内住宿需有宿舍楼、房间号、床位号；姓名自动从学生管理同步，区位可从宿舍楼匹配，未维护时归入“未分区”。已有住宿信息的学生，未填写的位置字段沿用原值。',
    validate:function(rows){return dormImportValidate(rows);},
    apply:function(rows){const result=dormImportApplyRows(rows);if(result.cancelled){showToast("已取消导入，未新增公寓资源或住宿信息","warn");return result;}if(result.failed){showToast(result.errors&&result.errors.length?"导入未写入：第 "+result.errors[0].row+" 行，"+result.errors[0].msg:"住宿导入存在缺项或床位冲突，已回滚整批导入","error");return result;}if(result.addedRooms)showToast("已在公寓资源中自动新增 "+result.addedRooms+" 间宿舍并完成导入","success");return result;},
    after:function(){goto("dorm");}
  });
}
function dormImportTemplate(){
  const headers=["学号","姓名","住宿情况","区位","宿舍楼","房间号","床位号"];
  const sample=["2024010101","示例同学","校内","东区","A栋","302","3"];
  downloadXlsxFile("住宿信息导入模板",[headers,sample],"住宿信息导入模板.xlsx");
}
async function dormImportParse(fileObj){ return await parseWorkbookToRows(fileObj,["学号","姓名","住宿情况","区位","宿舍楼","楼栋","房间号","床位号"]); }
function dormImportValidate(rows){
  const errors=[]; const ok=[]; const allIds=new Set(students.map(function(s){return String(s.id).trim();}));
  const seenIds=new Set();
  (rows||[]).forEach((r,i)=>{
    r=r||{};
    const errs=[],sid=String(r['学号']||'').trim(),accom=String(r['住宿情况']||'').trim();
    if(!sid)errs.push('学号为空');else if(!allIds.has(sid))errs.push('学号不存在');
    if(sid&&seenIds.has(sid))errs.push('学号重复，请合并该学生的住宿信息');if(sid)seenIds.add(sid);
    if(!accom)errs.push('住宿情况为必填，请填写校内、租房或走读');
    else if(['校内','租房','走读'].indexOf(accom)<0)errs.push('住宿情况只能为校内、租房或走读');
    if(accom==='校内'){
      const target=dormImportResolveRow(r),fields=target?target.fields:{building:String(r['宿舍楼']||r['楼栋']||'').trim(),room:String(r['房间号']||'').trim(),bed:String(r['床位号']||'').trim()};
      if(!fields.building)errs.push('校内住宿缺少宿舍楼');if(!fields.room)errs.push('校内住宿缺少房间号');if(!fields.bed)errs.push('校内住宿缺少床位号');
      else if(!Number.isInteger(Number(fields.bed))||Number(fields.bed)<1)errs.push('床位号必须为大于 0 的整数');
    }else if(['租房','走读'].indexOf(accom)>=0&&['区位','宿舍楼','楼栋','房间号','床位号'].some(function(key){return !!String(r[key]||'').trim();}))errs.push('租房、走读不能同时填写校内宿舍位置，请核对住宿情况');
    if(errs.length===0)ok.push(r);else errors.push({row:i+2,msg:errs.join('、'),data:r});
  });
  return {ok,errors};
}
async function dormImportApply(){
  const file=$('#dormImportFile');
  if(!file||!file.files||!file.files[0]){ alert('请先选择文件'); return; }
  let rows;
  try{ rows=await dormImportParse(file.files[0]); }
  catch(e){ alert("读取失败："+(e.message||e)); return; }
  const {ok}=dormImportValidate(rows);
  const result=dormImportApplyRows(ok);
  if(result.cancelled)return;
  if(result.failed){alert('导入失败：存在住宿缺项或床位冲突，整批数据已回滚');return;}
  closeModal(); goto('dorm');
  alert('成功导入 '+result.ok+' 条住宿信息'+(result.addedRooms?'，并在公寓资源中自动新增 '+result.addedRooms+' 间宿舍':''));
}
window.dormImport=dormImport;
