    +'<div class="row2"><div class="field"><label>违纪时间</label><input readonly value="'+escAttr(r.date||"")+'"></div><div class="field"><label>扣分</label><input readonly value="'+escAttr(r.score!=null?('-'+r.score):"")+'"></div></div>'
