PAGES.meeting=()=>{
  const terms=selectedViewTerms("meeting"),vt=selectedViewTermsText("meeting");
  const ms=viewFilter.meeting||{};
  let items=meetings.filter(function(m){return terms.indexOf(m.term||"")>=0;});
  items=items.filter(function(m){return meetingMatchesFilter(m,ms);});
  if(!queryReady("meeting")) items='<div class="card"><div class="empty">请设置条件后点击「查询」；不设置条件直接查询将显示全部班会/活动记录。</div></div>';
  else items=items.map(m=>`
    <div class="card" style="margin-bottom:14px">
      <div style="display:flex;justify-content:space-between;align-items:flex-start">
        <div><h3 style="margin-bottom:4px">${esc(m.topic||m.title||"未命名活动")}</h3><div style="color:var(--muted);font-size:13px">🏫 ${esc(meetingClassText(m)||"未填写班级")}　📅 ${esc(m.date||"未填写时间")}　📍 ${esc(m.place||"未填写地点")}${m.host?"　🎤 "+esc(m.host):""}</div></div>
        <div style="display:flex;gap:6px"><button class="btn btn-ghost btn-sm" onclick="meetingView(${jsArg(m.id)})">查看</button><button class="btn btn-ghost btn-sm" onclick="meetingEdit(${jsArg(m.id)})">编辑</button><button class="btn btn-ghost btn-sm" onclick="meetingDelete(${jsArg(m.id)})">删除</button></div>
      </div>
      <p style="margin:10px 0;font-size:13px;color:#41514c">${esc(m.content||m.summary||"未填写内容纪要")}</p>
      ${(m.files||[]).length?'<div class="tip" style="margin:0">📎 附件：'+(m.files||[]).map(function(f){if(!f||!f.id)return esc(f); const isImg=/\.(jpg|jpeg|png|gif|webp|bmp)$/i.test(f.name||''); const u=isImg?attachmentDisplayUrl(f):(f.url||('/attachments/'+f.id)); return isImg?'<a href="'+attr(u)+'" download="'+attr(f.name||'附件')+'" style="cursor:zoom-in" onclick="event.preventDefault();portraitZoomPhoto('+jsArg(u)+')">'+esc(f.name||'附件')+'</a>':'<a href="'+attr(u)+'" download="'+attr(f.name||'附件')+'">'+esc(f.name||'附件')+'</a>';}).join('、')+'</div>':''}
    </div>`).join('');
  if(queryReady("meeting") && !getTermList().length) items='<div class="card"><div class="empty">请先在顶部“增加学期”中维护当前学期，再录入班会/活动。</div></div>';
  else if(queryReady("meeting") && !items) items='<div class="card"><div class="empty">暂无符合条件的班会/活动记录。</div></div>';
  return `
  <h2 class="ptitle">📸 班会/活动 <span class="tag">纪要与本地附件 · ${vt}</span></h2>
  <div class="sub">创建班会（班级/学期）→ 录入主题、时间、地点与纪要 → 本地保存附件 → 存档可查。</div>
  ${WR_KPI_STYLE}${meetingStatsHtml()}
  <div class="toolbar qf-bar" data-page="meeting">
<div class="filter-item"><label>学期</label>${termPicker('meeting')}</div><div class="filter-item"><label>学院</label>${qfMulti("dept",[{v:"",l:"全部学院"}].concat(depts.map(d=>({v:d,l:d}))),ms.dept)}</div><div class="filter-item"><label>专业</label>${qfMulti("major",[{v:"",l:"全部专业"}].concat(majors.map(function(m){return {v:m,l:m};})),ms.major)}</div><div class="filter-item"><label>年级</label>${qfMulti("grade",[{v:"",l:"全部年级"}].concat(grades.map(g=>({v:g,l:g}))),ms.grade)}</div><div class="filter-item"><label>班级</label>${qfMulti("cls",[{v:"",l:"全部班级"}].concat(classes.map(c=>({v:c,l:c}))),ms.cls)}</div>${qfBtns('meeting')}<span style="flex:1"></span><button class="btn btn-ghost btn-sm" onclick="wrAiRun('meeting',this)">🤖 AI 分析</button><button class="btn btn-ghost btn-sm" onclick="exportMeeting()">⬇ 导出</button><button class="btn btn-primary btn-sm" onclick="openMeeting()">＋ 新建班会/活动</button></div>
  ${items}`;
};
function exportMeeting(){
  const terms=selectedViewTerms("meeting"),vt=selectedViewTermsText("meeting");
  const ms=viewFilter.meeting||{};
  const list=(meetings||[]).filter(function(m){return terms.indexOf(m.term||"")>=0&&meetingMatchesFilter(m,ms);})
    .sort(function(a,b){return (b.date||"").localeCompare(a.date||"");});
  if(!list.length){ alert("当前学期/筛选条件下暂无班会/活动记录可导出。"); return; }
  const rows=list.map(function(m){return [m.term||vt,m.date||"",meetingOrgValues(m,"dept").join("、"),meetingOrgValues(m,"major").join("、"),meetingOrgValues(m,"grade").join("、"),meetingClassText(m),m.topic||m.title||"",m.place||"",m.host||"",m.content||m.summary||"",wrFileNames(m)]; });
  downloadXlsxFile("班会活动",[["学期","日期","学院","专业","年级","班级","主题","地点","主持人","内容纪要","附件"],...rows],"班会活动_"+selectedViewTermsFileToken("meeting")+".xlsx");
  showToast("已导出 "+list.length+" 条班会/活动记录","ok");
}
window.exportMeeting=exportMeeting;
PAGES.fund=()=>{
  // 默认查看学期 = 第一个学期（首次进入 / 当前学期被删时自动回退）
  if(!window.fundViewTermId || !fundTermById(window.fundViewTermId)){
    window.fundViewTermId = (window.fundTerms[0] && window.fundTerms[0].id) || 0;
  }
  const curId = window.fundViewTermId;
  const curTerm = curId ? fundTermById(curId) : null;
  const fundTermInfo = pagerSlice('fund_terms', window.fundTerms);
  const termRows = renderFundTermRows(fundTermInfo.slice);
  const pane = `
    <div class="card" style="margin-bottom:14px">
      <div class="ae-bar" style="padding:0;border:0;background:transparent">
        <div class="row1" style="margin-bottom:10px">
          <div class="filter-item">
            <label>查看学期</label>
            ${qfSingle('fundViewTerm', window.fundTerms.length ? window.fundTerms.map(function(t){ return {v:String(t.id), l: esc(t.term) + '（' + ((fundRecords||[]).filter(function(r){return r.term===t.term;})).length + ' 条）'}; }) : [{v:'0', l:'（暂无学期）'}], String(curId || '0'))}
          </div>
          <span class="tag">学期由“学期设置”统一同步</span>
          <button class="btn btn-ghost btn-sm" onclick="wrAiRun('fund',this)">🤖 AI 分析</button>
          <button class="btn btn-ghost btn-sm" onclick="fundExportAll()">⬆ 导出全部学期</button>
          <span style="margin-left:auto;font-size:13px;color:var(--muted)" id="fundViewSummary"></span>
        </div>
      </div>
      <div class="module-table-wrap table-scroll"><table class="t-table" style="min-width:auto">
        <thead><tr><th style="width:280px">学期</th><th style="width:180px">状态</th><th style="width:200px">操作</th></tr></thead>
        <tbody id="fundTermTbody">${termRows}</tbody>
      </table></div>
      <div id="fundTermPager"></div>
      <div style="margin-top:10px"><button class="btn btn-ghost btn-sm" onclick="if(window.fundViewTermId) openEditFundTerm(window.fundViewTermId)">打开「查看学期」所选学期</button></div>
    </div>`;
  return `
  <h2 class="ptitle">💰 资助情况 <span class="tag">按学期记录</span></h2>
  <div class="sub">资助情况模块，按学期维护<b>资助信息</b>（贫困生、助学金、临时补助等）。点击「查看 / 编辑」进入学期明细。</div>
  ${pane}`;
};

/* ===== 资助情况：学期列表（与综测 academicTerms 同范式：列表页 → 大弹窗查看/编辑） ===== */
function renderFundTermRows(list){
  const L = sortTermsDesc(list || window.fundTerms);
  if(!L.length){
    return '<tr><td colspan="3" class="empty">暂无学期，请先到“学期设置”新增学期</td></tr>';
  }
  return L.map(function(t){
    const cnt = (fundRecords||[]).filter(function(r){ return r.term===t.term; }).length;
    const state = cnt>0 ? ('已录入 '+cnt+' 条') : '待录入';
    return '<tr data-tid="'+t.id+'">'
      + '<td><b>'+esc(t.term)+'</b></td>'
      + '<td>'+ (cnt>0 ? '<span class="badge b-green">'+state+'</span>' : '<span class="badge b-gray">'+state+'</span>') +'</td>'
      + '<td>　<a class="lk" onclick="openEditFundTerm('+t.id+')">查看</a>　<a class="lk" onclick="openEditFundTerm('+t.id+')">编辑</a>　<a class="lk" onclick="fundExportTerm('+t.id+')">导出</a></td>'
      + '</tr>';
  }).join('');
}
function fundRefreshList(){
  window.fundTerms = sortTermsDesc(window.fundTerms);
  const info = pagerSlice('fund_terms', window.fundTerms);
  const tb = document.getElementById('fundTermTbody');
  if(tb) tb.innerHTML = renderFundTermRows(info.slice);
  const pg = document.getElementById('fundTermPager');
  if(pg) pg.innerHTML = renderGenericPager('fund_terms', info, 'fundTermJump');
  const sgV = document.querySelector('.qf-single[data-qf="fundViewTerm"]');
  if(sgV){
    sgV.outerHTML = qfSingle('fundViewTerm', window.fundTerms.length ? window.fundTerms.map(function(t){ return {v:String(t.id), l: esc(t.term) + '（' + ((fundRecords||[]).filter(function(r){return r.term===t.term;})).length + ' 条）'}; }) : [{v:'0', l:'（暂无学期）'}], String(window.fundViewTermId || '0'));
  }
}
function openAddFundTerm(){
  showToast("学期只能在“学期设置”中统一新增","warn");goto("semester");
}
async function fundDeleteTerm(id){
  showToast("学期只能在“学期设置”中统一删除","warn");goto("semester");
}
function fundSwitchViewTerm(id){
  const i = parseInt(id,10);
  if(!i) return;
  window.fundViewTermId = i;
  if(typeof renderPage==="function") renderPage("fund");
}
function openEditFundTerm(id){
  const t = fundTermById(id);
  if(!t) return;
  const term = t.term;
  window.fundModalTermId = id;
  window.fundViewTermId = id;
  viewTerm.fund = term;
  viewFilter.fund = {};
  fundBatchSel.clear();
  /* 从学期列表进入明细时应直接展示该学期全部记录，不应被“尚未查询”状态拦截。 */
  setQueryReady('fund', true);
  resetModalLayout();
  document.getElementById("modalTitle").innerHTML = '<span>💰 资助情况 · '+esc(term)+'</span><span style="font-size:13px;color:var(--muted);font-weight:400" id="fundRowCount"></span>';
  document.getElementById("modalBody").innerHTML = fundInnerContent(term);
  document.getElementById("modalFoot").innerHTML = '<button class="btn btn-primary" onclick="closeModal()">关闭</button>';
  document.getElementById("modalFoot").style.display = "flex";
  const m = document.getElementById("modal");
  m.classList.remove("wide");
  m.classList.add("xwide","fund-detail-modal");
  var _vw = window.innerWidth || document.documentElement.clientWidth || 1440;
  var _main = document.querySelector('.main');
  var _ml = 204;
  try{ if(_main){ var _mr=_main.getBoundingClientRect(); if(_mr && _mr.width>0){ _ml=Math.round(_mr.left); } } }catch(e){}
  var _modalLeft = _ml + 12;
  var _modalW = _vw - _modalLeft - 12;
  if(!(_modalW>200)) _modalW = 1100;
  var _sets = { position:'fixed', left:_modalLeft+'px', right:'12px', top:'72px', bottom:'24px', width:_modalW+'px', 'max-width':'none', height:'auto', 'max-height':'none', transform:'none', margin:'0', 'box-sizing':'border-box', 'flex-direction':'column', display:'flex' };
  for(var _k in _sets){ try{ m.style.setProperty(_k, _sets[_k], 'important'); }catch(e){} }
  var _rule = '#modal.xwide{position:fixed !important;left:'+_modalLeft+'px !important;right:12px !important;top:72px !important;bottom:24px !important;width:'+_modalW+'px !important;max-width:none !important;height:auto !important;max-height:none !important;transform:none !important;margin:0 !important;box-sizing:border-box !important;display:flex !important;flex-direction:column !important;}';
  var _xs = document.getElementById('_xwideFix');
  if(_xs){ _xs.textContent = _rule; } else { _xs = document.createElement('style'); _xs.id='_xwideFix'; _xs.textContent=_rule; document.head.appendChild(_xs); }
  $("#mask").classList.add("show");
  m.classList.add("show");
  fundRebuildTable(id);
}
function fundInnerContent(term){
  const st = viewFilter.fund || {};
  return `
  <div class="fund-detail">
  <div class="sub">记录学生是否为贫困生、是否获得国家助学金 / 学院助学金，以及其它资助信息；导出会包含当前筛选的全部结果，不受分页影响，并可直接重新导入。</div>
  <div class="tip" style="margin-bottom:12px">⚠ 数据本地持久化：录入/导入均自动保存；清除浏览器缓存会重置为空模板。</div>
  <div id="fundKpi" class="kpi-row" style="margin-bottom:16px"></div>
  <div class="card fund-detail-card">
    <div class="toolbar qf-bar" data-page="fund">
<div class="filter-item"><label>学院</label>${qfMulti("dept",[{v:"",l:"全部学院"}].concat(depts.map(function(d){return {v:d,l:d};})),st.dept)}</div><div class="filter-item"><label>专业</label>${qfMulti("major",[{v:"",l:"全部专业"}].concat(majors.map(function(m){return {v:m,l:m};})),st.major)}</div><div class="filter-item"><label>年级</label>${qfMulti("grade",[{v:"",l:"全部年级"}].concat(grades.map(function(g){return {v:g,l:g};})),st.grade)}</div><div class="filter-item"><label>班级</label>${qfMulti("cls",[{v:"",l:"全部班级"}].concat(classes.map(function(c){return {v:c,l:c};})),st.cls)}</div><div class="filter-item"><label>关键字</label>${qfInput("kw","学生姓名/学号",st.kw,140)}</div><button class="btn btn-primary btn-sm" onclick="fundEditQuery()">查询</button><button class="btn btn-ghost btn-sm" onclick="fundEditReset()">重置</button><span id="fundBatchCount" class="tag">已选 0 条</span><button id="fundBatchEditBtn" class="btn btn-ghost btn-sm" onclick="fundBatchEdit()" disabled>📝 批量修改</button><button id="fundBatchDeleteBtn" class="btn btn-danger btn-sm" onclick="fundBatchDelete()" disabled>🗑 批量删除</button><span style="flex:1"></span><button class="btn btn-primary btn-sm" onclick="openFund()">＋ 录入/批量</button><button class="btn btn-ghost btn-sm" onclick="fundImport(${jsArg(term)})">⬇ 导入Excel</button><button class="btn btn-ghost btn-sm" onclick="fundExportCurrent()">⬆ 导出当前筛选</button></div>
    <div id="fundTableWrap"></div>
    <div id="fundPagerWrap"></div>
  </div>
  </div>`;
}
function fundBuildData(term, state){
  const useRecs = (fundRecords && fundRecords.length);
  const kw = state.kw ? state.kw.trim() : "";
  let data;
  if(useRecs){
    data = fundRecords.filter(function(r){
      return r.term===term && qfMatch(state.dept,r.dept) && qfMatch(state.major,r.major) && qfMatch(state.grade,r.grade) && qfMatch(state.cls,r.cls) && (!kw || (r.studentId||r.id||"").indexOf(kw)>=0 || (r.name||"").indexOf(kw)>=0);
    });
  } else {
    const ss = stuFilterByState(clsStudents(), state);
    data = ss.filter(function(s){ return (s.fund && s.fund.term===term); });
  }
  return { useRecs: useRecs, data: data };
}
function fundExportRow(record){
  const sid=String(record.studentId||record.id||""), student=students.find(function(s){return String(s.id||"")===sid;})||{}, fund=record.fund&&typeof record.fund==="object"?record.fund:record;
  const other=String(fund.other==null?"":fund.other).trim();
  return [
    sid,(student.name||record.name||""),(student.ethnic||student.nation||""),(student.dept||record.dept||""),(student.major||record.major||""),(student.grade||record.grade||classGrade(student.cls||record.cls)||""),(student.cls||record.cls||""),
    (record.term||fund.term||""),fund.isPoor===true?"是":"否",normalizeFundLevel(fund.poorLevel),fund.national===true?"是":"否",fund.college===true?"是":"否",fund.nationalMotivational===true?"是":"否",fund.collegeMotivational===true?"是":"否",fund.temporaryAid===true?"是":"否",other==="—"?"":other
  ];
}
function fundExportDownload(records,fileLabel){
  const rows=(records||[]).map(fundExportRow).sort(function(a,b){return String(b[7]).localeCompare(String(a[7]))||String(a[3]).localeCompare(String(b[3]),"zh-CN")||String(a[4]).localeCompare(String(b[4]),"zh-CN")||String(a[6]).localeCompare(String(b[6]),"zh-CN")||String(a[0]).localeCompare(String(b[0]));});
  if(!rows.length){showToast("暂无符合条件的资助数据可导出","warn");return false;}
  const safe=String(fileLabel||"全部学期").replace(/[\\/:*?"<>|]/g,"_");
  downloadXlsxFile("资助情况",[FUND_DATA_HEADERS.slice()].concat(rows),"资助情况_"+safe+".xlsx");
  showToast("已导出 "+rows.length+" 条资助记录","success");
  return true;
}
function fundExportTerm(id){
  const t=fundTermById(Number(id));if(!t){showToast("未找到要导出的学期","warn");return false;}
  return fundExportDownload(fundBuildData(t.term,{}).data,t.term);
}
function fundExportCurrent(){
  const t=fundTermById(Number(window.fundModalTermId));if(!t){showToast("请先打开一个资助学期","warn");return false;}
  return fundExportDownload(fundBuildData(t.term,viewFilter.fund||{}).data,t.term+"_当前筛选");
}
function fundExportAll(){
  const records=(fundRecords&&fundRecords.length)?fundRecords.slice():(students||[]).filter(function(s){return s.fund&&s.fund.term;});
  return fundExportDownload(records,"全部学期");
}
window.fundExportTerm=fundExportTerm;
window.fundExportCurrent=fundExportCurrent;
window.fundExportAll=fundExportAll;
function fundRebuildTable(id){
  const t = fundTermById(id);
  if(!t) return;
  const term = t.term;
  const state = viewFilter.fund || {};
  const built = fundBuildData(term, state);
  const useRecs = built.useRecs, data = built.data;
  const fundFk = JSON.stringify(state) + '|' + term + '|' + (useRecs?'recs':'stu');
  const fundInfo = pagerSlice('fund_'+id, data, fundFk);
  const wrap = document.getElementById('fundTableWrap');
  if(!wrap) return;
  const rows = fundInfo.slice.length ? fundInfo.slice.map(function(r){
    const f = useRecs ? r : r.fund;
    const fundKey=useRecs?String(r.id):('fund_'+encodeURIComponent(r.id)+'_'+encodeURIComponent(term));
    const linkedStudent=students.find(function(s){return String(s.id||"")===String(r.studentId||r.id||"");});
    return '<tr><td style="text-align:center"><input type="checkbox" class="fund-batch-cb" value="'+attr(fundKey)+'" '+(fundBatchSel.has(fundKey)?'checked':'')+' onchange="fundToggleOne(this.value,this.checked)" aria-label="选择 '+attr(r.name||'该学生')+' 的资助记录"></td><td>'+esc(term)+'</td>'
      +'<td>'+esc(r.dept)+'</td><td>'+esc(r.major)+'</td><td>'+esc(r.cls)+'</td><td>'+esc(r.studentId||r.id)+'</td><td>'+esc(r.name)+'</td><td>'+esc(linkedStudent?(linkedStudent.ethnic||linkedStudent.nation||""):"")+'</td>'
      +'<td>'+badge(f.isPoor?"是":"否",f.isPoor?"b-orange":"b-gray")+'</td>'
      +'<td>'+esc(normalizeFundLevel(f.poorLevel))+'</td>'
      +'<td>'+badge(f.national?"获得":"否",f.national?"b-green":"b-gray")+'</td>'
      +'<td>'+badge(f.college?"获得":"否",f.college?"b-green":"b-gray")+'</td>'
      +'<td>'+badge(f.nationalMotivational?"获得":"否",f.nationalMotivational?"b-green":"b-gray")+'</td>'
      +'<td>'+badge(f.collegeMotivational?"获得":"否",f.collegeMotivational?"b-green":"b-gray")+'</td>'
      +'<td>'+badge(f.temporaryAid?"获得":"否",f.temporaryAid?"b-orange":"b-gray")+'</td>'
      +'<td>'+esc(f.other||"—")+'</td>'
      +'<td><a class="lk" onclick="openEditFund('+jsArg(r.studentId||r.id)+','+jsArg(term)+')">修改</a></td></tr>';
  }).join('') : '<tr><td colspan="17" class="empty">'+esc(term)+' 暂无资助记录</td></tr>';
  wrap.innerHTML = '<div class="module-table-wrap">'+table(['<input type="checkbox" id="fundBatchMaster" title="全选/取消全选当前页" onchange="fundToggleAll(this.checked)" aria-label="全选当前页资助记录">',"学期","学院","专业","班级","学号","姓名","民族","是否贫困生","困难评定等级","国家助学金","学院助学金","国家励志助学金","学院励志助学金","临时补助","其他资助","操作"], rows)+'</div>';
  const pg = document.getElementById('fundPagerWrap');
  if(pg) pg.innerHTML = renderGenericPager('fund_'+id, fundInfo, 'fundJump_'+id);
  const poor = data.filter(function(r){ return useRecs ? r.isPoor : (r.fund && r.fund.isPoor); }).length;
  const nat = data.filter(function(r){ return useRecs ? r.national : (r.fund && r.fund.national); }).length;
  const col = data.filter(function(r){ return useRecs ? r.college : (r.fund && r.fund.college); }).length;
  const kpi = document.getElementById('fundKpi');
  if(kpi) kpi.innerHTML = '<div class="kpi"><div class="n" style="color:#e8830c">'+poor+'</div><div class="l">贫困生</div></div><div class="kpi"><div class="n" style="color:#12805c">'+nat+'</div><div class="l">国家助学金</div></div><div class="kpi"><div class="n" style="color:#12805c">'+col+'</div><div class="l">学院助学金</div></div>';
  const rc = document.getElementById('fundRowCount');
  if(rc) rc.textContent = '　共 '+data.length+' 条';
  fundBatchUpdateUI();
}
function fundBatchUpdateUI(){
  const boxes=Array.from(document.querySelectorAll('#fundTableWrap .fund-batch-cb'));
  const master=document.getElementById('fundBatchMaster');
  const checked=boxes.filter(function(cb){return cb.checked;}).length;
  if(master){ master.checked=boxes.length>0&&checked===boxes.length; master.indeterminate=checked>0&&checked<boxes.length; }
  const count=document.getElementById('fundBatchCount'); if(count) count.textContent='已选 '+fundBatchSel.size+' 条';
  const edit=document.getElementById('fundBatchEditBtn'), del=document.getElementById('fundBatchDeleteBtn');
  if(edit) edit.disabled=fundBatchSel.size===0; if(del) del.disabled=fundBatchSel.size===0;
}
function fundToggleOne(key,checked){ if(checked) fundBatchSel.add(String(key)); else fundBatchSel.delete(String(key)); fundBatchUpdateUI(); }
function fundToggleAll(checked){
  document.querySelectorAll('#fundTableWrap .fund-batch-cb').forEach(function(cb){ cb.checked=checked; if(checked) fundBatchSel.add(String(cb.value)); else fundBatchSel.delete(String(cb.value)); });
  fundBatchUpdateUI();
}
function fundSelectedRecords(term){ return (fundRecords||[]).filter(function(r){return r.term===term&&fundBatchSel.has(String(r.id));}); }
function fundRestoreDetail(id){ setTimeout(function(){ if(fundTermById(id)) openEditFundTerm(id); },80); }
function fundBatchEdit(){
  const id=window.fundModalTermId, t=fundTermById(id); if(!t) return;
  const picks=fundSelectedRecords(t.term);
  if(!picks.length){ showToast('请先勾选要批量修改的资助记录','warn'); return; }
  const chips=picks.map(function(r){return '<span class="batch-chip" data-fund-key="'+attr(r.id)+'"><span class="bc-name">'+esc(r.name||r.studentId)+'</span><span class="bc-meta">'+esc(r.studentId+' · '+(r.cls||'未分班'))+'</span><button type="button" class="bc-x" onclick="fundRemoveBatchChip('+jsArg(r.id)+',this)" title="从修改名单移除">×</button></span>';}).join('');
  const yesNo='<option value="">请选择</option><option value="true">是</option><option value="false">否</option>';
  const field=function(key,label,control){return '<div class="field" style="display:flex;align-items:center;gap:10px;margin-bottom:6px"><label style="width:150px;flex-shrink:0"><input type="checkbox" class="fund-batch-field" data-field="'+key+'" style="margin-right:6px">'+label+'</label>'+control+'</div>';};
  const levels='<option value="">请选择</option>'+FUND_POOR_LEVELS.map(function(x){return '<option value="'+attr(x)+'">'+esc(x)+'</option>';}).join('');
  const body='<div class="zf-section">修改名单（共 <span id="fundBatchModalCount">'+picks.length+'</span> 人）</div><div id="fundBatchChipsHost" style="display:flex;flex-wrap:wrap;gap:6px;margin:8px 4px 14px">'+chips+'</div>'
    +'<div class="zf-section">修改字段（只覆盖已勾选字段）</div><div style="display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:8px 24px;padding:10px 4px">'
    +field('isPoor','是否贫困生','<select id="fb_isPoor" style="flex:1">'+yesNo+'</select>')
    +field('poorLevel','困难评定等级','<select id="fb_poorLevel" style="flex:1">'+levels+'</select>')
    +field('national','国家助学金','<select id="fb_national" style="flex:1">'+yesNo+'</select>')
    +field('college','学院助学金','<select id="fb_college" style="flex:1">'+yesNo+'</select>')
    +field('nationalMotivational','国家励志助学金','<select id="fb_nationalMotivational" style="flex:1">'+yesNo+'</select>')
    +field('collegeMotivational','学院励志助学金','<select id="fb_collegeMotivational" style="flex:1">'+yesNo+'</select>')
    +field('temporaryAid','临时补助','<select id="fb_temporaryAid" style="flex:1">'+yesNo+'</select>')
    +field('other','其他资助','<input id="fb_other" style="flex:1" placeholder="可留空，留空表示清除">')+'</div>'
    +'<div class="tip">仅修改所勾选的字段；未勾选字段保持原值。困难评定等级独立保存，留空或旧数据中的“—”统一显示为“未评定等级”。</div>';
  openModal('批量修改资助情况 · '+t.term,body,function(){
    const current=fundSelectedRecords(t.term); if(!current.length){ alert('修改名单已为空'); return false; }
    const updates={};
    const checks=document.querySelectorAll('.fund-batch-field:checked'); if(!checks.length){ alert('请至少勾选一个要修改的字段'); return false; }
    for(let i=0;i<checks.length;i++){
      const key=checks[i].dataset.field, el=document.getElementById('fb_'+key), raw=el?(el.value||'').trim():'';
      if(key!=='other'&&!raw){ alert('已勾选“'+checks[i].parentElement.textContent.trim()+'”，请选择修改值'); return false; }
      updates[key]=key==='other'?(raw||'—'):(['isPoor','national','college','nationalMotivational','collegeMotivational','temporaryAid'].indexOf(key)>=0?raw==='true':raw);
    }
    let profileChanged=false;
    current.forEach(function(r){ Object.keys(updates).forEach(function(k){r[k]=updates[k];}); r.poorLevel=normalizeFundLevel(r.poorLevel); const s=students.find(function(x){return x.id===r.studentId;}); if(s&&syncFundProfileSnapshot(s)) profileChanged=true; });
    persistFund(); if(profileChanged) persistStudents(); fundBatchSel.clear(); fundRefreshList(); showToast('已批量修改 '+current.length+' 条资助记录','ok'); fundRestoreDetail(id); return true;
  });
  document.getElementById('modal').classList.add('wide');
  const cancel=document.querySelector('#modalFoot .btn-ghost'); if(cancel) cancel.onclick=function(){ closeModal(); fundRestoreDetail(id); };
}
function fundRemoveBatchChip(key,button){
  fundBatchSel.delete(String(key)); const chip=button&&button.closest('[data-fund-key]'); if(chip) chip.remove();
  const count=document.getElementById('fundBatchModalCount'); if(count) count.textContent=String(fundBatchSel.size);
  if(!fundBatchSel.size){ const id=window.fundModalTermId; closeModal(); showToast('修改名单已为空','warn'); fundRestoreDetail(id); }
}
async function fundBatchDelete(){
  const id=window.fundModalTermId, t=fundTermById(id); if(!t) return;
  const picks=fundSelectedRecords(t.term); if(!picks.length){ showToast('请先勾选要删除的资助记录','warn'); return; }
  const moved=await recycleMoveRecords("fund","fund_record",picks.map(function(r){return r.id;}));if(!moved)return;
  const keys=new Set(picks.map(function(r){return String(r.id);})), affected=new Set(picks.map(function(r){return String(r.studentId);}));
  let profileChanged=false; affected.forEach(function(sid){const s=students.find(function(x){return x.id===sid;}); if(s&&syncFundProfileSnapshot(s)) profileChanged=true;});
  if(profileChanged) persistStudents(); fundBatchSel.clear(); fundRefreshList(); fundRebuildTable(id); showToast('已删除 '+picks.length+' 条资助记录','ok');
}
function fundEditQuery(){
  const bar = document.querySelector('.qf-bar[data-page="fund"]');
  viewFilter.fund = bar ? qfGet('fund') : (viewFilter.fund || {});
  setQueryReady('fund', true);
  fundRebuildTable(window.fundModalTermId);
}
function fundEditReset(){
  viewFilter.fund = {};
  setQueryReady('fund', false);
  const bar = document.querySelector('.qf-bar[data-page="fund"]');
  if(bar){
    bar.querySelectorAll('.qf-multi').forEach(function(m){ m.querySelectorAll('input[type=checkbox]').forEach(function(c){ c.checked=false; }); if(typeof qfMultiRefresh==='function') qfMultiRefresh(m); });
  }
  const kw = document.getElementById('kw'); if(kw) kw.value = "";
  fundRebuildTable(window.fundModalTermId);
}
function fundStuIdChange(no){
  setStudentFormValues(studentByExactId(no),"",{sid:"fStuId",name:"fStuName",ethnic:"fStuEthnic"});
}
function fundStuNameChange(name){resolveStudentNameInput(name,function(student,typed){setStudentFormValues(student,typed,{sid:"fStuId",name:"fStuName",ethnic:"fStuEthnic"});},"资助情况");}
window.openFund=function(){
  openModal("录入资助情况",
    "<div class='field'><label>学期</label><select class='in' id='fTerm'>"+termOptionsHTML((viewTerm.fund)||CURRENT_TERM)+"</select></div>"
    +"<div class='row2'><div class='field'><label>学号 *</label><input id='fStuId' placeholder='输入学号自动匹配' oninput='fundStuIdChange(this.value)'></div><div class='field'><label>姓名</label><input id='fStuName' placeholder='输入姓名自动匹配' onchange='fundStuNameChange(this.value)'></div></div>"
    +"<div class='field'><label>民族</label><input id='fStuEthnic' readonly placeholder='由学生信息管理自动匹配'></div>"
    +"<div class='row2'><div class='field'><label>是否贫困生</label><select id='fPoor'><option>是</option><option>否</option></select></div><div class='field'><label>困难评定等级</label><select id='fLevel'>"+FUND_POOR_LEVELS.map(function(level){return '<option>'+level+'</option>';}).join('')+"</select></div></div>"
    +"<div class='row2'><div class='field'><label>国家助学金</label><select id='fNat'><option>是</option><option>否</option></select></div><div class='field'><label>学院助学金</label><select id='fCol'><option>是</option><option>否</option></select></div></div>"
    +"<div class='row2'><div class='field'><label>国家励志助学金</label><select id='fNatM'><option>是</option><option>否</option></select></div><div class='field'><label>学院励志助学金</label><select id='fColM'><option>是</option><option>否</option></select></div></div>"
    +"<div class='row2'><div class='field'><label>临时补助</label><select id='fTmp'><option>是</option><option>否</option></select></div><div class='field'><label>其他资助信息</label><input id='fOther' placeholder='如 国家励志奖学金'></div></div>",
    async ()=>{
      const sid=$('#fStuId').value.trim(); const s=students.find(x=>x.id===sid); if(!s){ alert('请输入有效的学号并确认自动匹配成功'); return; }
      const term=$('#fTerm').value;
      const isPoor=($('#fPoor').value==='是');
      const vals={isPoor:isPoor,poorLevel:$('#fLevel').value,national:($('#fNat').value==='是'),college:($('#fCol').value==='是'),nationalMotivational:($('#fNatM').value==='是'),collegeMotivational:($('#fColM').value==='是'),temporaryAid:($('#fTmp').value==='是'),other:$('#fOther').value||'—'};
      applyFundRecord(sid,s.name,s.dept,s.grade,s.cls,term,vals);
      if(window.workbench?.legacy?.flushStore) await window.workbench.legacy.flushStore();
      closeModal();
      if(typeof showToast==="function") showToast("已保存 "+s.name+" 的资助信息","ok");
      var __fid=window.fundModalTermId; setTimeout(function(){ if(__fid!=null) openEditFundTerm(__fid); else if(typeof renderPage==="function") renderPage("fund"); }, 60);
    });
};
window.openEditFund=function(sid, term){
  const s=students.find(x=>x.id===sid); if(!s){ alert('学生不存在'); return; }
  /* 明细编辑必须读取指定学期台账，不能使用学生档案中的“最新学期”快照。 */
  const f = fundRecordForStudentTerm(sid,term) || ((s.fund && s.fund.term===term) ? s.fund : {});
  const isPoor = f.isPoor===true;
  const yesSel = function(v){ return v===true ? ' selected' : ''; };
  const levelSel = function(v){ return v===normalizeFundLevel(f.poorLevel) ? ' selected' : ''; };
  const escAttr=function(v){ return String(v==null?"":v).replace(/&/g,"&amp;").replace(/</g,"&lt;").replace(/>/g,"&gt;").replace(/"/g,"&quot;"); };
  openModal("修改资助情况",
    "<div class='row2'><div class='field'><label>学期</label><select class='in' id='fTerm'>"+termOptionsHTML(term||CURRENT_TERM)+"</select></div>"
    +"<div class='field'><label>姓名</label><input id='fStuName' readonly value='"+escAttr(s.name)+"（"+escAttr(s.id)+"）'></div></div>"
    +"<div class='field'><label>民族</label><input id='fStuEthnic' readonly value='"+escAttr(s.ethnic||s.nation||"")+"'></div>"
    +"<div class='row2'><div class='field'><label>是否贫困生</label><select id='fPoor'><option"+ (isPoor?' selected':'') +">是</option><option"+ (isPoor?'':' selected') +">否</option></select></div><div class='field'><label>困难评定等级</label><select id='fLevel'>"+FUND_POOR_LEVELS.map(function(level){return '<option'+levelSel(level)+'>'+level+'</option>';}).join('')+"</select></div></div>"
    +"<div class='row2'><div class='field'><label>国家助学金</label><select id='fNat'><option"+ yesSel(f.national) +">是</option><option"+ (f.national===true?'':' selected') +">否</option></select></div><div class='field'><label>学院助学金</label><select id='fCol'><option"+ yesSel(f.college) +">是</option><option"+ (f.college===true?'':' selected') +">否</option></select></div></div>"
    +"<div class='row2'><div class='field'><label>国家励志助学金</label><select id='fNatM'><option"+ yesSel(f.nationalMotivational) +">是</option><option"+ (f.nationalMotivational===true?'':' selected') +">否</option></select></div><div class='field'><label>学院励志助学金</label><select id='fColM'><option"+ yesSel(f.collegeMotivational) +">是</option><option"+ (f.collegeMotivational===true?'':' selected') +">否</option></select></div></div>"
    +"<div class='row2'><div class='field'><label>临时补助</label><select id='fTmp'><option"+ yesSel(f.temporaryAid) +">是</option><option"+ (f.temporaryAid===true?'':' selected') +">否</option></select></div><div class='field'><label>其他资助信息</label><input id='fOther' placeholder='如 国家励志奖学金' value='"+escAttr(f.other||'')+"'></div></div>",
    async ()=>{
      const t=$('#fTerm').value;
      const ip=($('#fPoor').value==='是');
      const vals={isPoor:ip, poorLevel:$('#fLevel').value, national:($('#fNat').value==='是'), college:($('#fCol').value==='是'), nationalMotivational:($('#fNatM').value==='是'), collegeMotivational:($('#fColM').value==='是'), temporaryAid:($('#fTmp').value==='是'), other:$('#fOther').value||'—'};
      applyFundRecord(sid, s.name, s.dept, s.grade, s.cls, t, vals);
      if(window.workbench?.legacy?.flushStore) await window.workbench.legacy.flushStore();
      closeModal();
      if(typeof showToast==='function') showToast('已更新 '+s.name+' 的资助信息','ok');
      var __fid=window.fundModalTermId; setTimeout(function(){ if(__fid!=null) openEditFundTerm(__fid); else if(typeof renderPage==="function") renderPage('fund'); }, 60);
    });
};

/* v1.60：党团员发展台账。每名学生的党组织节点按 history 保存，可追溯、可更正；不再限制仅在校生，可按学籍状态筛选查看。 */
const PARTY_STAGES=["群众","共青团员","递交入党申请书","入党积极分子","发展对象","中共预备党员","中共党员"];
const PARTY_LEAGUE_STATUSES=["团员","非团员","已推优","保留团员的中共党员","退团"];
const PARTY_TRAINING_STATUSES=["未参加","培训中","已结业","未通过"];
const PARTY_TRAINING_CONFIG=[{key:"primary",label:"初级党课"},{key:"intermediate",label:"中级党课"},{key:"advanced",label:"高级党课"}];
const PARTY_CARD_CATEGORIES=[{key:"群众",label:"群众"},{key:"共青团员",label:"共青团员"},{key:"推优",label:"团推优（入党积极分子）"},{key:"中共预备党员",label:"预备党员"},{key:"中共党员",label:"中共党员"}];
function partyTrainingEnsure(p){
  if(!p.training || typeof p.training!=="object" || Array.isArray(p.training))p.training={};
  PARTY_TRAINING_CONFIG.forEach(function(item){
    const source=p.training[item.key];
    const record=source&&typeof source==="object"&&!Array.isArray(source)?source:{};
    p.training[item.key]={status:PARTY_TRAINING_STATUSES.includes(record.status)?record.status:"未参加",date:String(record.date||""),organizer:String(record.organizer||""),result:String(record.result||"")};
  });
  return p.training;
}
function partyCurrentStage(s){
  const p=partyEnsure(s);
  if(p.stage)return p.stage;
  if(PARTY_STAGES.includes(s.political))return s.political;
  return p.leagueStatus==="团员"?"共青团员":"群众";
}
function partyCardCategory(s){
  const stage=partyCurrentStage(s),p=partyEnsure(s);
  if(stage==="入党积极分子" || (p.leagueStatus==="已推优" && ["群众","共青团员","递交入党申请书"].includes(stage)))return "推优";
  return stage;
}
function partyFilteredRoster(list,state){
  return list.filter(function(s){return qfMatch(state.stage,partyCurrentStage(s)) && (!state.category||partyCardCategory(s)===state.category);});
}
function partySelectCard(category){
  if(!PARTY_CARD_CATEGORIES.some(function(card){return card.key===category;}))return;
  const state=qfGet("party");
  state.category=state.category===category?"":category;
  state.stage=[];
  viewFilter.party=state;
  setQueryReady("party",true);
  renderPage("party");
}
function partyEnsure(s){
  if(!s.party || typeof s.party!=="object") s.party={};
  const p=s.party;
  if(p.stage==="入团"){ p.stage="群众"; p.leagueStatus="团员"; }
  if(!p.leagueStatus) p.leagueStatus=s.political==="共青团员"?"团员":"非团员";
  if(!Array.isArray(p.history)) p.history=[];
  partyTrainingEnsure(p);
  return p;
}
function partyHistory(s){
  const p=partyEnsure(s);
  return p.history.slice().sort(function(a,b){return String(a.date||"").localeCompare(String(b.date||""));});
}
function partyStageClass(stage){ return stage==="中共党员"?"b-red":(stage==="中共预备党员"?"b-orange":(stage==="发展对象"?"b-purple":(stage==="入党积极分子"?"b-blue":"b-gray"))); }
function partyLeagueStatusClass(status){ return status==="已推优"?"b-blue":(status==="团员"||status==="保留团员的中共党员"?"b-green":"b-gray"); }
function partySetFormValue(id,value){const field=document.getElementById(id);if(field)field.value=value==null?"":String(value);}
function partyLoadFormStudent(sid){
  const student=students.find(function(item){return String(item.id)===String(sid);});
  if(!student)return;
  const p=partyEnsure(student);
  partySetFormValue("partyPolitical",student.political||"");partySetFormValue("partyLeague",p.leagueStatus||"非团员");partySetFormValue("partyStage",p.stage||"");partySetFormValue("partyDate",p.date||"");partySetFormValue("partyBranch",p.branch||"");partySetFormValue("partyContact",p.contact||"");partySetFormValue("partyIntroducer",p.introducer||"");partySetFormValue("partyMaterials",p.materials||"");partySetFormValue("partyNote",p.note||"");
  PARTY_TRAINING_CONFIG.forEach(function(item){const record=p.training[item.key];partySetFormValue("partyTraining_"+item.key+"_status",record.status);partySetFormValue("partyTraining_"+item.key+"_date",record.date);partySetFormValue("partyTraining_"+item.key+"_organizer",record.organizer);partySetFormValue("partyTraining_"+item.key+"_result",record.result);});
}
window.partyLoadFormStudent=partyLoadFormStudent;
function partyTrainingFormHtml(p){
  return '<div class="zf-section" style="margin-top:14px">党课培训记录</div><div class="tip" style="margin-bottom:10px">分别记录初级、中级、高级党课的培训状态、日期、培训单位和培训结果。</div>'+PARTY_TRAINING_CONFIG.map(function(item){const record=p.training[item.key],prefix="partyTraining_"+item.key+"_",statusOptions=PARTY_TRAINING_STATUSES.map(function(status){return '<option value="'+attr(status)+'"'+(record.status===status?' selected':'')+'>'+esc(status)+'</option>';}).join("");return '<div style="border:1px solid var(--border);border-radius:10px;padding:10px 12px;margin-bottom:9px"><div style="font-weight:700;margin-bottom:8px">'+esc(item.label)+'</div><div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(160px,1fr));gap:10px"><div class="field" style="margin:0"><label>培训状态</label><select id="'+prefix+'status">'+statusOptions+'</select></div><div class="field" style="margin:0"><label>培训/结业日期</label><input id="'+prefix+'date" type="date" value="'+attr(record.date)+'"></div><div class="field" style="margin:0"><label>培训单位</label><input id="'+prefix+'organizer" maxlength="200" value="'+attr(record.organizer)+'"></div><div class="field" style="margin:0"><label>培训结果</label><input id="'+prefix+'result" maxlength="500" value="'+attr(record.result)+'" placeholder="如：合格、优秀、证书编号"></div></div></div>';}).join("");
}
function partyOpenForm(id){
  const candidates=clsStudents();
  if(!candidates.length){ alert("当前没有学生，无法登记党团发展信息。"); return; }
  const s=id?candidates.find(function(x){return x.id===id;}):candidates[0];
  if(!s){ alert("请选择系统中的学生。"); return; }
  const p=partyEnsure(s);
  const current=p.stage||"";
  const stageOptions='<option value="">未填写</option>'+PARTY_STAGES.map(function(x){return '<option value="'+attr(x)+'"'+(x===current?' selected':'')+'>'+esc(x)+'</option>';}).join("");
  const politicalOptions='<option value="">未填写</option>'+political.map(function(x){return '<option value="'+attr(x)+'"'+(x===s.political?' selected':'')+'>'+esc(x)+'</option>';}).join("");
  const leagueOptions=PARTY_LEAGUE_STATUSES.map(function(x){return '<option value="'+attr(x)+'"'+(x===p.leagueStatus?' selected':'')+'>'+esc(x)+'</option>';}).join("");
  const studentOptions=candidates.map(function(x){return '<option value="'+attr(x.id)+'"'+(x.id===s.id?' selected':'')+'>'+esc(x.name+"（"+x.id+" · "+x.cls+"）")+'</option>';}).join("");
  const body='<div class="tip">政治面貌与学生管理双向同步；切换学生时会完整回填该生现有资料。填写当前发展阶段后才会新增或更新发展历程，党课培训记录独立保存。</div>'
    +'<div class="row2"><div class="field"><label>学生 *</label><select id="partySid" '+(id?'disabled':' onchange="partyLoadFormStudent(this.value)"')+'>'+studentOptions+'</select></div><div class="field"><label>政治面貌（与学生管理双向同步）</label><select id="partyPolitical">'+politicalOptions+'</select></div></div>'
    +'<div class="field"><label>团员身份</label><select id="partyLeague">'+leagueOptions+'</select></div>'
    +'<div class="row2"><div class="field"><label>当前发展阶段</label><select id="partyStage">'+stageOptions+'</select></div><div class="field"><label>确定日期</label><input id="partyDate" type="date" value="'+attr(p.date||"")+'"></div></div>'
    +'<div class="row2"><div class="field"><label>所属党支部</label><input id="partyBranch" value="'+attr(p.branch||"")+'" placeholder="如：信息工程学院学生第一党支部"></div><div class="field"><label>培养联系人</label><input id="partyContact" value="'+attr(p.contact||"")+'"></div></div>'
    +'<div class="row2"><div class="field"><label>入党介绍人</label><input id="partyIntroducer" value="'+attr(p.introducer||"")+'"></div><div class="field"><label>材料状态</label><input id="partyMaterials" value="'+attr(p.materials||"")+'" placeholder="如：申请书、政审材料已归档"></div></div>'
    +'<div class="field"><label>本次节点备注</label><textarea id="partyNote" rows="3" maxlength="2000" placeholder="记录培养考察、会议决议、转正意见等">'+esc(p.note||"")+'</textarea></div>'
    +partyTrainingFormHtml(p);
  openModal(id?"编辑党团发展信息":"登记党团发展节点",body,function(){
    const sid=id||document.getElementById("partySid").value;
    const target=students.find(function(x){return x.id===sid;});
    if(!target){ alert("请选择系统中的学生。"); return false; }
    const stage=document.getElementById("partyStage").value;
    const date=document.getElementById("partyDate").value;
    target.political=document.getElementById("partyPolitical").value;
    const pp=partyEnsure(target);
    const entry={stage:stage,date:date,branch:document.getElementById("partyBranch").value.trim(),contact:document.getElementById("partyContact").value.trim(),introducer:document.getElementById("partyIntroducer").value.trim(),materials:document.getElementById("partyMaterials").value.trim(),note:document.getElementById("partyNote").value.trim(),updated:fmtNow()};
    if(stage){
      const oldIndex=pp.history.findIndex(function(x){return x.stage===stage;});
      if(oldIndex>=0) pp.history[oldIndex]=Object.assign(pp.history[oldIndex],entry); else pp.history.push(entry);
    }
    pp.stage=stage; pp.date=date; pp.branch=entry.branch; pp.contact=entry.contact; pp.introducer=entry.introducer; pp.materials=entry.materials; pp.note=entry.note; pp.leagueStatus=document.getElementById("partyLeague").value;
    partyTrainingEnsure(pp);PARTY_TRAINING_CONFIG.forEach(function(item){const prefix="partyTraining_"+item.key+"_",status=document.getElementById(prefix+"status").value;pp.training[item.key]=status==="未参加"?{status:status,date:"",organizer:"",result:""}:{status:status,date:document.getElementById(prefix+"date").value,organizer:document.getElementById(prefix+"organizer").value.trim(),result:document.getElementById(prefix+"result").value.trim()};});
    persistStudents(); closeModal(); renderPage("party"); showToast("已保存 "+target.name+" 的党团发展信息","success");
  });
  document.getElementById("modal").classList.add("wide");
}
function partyView(id){
  const s=students.find(function(x){return x.id===id;}); if(!s) return;
  const p=partyEnsure(s), history=partyHistory(s);
  const rows=history.length?history.map(function(h,i){return '<tr><td>'+esc(h.stage)+'</td><td>'+esc(h.date||"—")+'</td><td>'+esc(h.branch||"—")+'</td><td>'+esc(h.contact||"—")+'</td><td>'+esc(h.introducer||"—")+'</td><td style="white-space:normal">'+esc(h.note||"—")+'</td><td><a class="lk" onclick="partyEditNode('+jsArg(s.id)+','+i+')">编辑</a></td></tr>';}).join(""):'<tr><td colspan="7" class="empty">暂未登记发展节点</td></tr>';
  const trainingRows=PARTY_TRAINING_CONFIG.map(function(item){const record=p.training[item.key];return '<tr><td><b>'+esc(item.label)+'</b></td><td>'+badge(esc(record.status),record.status==="已结业"?"b-green":(record.status==="培训中"?"b-blue":(record.status==="未通过"?"b-red":"b-gray")))+'</td><td>'+esc(record.date||"—")+'</td><td>'+esc(record.organizer||"—")+'</td><td style="white-space:normal">'+esc(record.result||"—")+'</td></tr>';}).join("");
  const body='<div class="zf-detail-head"><div class="avatar">'+esc((s.name||"?").charAt(0))+'</div><div><div style="font-size:17px;font-weight:700">'+esc(s.name)+'</div><div style="color:var(--muted);margin-top:4px">'+esc(s.id+" · "+s.cls)+'</div></div></div>'
    +portraitArchiveGrid([["政治面貌",s.political],["团员身份",p.leagueStatus],["当前阶段",p.stage],["确定日期",p.date],["所属支部",p.branch],["培养联系人",p.contact],["入党介绍人",p.introducer],["材料状态",p.materials]])
    +'<div class="zf-section">党课培训记录</div><div class="list-scroll">'+table(["培训级别","状态","培训/结业日期","培训单位","培训结果"],trainingRows)+'</div>'
    +'<div class="zf-section">发展历程</div><div class="list-scroll">'+table(["发展阶段","确定日期","所属支部","培养联系人","介绍人","备注","操作"],rows)+'</div>';
  openModal("党团发展档案 · "+s.name,body,null); $("#modalFoot").innerHTML='<button class="btn btn-ghost" data-sid="'+attr(s.id)+'" onclick="partyOpenForm(this.dataset.sid)">编辑</button><button class="btn btn-ghost" style="border-color:#e8830c;color:#e8830c" data-sid="'+attr(s.id)+'" onclick="partyInit(this.dataset.sid)">初始化</button><button class="btn btn-primary" onclick="closeModal()">关闭</button>'; $("#modal").classList.add("wide");
}
function partyInit(id){
  var s=students.find(function(x){return x.id===id;}); if(!s){ alert('学生不存在'); return; }
  var baseStage=(s.political==='共青团员'?'共青团员':'群众');
  if(!confirm('确定将「'+s.name+'（'+s.id+'）」的党团发展记录初始化为基线吗？\n\n将重置当前阶段为「'+baseStage+'」、清空全部发展历程节点；已有党课培训记录会保留。此操作不可恢复。')) return;
  var previous=s.party&&typeof s.party==='object'?s.party:{};
  s.party={stage:baseStage, leagueStatus:(s.political==='共青团员'?'团员':'非团员'), history:[], date:'', branch:'', contact:'', introducer:'', materials:'', note:'',training:previous.training,customFieldValues:previous.customFieldValues||{}};partyEnsure(s);
  persistStudents(); showToast('已初始化 '+s.name+' 的党团发展基线，党课培训记录已保留','ok'); renderPage('party');
}
function partyBatchInit(){
  var targets=students.filter(function(s){
    var p=s.party;
    if(!p || typeof p!=='object') return true;
    if(!Array.isArray(p.history)) return true;
    return p.history.length===0;
  });
  if(!targets.length){ alert('所有学生均已存在党团发展记录，无需批量初始化。'); return; }
  if(!confirm('确定对 '+targets.length+' 名“尚无党团发展节点”的学生批量建立基线吗？\n\n基线：群众/共青团员（按政治面貌自动判定）、无发展历程节点；已有党课培训记录会保留。已有发展节点的学生不受影响。')) return;
  targets.forEach(function(s){
    var previous=s.party&&typeof s.party==='object'?s.party:{};
    s.party={stage:(s.political==='共青团员'?'共青团员':'群众'), leagueStatus:(s.political==='共青团员'?'团员':'非团员'), history:[], date:'', branch:'', contact:'', introducer:'', materials:'', note:'',training:previous.training,customFieldValues:previous.customFieldValues||{}};partyEnsure(s);
  });
  persistStudents(); showToast('已为 '+targets.length+' 名学生建立党团发展基线，已有党课培训记录已保留','ok'); renderPage('party');
}
function partyEditNode(id, idx){
  var s=students.find(function(x){return x.id===id;}); if(!s) return;
  var hist=partyHistory(s); var node=hist[idx]; if(!node) return;
  var body='<div class="tip">修改该发展节点的详情，保存后同步到学生全档案。</div>'
    +'<div class="row2"><div class="field"><label>发展阶段</label><input id="pnStage" class="in" value="'+attr(node.stage||"")+'"></div><div class="field"><label>确定日期</label><input id="pnDate" type="date" value="'+attr(node.date||"")+'"></div></div>'
    +'<div class="row2"><div class="field"><label>所属党支部</label><input id="pnBranch" class="in" value="'+attr(node.branch||"")+'"></div><div class="field"><label>培养联系人</label><input id="pnContact" class="in" value="'+attr(node.contact||"")+'"></div></div>'
    +'<div class="row2"><div class="field"><label>入党介绍人</label><input id="pnIntro" class="in" value="'+attr(node.introducer||"")+'"></div><div class="field"><label>材料状态</label><input id="pnMat" class="in" value="'+attr(node.materials||"")+'"></div></div>'
    +'<div class="field"><label>备注</label><textarea id="pnNote" rows="3" class="in">'+attr(node.note||"")+'</textarea></div>';
  openModal("编辑发展节点",body,function(){
    node.stage=document.getElementById("pnStage").value.trim()||node.stage;
    node.date=document.getElementById("pnDate").value.trim();
    node.branch=document.getElementById("pnBranch").value.trim();
    node.contact=document.getElementById("pnContact").value.trim();
    node.introducer=document.getElementById("pnIntro").value.trim();
    node.materials=document.getElementById("pnMat").value.trim();
    node.note=document.getElementById("pnNote").value.trim();
    node.updated=(typeof fmtNow==='function')?fmtNow():new Date().toISOString();
    var p=partyEnsure(s);
    if(p.stage===node.stage){ p.date=node.date; p.branch=node.branch; p.contact=node.contact; p.introducer=node.introducer; p.materials=node.materials; p.note=node.note; }
    persistStudents(); closeModal(); partyView(id); showToast("已保存发展节点修改","success");
  });
  document.getElementById("modal").classList.add("wide");
}
function partyTrainingSummaryHtml(p){return '<div class="party-history">'+PARTY_TRAINING_CONFIG.map(function(item){const record=p.training[item.key];return '<span>'+esc(item.label)+' · '+esc(record.status||"未参加")+(record.date?' · '+esc(record.date):'')+'</span>';}).join("")+'</div>';}
PAGES.party=function(){
  if(!viewFilter.party) viewFilter.party={};
  const state=viewFilter.party;
  if(state.status===undefined) state.status=["在校"];
  const ss=stuFilterByState(clsStudents(),state);
  let rowsSrc=partyFilteredRoster(ss,state);
  if(state.kw){const k=state.kw.trim(); rowsSrc=rowsSrc.filter(function(s){return (s.id||"").includes(k)||(s.name||"").includes(k);});}
  const info=pagerSlice("party",rowsSrc,JSON.stringify(state));
  const rows=info.slice.length?info.slice.map(function(s){
    const p=partyEnsure(s), hist=partyHistory(s);
    const chips=hist.length?'<div class="party-history">'+hist.map(function(h){return '<span>'+esc(h.stage)+" · "+esc(h.date||"未填")+'</span>';}).join("")+'</div>':'<span style="color:var(--muted)">暂未登记节点</span>';
    return '<tr>'+stuCells(s)+'<td>'+esc(s.political||"—")+'</td><td>'+badge(esc(p.leagueStatus||"非团员"),partyLeagueStatusClass(p.leagueStatus))+'</td><td><span class="party-current">'+esc(partyCurrentStage(s))+'</span></td><td>'+esc(p.date||"—")+'</td><td>'+esc(p.branch||"—")+'</td><td style="white-space:normal;min-width:210px">'+partyTrainingSummaryHtml(p)+'</td><td style="white-space:normal;min-width:250px">'+chips+'</td><td><a class="lk" onclick="partyView('+jsArg(s.id)+')">查看</a> <a class="lk" onclick="partyOpenForm('+jsArg(s.id)+')">编辑</a> <a class="lk" onclick="partyInit('+jsArg(s.id)+')">初始化</a></td></tr>';
  }).join(""):'<tr><td colspan="13" class="empty">暂无符合条件的学生</td></tr>';
  const cards=PARTY_CARD_CATEGORIES.map(function(card){
    const count=ss.filter(function(s){return partyCardCategory(s)===card.key;}).length,active=state.category===card.key;
    return '<button type="button" class="party-kpi'+(active?' active':'')+'" aria-pressed="'+active+'" onclick="partySelectCard('+jsArg(card.key)+')"><b>'+count+'</b><span>'+esc(card.label)+'</span></button>';
  }).join("");
  return '<div class="party-hero"><h2>🚩 党团员发展台账</h2><p>按“团员身份—入党申请—积极分子—发展对象—预备党员—正式党员”完整留痕；可按学籍状态筛选查看，默认展示在校生。</p><div class="party-steps"><span>团员身份</span><span>递交申请书</span><span>积极分子</span><span>发展对象</span><span>预备党员</span><span>正式党员</span></div></div>'
    +'<div class="party-kpis">'+cards+'</div>'
    +'<div class="card"><div class="tip">名单按学生主档案中的“学籍状态”筛选；默认展示在校生，可切换查看其他学籍状态的学生；发展阶段、支部、联系人和每次节点均会同步到学生画像全档案。点击卡片查询对应名单，再次点击取消该分类；团推优统计已推优及入党积极分子，进入后续阶段后不再重复计入。</div><div class="toolbar qf-bar" data-page="party"><input type="hidden" data-qf="category" value="'+attr(state.category||"")+'">'
    +'<div class="filter-item"><label>关键字</label>'+qfInput("kw","搜索学号/姓名",state.kw,160)+'</div><div class="filter-item"><label>学院</label>'+qfMulti("dept",[{v:"",l:"全部学院"}].concat(depts.map(function(d){return {v:d,l:d};})),state.dept)+'</div><div class="filter-item"><label>专业</label>'+qfMulti("major",[{v:"",l:"全部专业"}].concat(majors.map(function(m){return {v:m,l:m};})),state.major)+'</div><div class="filter-item"><label>年级</label>'+qfMulti("grade",[{v:"",l:"全部年级"}].concat(grades.map(function(g){return {v:g,l:g};})),state.grade)+'</div><div class="filter-item"><label>班级</label>'+qfMulti("cls",[{v:"",l:"全部班级"}].concat(classes.map(function(c){return {v:c,l:c};})),state.cls)+'</div><div class="filter-item"><label>学籍状态</label>'+qfMulti("status",[{v:"",l:"全部学籍状态"}].concat(STU_STATUS_TABS.map(function(x){return {v:x.value,l:x.label};})),state.status)+'</div><div class="filter-item"><label>发展阶段</label>'+qfMulti("stage",[{v:"",l:"全部阶段"}].concat(PARTY_STAGES.map(function(x){return {v:x,l:x};})),state.stage)+'</div>'+qfBtns("party")+'<span style="flex:1"></span><button class="btn btn-primary btn-sm" onclick="partyOpenForm()">＋ 登记发展节点</button><button class="btn btn-ghost btn-sm" onclick="partyImportOpen()">⬆ 导入名册</button><button class="btn btn-ghost btn-sm" onclick="partyImportTemplate()">⇩ 下载导入模板</button><button class="btn btn-ghost btn-sm" onclick="exportParty()">⬇ 导出名册</button></div>'
    +'<div class="module-table-wrap">'+table(["学院","专业","班级","学号","姓名","政治面貌","团员身份","当前阶段","确定日期","所属支部","党课培训","发展历程","操作"],rows)+'</div>'+renderGenericPager("party",info,"partyJump")+'</div>';
};
window.openParty=function(){partyOpenForm();};

