      const name=$("#odName").value.trim();
      if(!name){ showToast("请填写学院名称","error"); return false; }
      if(code&&ORG_DEPTS.some(function(d){return d.code===code;})){ showToast("学院代码「"+code+"」已存在","error"); return false; }
      if(ORG_DEPTS.some(function(d){return d.name===name;})){ showToast("学院名称「"+name+"」已存在","error"); return false; }
