function scanStorageHealth(){
  try{
    var bad=[];
    BACKUP_KEYS.forEach(function(k){
      if(k==="nnuzc_current_term"||k==="nnuzc_student_integrity_review_version"||k==="nnuzc_fixed_value_review_version") return; // 该键存原始字符串，非 JSON，跳过解析
      var v=localStorage.getItem(k);
      if(v!=null){ try{ JSON.parse(v); }catch(e){ bad.push(k.replace("nnuzc_","")); } }
    });
    if(bad.length){
      var d=document.getElementById("corruptDetail");
      if(d) d.textContent="以下数据已损坏、无法解析：" + bad.join("、") + "。请到【数据备份】导入此前备份恢复，或清空本地数据后重新录入真实数据。";
      var b=document.getElementById("corruptBanner");
      if(b) b.style.display="block";
    }
  }catch(e){}
}
