/* ---- 通用工具 ---- */
function genId(p){ return (p||"r")+"_"+Date.now().toString(36)+Math.floor(Math.random()*1e4); }
function attr(v){ return String(v==null?"":v).replace(/&/g,"&amp;").replace(/"/g,"&quot;").replace(/</g,"&lt;").replace(/>/g,"&gt;"); }
function openRecordForm(title, fields, data, onSubmit){
  data = data || {};
  const body = fields.map(function(f){
    const id="rf_"+f.name;
    const val = (data[f.name]!=null)? data[f.name] : "";
    if(f.type==="select"){
      const opts=(f.options||[]).map(function(o){ return '<option value="'+attr(o)+'"'+(String(val)===String(o)?" selected":"")+'>'+esc(o)+'</option>'; }).join("");
      return '<div class="field"><label>'+esc(f.label)+'</label><select id="'+id+'" class="in">'+opts+'</select></div>';
    }
    if(f.type==="textarea"){
      return '<div class="field"><label>'+esc(f.label)+'</label><textarea id="'+id+'" class="in" rows="'+(f.rows||3)+'">'+attr(val)+'</textarea></div>';
    }
    return '<div class="field"><label>'+esc(f.label)+'</label><input id="'+id+'" class="in" value="'+attr(val)+'"></div>';
  }).join("");
  openModal(title, body, function(){});
  $("#modalFoot").innerHTML='<button class="btn btn-ghost" onclick="closeModal()">取消</button><button class="btn btn-primary" onclick="window.__rfSubmit()">保存</button>';
  window.__rfSubmit=function(){
    const v={}; fields.forEach(function(f){ v[f.name]=(document.getElementById("rf_"+f.name).value||"").trim(); });
    onSubmit(v);
  };
}
