const TALK_STATUS_OPTS=[{v:"",l:"全部学籍状态"}].concat(STU_STATUS_TABS.map(function(x){return {v:x.value,l:x.label};}));
/* ---- 工作台账三模块通用：列表滚动容器 + 数据分页（v1.52） ---- */
const talkPage={page:1,size:20};
const homePage={page:1,size:20};
const psychPage={page:1,size:20};
const eventPage={page:1,size:20};
function renderPager(prefix,total,page,size){
  const pageCount=Math.max(1,Math.ceil(total/size));
  page=Math.min(Math.max(1,page),pageCount);
  let nums=[];
  if(pageCount<=7){ for(let i=1;i<=pageCount;i++) nums.push(i); }
  else{
    nums.push(1);
    if(page>4) nums.push('…');
    const s=Math.max(2,page-2), e=Math.min(pageCount-1,page+2);
    for(let i=s;i<=e;i++) nums.push(i);
    if(page<pageCount-3) nums.push('…');
    nums.push(pageCount);
  }
  const btns=nums.map(function(n){
    if(n==='…') return '<span class="stu-page-ellipsis">…</span>';
    return '<button class="stu-page-btn'+(n===page?' active':'')+'" onclick="'+prefix+'GoPage('+n+')">'+n+'</button>';
  }).join('');
  const sizes=[10,20,50,100];
  const sizeOpts=sizes.map(function(s){return '<option value="'+s+'"'+(s===size?' selected':'')+'>'+s+' 条/页</option>';}).join('');
  return '<div class="stu-pager">'
    +'<span class="stu-pager-info">共 <strong>'+total+'</strong> 条 · 第 <strong>'+page+'</strong>/<strong>'+pageCount+'</strong> 页</span>'
    +'<div class="stu-pager-pages">'
    +'<button class="stu-page-btn" onclick="'+prefix+'GoPage(1)"'+(page<=1?' disabled':'')+'>«</button>'
    +btns
    +'<button class="stu-page-btn" onclick="'+prefix+'GoPage('+pageCount+')"'+(page>=pageCount?' disabled':'')+'>»</button>'
    +'</div>'
    +'<select class="stu-pager-size" onchange="'+prefix+'SetSize(this.value)">'+sizeOpts+'</select>'
    +'<div class="stu-pager-jump">跳至 <input type="number" min="1" max="'+pageCount+'" value="'+page+'" onchange="'+prefix+'GoPage(parseInt(this.value||1,10))"> 页</div>'
    +'</div>';
}
function talkGoPage(n){ talkPage.page=Math.max(1,parseInt(n,10)||1); talkRender(); }
function talkSetSize(v){ talkPage.size=parseInt(v,10)||20; talkPage.page=1; talkRender(); }
function homeGoPage(n){ homePage.page=Math.max(1,parseInt(n,10)||1); homeRender(); }
function homeSetSize(v){ homePage.size=parseInt(v,10)||20; homePage.page=1; homeRender(); }
function psychGoPage(n){ psychPage.page=Math.max(1,parseInt(n,10)||1); psychRender(); }
function psychSetSize(v){ psychPage.size=parseInt(v,10)||20; psychPage.page=1; psychRender(); }
function eventGoPage(n){ eventPage.page=Math.max(1,parseInt(n,10)||1); eventRender(); }
function eventSetSize(v){ eventPage.size=parseInt(v,10)||20; eventPage.page=1; eventRender(); }
