/* 突发事件附件：本次新选文件/文件夹 + 已确认附件 */
let evPendingFiles=[];
let evEditFiles=[];
let evOriginalFiles=[];
function evFileSelChanged(input){
  const MAX=100*1024*1024;
  for(const f of Array.from(input.files||[])){
    if(f.size>MAX){ alert('附件「'+(f.webkitRelativePath||f.name)+'」超过 100MB，已跳过（单文件上限 100MB）。'); continue; }
    if(f.size===0){ alert('附件「'+(f.webkitRelativePath||f.name)+'」为空文件，已跳过。'); continue; }
    evPendingFiles.push(f);
  }
  evRenderFileList();
}
function evRemovePending(i){ if(evPendingFiles[i]) evPendingFiles.splice(i,1); evRenderFileList(); }
function evRemoveAtt(i){ if(evEditFiles[i]) evEditFiles.splice(i,1); evRenderFileList(); }
function evRenderFileList(){
  const box=document.getElementById("evFileList"); if(!box) return;
  const items=[];
  (evEditFiles||[]).forEach(function(a,i){ items.push('<div style="display:inline-block;margin:3px 6px 3px 0;padding:4px 8px;background:#eef6f0;border:1px solid #cfe3d4;border-radius:6px;font-size:12.5px">📎 '+escAttr(a.name||"附件")+'（已上传）<span style="cursor:pointer;color:#c0392b;margin-left:6px" onclick="evRemoveAtt('+i+')">✕</span></div>'); });
  evPendingFiles.forEach(function(f,i){ const nm=(f.webkitRelativePath||f.name); items.push('<div style="display:inline-block;margin:3px 6px 3px 0;padding:4px 8px;background:#fff8e6;border:1px solid #f5d77f;border-radius:6px;font-size:12.5px">🖼️ '+escAttr(nm)+'（待上传）<span style="cursor:pointer;color:#c0392b;margin-left:6px" onclick="evRemovePending('+i+')">✕</span></div>'); });
  box.innerHTML=items.join('');
}
function evFilesHtml(r){
  const fs=(r&&r.files)||[];
  if(!fs.length) return '—';
  return fs.map(function(f){ if(!f||!f.id) return ''; const nm=f.name||'附件'; const isImg=/\.(jpg|jpeg|png|gif|webp|bmp)$/i.test(nm||''); const u=isImg?attachmentDisplayUrl(f):(f.url||('/attachments/'+f.id)); return isImg?'<a href="'+attr(u)+'" download="'+attr(nm)+'" style="cursor:zoom-in" onclick="event.preventDefault();portraitZoomPhoto('+jsArg(u)+')">'+esc(nm)+'</a>':'<a href="'+attr(u)+'" download="'+attr(nm)+'">'+esc(nm)+'</a>'; }).join('、');
}
function openEventForm(id){
  const isEdit=!!id;
  const rec=isEdit? eventRecords.find(function(x){return x.id===id;}) : null;
  const v=isEdit? (rec||{}) : {};
  evPendingFiles=[];
  evEditFiles=(rec&&rec.files&&rec.files.length)?rec.files.slice():[];
  evOriginalFiles=evEditFiles.slice();
  const initTerm=v.term||CURRENT_TERM;
  const opt=function(arr,sel){ return arr.map(function(x){ return "<option value='"+attr(x)+"'"+(x===sel?" selected":"")+">"+attr(x)+"</option>"; }).join(""); };
  const body=[
    "<div class='row2'><div class='field'><label>学期</label><select class='in' id='efTerm'>"+termOptionsHTML(initTerm)+"</select></div>",
    "<div class='field'><label>学号</label><input id='efSid' placeholder='输入学号自动匹配' value='"+attr(v.sid||"")+"' oninput='eventAutoFill(this.value)'></div></div>",
    "<div class='row2'><div class='field'><label>姓名</label><input id='efName' placeholder='输入姓名自动匹配' onchange='eventNameAutoFill(this.value)' value='"+attr(v.name||"")+"'></div>",
    "<div class='field'><label>学院</label><input id='efDept' readonly placeholder='自动匹配' value='"+attr(v.dept||"")+"'></div></div>",
    "<div class='row2'><div class='field'><label>专业</label><input id='efMajor' readonly placeholder='自动匹配' value='"+attr(v.major||"")+"'></div>",
    "<div class='field'><label>年级</label><input id='efGrade' readonly placeholder='自动匹配' value='"+attr(v.grade||"")+"'></div></div>",
    "<div class='row2'><div class='field'><label>班级</label><input id='efCls' readonly placeholder='自动匹配' value='"+attr(v.cls||"")+"'></div>",
    "<div class='field'><label>学籍状态</label><input id='efStatus' readonly placeholder='自动匹配' value='"+attr(eventStatusLabel(v.status||""))+"'></div></div>",
    "<div class='row2'><div class='field'><label>日期</label><input id='efDate' type='date' value='"+attr(v.date||fmtNow().slice(0,10))+"'></div>",
    "<div class='field'><label>类型</label><select class='in' id='efType'>"+opt(["日常","预警","危机","家访"],v.type||"日常")+"</select></div></div>",
    "<div class='row2'><div class='field'><label>方式</label><select class='in' id='efWay'>"+opt(["面谈","电话","线上","其他"],v.way||"面谈")+"</select></div>",
    "<div class='field'><label>情绪</label><select class='in' id='efMood'>"+opt(["好","中","差"],v.mood||"中")+"</select></div></div>",
    "<div class='field'><label>谈话内容</label><textarea id='efContent' class='in' rows='4'>"+attr(v.content||"")+"</textarea></div>",
    "<div class='field'><label>后续跟进</label><textarea id='efFollow' class='in' rows='2'>"+attr(v.followUp||"")+"</textarea></div>",
    "<div class='field'><label>附件（支持任意类型文件 / 文件夹，单文件≤100MB）</label><div style='display:flex;gap:8px;flex-wrap:wrap;margin-bottom:6px'><button type='button' class='btn btn-ghost btn-sm' onclick=\"document.getElementById('evFile').click()\">📁 选择文件</button><button type='button' class='btn btn-ghost btn-sm' onclick=\"document.getElementById('evFolder').click()\">📂 选择文件夹</button><input type='file' id='evFile' multiple style='display:none' onchange='evFileSelChanged(this)'><input type='file' id='evFolder' webkitdirectory multiple style='display:none' onchange='evFileSelChanged(this)'></div><div id='evFileList' style='margin-top:4px'></div></div>"
  ].join("");
  openModal(isEdit?"编辑突发事件":"新增突发事件", body, async function(){
    const o=eventReadForm();
    if(!o.sid){ alert("请填写学号（学号为必填项）"); return false; }
    if(!o.name){ alert("请填写姓名（请输入有效学号自动匹配，或手动填写姓名）"); return false; }
    const uploaded=[];
    try{
      for(const f of evPendingFiles){
        const upName=f.webkitRelativePath||f.name;
        const saved=await window.workbench.legacy.attachmentUploadFile(upName,f);
        uploaded.push(Object.assign({},saved,{mime:f.type||"application/octet-stream"}));
      }
    }catch(error){ await Promise.all(uploaded.map(function(a){ return window.workbench.legacy.attachmentDelete(a.id).catch(function(){}); })); alert('附件保存失败：'+error.message); return false; }
    o.files=evEditFiles.concat(uploaded);
    const keptIds=new Set(evEditFiles.map(function(a){return a&&a.id;}).filter(Boolean));
    const removedFiles=evOriginalFiles.filter(function(a){return a&&a.id&&!keptIds.has(a.id);});
    const previous=isEdit?JSON.parse(JSON.stringify(rec)):null;
    if(isEdit){ Object.assign(rec,o); }
    else{ o.id=genId("ev"); eventRecords.push(o); }
    try{persistEvents();}catch(error){if(isEdit)Object.assign(rec,previous);else eventRecords=eventRecords.filter(function(x){return x!==o;});await deleteAttachmentRefs(uploaded);alert('记录保存失败：'+error.message);return false;}
    await deleteAttachmentRefs(removedFiles); closeModal(); eventRender(); showToast(isEdit?"已更新":"已保存","success");
  });
  evRenderFileList();
  if(isEdit && rec && rec.sid){ setTimeout(function(){ eventAutoFill(rec.sid); },0); }
}
function eventApplyFilter(){
  const f=eventFilter;
  return eventRecords.filter(function(r){
    if(f.sid && (r.sid||"").indexOf(f.sid)<0) return false;
    if(f.name && (r.name||"").indexOf(f.name)<0) return false;
    if(!qfMatch(f.dept,r.dept||"")) return false;
    if(!qfMatch(f.major,r.major||"")) return false;
    if(!qfMatch(f.grade,r.grade||"")) return false;
    if(!qfMatch(f.cls,r.cls||"")) return false;
    if(!qfMatch(f.status,stuNormalizeStatus(r.status||""))) return false;
    return true;
  });
}
function eventRows(){
  const terms=selectedViewTerms("events"),vt=selectedViewTermsText("events");
  const list=eventApplyFilter().filter(function(r){return terms.indexOf(r.term||"")>=0;}).sort(function(a,b){return (b.date||"").localeCompare(a.date||"");});
  const total=list.length;
  const size=eventPage.size||20;
  const pageCount=Math.max(1,Math.ceil(total/size));
  const page=Math.min(Math.max(1,eventPage.page||1),pageCount);
  eventPage.page=page;
  const start=(page-1)*size;
  const pageRows=list.slice(start,start+size);
  const emptyMsg=eventRecords.length? ('当前学期 '+esc(vt)+' 下暂无记录（请切换学期或新增）') : '暂无突发事件，点击「新增记录」登记';
  const rows=pageRows.length? pageRows.map(function(r){
    return '<tr><td>'+esc(r.date||"—")+'</td><td>'+esc(r.term||"—")+'</td><td>'+esc(r.dept||"—")+'</td><td>'+esc(r.major||"—")+'</td><td>'+esc(r.grade||"—")+'</td><td>'+esc(r.cls||"—")+'</td><td>'+esc(r.sid||"—")+'</td><td>'+esc(r.name||"—")+'</td><td>'+badge(esc(r.type||"—"), r.type==="危机"?"b-red":(r.type==="预警"?"b-orange":"b-gray"))+'</td><td>'+esc(r.way||"—")+'</td><td>'+badge(esc(r.mood||"—"), r.mood==="差"?"b-red":(r.mood==="中"?"b-orange":"b-green"))+'</td><td style="max-width:240px;white-space:normal">'+esc(r.content||"—")+'</td><td style="max-width:200px;white-space:normal">'+esc(r.followUp||"")+'</td><td>'+evFilesHtml(r)+'</td><td><a class="lk" onclick="openEventForm('+jsArg(r.id)+')">编辑</a> <a class="lk danger" onclick="eventDel('+jsArg(r.id)+')">删除</a></td></tr>';
  }).join("") : '<tr><td colspan="15" class="empty">'+emptyMsg+'</td></tr>';
  const tbl=table(["日期","学期","学院","专业","年级","班级","学号","姓名","类型","方式","情绪","谈话内容","后续跟进","附件","操作"],rows);
  return '<div class="list-scroll">'+tbl+'</div>'+renderPager("event",total,page,size);
}
function eventRender(){ const el=document.getElementById("eventBody"); if(el) el.innerHTML=eventRows(); const b=document.getElementById("eventsBar"); if(b) setTimeout(function(){ cascadeSingle(b); },0); }
async function eventDel(id){ const rec=eventRecords.find(function(x){return String(x.id)===String(id);});if(!rec)return;const moved=await recycleMoveRecords("events","event_record",[rec.id]);if(!moved)return;eventRecords=eventRecords.filter(function(x){return String(x.id)!==String(id);});eventRender(); }
function eventReadFilter(){ const bar=document.getElementById("eventsBar"); if(bar) Object.assign(eventFilter, barFilterGet(bar)); eventPage.page=1; }
function eventQuery(){ setQueryReady("events",true); captureViewTerms("events"); eventReadFilter(); eventRender(); }
function eventFilterReset(){ const bar=document.getElementById("eventsBar"); if(bar) barFilterReset(bar); for(const k in eventFilter) eventFilter[k]=""; resetViewTerms("events"); setQueryReady("events",false); eventPage.page=1; renderPage("events"); }
