  return '<div class="wr-kpi"><div><small>重点</small><b>'+key+'</b></div><div><small>关注</small><b>'+watch+'</b></div><div><small>正常</small><b>'+normal+'</b></div><div><small>有备注</small><b>'+withNote+'</b></div><div><small>在校总数</small><b>'+list.length+'</b></div></div>';
