  o.rate=(document.getElementById("ccRate").value||"").trim();
  o.late=(document.getElementById("ccLate").value||"").trim();
  o.leave=(document.getElementById("ccLeave").value||"").trim();
  o.content=(document.getElementById("ccContent").value||"").trim();
  o.absentStudentIds=ccBehaviorSelected.absent.slice();
  if(ccLeaveListManaged){o.personalLeaveStudentIds=ccBehaviorSelected.personalLeave.slice();o.sickLeaveStudentIds=ccBehaviorSelected.sickLeave.slice();o.publicLeaveStudentIds=ccBehaviorSelected.publicLeave.slice();o.leaveStudentIds=Array.from(new Set(o.personalLeaveStudentIds.concat(o.sickLeaveStudentIds,o.publicLeaveStudentIds)));}
