function checkClassApplyFilter(){
  const f=ccFilter;
  return checkClassRecords.filter(function(r){
    const meta=ccRecordOrgMeta(r);
    if(!ccClassesOf(r).some(function(cls){const org=ccClassesOf(r).length===1?meta:ccClassOrgMeta(cls);return qfMatch(f.dept,org.dept||"")&&qfMatch(f.grade,org.grade||"")&&qfMatch(f.cls,cls);})) return false;
    if(f.course && (r.course||"").indexOf(f.course)<0) return false;
    if(f.teacher && (r.teacher||"").indexOf(f.teacher)<0) return false;
    return true;
  });
}
function checkClassRows(){
  const terms=selectedViewTerms("checkClass"),vt=selectedViewTermsText("checkClass");
  const list=checkClassApplyFilter().filter(function(r){return terms.indexOf(r.term||"")>=0;}).sort(function(a,b){return (b.date||"").localeCompare(a.date||"");});
  const total=list.length;
  const size=ccPage.size||20;
  const pageCount=Math.max(1,Math.ceil(total/size));
  const page=Math.min(Math.max(1,ccPage.page||1),pageCount);
  ccPage.page=page;
  const start=(page-1)*size;
  const pageRows=list.slice(start,start+size);
  const emptyMsg=checkClassRecords.length? ('当前学期 '+esc(vt)+' 下暂无记录（请切换学期或新增）') : '暂无查课记录，点击「新增查课」登记';
  const rateBadge=function(v){ const n=parseFloat(String(v||"").replace('%','')); const cls=n>=90?'b-green':(n>=75?'b-orange':'b-red'); return badge(esc(v||"—"),cls); };
  const rows=pageRows.length? pageRows.map(function(r){
    const meta=ccRecordOrgMeta(r);
    const absent=ccBehaviorStudentText(r,"absent",true)||"—",personalLeave=ccBehaviorStudentText(r,"personalLeave",true)||"—",sickLeave=ccBehaviorStudentText(r,"sickLeave",true)||"—",publicLeave=ccBehaviorStudentText(r,"publicLeave",true)||"—",late=ccBehaviorStudentText(r,"late",true)||"—",early=ccBehaviorStudentText(r,"early",true)||"—";
    return '<tr><td>'+esc(r.date||"—")+'</td><td>'+esc(r.term||"—")+'</td><td>'+esc(meta.dept||"—")+'</td><td>'+esc(meta.grade||"—")+'</td><td>'+esc(r.cls||"—")+'</td><td>'+esc(r.course||"—")+'</td><td>'+esc(r.teacher||"—")+'</td><td>'+esc(r.period||"—")+'</td><td>'+esc(r.location||"—")+'</td><td>'+esc(r.headcount||"—")+'</td><td>'+esc(r.attended||"—")+'</td><td>'+rateBadge(r.rate)+'</td><td>'+esc(r.leave||"—")+'</td><td>'+esc(r.late||"—")+'</td><td style="max-width:240px;white-space:normal">'+absent+'</td><td style="max-width:240px;white-space:normal">'+personalLeave+'</td><td style="max-width:240px;white-space:normal">'+sickLeave+'</td><td style="max-width:240px;white-space:normal">'+publicLeave+'</td><td style="max-width:240px;white-space:normal">'+late+'</td><td style="max-width:240px;white-space:normal">'+early+'</td><td style="max-width:220px;white-space:normal">'+esc(r.content||"—")+(r.source==="学习通"?'<br><a class="lk" onclick="chaoxingImportDetails('+jsArg(r.id)+')">学习通原始明细</a>':'')+'</td><td>'+wrFilesHtml(r)+'</td><td><a class="lk" onclick="openCheckClassForm('+jsArg(r.id)+')">编辑</a> <a class="lk danger" onclick="checkClassDel('+jsArg(r.id)+')">删除</a></td></tr>';
  }).join("") : '<tr><td colspan="23" class="empty">'+emptyMsg+'</td></tr>';
  const tbl=table(["日期","学期","学院","年级","班级","课程","任课教师","节次","地点","应到","实到","到课率","请假总人数","迟到人数","旷课名单","事假名单","病假名单","公假名单","迟到名单","早退名单","课堂情况","附件","操作"],rows);
  return '<div class="list-scroll">'+tbl+'</div>'+renderPager("cc",total,page,size);
}
function checkClassRender(){ const el=document.getElementById("checkClassBody"); if(el) el.innerHTML=checkClassRows(); }
async function checkClassDel(id){const rec=checkClassRecords.find(function(x){return x.id===id;});if(!rec)return;const moved=await recycleMoveRecords("checkClassRecord","check_class_record",[id]);if(!moved)return;checkClassRender();showToast("查课记录及其生成的学生考勤明细已移入回收站","success");}
function checkClassReadFilter(){ const bar=document.getElementById("checkClassBar"); if(bar) Object.assign(ccFilter, barFilterGet(bar)); ccPage.page=1; }
function checkClassQuery(){ setQueryReady("checkClass",true); captureViewTerms("checkClass"); checkClassReadFilter(); checkClassRender(); }
function checkClassFilterReset(){ const bar=document.getElementById("checkClassBar"); if(bar) barFilterReset(bar); for(const k in ccFilter) ccFilter[k]=""; resetViewTerms("checkClass"); setQueryReady("checkClass",false); ccPage.page=1; renderPage("checkClass"); }
PAGES.checkClass=function(){
  const deptOpts=[{v:"",l:"全部学院"}].concat(orgFilterValues("dept").map(function(x){return {v:x,l:x};}));
  const gradeOpts=[{v:"",l:"全部年级"}].concat(orgFilterValues("grade").map(function(x){return {v:x,l:x};}));
  const clsOpts=[{v:"",l:"全部班级"}].concat(orgFilterValues("cls").map(function(x){return {v:x,l:x};}));
  return `
  <h2 class="ptitle">📖 查课记录 <span class="tag">深入课堂 · 记录听课查课与到课情况</span></h2>
  <div class="card ledger-filter-card">
    ${WR_KPI_STYLE}${checkClassStatsHtml()}
    <div class="qf-bar ledger-filters ledger-filters-6" data-page="checkClass" id="checkClassBar">
      <div class="filter-item"><label>学期</label>${termPicker('checkClass')}</div>
      <div class="filter-item"><label>学院</label>${qfMulti('dept',deptOpts,ccFilter.dept)}</div>
      <div class="filter-item"><label>年级</label>${qfMulti('grade',gradeOpts,ccFilter.grade)}</div>
      <div class="filter-item"><label>班级</label>${qfMulti('cls',clsOpts,ccFilter.cls)}</div>
      <div class="filter-item"><label>课程名称</label>${qfInput('course','课程名称',ccFilter.course,140)}</div>
      <div class="filter-item"><label>任课教师</label>${qfInput('teacher','任课教师',ccFilter.teacher,120)}</div>
      <div class="ledger-filter-actions">
      <button class="btn btn-primary btn-sm" onclick="checkClassQuery()">查询</button>
      <button class="btn btn-ghost btn-sm" onclick="checkClassFilterReset()">重置</button>
      </div>
    </div>
    <div class="toolbar" style="display:flex;gap:10px;align-items:center;flex-wrap:wrap;margin-bottom:12px">
      <span style="flex:1"></span>
      <button class="btn btn-ghost btn-sm" onclick="wrAiRun('checkClass',this)">🤖 AI 分析</button>
      <button class="btn btn-ghost btn-sm" onclick="exportCheckClass()">⬇ 导出</button>
      <button class="btn btn-ghost btn-sm" onclick="chaoxingImportOpen()">导入学习通考勤</button><button class="btn btn-ghost btn-sm" onclick="chaoxingImportHistory()">学习通导入历史</button><button class="btn btn-primary btn-sm" onclick="openCheckClassForm()">＋ 新增查课</button>
    </div>
    <div id="checkClassBody">${checkClassRows()}</div>
  </div>`;
};
function exportCheckClass(){
  const terms=selectedViewTerms("checkClass"),vt=selectedViewTermsText("checkClass");
  const list=checkClassApplyFilter().filter(function(r){return terms.indexOf(r.term||"")>=0;}).sort(function(a,b){return (b.date||"").localeCompare(a.date||"");});
  if(!list.length){ alert("当前学期/筛选条件下暂无查课记录可导出。"); return; }
  const rows=list.map(function(r){ const meta=ccRecordOrgMeta(r);return [r.date||"",r.term||vt,meta.dept||"",meta.grade||"",r.cls||"",r.course||"",r.teacher||"",r.period||"",r.location||"",r.headcount||"",r.attended||"",r.rate||"",r.leave||"",r.late||"",ccBehaviorStudentText(r,"absent",false),ccBehaviorStudentText(r,"personalLeave",false),ccBehaviorStudentText(r,"sickLeave",false),ccBehaviorStudentText(r,"publicLeave",false),ccBehaviorStudentText(r,"late",false),ccBehaviorStudentText(r,"early",false),r.content||"",wrFileNames(r)]; });
  downloadXlsxFile("查课记录",[["日期","学期","学院","年级","班级","课程","任课教师","节次","地点","应到","实到","到课率","请假总人数","迟到人数","旷课名单","事假名单","病假名单","公假名单","迟到名单","早退名单","课堂情况","附件"],...rows],"查课记录_"+selectedViewTermsFileToken("checkClass")+".xlsx");
  showToast("已导出 "+list.length+" 条查课记录","ok");
}
window.exportCheckClass=exportCheckClass;

/* ---- 查寝记录（宿舍级） ---- */
const cdFilter={building:"",room:"",hygiene:""};
const cdPage={page:1,size:20};
function cdGoPage(n){ cdPage.page=Math.max(1,parseInt(n,10)||1); checkDormRender(); }
function cdSetSize(v){ cdPage.size=parseInt(v,10)||20; cdPage.page=1; checkDormRender(); }
let cdPendingFiles=[];
let cdEditFiles=[];
let cdOriginalFiles=[];
function cdFileSelChanged(input){
  const MAX=100*1024*1024;
  for(const f of Array.from(input.files||[])){
    if(f.size>MAX){ alert('附件「'+(f.webkitRelativePath||f.name)+'」超过 100MB，已跳过（单文件上限 100MB）。'); continue; }
    if(f.size===0){ alert('附件「'+(f.webkitRelativePath||f.name)+'」为空文件，已跳过。'); continue; }
    cdPendingFiles.push(f);
  }
  cdRenderFileList();
}
function cdRemovePending(i){ if(cdPendingFiles[i]) cdPendingFiles.splice(i,1); cdRenderFileList(); }
function cdRemoveAtt(i){ if(cdEditFiles[i]) cdEditFiles.splice(i,1); cdRenderFileList(); }
function cdRenderFileList(){
  const box=document.getElementById("cdFileList"); if(!box) return;
  const items=[];
  (cdEditFiles||[]).forEach(function(a,i){ items.push('<div style="display:inline-block;margin:3px 6px 3px 0;padding:4px 8px;background:#eef6f0;border:1px solid #cfe3d4;border-radius:6px;font-size:12.5px">📎 '+escAttr(a.name||"附件")+'（已上传）<span style="cursor:pointer;color:#c0392b;margin-left:6px" onclick="cdRemoveAtt('+i+')">✕</span></div>'); });
  cdPendingFiles.forEach(function(f,i){ const nm=(f.webkitRelativePath||f.name); items.push('<div style="display:inline-block;margin:3px 6px 3px 0;padding:4px 8px;background:#fff8e6;border:1px solid #f5d77f;border-radius:6px;font-size:12.5px">🖼️ '+escAttr(nm)+'（待上传）<span style="cursor:pointer;color:#c0392b;margin-left:6px" onclick="cdRemovePending('+i+')">✕</span></div>'); });
  box.innerHTML=items.join('');
}
function cdReadForm(){
  const o={};
  o.term=document.getElementById("cdTerm").value;
  o.date=(document.getElementById("cdDate").value||"").trim()||fmtNow().slice(0,10);
  o.building=(document.getElementById("cdBuilding").value||"").trim();
  o.room=(document.getElementById("cdRoom").value||"").trim();
  o.hygiene=document.getElementById("cdHygiene").value;
  o.visited=document.getElementById("cdVisited").value;
  o.count=(document.getElementById("cdCount").value||"").trim();
  o.content=(document.getElementById("cdContent").value||"").trim();
  return o;
}
function openCheckDormForm(id){
  const isEdit=!!id;
  const rec=isEdit? checkDormRecords.find(function(x){return x.id===id;}) : null;
  const v=isEdit? (rec||{}) : {};
  cdPendingFiles=[];
  cdEditFiles=(rec&&rec.files&&rec.files.length)?rec.files.slice():[];
  cdOriginalFiles=cdEditFiles.slice();
  const initTerm=v.term||CURRENT_TERM;
  const opt=function(arr,sel){ return arr.map(function(x){ return "<option value='"+attr(x)+"'"+(x===sel?" selected":"")+">"+attr(x)+"</option>"; }).join(""); };
  const body=[
    "<div class='row2'><div class='field'><label>学期</label><select class='in' id='cdTerm'>"+termOptionsHTML(initTerm)+"</select></div>",
    "<div class='field'><label>日期</label><input id='cdDate' type='date' value='"+attr(v.date||fmtNow().slice(0,10))+"'></div></div>",
    "<div class='row2'><div class='field'><label>楼栋</label><input id='cdBuilding' placeholder='如 1栋' value='"+attr(v.building||"")+"'></div>",
    "<div class='field'><label>宿舍号</label><input id='cdRoom' placeholder='如 302' value='"+attr(v.room||"")+"'></div></div>",
    "<div class='row2'><div class='field'><label>卫生情况</label><select class='in' id='cdHygiene'>"+opt(["优","良","中","差"],v.hygiene||"良")+"</select></div>",
    "<div class='field'><label>是否走访</label><select class='in' id='cdVisited'>"+opt(["是","否"],v.visited||"是")+"</select></div></div>",
    "<div class='row2'><div class='field'><label>在寝人数</label><input id='cdCount' type='number' min='0' value='"+attr(v.count||"")+"'></div>",
    "<div class='field'><label>走访情况</label><textarea id='cdContent' class='in' rows='3'>"+attr(v.content||"")+"</textarea></div></div>",
    "<div class='field'><label>附件（支持任意类型文件 / 文件夹，单文件≤100MB）</label><div style='display:flex;gap:8px;flex-wrap:wrap;margin-bottom:6px'><button type='button' class='btn btn-ghost btn-sm' onclick=\"document.getElementById('cdFile').click()\">📁 选择文件</button><button type='button' class='btn btn-ghost btn-sm' onclick=\"document.getElementById('cdFolder').click()\">📂 选择文件夹</button><input type='file' id='cdFile' multiple style='display:none' onchange='cdFileSelChanged(this)'><input type='file' id='cdFolder' webkitdirectory multiple style='display:none' onchange='cdFileSelChanged(this)'></div><div id='cdFileList' style='margin-top:4px'></div></div>"
  ].join("");
  openModal(isEdit?"编辑查寝记录":"新增查寝记录", body, async function(){
    const o=cdReadForm();
    if(!o.building){ alert("请填写楼栋"); return false; }
    if(!o.room){ alert("请填写宿舍号"); return false; }
    const uploaded=[];
    try{
      for(const f of cdPendingFiles){
        const upName=f.webkitRelativePath||f.name;
        const saved=await window.workbench.legacy.attachmentUploadFile(upName,f);
        uploaded.push(Object.assign({},saved,{mime:f.type||"application/octet-stream"}));
      }
    }catch(error){ await Promise.all(uploaded.map(function(a2){ return window.workbench.legacy.attachmentDelete(a2.id).catch(function(){}); })); alert('附件保存失败：'+error.message); return false; }
    o.files=cdEditFiles.concat(uploaded);
    const keptIds=new Set(cdEditFiles.map(function(a){return a&&a.id;}).filter(Boolean));
    const removedFiles=cdOriginalFiles.filter(function(a){return a&&a.id&&!keptIds.has(a.id);});
    const previous=isEdit?JSON.parse(JSON.stringify(rec)):null;
    if(isEdit){ Object.assign(rec,o); }
    else{ o.id=genId("cd"); checkDormRecords.push(o); }
    try{persistCheckDorm();}catch(error){if(isEdit)Object.assign(rec,previous);else checkDormRecords=checkDormRecords.filter(function(x){return x!==o;});await deleteAttachmentRefs(uploaded);alert('记录保存失败：'+error.message);return false;}
    await deleteAttachmentRefs(removedFiles); closeModal(); checkDormRender(); showToast(isEdit?"已更新":"已保存","success");
  });
  cdRenderFileList();
}
function checkDormApplyFilter(){
  const f=cdFilter;
  return checkDormRecords.filter(function(r){
    if(f.building && (r.building||"").indexOf(f.building)<0) return false;
    if(f.room && (r.room||"").indexOf(f.room)<0) return false;
    if(!qfMatch(f.hygiene,r.hygiene||"")) return false;
    return true;
  });
}
function checkDormRows(){
  const terms=selectedViewTerms("checkDorm"),vt=selectedViewTermsText("checkDorm");
  const list=checkDormApplyFilter().filter(function(r){return terms.indexOf(r.term||"")>=0;}).sort(function(a,b){return (b.date||"").localeCompare(a.date||"");});
  const total=list.length;
  const size=cdPage.size||20;
  const pageCount=Math.max(1,Math.ceil(total/size));
  const page=Math.min(Math.max(1,cdPage.page||1),pageCount);
  cdPage.page=page;
  const start=(page-1)*size;
  const pageRows=list.slice(start,start+size);
  const emptyMsg=checkDormRecords.length? ('当前学期 '+esc(vt)+' 下暂无记录（请切换学期或新增）') : '暂无查寝记录，点击「新增查寝」登记';
  const hyBadge=function(v){ const cls=v==="优"?"b-green":(v==="良"?"b-blue":(v==="中"?"b-orange":"b-red")); return badge(esc(v||"—"),cls); };
  const rows=pageRows.length? pageRows.map(function(r){
    return '<tr><td>'+esc(r.date||"—")+'</td><td>'+esc(r.term||"—")+'</td><td>'+esc(r.building||"—")+'</td><td>'+esc(r.room||"—")+'</td><td>'+hyBadge(r.hygiene)+'</td><td>'+esc(r.visited||"—")+'</td><td>'+esc(r.count||"—")+'</td><td style="max-width:240px;white-space:normal">'+esc(r.content||"—")+'</td><td>'+wrFilesHtml(r)+'</td><td><a class="lk" onclick="openCheckDormForm('+jsArg(r.id)+')">编辑</a> <a class="lk danger" onclick="checkDormDel('+jsArg(r.id)+')">删除</a></td></tr>';
  }).join("") : '<tr><td colspan="10" class="empty">'+emptyMsg+'</td></tr>';
  const tbl=table(["日期","学期","楼栋","宿舍号","卫生情况","是否走访","在寝人数","走访情况","附件","操作"],rows);
  return '<div class="list-scroll">'+tbl+'</div>'+renderPager("cd",total,page,size);
}
function checkDormRender(){ const el=document.getElementById("checkDormBody"); if(el) el.innerHTML=checkDormRows(); }
async function checkDormDel(id){ const rec=checkDormRecords.find(function(x){return String(x.id)===String(id);});if(!rec)return;const moved=await recycleMoveRecords("checkDorm","dorm_inspection_record",[rec.id]);if(!moved)return;checkDormRecords=checkDormRecords.filter(function(x){return String(x.id)!==String(id);});checkDormRender(); }
function checkDormReadFilter(){ const bar=document.getElementById("checkDormBar"); if(bar) Object.assign(cdFilter, barFilterGet(bar)); cdPage.page=1; }
function checkDormQuery(){ setQueryReady("checkDorm",true); captureViewTerms("checkDorm"); checkDormReadFilter(); checkDormRender(); }
function checkDormFilterReset(){ const bar=document.getElementById("checkDormBar"); if(bar) barFilterReset(bar); for(const k in cdFilter) cdFilter[k]=""; resetViewTerms("checkDorm"); setQueryReady("checkDorm",false); cdPage.page=1; renderPage("checkDorm"); }
PAGES.checkDorm=function(){
  const hyOpts=[{v:"",l:"全部卫生"},{v:"优",l:"优"},{v:"良",l:"良"},{v:"中",l:"中"},{v:"差",l:"差"}];
  return `
  <h2 class="ptitle">🛏️ 查寝记录 <span class="tag">宿舍走访 · 记录安全卫生与在寝情况</span></h2>
  <div class="card ledger-filter-card">
    ${WR_KPI_STYLE}${checkDormStatsHtml()}
    <div class="qf-bar ledger-filters ledger-filters-4" data-page="checkDorm" id="checkDormBar">
      <div class="filter-item"><label>学期</label>${termPicker('checkDorm')}</div>
      <div class="filter-item"><label>楼栋</label>${qfInput('building','楼栋',cdFilter.building,100)}</div>
      <div class="filter-item"><label>宿舍号</label>${qfInput('room','宿舍号',cdFilter.room,100)}</div>
      <div class="filter-item"><label>卫生情况</label>${qfMulti('hygiene',hyOpts,cdFilter.hygiene)}</div>
      <div class="ledger-filter-actions">
      <button class="btn btn-primary btn-sm" onclick="checkDormQuery()">查询</button>
      <button class="btn btn-ghost btn-sm" onclick="checkDormFilterReset()">重置</button>
      </div>
    </div>
    <div class="toolbar" style="display:flex;gap:10px;align-items:center;flex-wrap:wrap;margin-bottom:12px">
      <span style="flex:1"></span>
      <button class="btn btn-ghost btn-sm" onclick="wrAiRun('checkDorm',this)">🤖 AI 分析</button>
      <button class="btn btn-ghost btn-sm" onclick="exportCheckDorm()">⬇ 导出</button>
      <button class="btn btn-primary btn-sm" onclick="openCheckDormForm()">＋ 新增查寝</button>
    </div>
    <div id="checkDormBody">${checkDormRows()}</div>
  </div>`;
};
function exportCheckDorm(){
  const terms=selectedViewTerms("checkDorm"),vt=selectedViewTermsText("checkDorm");
  const list=checkDormApplyFilter().filter(function(r){return terms.indexOf(r.term||"")>=0;}).sort(function(a,b){return (b.date||"").localeCompare(a.date||"");});
  if(!list.length){ alert("当前学期/筛选条件下暂无查寝记录可导出。"); return; }
  const rows=list.map(r=>[r.date||"",r.term||vt,r.building||"",r.room||"",r.hygiene||"",r.visited||"",r.count||"",r.content||"",wrFileNames(r)]);
  downloadXlsxFile("查寝记录",[["日期","学期","楼栋","宿舍号","卫生情况","是否走访","在寝人数","走访情况","附件"],...rows],"查寝记录_"+selectedViewTermsFileToken("checkDorm")+".xlsx");
  showToast("已导出 "+list.length+" 条查寝记录","ok");
}
window.exportCheckDorm=exportCheckDorm;

