/* ---- 学生画像 · 6 字段筛选（实时驱动：1 个匹配→直接展示；多个→候选列表；0 个→空提示） ----
   v1.42：select 级联——选择学院→专业/年级/班级只显示该学院下；选择专业→年级/班级只显示该专业下；选择年级→班级只显示该年级下 */
function portraitGetOptions(scope){
  const ss = clsStudents();
  const deptSet = new Set(); const majorSet = new Set(); const gradeSet = new Set(); const clsSet = new Set();
  ss.forEach(function(s){
    const depOk = !scope.dept || scope.dept.indexOf(s.dept) !== -1;
    const majOk = !scope.major || scope.major.indexOf(s.major) !== -1;
    const graOk = !scope.grade || scope.grade.indexOf(classGrade(s.cls)) !== -1;
    const clsOk = !scope.cls || scope.cls.indexOf(s.cls) !== -1;
    if(depOk && (scope.major || majOk) && (scope.grade || graOk) && (scope.cls || clsOk)){ if(s.dept) deptSet.add(s.dept); }
    if(depOk && majOk && (scope.grade || graOk) && (scope.cls || clsOk)){ if(s.major) majorSet.add(s.major); }
    if(depOk && majOk && graOk && (scope.cls || clsOk)){ const g = classGrade(s.cls); if(g) gradeSet.add(g); }
    if(depOk && majOk && graOk && clsOk){ if(s.cls) clsSet.add(s.cls); }
  });
  return { dept:[...deptSet].sort(), major:[...majorSet].sort(), grade:[...gradeSet].sort().reverse(), cls:[...clsSet].sort() };
}
function portraitRepaintSelects(keepVals){
  const o = portraitGetOptions(keepVals);
  const map = { dept:"pDept", major:"pMajor", grade:"pGrade", cls:"pCls" };
  Object.keys(map).forEach(function(k){
    const el = document.getElementById(map[k]); if(!el) return;
    const cur = keepVals[k] || "";
    const opts = ['<option value="">请选择</option>'].concat(o[k].map(function(v){ return '<option value="'+v+'">'+v+'</option>'; })).join('');
    el.innerHTML = opts;
    if(o[k].indexOf(cur) >= 0){ el.value = cur; }
    else { el.value = ""; }
  });
}
function portraitFilter(){
  const idKw = ((document.getElementById("pId")||{}).value || "").trim().toLowerCase();
  const nameKw = ((document.getElementById("pName")||{}).value || "").trim().toLowerCase();
  const dept = (document.getElementById("pDept")||{}).value || "";
  const major = (document.getElementById("pMajor")||{}).value || "";
  const grade = (document.getElementById("pGrade")||{}).value || "";
  const cls = (document.getElementById("pCls")||{}).value || "";
  /* 级联：按当前已选值收缩其它三个 select 的可选项，失效值自动清空 */
  portraitRepaintSelects({ dept:dept, major:major, grade:grade, cls:cls });
  const finalDept = (document.getElementById("pDept")||{}).value || "";
  const finalMajor = (document.getElementById("pMajor")||{}).value || "";
  const finalGrade = (document.getElementById("pGrade")||{}).value || "";
  const finalCls = (document.getElementById("pCls")||{}).value || "";
  const list = clsStudents().filter(function(s){
    if(idKw && !(s.id||"").toLowerCase().includes(idKw)) return false;
    if(nameKw && !(s.name||"").toLowerCase().includes(nameKw)) return false;
    if(finalDept && s.dept !== finalDept) return false;
    if(finalMajor && s.major !== finalMajor) return false;
    if(finalGrade && classGrade(s.cls) !== finalGrade) return false;
    if(finalCls && s.cls !== finalCls) return false;
    return true;
  });
  const body = document.getElementById("portraitBody");
  if(!body) return;
  if(!list.length){
    body.innerHTML = '<div class="empty">未找到匹配学生，请调整筛选条件</div>';
    return;
  }
  if(list.length === 1){
    portraitShow(list[0].id);
    return;
  }
  // 多个候选：列出来，点击姓名/操作查看画像
  const rows = list.map(function(s){
    return '<tr><td>'+esc(s.id)+'</td><td><a class="lk" onclick="portraitShow('+jsArg(s.id)+')">'+esc(s.name)+'</a></td><td>'+esc(s.dept||"—")+'</td><td>'+esc(classGrade(s.cls))+'</td><td>'+esc(s.cls)+'</td><td><a class="lk" onclick="portraitShow('+jsArg(s.id)+')">查看画像</a></td></tr>';
  }).join("");
  body.innerHTML = '<div class="tip" style="margin-bottom:10px">共匹配 '+list.length+' 名学生，请点击姓名查看画像</div>'
    + table(["学号","姓名","学院","年级","班级","操作"], rows);
}
