function portraitStudentGrade(s){ return s.grade || (s.cls ? classGrade(s.cls) : ""); }
function portraitFilteredStudents(){
  const f=viewFilter.portrait||{};
  return clsStudents().filter(function(s){
    return (!f.id || (s.id||"").includes(f.id))
      && (!f.name || (s.name||"").includes(f.name))
      && qfMatch(f.dept,s.dept) && qfMatch(f.major,s.major)
      && qfMatch(f.grade,portraitStudentGrade(s)) && qfMatch(f.cls,s.cls)
      && qfMatch(f.status,stuNormalizeStatus(s.status));
  });
}
function portraitResultHTML(){
  if(!queryReady("portrait")) return '<div class="empty">请设置条件后点击「查询」；不设置条件直接查询将显示全部学生。</div>';
  const list=portraitFilteredStudents();
  if(!list.length) return '<div class="empty">未找到符合条件的学生，请调整条件后重新查询。</div>';
  const rows=list.map(function(s){
    return '<tr><td>'+esc(s.id)+'</td><td>'+esc(s.name)+'</td><td>'+esc(s.dept||"—")+'</td><td>'+esc(s.major||"—")+'</td><td>'+esc(portraitStudentGrade(s)||"—")+'</td><td>'+esc(s.cls||"—")+'</td><td>'+badge(esc(stuStatusLabel(s.status)),stuStatusBadge(s.status))+'</td><td><a class="lk" onclick="portraitShow('+jsArg(s.id)+')">查看画像</a></td></tr>';
  }).join("");
  return '<div class="tip" style="margin-bottom:10px">共查询到 '+list.length+' 名学生，请点击“查看画像”查看个人画像。</div>'+table(["学号","姓名","学院","专业","年级","班级","学籍状态","操作"],rows);
}
