function portraitArchiveValue(v){
  if(v===true) return "是";
  if(v===false) return "否";
  if(Array.isArray(v)) return v.length ? v.join("、") : "—";
  return v===undefined || v===null || v==="" ? "—" : String(v);
}
function portraitArchiveGrid(items){
  return '<div class="zf-form">'+items.map(function(item){
    return '<div class="f"><div class="k">'+esc(item[0])+'</div><div class="v"'+(item[0]==="身份证号"?' title="'+escAttr(studentIdentityTooltip(item[1]))+'"':'')+'>'+esc(portraitArchiveValue(item[1]))+'</div></div>';
  }).join("")+'</div>';
}
function portraitArchiveSection(title, body){
  return '<div class="zf-section" style="margin-top:18px">'+title+'</div>'+body;
}
function portraitArchiveTable(headers, rows, emptyText){
  const body=rows.length ? rows.join("") : '<tr><td colspan="'+headers.length+'" class="empty">'+esc(emptyText||"暂无记录")+'</td></tr>';
  return '<div class="list-scroll" style="max-height:280px">'+table(headers,body)+'</div>';
}
let portraitRenderTimer=null;
function portraitShow(id){
  const s=students.find(function(x){return x.id===id;});
  if(!s) return;
  window.__currentArchiveStudent=s;
  openModal("学生全档案 · "+s.name,'<div role="status">正在加载学生档案…</div>',null);
  $("#modal").classList.add("wide","portrait-archive-modal");
  $("#modalFoot").innerHTML='<button class="btn btn-ghost" onclick="downloadStudentArchivePDF()">⬇ 下载学生全档案</button><button class="btn btn-ghost" onclick="portraitRefreshArchive('+jsArg(s.id)+')">刷新档案</button><button class="btn btn-primary" onclick="closeModal()">关闭</button>';
  // 先显示可关闭的弹窗，再汇总档案；关闭或切换弹窗时取消尚未开始的渲染。
  portraitRenderTimer=setTimeout(function(){
    portraitRenderTimer=null;
    try{
      const archive=portraitArchiveHTML(s);
      $("#modalBody").innerHTML=archive;
      if(typeof window.portraitSummaryHTML==="function"){
        try{$("#modalBody").insertAdjacentHTML("afterbegin",window.portraitSummaryHTML(s.id));}
        catch(error){console.error("学生画像研判加载失败",error);$("#modalBody").insertAdjacentHTML("afterbegin",'<div class="tip" role="alert">态势研判暂时无法加载，以下学生档案仍可查看。</div>');}
      }
    }catch(error){
      console.error("学生画像档案加载失败",error);
      $("#modalBody").innerHTML='<div class="tip" role="alert">学生档案加载失败，请检查关联数据后点击“刷新档案”重试。您可以关闭此窗口继续使用其他功能。</div>';
    }
  },0);
}
