function portraitRefreshArchive(id){ portraitShow(id); }
function portraitArchiveSafeName(value){
  return String(value||"").replace(/[\\/*?:"<>|\x00-\x1f]/g,"_").replace(/[. ]+$/,"_").slice(0,120)||"未命名";
}
function portraitArchiveExportElement(s){
  const host=document.createElement("div");
  host.setAttribute("aria-hidden","true");
  host.style.cssText="position:fixed;left:-10000px;top:0;width:277mm;box-sizing:border-box;background:#fff;color:#111;z-index:-1;pointer-events:none;";
  const content=document.createElement("article");
  content.className="portrait-archive-export";
  content.style.cssText="width:277mm;box-sizing:border-box;background:#fff;color:#111;padding:0;font-family:'Microsoft YaHei','PingFang SC',Arial,sans-serif;font-size:11px;line-height:1.45;";
  content.innerHTML='<div style="display:flex;justify-content:space-between;align-items:flex-end;margin:0 0 5mm;padding-bottom:3mm;border-bottom:2px solid #167657"><div><div style="font-size:21px;font-weight:800">学生全档案</div><div style="margin-top:1mm;color:#52645d">'+esc((s.id||"—")+" · "+(s.name||"—"))+'</div></div><div style="color:#687871;font-size:10px">生成时间：'+esc(fmtNow())+'</div></div>'+portraitArchiveHTML(s);
  content.querySelectorAll("button,script").forEach(function(node){ node.remove(); });
  content.querySelectorAll("[onclick]").forEach(function(node){ node.removeAttribute("onclick"); });
  content.querySelectorAll(".list-scroll").forEach(function(box){
    box.style.cssText="max-height:none!important;height:auto!important;overflow:visible!important;margin:2mm 0 4mm;break-inside:auto;page-break-inside:auto;";
  });
  content.querySelectorAll("table").forEach(function(tbl){
    tbl.style.cssText="width:100%!important;min-width:0!important;max-width:100%!important;table-layout:fixed;border-collapse:collapse;font-size:9px;";
  });
  content.querySelectorAll("th,td").forEach(function(cell){
    cell.style.cssText="min-width:0!important;max-width:none!important;white-space:normal!important;overflow-wrap:anywhere;word-break:break-word;padding:1.4mm 1mm!important;vertical-align:top;";
  });
  content.querySelectorAll("tr").forEach(function(row){ row.style.breakInside="avoid"; row.style.pageBreakInside="avoid"; });
  content.querySelectorAll(".zf-section").forEach(function(section){ section.style.breakAfter="avoid"; section.style.pageBreakAfter="avoid"; });
  content.querySelectorAll(".zf-form .f").forEach(function(field){ field.style.breakInside="avoid"; field.style.pageBreakInside="avoid"; });
  content.querySelectorAll("img").forEach(function(img){ img.style.maxWidth="96px"; img.style.maxHeight="96px"; });
  host.appendChild(content);
  document.body.appendChild(host);
  return {host:host,content:content};
}
async function portraitArchiveWaitForAssets(content){
  if(typeof window.academicPublicLoadArchive==="function")await window.academicPublicLoadArchive(content);
  if(document.fonts&&document.fonts.ready){ try{ await document.fonts.ready; }catch(_e){} }
  const images=Array.prototype.slice.call(content.querySelectorAll("img"));
  await Promise.all(images.map(function(img){
    if(img.complete) return Promise.resolve();
    return new Promise(function(resolve){
      const done=function(){ resolve(); };
      img.addEventListener("load",done,{once:true}); img.addEventListener("error",done,{once:true});
      setTimeout(done,3000);
    });
  }));
}
async function portraitArchivePdfBlob(s){
  if(typeof html2pdf!=="function") throw new Error("PDF 组件未加载，请刷新页面后重试");
  const rendered=portraitArchiveExportElement(s);
  try{
    await portraitArchiveWaitForAssets(rendered.content);
    const blob=await html2pdf().set({
      margin:[10,10,10,10],
      image:{type:"jpeg",quality:0.96},
      html2canvas:{scale:1.5,useCORS:true,allowTaint:false,backgroundColor:"#ffffff",logging:false,scrollX:0,scrollY:0},
      jsPDF:{unit:"mm",format:"a4",orientation:"landscape",compress:true},
      pagebreak:{mode:["css","legacy"],avoid:["tr",".zf-form .f"]}
    }).from(rendered.content).outputPdf("blob");
    if(!(blob instanceof Blob)||blob.size<1000) throw new Error("生成的 PDF 内容为空或不完整");
    const signature=await blob.slice(0,5).text();
    if(signature!=="%PDF-") throw new Error("生成结果不是有效的 PDF 文件");
    return blob.type==="application/pdf"?blob:new Blob([blob],{type:"application/pdf"});
  }finally{
    if(rendered.host&&rendered.host.parentNode) rendered.host.remove();
  }
}
function portraitArchiveDownloadBlob(blob,filename){
  const url=URL.createObjectURL(blob);
  const a=document.createElement("a");
  a.href=url; a.download=filename; a.style.display="none";
  document.body.appendChild(a); a.click(); a.remove();
  // Edge 需要在下载任务读取 Blob 后再释放地址；立即 revoke 可能得到空文件。
  setTimeout(function(){ URL.revokeObjectURL(url); },30000);
}
async function downloadStudentArchivePDF(){
  const s=window.__currentArchiveStudent;
  if(!s){ showToast("未找到当前学生档案","error"); return; }
  const btn=document.querySelector('button[onclick="downloadStudentArchivePDF()"]');
  if(btn){ btn.disabled=true; btn.textContent="生成 PDF…"; }
  showToast("正在生成完整档案，请稍候…","info");
  try{
    const blob=await portraitArchivePdfBlob(s);
    portraitArchiveDownloadBlob(blob,portraitArchiveSafeName((s.id||"unknown")+" "+(s.name||""))+".pdf");
    showToast("学生全档案已生成","success");
  }catch(err){
    console.error("学生全档案PDF生成失败",err);
    showToast("PDF 生成失败："+(err&&err.message?err.message:String(err)),"error");
  }finally{
    if(btn){ btn.disabled=false; btn.textContent="⬇ 下载学生全档案"; }
  }
}
async function portraitArchiveZipBlob(list,onProgress){
  if(typeof JSZip==="undefined") throw new Error("打包组件未加载，请刷新页面重试");
  const zip=new JSZip();
  let completed=0,failed=0;
  for(let idx=0;idx<list.length;idx++){
    const s=list[idx];
    try{
      const pdf=await portraitArchivePdfBlob(s);
      zip.folder(portraitArchiveSafeName(s.cls||"未分班级")).file(portraitArchiveSafeName((s.id||"unknown")+" "+(s.name||""))+".pdf",pdf,{binary:true});
      completed++;
    }catch(error){
      failed++;
      console.error("学生档案PDF生成失败",s.id,s.name,error);
    }
    if(typeof onProgress==="function") onProgress({phase:"pdf",current:idx+1,total:list.length,completed:completed,failed:failed});
    if((idx+1)%2===0) await new Promise(function(resolve){ setTimeout(resolve,20); });
  }
  if(!completed) throw new Error("没有成功生成任何学生档案");
  if(typeof onProgress==="function") onProgress({phase:"zip",current:list.length,total:list.length,completed:completed,failed:failed});
  const blob=await zip.generateAsync({type:"blob",mimeType:"application/zip",compression:"DEFLATE",compressionOptions:{level:6}});
  if(!(blob instanceof Blob)||blob.size<100) throw new Error("生成的压缩包为空或不完整");
  return {blob:blob,completed:completed,failed:failed};
}
async function batchDownloadStudentArchives(){
  if(!queryReady("portrait")){ showToast("请先点击「查询」获取学生列表","error"); return; }
  const list=portraitFilteredStudents();
  if(!list.length){ showToast("当前查询结果为空，无法下载","error"); return; }
  if(list.length>50&&!confirm("当前共 "+list.length+" 名学生，批量生成 PDF 会比较慢，是否继续？")) return;
  const btn=document.getElementById("batchDownloadArchivesBtn");
  if(btn){ btn.disabled=true; btn.textContent="准备生成 0/"+list.length; }
  showToast("开始生成学生档案压缩包，请稍候…","info");
  try{
    const result=await portraitArchiveZipBlob(list,function(progress){
      if(!btn) return;
      btn.textContent=progress.phase==="zip"?"正在打包…":"生成档案… "+progress.current+"/"+progress.total;
    });
    portraitArchiveDownloadBlob(result.blob,"学生全档案.zip");
    showToast("压缩包已生成（成功 "+result.completed+"，失败 "+result.failed+"）",result.failed?"warning":"success");
  }catch(error){
    console.error("学生全档案压缩包生成失败",error);
    showToast("压缩包生成失败："+(error&&error.message?error.message:String(error)),"error");
  }finally{
    if(btn){ btn.disabled=false; btn.textContent="⬇ 下载学生全档案"; }
  }
}
function portraitZoomPhoto(src){
  if(!src) return;
  var ov=document.createElement('div');
  ov.style.cssText='position:fixed;inset:0;z-index:10000;background:rgba(0,0,0,.82);display:flex;align-items:center;justify-content:center;cursor:zoom-out;opacity:0;transition:opacity .2s';
  var img=document.createElement('img');
  img.src=src;
  img.style.cssText='max-width:88vw;max-height:86vh;border-radius:8px;box-shadow:0 8px 40px rgba(0,0,0,.5);object-fit:contain';
  img.onclick=function(e){ e.stopPropagation(); };
  ov.appendChild(img);
  var hint=document.createElement('div');
  hint.textContent='点击任意处关闭';
  hint.style.cssText='position:absolute;bottom:24px;left:50%;transform:translateX(-50%);color:rgba(255,255,255,.6);font-size:13px;pointer-events:none';
  ov.appendChild(hint);
  ov.onclick=function(){ ov.style.opacity='0'; setTimeout(function(){ if(ov.parentNode) ov.parentNode.removeChild(ov); },200); };
  document.body.appendChild(ov);
  if(window.requestAnimationFrame){ requestAnimationFrame(function(){ ov.style.opacity='1'; }); }
  else { ov.style.opacity='1'; }
}
/* ============ 交互 ============ */
function handleDisabCert(input){
  const file=input.files[0]; if(!file) return;
  if(file.type!=="application/pdf" && !file.name.toLowerCase().endsWith(".pdf")){ alert("仅支持 PDF 格式"); input.value=""; return; }
  const fr=new FileReader();
  fr.onload=e=>{ $("#fDisabCert").value=e.target.result; $("#fDisabCertName").textContent="已选择："+file.name; alert("PDF 已读取，保存后生效"); };
  fr.readAsDataURL(file);
}
function handleStatusAttachment(input){
  const file=input.files[0]; if(!file) return;
  const isImg=/^image\//.test(file.type||"") || /\.(jpg|jpeg|png|gif|webp|bmp)$/i.test(file.name);
  if(!isImg){ alert("学籍异动单仅支持图片格式（jpg、jpeg、png、gif、webp、bmp）"); input.value=""; return; }
  window.workbench.legacy.attachmentUploadFile(file.name,file).then(function(saved){
    const att={id:saved.id,name:saved.name,fileName:saved.name,mime:file.type||"image/jpeg",size:saved.size,url:saved.url};
    $("#fStatusAttachment").value=JSON.stringify(att);
    const previewUrl=att.url||(att.id?"/attachments/"+att.id:"")
    $("#fStatusAttachmentName").innerHTML='已上传：<a href="'+attr(previewUrl)+'" target="_blank" rel="noopener" style="color:#2f6fed">'+esc(att.name)+'</a> <a class="lk danger" style="margin-left:8px" onclick="clearStatusAttachment();return false">清除</a>';
  }).catch(function(e){ alert('上传失败：'+e.message); input.value=""; });
}
function clearStatusAttachment(){
  $("#fStatusAttachment").value="";
  const f=$("#fStatusAttachmentFile"); if(f) f.value="";
  $("#fStatusAttachmentName").textContent="未选择文件（仅支持图片格式）";
}
/* === 浮层无障碍：焦点保存/移入/陷阱/归还 + Esc 关闭（WCAG 2.1.2 / 2.4.3） === */
let _overlayLastFocused = null;
let _overlayKeydownHandler = null;
function _overlayOpenFocus(rootEl){
  _overlayLastFocused = document.activeElement;
  setTimeout(function(){ if(!rootEl) return; const f = rootEl.querySelector('input,select,textarea,button,a[href],.lk,[tabindex]:not([tabindex="-1"])'); (f || rootEl).focus(); }, 0);
  if(!_overlayKeydownHandler){ _overlayKeydownHandler = _overlayTrap; document.addEventListener('keydown', _overlayKeydownHandler, true); }
}
function _overlayCloseFocus(){
  if(_overlayKeydownHandler){ document.removeEventListener('keydown', _overlayKeydownHandler, true); _overlayKeydownHandler = null; }
  if(_overlayLastFocused && typeof _overlayLastFocused.focus === 'function'){ try{ _overlayLastFocused.focus(); }catch(_){ } }
  _overlayLastFocused = null;
}
function _overlayTrap(e){
  const m = document.getElementById('modal'), d = document.getElementById('drawer');
  const modalOpen = m && m.classList.contains('show');
  const drawerOpen = d && d.classList.contains('show');
  if(e.key === 'Escape'){
    const popup=(modalOpen?m:drawerOpen?d:document).querySelector('.qf-multi.open,.qf-single.open,.sf-native-select.open');
    if(popup){
      e.preventDefault();e.stopPropagation();popup.classList.remove('open');
      const trigger=popup.querySelector('.qf-multi-trigger,.qf-single-trigger,.sf-native-trigger');
      if(trigger){trigger.setAttribute('aria-expanded','false');trigger.focus();}
      return;
    }
    if(modalOpen){e.preventDefault();e.stopPropagation();closeModal(true);return;}
    if(drawerOpen){ e.preventDefault(); e.stopPropagation(); showDrawer(false); return; }
    return;
  }
  if(e.key === 'Tab'){
    const root = modalOpen ? m : (drawerOpen ? d : null);
    if(!root) return;
    const f = root.querySelectorAll('a[href],button:not([disabled]),input:not([disabled]),select:not([disabled]),textarea:not([disabled]),[tabindex]:not([tabindex="-1"])');
    if(!f.length){ e.preventDefault(); return; }
    const first = f[0], last = f[f.length-1];
    if(e.shiftKey && document.activeElement === first){ e.preventDefault(); last.focus(); }
    else if(!e.shiftKey && document.activeElement === last){ e.preventDefault(); first.focus(); }
  }
}
function showDrawer(v){
  $("#mask").classList.toggle("show", v);
  $("#drawer").classList.toggle("show", v);
  if(v){ _overlayOpenFocus($("#drawer")); } else { _overlayCloseFocus(); }
}
function showToast(msg, type){
  if(window.WorkbenchUI&&WorkbenchUI.deferToast(msg,type))return;
  try{
    let host = document.getElementById('toastHost');
    if(!host){ host = document.createElement('div'); host.id='toastHost'; host.style.cssText='position:fixed;right:18px;bottom:18px;z-index:9999;display:flex;flex-direction:column;gap:8px'; document.body.appendChild(host); }
    const t = document.createElement('div');
    const isErr = type==='error';
    t.setAttribute('role', isErr ? 'alert' : 'status');
    t.setAttribute('aria-live', isErr ? 'assertive' : 'polite');
    const bg = type==='success' ? '#2e9e5b' : (isErr ? '#d6453d' : '#1e5494');
    t.style.cssText = 'background:'+bg+';color:#fff;padding:9px 14px;border-radius:8px;font-size:13px;'+'box-shadow:0 4px 14px rgba(0,0,0,.18);opacity:0;transition:opacity .2s;max-width:320px';
    t.textContent = msg;
    host.appendChild(t);
    if(window.WorkbenchProgress)WorkbenchProgress.syncToastOffset();
    if(window.requestAnimationFrame){ requestAnimationFrame(function(){ t.style.opacity='1'; }); }
    else { t.style.opacity='1'; }
    setTimeout(function(){ t.style.opacity='0'; setTimeout(function(){ if(t.parentNode)t.parentNode.removeChild(t);if(window.WorkbenchProgress)WorkbenchProgress.syncToastOffset(); }, 260); }, 2200);
  }catch(_){}
}

