// Tab 委托
document.addEventListener("click",e=>{
  const tab=e.target.closest(".tab");
  if(tab){
    const grp=tab.parentElement;
    if(!grp) return;
    grp.querySelectorAll(".tab").forEach(t=>t.classList.remove("active"));
    tab.classList.add("active");
    const panes=grp.nextElementSibling&&grp.nextElementSibling.parentElement?grp.parentElement.querySelectorAll(".pane"):[];
    // 处理抽屉内与卡片内两种结构
    const container=grp.closest(".drawer-body")||grp.closest(".card")||grp.parentElement;
    if(!container) return;
    container.querySelectorAll(".pane").forEach(p=>p.classList.remove("active"));
    const tid=tab.dataset.t||tab.dataset.ev;
    const pane=container.querySelector("#"+tid);
    if(pane) pane.classList.add("active");
    /* v1.46 按当前所在页分发 Tab 选择：maint 页 d1/d2/d3/d4 → maintTab（dorm 页已无子标签，移除旧 dormTab 分发） */
    if(currentView==="maint"){
      if(tid==="d1") window.maintTab="d1";
      else if(tid==="d2") window.maintTab="d2";
      else if(tid==="d3") window.maintTab="d3";
      else if(tid==="d4") window.maintTab="d4";
      else if(tid==="d5") window.maintTab="d5";
      else if(tid==="d6") window.maintTab="d6";
    }
  }
});
