/* === 列表操作链接 .lk 集中式键盘可达（WCAG 2.1.1 / 4.1.2）=== */
function applyLinkA11y(root){
  if(!root || !root.querySelectorAll) return;
  const as = root.querySelectorAll('a:not([href])');
  for(let i=0;i<as.length;i++){
    const a = as[i];
    if(a.getAttribute('role') === 'button') continue;
    if(a.hasAttribute('onclick') || a.onclick){
      a.setAttribute('role','button');
      if(!a.hasAttribute('tabindex')) a.tabIndex = 0;
    }
  }
}
(function(){
  const c = document.getElementById('content');
  if(c) applyLinkA11y(c);
  ['content','modalBody','drawerBody','modalFoot'].forEach(function(id){
    const el = document.getElementById(id);
    if(el) new MutationObserver(function(){ applyLinkA11y(el); }).observe(el, { childList:true, subtree:true });
  });
  document.addEventListener('keydown', function(e){
    const t = e.target;
    if(t && t.tagName === 'A' && t.getAttribute('role') === 'button' && (e.key === 'Enter' || e.key === ' ')){
      e.preventDefault(); t.click();
    }
  });
})();
