/* 【v1.6】学业情况启动清理：移除所有 _rid 前缀为 seed_/seed_r_/seed_w_ 的学期行；学期内剩余行全部为 seed 时整学期移除；空 key 直接 removeItem —— 保证管理端进入「学业情况」为空模板，仅保留真实录入 */
try{
  ["nnuzc_academic_terms","nnuzc_academic_warnings"].forEach(function(key){
    const raw = localStorage.getItem(key);
    if(!raw) return;
    const a = JSON.parse(raw);
    if(!Array.isArray(a)) { localStorage.removeItem(key); return; }
    const cleaned = a.filter(function(t){
      const origRows = t.rows || [];
      if(origRows.length === 0) return true; /* 本就无数据的空学期，保留（用户手动添加的） */
      return origRows.some(function(r){ return !r || !r._rid || (typeof r._rid==="string" && r._rid.indexOf("seed_")!==0); });
    }).map(function(t){
      const rows = (t.rows||[]).filter(function(r){ return !r || !r._rid || (typeof r._rid==="string" && r._rid.indexOf("seed_")!==0); });
      return Object.assign({}, t, { rows: rows });
    });
    if(cleaned.length===0) localStorage.removeItem(key);
    else if(JSON.stringify(cleaned)!==raw) localStorage.setItem(key, JSON.stringify(cleaned));
  });
}catch(e){}
