/* ============ 品牌设置：侧栏与登录页使用独立 Logo ============ */
function brandingLogoPreviewUrl(target){const side=target==="sidebar",action=side?BRANDING_SIDEBAR_LOGO_ACTION:BRANDING_LOGIN_LOGO_ACTION,pending=side?BRANDING_PENDING_SIDEBAR_LOGO_DATA:BRANDING_PENDING_LOGIN_LOGO_DATA,defaultUrl=side?"/assets/login-logo-icon.png":"/assets/login-logo.png",saved=side?WORKBENCH_BRANDING.sidebarLogoUrl:WORKBENCH_BRANDING.loginLogoUrl;return action==="replace"?pending:(action==="clear"?defaultUrl:saved);}
function brandingLogoState(target){const side=target==="sidebar",action=side?BRANDING_SIDEBAR_LOGO_ACTION:BRANDING_LOGIN_LOGO_ACTION,hasCustom=side?WORKBENCH_BRANDING.hasCustomSidebarLogo:WORKBENCH_BRANDING.hasCustomLoginLogo;return action==="replace"?"已选择新 Logo，保存后生效":(action==="clear"?"将恢复默认 Logo，保存后生效":(hasCustom?"当前使用自定义 Logo":"当前使用默认 Logo"));}
function brandingSettingsRefresh(){
  const name=document.getElementById("brandingName");if(name)name.value=workbenchBrandName();
  ["sidebar","login"].forEach(function(target){const preview=document.getElementById("branding"+(target==="sidebar"?"Sidebar":"Login")+"Preview"),state=document.getElementById("branding"+(target==="sidebar"?"Sidebar":"Login")+"State");if(preview)preview.src=brandingLogoPreviewUrl(target);if(state)state.textContent=brandingLogoState(target);});
}
window.brandingLogoChanged=function(input,target){
  const file=input&&input.files&&input.files[0];if(!file)return;
  if(!/^image\/(png|jpeg|webp)$/i.test(file.type||"")){showToast("Logo 仅支持 PNG、JPG 或 WebP 图片","error");input.value="";return;}
  if(file.size>2*1024*1024){showToast("Logo 不能超过 2MB","error");input.value="";return;}
  const reader=new FileReader();reader.onerror=function(){showToast("读取 Logo 失败，请重新选择图片","error");};reader.onload=function(){if(target==="sidebar"){BRANDING_PENDING_SIDEBAR_LOGO_DATA=String(reader.result||"");BRANDING_SIDEBAR_LOGO_ACTION="replace";}else{BRANDING_PENDING_LOGIN_LOGO_DATA=String(reader.result||"");BRANDING_LOGIN_LOGO_ACTION="replace";}brandingSettingsRefresh();};reader.readAsDataURL(file);
};
window.brandingRestoreDefault=function(target){if(target==="sidebar"){BRANDING_PENDING_SIDEBAR_LOGO_DATA="";BRANDING_SIDEBAR_LOGO_ACTION="clear";}else{BRANDING_PENDING_LOGIN_LOGO_DATA="";BRANDING_LOGIN_LOGO_ACTION="clear";}brandingSettingsRefresh();};
window.brandingSave=async function(){
  const input=document.getElementById("brandingName"),name=String(input&&input.value||"").trim();
  if(!name||name.length>40){showToast("工作台名称需为 1 到 40 个字符","error");return;}
  const payload={name:name};if(BRANDING_SIDEBAR_LOGO_ACTION==="replace")payload.sidebarLogoData=BRANDING_PENDING_SIDEBAR_LOGO_DATA;if(BRANDING_SIDEBAR_LOGO_ACTION==="clear")payload.clearSidebarLogo=true;if(BRANDING_LOGIN_LOGO_ACTION==="replace")payload.loginLogoData=BRANDING_PENDING_LOGIN_LOGO_DATA;if(BRANDING_LOGIN_LOGO_ACTION==="clear")payload.clearLoginLogo=true;
  const button=document.getElementById("brandingSaveBtn");if(button)button.disabled=true;
  try{
    const response=await fetch("/api/branding",{method:"PUT",headers:{"Content-Type":"application/json","X-Workbench-Token":TOKEN},body:JSON.stringify(payload)});
    const result=await response.json().catch(function(){return {};});if(!response.ok)throw new Error(result.error||"保存失败");
    BRANDING_SIDEBAR_LOGO_ACTION="keep";BRANDING_LOGIN_LOGO_ACTION="keep";BRANDING_PENDING_SIDEBAR_LOGO_DATA="";BRANDING_PENDING_LOGIN_LOGO_DATA="";applyWorkbenchBranding(result);renderPage("brandSettings");showToast("两处品牌设置已保存，授权状态不受影响","success");
  }catch(error){showToast("保存失败："+(error.message||error),"error");}
  finally{if(button)button.disabled=false;}
};
