window.navVisibilityChanged=async function(input){
  const view=String(input&&input.dataset&&input.dataset.navCustomView||"").trim();
  if(!view)return;
  if(NAV_VISIBILITY_REQUIRED.has(view)){input.checked=true;return;}
  if(input.checked)navHiddenViews.delete(view);else navHiddenViews.add(view);
  renderNav();updateNavVisibilitySummary();
  const saved=await saveNavVisibility();
  if(saved===false)showToast("导航设置已在当前页面生效，但写入本地数据库失败","error");
};
window.navVisibilityReset=async function(){
  navHiddenViews.clear();
  document.querySelectorAll("[data-nav-custom-view]").forEach(function(input){input.checked=true;});
  renderNav();updateNavVisibilitySummary();
  const saved=await saveNavVisibility();
  showToast(saved===false?"导航设置已恢复，但写入本地数据库失败":"已恢复显示全部二级菜单",saved===false?"error":"ok");
};

