let employmentResourceRecords=[];
const employmentResourceFilter={kw:"",region:"",industry:""};
function employmentResourceLoad(){
  try{
    const raw=localStorage.getItem("nnuzc_employment_resources");
    if(raw==null){employmentResourceRecords=EMPLOYMENT_RESOURCE_DEFAULTS.map(function(x){return Object.assign({},x);});employmentResourcePersist();return;}
    const a=JSON.parse(raw);employmentResourceRecords=Array.isArray(a)?a:[];
  }catch(e){employmentResourceRecords=[];reportDataError("就业资源加载",e);}
}
function employmentResourcePersist(){localStorage.setItem("nnuzc_employment_resources",JSON.stringify(employmentResourceRecords));}
function employmentResourceFind(id){return employmentResourceRecords.find(function(r){return r.id===id;});}
function employmentResourceValidUrl(value){try{const u=new URL(String(value||"").trim());return u.protocol==="http:"||u.protocol==="https:";}catch(e){return false;}}
function employmentResourceFieldInput(field,record){
  const value=record?record[field.key]||"":"",id="erf_"+field.key,required=field.required?' <span class="req">*</span>':'';
  if(field.key==="status")return '<div class="field"><label>'+field.label+'</label><select id="'+id+'">'+["待核验","有效","失效"].map(function(x){return '<option value="'+x+'"'+((value||"待核验")===x?' selected':'')+'>'+x+'</option>';}).join('')+'</select></div>';
  if(field.key==="verifiedAt")return '<div class="field"><label>'+field.label+'</label><input id="'+id+'" type="date" value="'+attr(value)+'"></div>';
  if(field.key==="note")return '<div class="field" style="grid-column:span 2"><label>'+field.label+'</label><textarea id="'+id+'" rows="3">'+esc(value)+'</textarea></div>';
  return '<div class="field"><label>'+field.label+required+'</label><input id="'+id+'" value="'+attr(value)+'"'+(field.key==="url"?' placeholder="https://"':'')+'></div>';
}
function employmentResourceOpenForm(id){
  const record=id?employmentResourceFind(id):null;if(id&&!record)return;
  const body='<div class="tip" style="margin-bottom:12px">官方网址仅允许 http/https 链接；新增或修改后默认为待核验，可在确认官网可访问后标记为有效。</div><div style="display:grid;grid-template-columns:1fr 1fr;gap:10px 14px">'+EMPLOYMENT_RESOURCE_FIELDS.map(function(f){return employmentResourceFieldInput(f,record);}).join('')+'</div>';
  openModal(id?'编辑就业资源':'新增就业资源',body,function(){
    const row={};for(let i=0;i<EMPLOYMENT_RESOURCE_FIELDS.length;i++){const f=EMPLOYMENT_RESOURCE_FIELDS[i],el=document.getElementById("erf_"+f.key),v=(el?el.value:"").trim();if(f.required&&!v){showToast('请填写“'+f.label+'”','error');return false;}row[f.key]=v;}
    if(!employmentResourceValidUrl(row.url)){showToast("官方网址必须是有效的 http/https 地址","error");return false;}
    const duplicate=employmentResourceRecords.find(function(x){return x.id!==id&&String(x.url||"").toLowerCase()===row.url.toLowerCase();});if(duplicate){showToast("该官方网址已存在","error");return false;}
    if(record)Object.assign(record,row,{updatedAt:fmtNow()});else employmentResourceRecords.unshift(Object.assign({id:genId("er"),createdAt:fmtNow()},row));
    employmentResourcePersist();renderPage("employment");showToast(id?'就业资源已更新':'就业资源已新增','success');return true;
  });
}
async function employmentResourceDelete(id){const r=employmentResourceFind(id);if(!r)return;const moved=await recycleMoveRecords("employmentResource","employment_resource",[id]);if(!moved)return;renderPage("employment");showToast("就业资源已移入回收站","success");}
function employmentResourceMarkVerified(id){const r=employmentResourceFind(id);if(!r)return;if(!confirm('确认已打开并核对“'+r.title+'”的官方网址可正常使用吗？'))return;r.status="有效";r.verifiedAt=isoToday();r.updatedAt=fmtNow();employmentResourcePersist();renderPage("employment");showToast("已标记为有效并更新核验日期","success");}
function employmentResourceFiltered(){const kw=employmentResourceFilter.kw.toLowerCase();return employmentResourceRecords.filter(function(r){return (!kw||[r.title,r.organizer,r.url,r.note].some(function(v){return String(v||"").toLowerCase().indexOf(kw)>=0;}))&&(!employmentResourceFilter.region||r.region===employmentResourceFilter.region)&&(!employmentResourceFilter.industry||r.industry===employmentResourceFilter.industry);});}
function employmentResourceSetFilter(key,value){employmentResourceFilter[key]=String(value||"").trim();const host=document.getElementById("employmentResourceContent");if(host)host.innerHTML=employmentResourceContentHtml();}
function employmentResourceContentHtml(){
  const list=employmentResourceFiltered(),valid=employmentResourceRecords.filter(function(r){return r.status==="有效";}).length,pending=employmentResourceRecords.filter(function(r){return r.status==="待核验";}).length,regions=new Set(employmentResourceRecords.map(function(r){return r.region;}).filter(Boolean)).size;
  const stats=[["资源总数",employmentResourceRecords.length],["当前显示",list.length],["覆盖地域",regions],["已核验有效",valid],["待核验",pending]];
  const cards=list.length?list.map(function(r){const cls=r.status==="有效"?"b-green":r.status==="失效"?"b-red":"b-gray",safeUrl=employmentResourceValidUrl(r.url)?r.url:"#";return '<article class="card" style="margin:0;padding:16px;display:flex;flex-direction:column;gap:10px;min-height:210px"><div style="display:flex;justify-content:space-between;align-items:center"><span style="font-size:21px">🔗</span><span class="badge '+cls+'">'+esc(r.status||'待核验')+'</span></div><div style="font-size:17px;font-weight:750">'+esc(r.title||'未命名资源')+'</div><div style="color:var(--muted);font-size:13px">'+esc(r.organizer||'未记录主办单位')+' · '+esc(r.industry||'综合')+'</div><div style="display:flex;gap:8px;flex-wrap:wrap;font-size:12.5px"><span class="tag">'+esc(r.region||'全国')+'</span><span class="tag">核验 '+esc(r.verifiedAt||'未记录')+'</span></div><div style="margin-top:auto;display:flex;gap:7px;flex-wrap:wrap"><a class="btn btn-primary btn-sm" href="'+attr(safeUrl)+'" target="_blank" rel="noopener noreferrer">打开官网</a><button class="btn btn-ghost btn-sm" onclick="employmentResourceOpenForm('+jsArg(r.id)+')">编辑</button>'+(r.status!=="有效"?'<button class="btn btn-ghost btn-sm" onclick="employmentResourceMarkVerified('+jsArg(r.id)+')">标记已核验</button>':'')+'<button class="btn btn-ghost btn-sm" style="color:#c43d36" onclick="employmentResourceDelete('+jsArg(r.id)+')">删除</button></div></article>';}).join(''):'<div class="empty" style="grid-column:1/-1">暂无匹配的就业资源</div>';
  return '<div style="display:grid;grid-template-columns:repeat(5,minmax(120px,1fr));gap:10px;margin-bottom:14px">'+stats.map(function(x){return '<div class="card" style="margin:0;padding:14px"><div style="color:var(--muted);font-size:12.5px">'+x[0]+'</div><div style="font-size:23px;font-weight:750;margin-top:5px">'+x[1]+'</div></div>';}).join('')+'</div><div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(260px,1fr));gap:12px">'+cards+'</div>';
}
function employmentResourceExport(){if(!employmentResourceRecords.length){alert("暂无就业资源可导出。");return;}const data=[EMPLOYMENT_RESOURCE_FIELDS.map(function(f){return f.header;})].concat(employmentResourceRecords.map(function(r){return EMPLOYMENT_RESOURCE_FIELDS.map(function(f){return r[f.key]||"";});}));downloadXlsxFile("就业资源",data,"就业资源_"+xcmStamp()+".xlsx");showToast("已导出 "+employmentResourceRecords.length+" 条就业资源","success");}
function employmentResourceDownloadTemplate(){downloadXlsxFile("就业资源导入模板",[EMPLOYMENT_RESOURCE_FIELDS.map(function(f){return f.header;}),["国家大学生就业服务平台","全国","综合就业服务","教育部","https://www.ncss.cn/","","待核验",""]],"就业资源导入模板.xlsx");}
function employmentResourceImport(){
  const body='<div class="tip" style="margin-bottom:12px">支持 .xlsx/.csv；以官方网址为唯一键。导入链接必须使用 http/https，状态可填写“有效、待核验、失效”。</div><input type="file" id="erImportFile" accept=".xlsx,.csv"><div style="margin-top:14px"><label><input type="radio" name="erMode" value="merge" checked> 新增并更新（推荐）</label>　<label><input type="radio" name="erMode" value="append"> 仅新增</label>　<label><input type="radio" name="erMode" value="replace"> 仅更新已有资源</label></div>';
  openModal("导入就业资源",body,async function(){const file=(document.getElementById("erImportFile").files||[])[0];if(!file){showToast("请选择导入文件","error");return false;}const hints=[];EMPLOYMENT_RESOURCE_FIELDS.forEach(function(field){hints.push(field.header,field.label,field.key);});const rows=await parseWorkbookToRows(file,hints);const smartMatch=await importConfirmApproximateMatches("就业资源",rows);if(!smartMatch.confirmed)return false;const enumErrors=importEnumRows("就业资源",rows);if(enumErrors.length){showToast("导入失败：第 "+enumErrors[0].row+" 行，"+enumErrors[0].msg,"error");return false;}const mode=(document.querySelector('input[name="erMode"]:checked')||{}).value||"merge";let added=0,updated=0,skipped=0;rows.forEach(function(raw){const row={};EMPLOYMENT_RESOURCE_FIELDS.forEach(function(f){row[f.key]=smartCell(raw,[f.header,f.label]);});if(!row.title||!employmentResourceValidUrl(row.url)){skipped++;return;}if(["有效","待核验","失效"].indexOf(row.status)<0)row.status="待核验";const old=employmentResourceRecords.find(function(x){return String(x.url||"").toLowerCase()===row.url.toLowerCase();});if(old){if(mode!=="append"){Object.assign(old,row,{updatedAt:fmtNow(),importFile:file.name});updated++;}else skipped++;}else if(mode!=="replace"){employmentResourceRecords.push(Object.assign({id:genId("er"),createdAt:fmtNow(),importFile:file.name},row));added++;}else skipped++;});employmentResourcePersist();renderPage("employment");showToast("导入完成：新增 "+added+"，更新 "+updated+"，跳过 "+skipped,"success");return true;});
}
function employmentResourcesPane(){
  const regions=[...new Set(employmentResourceRecords.map(function(r){return r.region;}).filter(Boolean))].sort(),industries=[...new Set(employmentResourceRecords.map(function(r){return r.industry;}).filter(Boolean))].sort();
  const toolbar='<div class="toolbar" style="display:flex;gap:10px;align-items:center;flex-wrap:wrap;margin-bottom:14px"><input class="in" style="width:260px" placeholder="搜索平台、主办单位或网址" value="'+attr(employmentResourceFilter.kw)+'" oninput="employmentResourceSetFilter(\'kw\',this.value)"><select class="in" onchange="employmentResourceSetFilter(\'region\',this.value)"><option value="">全部地域</option>'+regions.map(function(x){return '<option value="'+attr(x)+'"'+(employmentResourceFilter.region===x?' selected':'')+'>'+esc(x)+'</option>';}).join('')+'</select><select class="in" onchange="employmentResourceSetFilter(\'industry\',this.value)"><option value="">全部方向</option>'+industries.map(function(x){return '<option value="'+attr(x)+'"'+(employmentResourceFilter.industry===x?' selected':'')+'>'+esc(x)+'</option>';}).join('')+'</select><span style="flex:1"></span><button class="btn btn-sm btn-ghost" onclick="employmentResourceDownloadTemplate()">下载模板</button><button class="btn btn-sm btn-ghost" onclick="employmentResourceImport()">导入资源</button><button class="btn btn-sm btn-ghost" onclick="employmentResourceExport()">导出资源</button><button class="btn btn-primary btn-sm" onclick="employmentResourceOpenForm()">＋ 新增资源</button></div>';
  return '<div class="tip" style="margin-bottom:14px"><b>离线就业资源目录：</b>集中维护官方就业服务、校园招聘、公共就业和人才服务入口。系统不会自动抓取外部网页；请在人工确认官网可访问后标记为“有效”。</div><div class="card">'+toolbar+'<div id="employmentResourceContent">'+employmentResourceContentHtml()+'</div></div>';
}
PAGES.employment=function(){return '<h2 class="ptitle">🎯 毕业生就业 <span class="tag">就业意向 / 就业跟踪 / 就业资源</span></h2><div class="sub">从就业意向摸排、去向落实到资源服务，分阶段维护毕业生就业数据。</div><div class="tabs" style="margin-bottom:14px"><button class="tab '+(employmentActiveTab==='intention'?'active':'')+'" onclick="employmentSwitchTab(\'intention\')">📊 就业意向统计</button><button class="tab '+(employmentActiveTab==='destination'?'active':'')+'" onclick="employmentSwitchTab(\'destination\')">🎯 就业跟踪</button><button class="tab '+(employmentActiveTab==='resources'?'active':'')+'" onclick="employmentSwitchTab(\'resources\')">🔗 就业资源</button><span style="flex:1"></span><button class="btn btn-ghost btn-sm" onclick="wrAiRun(\'employment\',this)">🤖 AI 分析</button></div>'+(employmentActiveTab==='intention'?employmentIntentionsPane():employmentActiveTab==='destination'?employmentDestinationPane():employmentResourcesPane());};
