function subjectCompetitionExport(){if(!subjectCompetitionRecords.length){alert("暂无科创竞赛资源可导出。");return;}const data=[SUBJECT_COMPETITION_FIELDS.map(function(field){return field.header;})].concat(subjectCompetitionRecords.map(function(record){return SUBJECT_COMPETITION_FIELDS.map(function(field){return record[field.key]||"";});}));downloadXlsxFile("科创竞赛",data,"科创竞赛资源_"+xcmStamp()+".xlsx");showToast("已导出 "+subjectCompetitionRecords.length+" 条科创竞赛资源","success");}
