function subjectCompetitionImport(){
  const body='<div class="tip" style="margin-bottom:12px">支持 XLSX/XLS/CSV；至少填写“竞赛名称”，官网可后续补充。合并时优先按目录序号、其次按竞赛名称或网址更新。</div><input id="scImportFile" type="file" accept=".xlsx,.xls,.csv"><div style="margin-top:12px;display:flex;gap:18px"><label><input type="radio" name="scMode" value="merge" checked> 合并更新</label><label><input type="radio" name="scMode" value="append"> 仅追加</label><label><input type="radio" name="scMode" value="replace"> 全量替换</label></div>';
  openModal("导入科创竞赛",body,async function(){const file=(document.getElementById("scImportFile").files||[])[0];if(!file){showToast("请选择导入文件","error");return false;}const hints=[];SUBJECT_COMPETITION_FIELDS.forEach(function(field){hints.push(field.header,field.label,field.key);});const rows=await parseWorkbookToRows(file,hints);const smartMatch=await importConfirmApproximateMatches("科创竞赛",rows);if(!smartMatch.confirmed)return false;const enumErrors=importEnumRows("科创竞赛",rows);if(enumErrors.length){showToast("导入失败：第 "+enumErrors[0].row+" 行，"+enumErrors[0].msg,"error");return false;}const mode=(document.querySelector('input[name="scMode"]:checked')||{}).value||"merge";if(mode==="replace")subjectCompetitionRecords=[];let added=0,updated=0,skipped=0;rows.forEach(function(raw){const row={};SUBJECT_COMPETITION_FIELDS.forEach(function(field){row[field.key]=smartCell(raw,[field.header,field.label]);});if(!row.title||row.url&&!subjectCompetitionValidUrl(row.url)){skipped++;return;}if(["有效","待核验","失效"].indexOf(row.status)<0)row.status="待核验";const old=subjectCompetitionRecords.find(function(item){return row.catalogNo&&row.sourceVersion&&item.catalogNo===row.catalogNo&&item.sourceVersion===row.sourceVersion||String(item.title||"").trim()===row.title.trim()||row.url&&String(item.url||"").toLowerCase()===row.url.toLowerCase();});if(old){if(mode!=="append"){Object.assign(old,row,{updatedAt:fmtNow(),importFile:file.name});updated++;}else skipped++;}else{subjectCompetitionRecords.push(Object.assign({id:genId("sc"),createdAt:fmtNow(),importFile:file.name},row));added++;}});subjectCompetitionPersist();renderPage("subjectCompetition");showToast("导入完成：新增 "+added+"，更新 "+updated+"，跳过 "+skipped,"success");return true;});
}
function subjectCompetitionPage(){
  const levels=[...new Set(subjectCompetitionRecords.map(function(record){return record.level;}).filter(Boolean))].sort(),directions=[...new Set(subjectCompetitionRecords.map(function(record){return record.direction;}).filter(Boolean))].sort();
  const toolbar='<div class="toolbar" style="display:flex;gap:10px;align-items:center;flex-wrap:wrap;margin-bottom:14px"><input class="in" style="width:260px" placeholder="搜索竞赛、主办单位或网址" value="'+attr(subjectCompetitionFilter.kw)+'" oninput="subjectCompetitionSetFilter(\'kw\',this.value)"><select class="in" onchange="subjectCompetitionSetFilter(\'level\',this.value)"><option value="">全部级别</option>'+levels.map(function(value){return '<option value="'+attr(value)+'"'+(subjectCompetitionFilter.level===value?' selected':'')+'>'+esc(value)+'</option>';}).join('')+'</select><select class="in" onchange="subjectCompetitionSetFilter(\'direction\',this.value)"><option value="">全部方向</option>'+directions.map(function(value){return '<option value="'+attr(value)+'"'+(subjectCompetitionFilter.direction===value?' selected':'')+'>'+esc(value)+'</option>';}).join('')+'</select><span style="flex:1"></span><button class="btn btn-sm btn-ghost" onclick="subjectCompetitionDownloadTemplate()">下载模板</button><button class="btn btn-sm btn-ghost" onclick="subjectCompetitionImport()">导入资源</button><button class="btn btn-sm btn-ghost" onclick="subjectCompetitionExport()">导出资源</button><button class="btn btn-primary btn-sm" onclick="subjectCompetitionOpenForm()">＋ 新增竞赛</button></div>';
  return '<h2 class="ptitle">🏆 科创竞赛 <span class="tag">84项目录 + 补充赛事</span></h2><div class="sub">集中维护科创竞赛目录、官网、方向和主办单位，为赛事通知、报名组织和证书归档提供统一入口。</div><div class="tip" style="margin-bottom:14px"><b>目录来源：</b>'+esc(SUBJECT_COMPETITION_CATALOG_VERSION)+'，共84项，由中国高等教育学会高校竞赛评估与管理体系研究专家工作组发布；并非教育部直接发布的行政认定目录。<b>84项官网入口已补齐</b>，另收录教育部主办的“全国大学生职业规划大赛”作为目录外补充；没有独立官网的赛事使用主办方或当届承办单位的正式赛事页面。报名时间、参赛要求仍须以当届通知为准。</div><div class="card">'+toolbar+'<div id="subjectCompetitionContent">'+subjectCompetitionContentHtml()+'</div></div>';
}
