function achievementUnits(value){return Array.from(new Set(String(value||"").split(/[、,，;；\n]+/).map(function(x){return x.trim();}).filter(Boolean))).join("、");}
function achievementStudent(sid){return (students||[]).find(function(s){return String(s.id||"")===String(sid||"").trim();})||null;}
function achievementNormalize(row,source){const r=row||{},s=achievementStudent(r.sid);return {id:r.id||genId("achievement"),sid:String(r.sid||"").trim(),name:r.name||(s&&s.name)||"",dept:r.dept||(s&&s.dept)||"",major:r.major||(s&&s.major)||"",grade:r.grade||(s&&(s.grade||classGrade(s.cls)))||classGrade(r.cls)||"",cls:r.cls||(s&&s.cls)||"",category:r.category||"其他荣誉",level:r.level||"未判定",awardName:r.awardName||r.title||"",prize:r.prize||"",organization:achievementUnits(r.organization||""),issuingOrganization:achievementUnits(r.issuingOrganization||r.org||""),date:r.date||"",role:r.role||"学生获奖人",teachers:r.teachers||"",members:r.members||"",source:r.source||source||"manual",certificateId:r.certificateId||"",attachment:r.attachment||null,customFieldValues:r.customFieldValues&&typeof r.customFieldValues==="object"&&!Array.isArray(r.customFieldValues)?r.customFieldValues:{},createdAt:r.createdAt||fmtNow(),updatedAt:r.updatedAt||""};}
function achievementOrgMeta(record){const r=record||{},s=achievementStudent(r.sid);return {dept:(s&&s.dept)||r.dept||"",major:(s&&s.major)||r.major||"",grade:(s&&(s.grade||classGrade(s.cls)))||r.grade||classGrade(r.cls)||"",cls:(s&&s.cls)||r.cls||""};}
function achievementPersist(){localStorage.setItem(ACHIEVEMENT_KEY,JSON.stringify(achievementRecords));}
function achievementLoad(){try{const saved=JSON.parse(localStorage.getItem(ACHIEVEMENT_KEY)||"[]");achievementRecords=Array.isArray(saved)?saved.map(function(r){return achievementNormalize(r,r.source||"manual");}):[];if(!achievementRecords.length){const legacy=JSON.parse(localStorage.getItem(ACHIEVEMENT_LEGACY_KEY)||"[]");if(Array.isArray(legacy)&&legacy.length){achievementRecords=legacy.map(function(r){return achievementNormalize(r,"legacy");});achievementPersist();}}}catch(e){achievementRecords=[];reportDataError("获奖情况加载",e);}}
const ACHIEVEMENT_STAT_DIMENSIONS={dept:"学院",major:"专业",grade:"年级",cls:"班级"};
function achievementOrgStatsHtml(list){
  const dimension=ACHIEVEMENT_STAT_DIMENSIONS[achievementStatDimension]?achievementStatDimension:"dept";
  const groups={};
  list.forEach(function(r){
    const meta=achievementOrgMeta(r),name=String(meta[dimension]||"未维护").trim()||"未维护";
    if(!groups[name])groups[name]={name:name,records:0,students:new Set(),highLevel:0,categories:{},latest:""};
    const g=groups[name];g.records++;if(r.sid)g.students.add(String(r.sid));if(r.level==="国家级"||r.level==="省级")g.highLevel++;
    const category=r.category||"未判定";g.categories[category]=(g.categories[category]||0)+1;if(String(r.date||"")>g.latest)g.latest=String(r.date||"");
  });
  const rows=Object.keys(groups).map(function(name){return groups[name];}).sort(function(a,b){return b.records-a.records||a.name.localeCompare(b.name,"zh-CN");});
  const tableRows=rows.length?rows.map(function(g,index){
    const categories=Object.keys(g.categories).sort(function(a,b){return g.categories[b]-g.categories[a];}).map(function(k){return k+" "+g.categories[k]+"条";}).join("、");
    return '<tr><td>'+(index+1)+'</td><td><b>'+esc(g.name)+'</b></td><td><b>'+g.records+'</b></td><td>'+g.students.size+'</td><td>'+g.highLevel+'</td><td style="white-space:normal;min-width:220px">'+esc(categories||"—")+'</td><td>'+esc(g.latest||"—")+'</td></tr>';
  }).join(""):'<tr><td colspan="7" class="empty">当前筛选条件下暂无可统计的获奖记录</td></tr>';
  const buttons=Object.keys(ACHIEVEMENT_STAT_DIMENSIONS).map(function(key){
    const count=new Set(list.map(function(r){return achievementOrgMeta(r)[key]||"未维护";})).size;
    return '<button type="button" class="btn btn-sm '+(dimension===key?'btn-primary':'btn-ghost')+'" data-achievement-stat="'+attr(key)+'" onclick="achievementSetStatDimension('+jsArg(key)+')">按'+ACHIEVEMENT_STAT_DIMENSIONS[key]+'统计 <span class="tag" style="margin-left:4px">'+count+'</span></button>';
  }).join("");
  return '<div class="card" id="achievementOrgStats" style="margin:0 0 12px;padding:14px"><div style="display:flex;align-items:center;gap:8px;flex-wrap:wrap"><div><b>组织维度统计</b><small style="display:block;color:var(--muted);margin-top:3px">统计结果随上方搜索、获奖类型和级别筛选同步更新</small></div><span style="flex:1"></span>'+buttons+'</div><div class="list-scroll" style="margin-top:12px">'+table(["排名",ACHIEVEMENT_STAT_DIMENSIONS[dimension],"获奖记录","获奖学生","国家/省级","类型分布","最近获奖"],tableRows)+'</div></div>';
}
PAGES.achievement=function(){return enhancedPageFallback("获奖情况");};window.achievementSetStatDimension=function(dimension){if(!ACHIEVEMENT_STAT_DIMENSIONS[dimension])return;achievementStatDimension=dimension;renderPage("achievement");};
function achievementStudentsByName(name){const value=String(name||"").trim();return value?(students||[]).filter(function(s){return String(s.name||"").trim()===value;}):[];}
function achievementResolveStudent(sid,name){const studentId=String(sid||"").trim();if(studentId)return achievementStudent(studentId);const matches=achievementStudentsByName(name);return matches.length===1?matches[0]:null;}
function achievementStudentInfoHtml(sid,name){const studentId=String(sid||"").trim(),studentName=String(name||"").trim(),matches=achievementStudentsByName(studentName),s=achievementResolveStudent(studentId,studentName);if(!studentId&&!studentName)return '<div class="tip" style="margin:0">输入学号或姓名后，自动匹配学院、专业、年级、班级等完整学籍信息；同名学生请在弹出的候选信息中人工选择。</div>';if(!s){const reason=!studentId&&matches.length>1?'姓名 <b>'+esc(studentName)+'</b> 存在 '+matches.length+' 名同名学生，请在弹出的候选信息中人工选择。':'未在“学生管理”中匹配到该学生，请核对姓名和学号。';return '<div class="tip" style="margin:0;border-color:#f0c58a;color:#9a6517">'+reason+'</div>';}const fields=[["姓名",s.name],["性别",s.gender],["学院",s.dept],["专业",s.major],["年级",s.grade||classGrade(s.cls)],["班级",s.cls],["学籍状态",stuStatusLabel(s.status)||s.status],["学历",s.level],["招生类别",s.enrollType],["入学日期",s.enroll],["辅导员",s.counsel]];return '<div style="margin:0;padding:11px 12px;border:1px solid #c9e2d7;border-radius:9px;background:#f8fdf9"><b style="color:#126b49">已匹配学生学籍</b><span style="margin-left:8px;color:var(--muted)">学号：'+esc(s.id||studentId)+'</span><div style="display:grid;grid-template-columns:repeat(4,minmax(110px,1fr));gap:8px 12px;margin-top:9px">'+fields.map(function(x){return '<div><small style="display:block;color:var(--muted)">'+x[0]+'</small><span>'+esc(x[1]||"未维护")+'</span></div>';}).join("")+'</div></div>';}
window.achievementMatchStudent=function(source,value){const sidEl=document.getElementById("achievement_sid"),nameEl=document.getElementById("achievement_name"),info=document.getElementById("achievementStudentInfo");function apply(s,typed){if(sidEl)sidEl.value=s?(s.id||""):"";if(nameEl)nameEl.value=s?(s.name||""):(typed||"");if(info)info.innerHTML=achievementStudentInfoHtml(sidEl?sidEl.value:"",nameEl?nameEl.value:"");}if(source==="sid"){const s=achievementStudent(value);apply(s,"");return;}resolveStudentNameInput(value,apply,"获奖情况");};
