const STUDENT_INTEGRITY_REVIEW_KEY="nnuzc_student_integrity_review_version";
let studentIntegrityReviewRunning=false;
function studentIntegrityStorageSnapshot(){
  const snapshot={},api=window.StudentLinkIntegrity;if(!api)return snapshot;
  Object.keys(api.STORAGE_LABELS||{}).forEach(function(key){const value=localStorage.getItem(key);if(value!==null)snapshot[key]=value;});return snapshot;
}
async function studentIntegrityPublicScan(){
  const response=await fetch("/api/academic-public/integrity",{headers:{"X-Workbench-Token":TOKEN}});
  if(response.status===403)return {version:null,total:0,datasets:[]};
  const payload=await response.json().catch(function(){return {};});
  if(!response.ok)throw new Error(payload&&payload.error&&payload.error.message||"公用版学业数据检查失败");
  return payload;
}
async function studentIntegrityDeletePublic(version){
  const response=await fetch("/api/academic-public/integrity",{method:"POST",headers:{"Content-Type":"application/json","X-Workbench-Token":TOKEN},body:JSON.stringify({action:"delete",version:version})});
  const payload=await response.json().catch(function(){return {};});
  if(!response.ok)throw new Error(payload&&payload.error&&payload.error.message||"公用版学业数据删除失败");
  return payload;
}
async function studentIntegritySaveValues(values){
  const bridge=window.workbench&&window.workbench.legacy,entries=Object.entries(values||{});
  if(bridge&&bridge.commitStoreBatch){const operations=entries.map(function(entry){return {key:entry[0],method:"PUT",value:String(entry[1]),baseValue:localStorage.getItem(entry[0])};});await bridge.commitStoreBatch(operations);return;}
  entries.forEach(function(entry){localStorage.setItem(entry[0],String(entry[1]));});if(bridge&&bridge.flushStore)await bridge.flushStore();
}
