/* 固定选项历史值巡检：仅检查真正由系统锁定的字段，不把招生类别等可维护字典当成异常。 */
const FIXED_VALUE_REVIEW_KEY="nnuzc_fixed_value_review_version";
const FIXED_VALUE_REVIEW_SIGNATURE=SYS_VER+"|detail-v2";
let fixedValueReviewRunning=false;
function fixedValueReviewDefinitions(){
  const common=importFixedOptions(""),talk=importFixedOptions("谈心谈话"),home=importFixedOptions("家校联系"),employment=importFixedOptions("就业意向"),status=["待核验","有效","失效"];
  const field=function(path,label,choices){return {path:path.split("."),label:label,choices:choices||common[label]||[]};};
  return [
    {key:"nnuzc_students",label:"学生信息",fields:[field("gender","性别"),field("ethnic","民族"),field("political","政治面貌"),field("status","学籍状态"),field("level","学历"),field("transferNote","转专业备注"),field("accom","住宿情况"),field("psych.level","关怀等级"),field("fund.poorLevel","困难评定等级"),field("party.stage","当前阶段",PARTY_STAGES),field("party.leagueStatus","团员身份",PARTY_LEAGUE_STATUSES),...PARTY_TRAINING_CONFIG.map(function(item){return field("party.training."+item.key+".status",item.label+"状态",PARTY_TRAINING_STATUSES);})]},
    {key:"nnuzc_orgs",label:"班级基础数据",rows:"classes",fields:[field("level","学历")]},
    {key:"nnuzc_dorm_dist",label:"住宿分布",fields:[field("accom","住宿情况")]},
    {key:"nnuzc_fund_records",label:"资助记录",fields:[field("poorLevel","困难评定等级")]},
    {key:"nnuzc_talks",label:"谈心谈话",fields:[field("type","类型",talk["类型"]),field("way","方式",talk["方式"]),field("mood","情绪",talk["情绪"])]},
    {key:"nnuzc_events",label:"突发事件",fields:[field("type","类型",talk["类型"]),field("way","方式",talk["方式"]),field("mood","情绪",talk["情绪"])]},
    {key:"nnuzc_home",label:"家校联系",fields:[field("channel","渠道",home["渠道"])]},
    {key:"nnuzc_checkclass",label:"查课记录",fields:[field("type","类型",importFixedOptions("课堂")["类型"])]},
    {key:"nnuzc_checkdorm",label:"查寝记录",fields:[field("hygiene","卫生情况"),field("visited","是否走访")]},
    {key:"nnuzc_help",label:"帮扶记录",fields:[field("type","帮扶类型"),field("status2","帮扶状态")]},
    {key:"nnuzc_employment_intentions",label:"就业意向",fields:[field("intention","就业意向",employment["就业意向"]),field("englishStatus","英语通过情况",employment["英语通过情况"])]},
    {key:"nnuzc_employment_resources",label:"就业资源",fields:[field("status","状态",status)]},
    {key:"nnuzc_subject_competition_resources",label:"科创竞赛资源",fields:[field("status","状态",status)]}
  ];
}
function fixedValueReviewGet(row,path){return path.reduce(function(value,key){return value&&typeof value==="object"?value[key]:undefined;},row);}
function fixedValueReviewScan(){
  const groups=[],snapshots={},index=new Map();
  fixedValueReviewDefinitions().forEach(function(def){
    const raw=localStorage.getItem(def.key);if(raw===null)return;
    let data;try{data=JSON.parse(raw);}catch(error){throw new Error(def.label+"数据无法解析，请先修复后再检查");}
    const rows=def.rows?data&&data[def.rows]:data;
    if(def.rows&&rows===undefined)return;
    if(!Array.isArray(rows))throw new Error(def.label+"数据结构异常，请先修复后再检查");
    snapshots[def.key]=raw;
    rows.forEach(function(row,rowIndex){
      if(!row||typeof row!=="object")return;
      def.fields.forEach(function(field){
        const value=fixedValueReviewGet(row,field.path);
        if(typeof value!=="string"||!value.trim()||field.choices.includes(value))return;
        const groupKey=JSON.stringify([def.key,field.path,value]);let group=index.get(groupKey);
        if(!group){const suggestion=importSmartMatchSuggestion(field.label,value,field.choices);group={key:def.key,rows:def.rows||"",module:def.label,path:field.path,label:field.label,value:value,choices:field.choices,suggestion:suggestion.value||"",indices:[]};index.set(groupKey,group);groups.push(group);}
        group.indices.push(rowIndex);
      });
    });
  });
  return {groups:groups,snapshots:snapshots,total:groups.reduce(function(sum,group){return sum+group.indices.length;},0)};
}
async function fixedValueReviewCheckAfterUpdate(){
  if(workbenchIsReadOnly())return;
  if(fixedValueReviewRunning||localStorage.getItem(FIXED_VALUE_REVIEW_KEY)===FIXED_VALUE_REVIEW_SIGNATURE)return;
  if(studentIntegrityReviewRunning||document.getElementById("studentIntegrityUpdateLayer")){setTimeout(fixedValueReviewCheckAfterUpdate,1000);return;}
  let scan;try{scan=fixedValueReviewScan();}catch(error){showToast("固定选项历史值检查未完成："+(error.message||error),"warn");return;}
  if(!scan.total){try{await studentIntegritySaveValues({[FIXED_VALUE_REVIEW_KEY]:FIXED_VALUE_REVIEW_SIGNATURE});}catch(error){showToast("固定选项检查结果保存失败："+(error.message||error),"warn");}return;}
  fixedValueReviewRunning=true;fixedValueReviewOpen(scan);
}
function fixedValueReviewOpen(scan){
  document.getElementById("fixedValueReviewLayer")?.remove();
  const layer=document.createElement("div");layer.id="fixedValueReviewLayer";layer.setAttribute("role","dialog");layer.setAttribute("aria-modal","true");layer.setAttribute("aria-labelledby","fixedValueReviewTitle");layer.style.cssText="position:fixed;inset:0;z-index:30021;background:rgba(20,42,62,.48);display:flex;align-items:center;justify-content:center;padding:20px";
  function recordLabel(group,row,rowIndex){
    const parts=["源记录第 "+(rowIndex+1)+" 条"],studentId=String(row.studentId||row.sid||(group.key==="nnuzc_students"||group.key==="nnuzc_dorm_dist"?row.id:"")||"").trim();
    const student=studentId?students.find(function(item){return String(item.id)===studentId;}):null;
    if(studentId)parts.push("学号 "+studentId);
    const name=String(row.name||row.studentName||row.sname||(student&&student.name)||"").trim();if(name)parts.push("姓名 "+name);
    if(group.key==="nnuzc_orgs"&&row.name)parts.push("班级 "+row.name);
    if(row.cls&&group.key!=="nnuzc_orgs")parts.push("班级 "+row.cls);
    if(row.term)parts.push("学期 "+row.term);
    if(row.company)parts.push("单位 "+row.company);
    if(row.title)parts.push("标题 "+row.title);
    if(row.course)parts.push("课程 "+row.course);
    if(row.building||row.room)parts.push("宿舍 "+[row.building,row.room].filter(Boolean).join("-"));
    if(row.date)parts.push("日期 "+row.date);
    if(parts.length===1&&row.id)parts.push("记录ID "+row.id);
    return parts.join(" · ");
  }
  const issues=[];
  scan.groups.forEach(function(group){const data=JSON.parse(scan.snapshots[group.key]),rows=group.rows?data[group.rows]:data;group.indices.forEach(function(rowIndex){issues.push({group:group,rowIndex:rowIndex,record:recordLabel(group,rows[rowIndex],rowIndex)});});});
  const pageSize=50,pageCount=Math.max(1,Math.ceil(issues.length/pageSize)),selections=new Map();let currentPage=1;
  layer.innerHTML='<div style="width:min(1120px,calc(100vw - 40px));max-height:calc(100vh - 40px);overflow:auto;background:var(--card,#fff);border-radius:16px;box-shadow:0 24px 70px rgba(14,39,65,.3);border:1px solid var(--line,#dce7f1)"><div style="padding:22px 24px 12px"><h3 id="fixedValueReviewTitle" style="margin:0;font-size:20px">固定选项历史值检查</h3><p style="line-height:1.75;color:var(--muted);margin:10px 0 0">发现 <b>'+scan.total+'</b> 处字段值与当前固定选项不一致。下表逐条显示对应记录；系统不会自动修改，请按记录选择标准值或保留原值。下次版本升级后会重新检查保留的记录。</p></div><div style="padding:0 24px 18px"><div style="overflow:auto;max-height:50vh;border:1px solid var(--line);border-radius:10px"><table style="width:100%;min-width:800px"><thead><tr><th>业务模块</th><th>字段</th><th style="min-width:220px">涉及记录</th><th>现有值</th><th>建议</th><th>修改为</th></tr></thead><tbody id="fixedValueReviewRows"></tbody></table></div><div style="display:flex;align-items:center;justify-content:space-between;gap:12px;flex-wrap:wrap;margin-top:10px"><span id="fixedValueReviewPageInfo" class="tip"></span><span style="display:flex;gap:8px"><button type="button" class="btn btn-ghost btn-sm" id="fixedValueReviewPrev">上一页</button><button type="button" class="btn btn-ghost btn-sm" id="fixedValueReviewNext">下一页</button></span></div><div class="tip" style="margin-top:8px">每条记录可单独选择；仅修改您明确选择了标准值的字段，未选择的历史值继续保留。</div></div><div style="padding:14px 24px;border-top:1px solid var(--line);display:flex;justify-content:flex-end;gap:10px"><button type="button" class="btn btn-ghost" id="fixedValueReviewKeep">保留原值，稍后处理</button><button type="button" class="btn btn-primary" id="fixedValueReviewApply">应用所选修改</button></div></div>';
  document.body.appendChild(layer);
  const tbody=layer.querySelector("#fixedValueReviewRows");
  function renderPage(){
    const start=(currentPage-1)*pageSize;
    tbody.innerHTML=issues.slice(start,start+pageSize).map(function(issue,offset){const index=start+offset,group=issue.group,selected=selections.get(index)||"",options='<option value="">保留原值</option>'+group.choices.map(function(choice){return '<option value="'+attr(choice)+'"'+(selected===choice?' selected':'')+'>'+esc(choice)+'</option>';}).join("");return '<tr><td>'+esc(group.module)+'</td><td>'+esc(group.label)+'</td><td style="line-height:1.6;overflow-wrap:anywhere">'+esc(issue.record)+'</td><td>'+esc(group.value)+'</td><td>'+(group.suggestion?'建议：'+esc(group.suggestion):'—')+'</td><td><select data-review-index="'+index+'" aria-label="'+attr(group.module+group.label+issue.record)+'" style="min-width:120px">'+options+'</select></td></tr>';}).join("");
    layer.querySelector("#fixedValueReviewPageInfo").textContent="第 "+currentPage+" / "+pageCount+" 页 · 共 "+issues.length+" 处异常 · 已选择 "+selections.size+" 处修改";
    layer.querySelector("#fixedValueReviewPrev").disabled=currentPage<=1;layer.querySelector("#fixedValueReviewNext").disabled=currentPage>=pageCount;
  }
  tbody.onchange=function(event){const select=event.target.closest("select[data-review-index]");if(!select)return;const index=Number(select.dataset.reviewIndex);if(select.value)selections.set(index,select.value);else selections.delete(index);layer.querySelector("#fixedValueReviewPageInfo").textContent="第 "+currentPage+" / "+pageCount+" 页 · 共 "+issues.length+" 处异常 · 已选择 "+selections.size+" 处修改";};
  layer.querySelector("#fixedValueReviewPrev").onclick=function(){if(currentPage>1){currentPage--;renderPage();}};
  layer.querySelector("#fixedValueReviewNext").onclick=function(){if(currentPage<pageCount){currentPage++;renderPage();}};
  renderPage();
  function finish(){fixedValueReviewRunning=false;layer.remove();}
  layer.querySelector("#fixedValueReviewKeep").onclick=async function(){this.disabled=true;try{await studentIntegritySaveValues({[FIXED_VALUE_REVIEW_KEY]:FIXED_VALUE_REVIEW_SIGNATURE});finish();showToast("已保留现有值，下个版本将重新检查","success");}catch(error){this.disabled=false;showToast("保存选择失败："+(error.message||error),"error");}};
  layer.querySelector("#fixedValueReviewApply").onclick=async function(){
    const button=this,selected=Array.from(selections,function(entry){return {index:entry[0],value:entry[1]};});
    if(!selected.length){showToast("请先选择要修改的标准值，或点击保留原值","warn");return;}
    button.disabled=true;layer.querySelector("#fixedValueReviewKeep").disabled=true;
    try{
      const values={[FIXED_VALUE_REVIEW_KEY]:FIXED_VALUE_REVIEW_SIGNATURE},parsed={};
      selected.forEach(function(item){const issue=issues[item.index],group=issue&&issue.group;if(!group||!group.choices.includes(item.value))throw new Error("所选标准值已失效，请重新检查");if(localStorage.getItem(group.key)!==scan.snapshots[group.key])throw new Error("数据在检查后已发生变化，请刷新后重试");if(!parsed[group.key])parsed[group.key]=JSON.parse(scan.snapshots[group.key]);const data=parsed[group.key],rows=group.rows?data[group.rows]:data;let target=rows[issue.rowIndex];for(let i=0;i<group.path.length-1;i++)target=target&&target[group.path[i]];const leaf=group.path[group.path.length-1];if(!target||target[leaf]!==group.value)throw new Error("原值已变化，请刷新后重试");target[leaf]=item.value;});
      Object.keys(parsed).forEach(function(key){values[key]=JSON.stringify(parsed[key]);});
      await studentIntegritySaveValues(values);showToast("已修改选中的固定选项值，正在刷新页面","success");setTimeout(function(){location.reload();},350);
    }catch(error){button.disabled=false;layer.querySelector("#fixedValueReviewKeep").disabled=false;showToast("修改失败："+(error.message||error),"error");}
  };
}
