function directImportApplySpecial(type, rows){
  let ok=0,skip=0;
  if(type==="classroom"){
    rows.forEach(function(r){
      const sid=smartCell(r,["学号"]), s=students.find(function(x){return String(x.id)===sid;}), course=smartCell(r,["课程","课程名称"]);
      if(!s||!course){skip++;return;}
      const rec={term:smartCell(r,["学期"])||CURRENT_TERM,course:course,week:smartCell(r,["周次"])||"",section:smartCell(r,["节次"])||"",type:smartCell(r,["类型"])||"旷课",reason:smartCell(r,["原因"])||"",result:smartCell(r,["处理结果"])||"",teacher:smartCell(r,["教师","任课教师"])||"",date:smartCell(r,["日期"])||isoToday()};
      s.classroom=s.classroom||[];
      if(s.classroom.some(function(x){return x.term===rec.term&&x.course===rec.course&&x.date===rec.date&&x.week===rec.week&&x.section===rec.section;})){skip++;return;}
      s.classroom.push(rec); ok++;
    });
    persistStudents();
  }else if(type==="meeting"){
    rows.forEach(function(r){
      const term=smartCell(r,["学期"])||CURRENT_TERM, classList=String(smartCell(r,["班级","班级名称"])||"").split(/[、,，;；]+/).map(function(v){return v.trim();}).filter(Boolean), topic=smartCell(r,["班会主题","主题"]), orgs=classList.map(function(cls){return ORG_CLASSES.find(function(x){return x.name===cls;});});
      if(!classList.length||!topic||orgs.some(function(org){return !org;})){skip++;return;}
      const date=smartCell(r,["日期","时间"])||"";
      const key=classList.slice().sort().join("|");
      if(meetings.some(function(x){return x.term===term&&meetingClassesOf(x).slice().sort().join("|")===key&&(x.topic||x.title)===topic&&x.date===date;})){skip++;return;}
      const departments=Array.from(new Set(orgs.map(function(org){return org.dept;}).filter(Boolean))),majors2=Array.from(new Set(orgs.map(function(org){return org.major;}).filter(Boolean))),grades2=Array.from(new Set(orgs.map(function(org,index){return org.grade||classGrade(classList[index]);}).filter(Boolean)));
      meetings.push({id:"mt_"+Date.now()+"_"+ok,term:term,classes:classList,cls:classList.join("、"),departments:departments,majors:majors2,grades:grades2,dept:departments.join("、"),major:majors2.join("、"),grade:grades2.join("、"),topic:topic,date:date,place:smartCell(r,["地点"]),host:smartCell(r,["主持人"]),content:smartCell(r,["内容纪要","内容"]),files:[],createdAt:fmtNow()}); ok++;
    });
    persistMeetings();
  }
  return {ok:ok,skip:skip};
}
function openDirectModuleImport(view){
  const cfg=DIRECT_MODULE_IMPORTS[view]; if(!cfg)return;
  const hasTerm=cfg.headers.indexOf("学期")>=0;let targetTerm="";
  if(hasTerm){try{targetTerm=selectedImportTerm(viewTermKeyForPage(view));}catch(error){showToast(error.message,"warn");return;}}
  openMappedImportWizard({
    name:cfg.name+(hasTerm?" · "+targetTerm:""), fields:cfg.headers, requiredFields:cfg.type==="classroom"?["学号","课程"]:(cfg.type==="meeting"?["班级","班会主题"]:(cfg.type==="dormviolate"?["学号","原因"]:[])), template:"directImportTemplate('"+view+"')",
    infoHtml:hasTerm?"本次导入已锁定为“"+esc(targetTerm)+"”；文件中的学期值不会覆盖所选学期。":"",
    validate:function(rows){
      if(hasTerm)rows.forEach(function(row){row["学期"]=targetTerm;});
      const plan=rows.length?[{type:cfg.type,sheet:cfg.name,records:rows}]:[];
      const errors=smartImportPreflight(plan).map(function(msg){return {row:'—',msg:msg};});
      return {ok:errors.length?[]:rows,errors:errors};
    },
    apply:function(rows){
      const before=typeof smartImportSnapshot==="function"?smartImportSnapshot():{};
      try{return (cfg.type==="classroom"||cfg.type==="meeting")?directImportApplySpecial(cfg.type,rows):smartImportApplyPlan([{type:cfg.type,sheet:cfg.name,records:rows}]);}
      catch(e){if(typeof restoreSmartImportSnapshot==="function")restoreSmartImportSnapshot(before);throw e;}
    },
    after:function(result){goto(currentView);showToast(cfg.name+"导入完成："+result.ok+" 条写入，"+result.skip+" 条跳过","success");}
  });
}
function installDirectModuleImport(view){
  const cfg=DIRECT_MODULE_IMPORTS[view], content=document.getElementById("content"); if(!cfg||!content||content.querySelector('[data-direct-import="'+view+'"]'))return;
  const bars=Array.from(content.querySelectorAll(".toolbar")); let bar=bars.reverse().find(function(x){return x.querySelector("button");});
  if(!bar){bar=document.createElement("div");bar.className="toolbar";const anchor=content.querySelector(".sub")||content.querySelector("h2");if(anchor)anchor.insertAdjacentElement("afterend",bar);else content.prepend(bar);}
  const button=document.createElement("button");button.type="button";button.className="btn btn-ghost btn-sm";button.dataset.directImport=view;button.textContent="⬆ 导入";button.onclick=function(){openDirectModuleImport(view);};
  /* 顺序要求：导入在前、导出在后——插入到工具栏中的导出按钮之前 */
  const exportBtn=Array.from(bar.querySelectorAll("button")).find(function(b){ return /export/i.test(String(b.getAttribute("onclick")||"")); });
  if(exportBtn) bar.insertBefore(button, exportBtn); else bar.appendChild(button);
}
