async function meetingUploadNewFiles(){
  const selected=Array.from($("#meetFiles").files||[]), files=[];
  try{
    for(const file of selected){
      if(!/^image\//.test(file.type||"")) throw new Error('附件“'+file.name+'”不是图片格式，只能上传图片文件。');
      if(file.size>8*1024*1024) throw new Error('附件“'+file.name+'”超过 8MB。');
      const saved=await window.workbench.legacy.attachmentUploadFile(file.name,file);
      files.push(Object.assign({},saved,{mime:file.type||"application/octet-stream"}));
    }
  }catch(error){
    await Promise.all(files.map(function(f){return window.workbench.legacy.attachmentDelete(f.id).catch(function(){});}));
    throw error;
  }
  return files;
}
