function smartImportSnapshot(){
  const snapshot={};
  BACKUP_KEYS.forEach(function(key){ snapshot[key]=localStorage.getItem(key); });
  return snapshot;
}
function restoreSmartImportSnapshot(snapshot){
  Object.keys(snapshot).forEach(function(key){
    if(snapshot[key]===null) localStorage.removeItem(key);
    else localStorage.setItem(key,snapshot[key]);
  });
}

