    nnuzc_punishments:function(value){punishments=value;},nnuzc_dorm_dist:function(value){dormDistRecords=value;},
    nnuzc_fund_records:function(value){fundRecords=value;},nnuzc_task_notes:function(value){taskNotes=value;},
    nnuzc_academic_terms:function(value){window.academicTerms=sortTermsDesc(value);},
